/// <summary>
/// A cache file the SITE side writes and the game only reads: one "alias&lt;TAB&gt;value" per line, an alias may
/// repeat. The game never calls Supabase for this data. On serverb, ~/zones/scripts/ctf-site-cache.sh fetches it
/// and rewrites the file atomically when it changed (cron; ideally also kicked when a purchase lands). Reading
/// costs the game thread one stat() a minute, plus a parse only when the file actually changed.
/// A missing or unreadable file keeps whatever was loaded last.
/// </summary>
public class SiteCacheFile
{
    private static readonly TimeSpan CheckEvery = TimeSpan.FromMinutes(1);

    private readonly string _path;
    private DateTime _nextCheck = DateTime.MinValue;
    private DateTime _loadedMtime = DateTime.MinValue;
    private volatile Dictionary<string, List<string>> _byAlias = new Dictionary<string, List<string>>();

    public SiteCacheFile(string fileName)
    {
        _path = System.IO.Path.Combine("scripts", "GameTypes", "CTF", fileName);
    }

    /// <summary>Every value listed for the alias (case-insensitive), or an empty list.</summary>
    public List<string> Get(string alias)
    {
        Refresh(false);
        List<string> values;
        if (string.IsNullOrEmpty(alias) || !_byAlias.TryGetValue(alias.ToLower(), out values))
            return new List<string>();
        return values;
    }

    public int AliasCount { get { return _byAlias.Count; } }

    public Dictionary<string, List<string>> Snapshot() { return new Dictionary<string, List<string>>(_byAlias); }

    /// <summary>One line for staff: where the file is, how many aliases, and how old it is.</summary>
    public string Describe()
    {
        Refresh(true);
        if (_loadedMtime == DateTime.MinValue)
            return string.Format("{0}: not loaded (file missing?)", _path);
        return string.Format("{0}: {1} aliases, written {2:0} min ago", _path, _byAlias.Count,
            (DateTime.UtcNow - _loadedMtime).TotalMinutes);
    }

    public void Refresh(bool force)
    {
        DateTime now = DateTime.UtcNow;
        if (!force && now < _nextCheck)
            return;
        _nextCheck = now + CheckEvery;

        try
        {
            if (!System.IO.File.Exists(_path))
                return;
            DateTime mtime = System.IO.File.GetLastWriteTimeUtc(_path);
            if (mtime == _loadedMtime)
                return;

            var fresh = new Dictionary<string, List<string>>();
            foreach (string raw in System.IO.File.ReadAllLines(_path))
            {
                int tab = raw.IndexOf('\t');
                if (tab <= 0)
                    continue;
                string alias = raw.Substring(0, tab).Trim().ToLower();
                string value = raw.Substring(tab + 1).Trim();
                if (alias.Length == 0 || value.Length == 0)
                    continue;
                List<string> values;
                if (!fresh.TryGetValue(alias, out values))
                    fresh[alias] = values = new List<string>();
                values.Add(value);
            }
            _byAlias = fresh;
            _loadedMtime = mtime;
        }
        catch (Exception ex)
        {
            Console.WriteLine(String.Format("Site cache {0} not reloaded: {1}", _path, ex.Message));
        }
    }
}

public class PhraseExplosionManager
{
    // Kill phrases: PhraseCache.txt, "alias<TAB>phrase". This used to be an HTTPS POST to Supabase made from
    // Player.Death through .Result, which froze every arena in the zone (ZoneArenas polls them all on one
    // thread) for the round trip every 5 minutes - and on EVERY kill while the endpoint was failing.
    private static readonly SiteCacheFile _cache = new SiteCacheFile("PhraseCache.txt");

    /// <summary>The phrase the site has for the alias (PhraseCache.txt), or null: whoever has one bought the perk.</summary>
    public static string GetSitePhrase(string playerAlias)
    {
        List<string> phrases = _cache.Get(playerAlias);
        return phrases.Count == 0 ? null : phrases[phrases.Count - 1];
    }

    // ?phrase (Travis 10-25): a player with the perk can change their phrase in game. It is kept in PhraseOverrides.txt (zone-written,
    // never push): alias TAB phrase TAB the site's phrase at that moment TAB UTC time. It wins over the site's phrase until the site's
    // own phrase changes (an edit on the dashboard is newer, so it takes over again). The site can read the file to pick the change up.
    private static readonly string OVERRIDE_PATH = System.IO.Path.Combine("scripts", "GameTypes", "CTF", "PhraseOverrides.txt");
    private static readonly object _overrideLock = new object();
    private static Dictionary<string, string[]> _overrides;   // alias -> [phrase, site phrase when set, utc time]

    private static void LoadOverrides()
    {
        if (_overrides != null) return;
        _overrides = new Dictionary<string, string[]>(StringComparer.OrdinalIgnoreCase);
        try
        {
            if (!System.IO.File.Exists(OVERRIDE_PATH)) return;
            foreach (string raw in System.IO.File.ReadAllLines(OVERRIDE_PATH))
            {
                if (raw.StartsWith("#")) continue;
                string[] f = raw.Split('\t');
                if (f.Length < 2 || f[0].Trim().Length == 0 || f[1].Trim().Length == 0) continue;
                _overrides[f[0].Trim()] = new[] { f[1].Trim(), f.Length > 2 ? f[2].Trim() : "", f.Length > 3 ? f[3].Trim() : "" };
            }
        }
        catch (Exception ex) { Console.WriteLine("PhraseOverrides.txt not read: " + ex.Message); }
    }

    private static void SaveOverrides()
    {
        try
        {
            var lines = new List<string> { "# alias<TAB>phrase<TAB>site phrase when set<TAB>UTC - written by the zone (?phrase). Never push this from local." };
            foreach (var kv in _overrides.OrderBy(k => k.Key, StringComparer.OrdinalIgnoreCase))
                lines.Add(kv.Key + "\t" + kv.Value[0] + "\t" + kv.Value[1] + "\t" + kv.Value[2]);
            string tmp = OVERRIDE_PATH + ".tmp";
            System.IO.File.WriteAllLines(tmp, lines);
            if (System.IO.File.Exists(OVERRIDE_PATH)) System.IO.File.Delete(OVERRIDE_PATH);
            System.IO.File.Move(tmp, OVERRIDE_PATH);
        }
        catch (Exception ex) { Console.WriteLine("PhraseOverrides.txt not written: " + ex.Message); }
    }

    /// <summary>The in-game phrase that is still current for the alias, or null (none, or the site's own phrase changed since).</summary>
    public static string GetOverride(string playerAlias)
    {
        if (string.IsNullOrEmpty(playerAlias)) return null;
        lock (_overrideLock)
        {
            LoadOverrides();
            string[] o;
            if (!_overrides.TryGetValue(playerAlias, out o)) return null;
            string site = GetSitePhrase(playerAlias) ?? "";
            return string.Equals(site, o[1], StringComparison.Ordinal) ? o[0] : null;
        }
    }

    /// <summary>Sets (phrase) or clears (null) the alias's in-game phrase.</summary>
    public static void SetOverride(string playerAlias, string phrase)
    {
        lock (_overrideLock)
        {
            LoadOverrides();
            if (phrase == null) _overrides.Remove(playerAlias);
            else _overrides[playerAlias] = new[] { phrase, GetSitePhrase(playerAlias) ?? "", DateTime.UtcNow.ToString("yyyy-MM-dd HH:mm") };
            SaveOverrides();
        }
    }

    /// <summary>The player's kill phrase (their in-game change if it is still current, else the site's), or null. Never touches the network.</summary>
    public static string GetCachedPhrase(string playerAlias)
    {
        return GetOverride(playerAlias) ?? GetSitePhrase(playerAlias) ?? GetChampionPhrase(playerAlias);
    }

    // Dueling champions' own kill phrases (Round 4, 10-25): used ONLY when the site has no phrase for the alias (no perk). alias -> phrase, 1-12 characters,
    // letters / digits / space / ! ? . - (the v2 font). Add a champion here; a perk holder's site phrase or ?phrase override always wins over it.
    private static readonly Dictionary<string, string> ChampionPhrases = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
    {
        { "Dro", "EZ 1V1" },
        { "Dropped", "EZ 1V1" },
    };

    public static string GetChampionPhrase(string playerAlias)
    {
        string phrase;
        return !string.IsNullOrEmpty(playerAlias) && ChampionPhrases.TryGetValue(playerAlias, out phrase) ? phrase : null;
    }

    /// <summary>Kept for existing callers; completes immediately from the file cache.</summary>
    public static Task<string> GetPlayerPhrase(string playerAlias)
    {
        return Task.FromResult(GetCachedPhrase(playerAlias));
    }

    /// <summary>Re-reads PhraseCache.txt now instead of waiting for the next once-a-minute check.</summary>
    public static void ForceRefreshPhrases()
    {
        _cache.Refresh(true);
    }

    public static string Describe()
    {
        return _cache.Describe();
    }

    // Method to get all cached phrases (for debugging)
    public static Dictionary<string, string> GetCachedPhrases()
    {
        var all = new Dictionary<string, string>();
        foreach (var kv in _cache.Snapshot())
            all[kv.Key] = kv.Value[kv.Value.Count - 1];
        return all;
    }
}

// Extension method to create custom explosion text
    public class ProductPurchaseManager
    {
        // Who owns which product: PurchaseCache.txt, "alias<TAB>product_name" (see SiteCacheFile). This was a
        // Supabase fetch with no single-flight: a stale cache made every build item start its own refresh, so the
        // rest of ?b/?bw, spawn autobuy and armory builds finished on thread-pool threads, editing inventories
        // under the arena thread (the SC_Inventory "Collection was modified" exceptions). Reading a file keeps
        // GetConvertedItemName synchronous, so every await on it completes in place on the caller's thread.
        private static readonly SiteCacheFile _cache = new SiteCacheFile("PurchaseCache.txt");

        /// <summary>
        /// Item alias mappings - maps short names to full item names
        /// </summary>
        private static readonly Dictionary<string, string> ITEM_ALIASES = new Dictionary<string, string>
        {
            { "caw", "Kuchler A6 CAW" },
            { "ar", "Assault Rifle" },
            { "rpg", "RPG" },
            // Add more aliases as needed
        };

        /// <summary>
        /// Product conversion mappings - add new products here
        /// </summary>
        private static readonly Dictionary<string, Dictionary<string, string>> PRODUCT_CONVERSIONS = new Dictionary<string, Dictionary<string, string>>
        {
            // rainbow_caw (Kuchler A6 CAW -> Rainbow CAW) moved to the CTFSkins.cs catalogue 10-27: an item skin like the others (off until the
            // owner turns it on with ?skin), and this ?b-only conversion no longer fights the skin sweep over the same CAW.
            // Add more products here as needed:
            // {
            //     "premium_rifle", new Dictionary<string, string>
            //     {
            //         { "Assault Rifle", "Premium AR" }
            //     }
            // }
        };

        public static Task<List<string>> GetPlayerProducts(string playerAlias)
        {
            return Task.FromResult(_cache.Get(playerAlias));
        }

        public static async Task<bool> HasPlayerPurchased(string playerAlias, string productName)
        {
            var products = await GetPlayerProducts(playerAlias);
            return products.Any(p => p.Equals(productName, StringComparison.OrdinalIgnoreCase));
        }

        public static string Describe()
        {
            return _cache.Describe();
        }

        /// <summary>
        /// Gets the converted item name if player has purchased the product
        /// </summary>
        public static async Task<string> GetConvertedItemName(string playerAlias, string originalItemName)
        {
            try
            {
                var playerProducts = await GetPlayerProducts(playerAlias);
                
                // Check each product the player has purchased
                foreach (var product in playerProducts)
                {
                    if (PRODUCT_CONVERSIONS.ContainsKey(product.ToLower()))
                    {
                        var conversions = PRODUCT_CONVERSIONS[product.ToLower()];
                        if (conversions.ContainsKey(originalItemName))
                        {
                            return conversions[originalItemName];
                        }
                    }
                }
                
                return originalItemName; // No conversion found
            }
            catch (Exception ex)
            {
                Console.WriteLine(string.Format("Error getting converted item for {0}: {1}", playerAlias, ex.Message));
                return originalItemName; // Return original on error
            }
        }

        public static Task ForceRefreshCache()
        {
            _cache.Refresh(true);
            return Task.CompletedTask;
        }
    }

