    /// <summary>
/// Kill-phrase layout (font fork, 2026-10-25). The Letters items (A-Z, digits, ! $ #, plus the kt_* punctuation items) are
/// single-frame projectile sprites of different widths, so a fixed advance left uneven gaps (I far from W). Each glyph's
/// box (left edge relative to its sprite anchor, width in px) is measured from the sprite itself; Layout advances by that
/// width plus Gap, a space is SpaceWidth, and the whole phrase is centred on the kill spot.
/// Set = which font the items are drawn with ("v1" stock 8 px CMfont, "v2" bold, "fade" bold light that fades out); the
/// table below belongs to that set and must match patch_font.py's --set.
/// </summary>
public static class KillFont
{
    public const string Set = "v2";
    private const int Gap = 1;
    private const int SpaceWidth = 6;
    private const int MaxGlyphs = 48;   // a phrase is capped here so one kill cannot flood the audience with packets

    // char -> { left edge from the anchor, width }, measured from the sprites of Set
    private static readonly Dictionary<char, int[]> Boxes = new Dictionary<char, int[]>
    {
            { '!', new[] { -2, 4 } },
            { '"', new[] { -3, 7 } },
            { '#', new[] { -4, 9 } },
            { '$', new[] { -4, 8 } },
            { '%', new[] { -5, 10 } },
            { '&', new[] { -4, 9 } },
            { '\'', new[] { -2, 4 } },
            { '(', new[] { -3, 6 } },
            { ')', new[] { -3, 6 } },
            { '*', new[] { -3, 7 } },
            { '+', new[] { -4, 8 } },
            { ',', new[] { -2, 4 } },
            { '-', new[] { -3, 6 } },
            { '.', new[] { -2, 4 } },
            { '/', new[] { -4, 8 } },
            { '0', new[] { -4, 8 } },
            { '1', new[] { -3, 6 } },
            { '2', new[] { -4, 8 } },
            { '3', new[] { -4, 8 } },
            { '4', new[] { -4, 8 } },
            { '5', new[] { -4, 8 } },
            { '6', new[] { -4, 8 } },
            { '7', new[] { -4, 8 } },
            { '8', new[] { -4, 8 } },
            { '9', new[] { -4, 8 } },
            { ':', new[] { -2, 4 } },
            { '=', new[] { -4, 8 } },
            { '?', new[] { -4, 8 } },
            { '@', new[] { -5, 10 } },
            { 'A', new[] { -4, 9 } },
            { 'B', new[] { -4, 8 } },
            { 'C', new[] { -4, 8 } },
            { 'D', new[] { -4, 8 } },
            { 'E', new[] { -3, 7 } },
            { 'F', new[] { -3, 7 } },
            { 'G', new[] { -4, 8 } },
            { 'H', new[] { -4, 8 } },
            { 'I', new[] { -3, 6 } },
            { 'J', new[] { -3, 7 } },
            { 'K', new[] { -4, 8 } },
            { 'L', new[] { -3, 7 } },
            { 'M', new[] { -5, 10 } },
            { 'N', new[] { -4, 8 } },
            { 'O', new[] { -4, 9 } },
            { 'P', new[] { -4, 8 } },
            { 'Q', new[] { -4, 8 } },
            { 'R', new[] { -4, 8 } },
            { 'S', new[] { -4, 8 } },
            { 'T', new[] { -4, 8 } },
            { 'U', new[] { -4, 8 } },
            { 'V', new[] { -4, 8 } },
            { 'W', new[] { -5, 10 } },
            { 'X', new[] { -4, 8 } },
            { 'Y', new[] { -4, 8 } },
            { 'Z', new[] { -4, 8 } },
    };

    // characters whose item is not named after the character
    private static readonly Dictionary<char, string> ItemNames = new Dictionary<char, string>
    {
            { '?', "kt_question" },
            { '.', "kt_period" },
            { ':', "kt_colon" },
            { '/', "kt_slash" },
            { '*', "kt_star" },
            { '\"', "kt_dquote" },
            { ',', "kt_comma" },
            { '\'', "kt_apos" },
            { '-', "kt_dash" },
            { '+', "kt_plus" },
            { '=', "kt_equals" },
            { '(', "kt_lparen" },
            { ')', "kt_rparen" },
            { '@', "kt_at" },
            { '%', "kt_percent" },
            { '&', "kt_amp" },
    };
    private static readonly string[] DigitNames = { "zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine" };

    private static readonly Dictionary<char, ItemInfo.Projectile> _items = new Dictionary<char, ItemInfo.Projectile>();
    private static readonly HashSet<char> _missing = new HashSet<char>();

    /// <summary>the Letters item for a character (upper-cased), or null</summary>
    public static ItemInfo.Projectile Item(char letter)
    {
        letter = char.ToUpperInvariant(letter);
        ItemInfo.Projectile found;
        if (_items.TryGetValue(letter, out found))
            return found;

        ItemInfo.Projectile item;
        string named;
        if (letter == 'N')
            item = AssetManager.Manager.getItemByID(1341) as ItemInfo.Projectile;   // the items 'n' and 'm' exist too, so N and M go by id
        else if (letter == 'M')
            item = AssetManager.Manager.getItemByID(1356) as ItemInfo.Projectile;
        else if (char.IsDigit(letter))
            item = AssetManager.Manager.getItemByName(DigitNames[letter - '0']) as ItemInfo.Projectile;
        else if (ItemNames.TryGetValue(letter, out named))
            item = AssetManager.Manager.getItemByName(named) as ItemInfo.Projectile;
        else
            item = AssetManager.Manager.getItemByName(letter.ToString()) as ItemInfo.Projectile;

        if (item != null)
            _items[letter] = item;
        else if (_missing.Add(letter))
            Console.WriteLine(String.Format("Could not find weapon for letter: {0}", letter));   // once per character
        return item;
    }

    /// <summary>each visible letter's item and the x its sprite is anchored at, for a phrase centred on centreX</summary>
    public static List<KeyValuePair<ItemInfo.Projectile, int>> Layout(string text, int centreX)
    {
        var glyphs = new List<KeyValuePair<ItemInfo.Projectile, int>>();
        if (string.IsNullOrEmpty(text))
            return glyphs;

        var edges = new List<int>();            // each glyph's left edge, from the start of the phrase
        var boxes = new List<int[]>();
        int cursor = 0, pendingGap = 0, shown = 0;
        foreach (char raw in text)
        {
            if (raw == ' ')
            {
                cursor += SpaceWidth;
                pendingGap = 0;
                continue;
            }
            char c = char.ToUpperInvariant(raw);
            int[] box;
            if (shown >= MaxGlyphs || !Boxes.TryGetValue(c, out box))
                continue;
            ItemInfo.Projectile item = Item(c);
            if (item == null)
                continue;
            cursor += pendingGap;
            glyphs.Add(new KeyValuePair<ItemInfo.Projectile, int>(item, 0));
            edges.Add(cursor);
            boxes.Add(box);
            cursor += box[1];
            pendingGap = Gap;
            shown++;
        }

        int start = centreX - cursor / 2;
        for (int i = 0; i < glyphs.Count; i++)
            glyphs[i] = new KeyValuePair<ItemInfo.Projectile, int>(glyphs[i].Key, start + edges[i] - boxes[i][0]);
        return glyphs;
    }
}

public static class ExplosionHelper
    {
        // Letters only go to people who could have the spot on screen (half the diagonal of a 2560x1440
        // view is ~1470px). They used to go to every player in the arena, one reliable packet per letter,
        // queued AHEAD of the kill packet the server routes right after Player.Death returns.
        private const int PHRASE_AUDIENCE_RANGE = 1600;

        /// <summary>
        /// Synchronous, game-thread version for Player.Death and *testphrase: the caller already has the
        /// phrase from PhraseExplosionManager.GetCachedPhrase.
        /// </summary>
        public static void ShowPhrase(Arena arena, Player killerPlayer, string phrase, short posX, short posY, short posZ)
        {
            if (string.IsNullOrEmpty(phrase))
                return;
            CreateTextExplosion(arena, phrase, posX, posY, posZ, killerPlayer);
        }

        /// <summary>?phrase: the phrase drawn for ONE player only (above where they stand), the way a kill would show it</summary>
        public static void ShowPhraseTo(Player viewer, string phrase, short x, short y, short z)
        {
            if (viewer == null || string.IsNullOrEmpty(phrase))
                return;
            foreach (KeyValuePair<ItemInfo.Projectile, int> glyph in KillFont.Layout(phrase, x))
            {
                var letter = new SC_Projectile
                {
                    projectileID = (short)glyph.Key.id,
                    playerID = (ushort)viewer._id,
                    posX = (short)glyph.Value,
                    posY = y,
                    posZ = z,
                    yaw = viewer._state.yaw
                };
                viewer._client.sendReliable(letter);
            }
        }

        public static async Task CreateCustomExplosion(Arena arena, Player killerPlayer, short posX, short posY, short posZ)
    {
        try
        {
            // Get the killer's custom phrase
            string customPhrase = await PhraseExplosionManager.GetPlayerPhrase(killerPlayer._alias);
            
            // Create the explosion with custom text at victim's location
            CreateTextExplosion(arena, customPhrase, posX, posY, posZ, killerPlayer);
            
            // Optional: Log the explosion for debugging
            // Console.WriteLine(String.Format("{0} triggered explosion with phrase: {1}", killerPlayer._alias, customPhrase));
        }
        catch (Exception ex)
        {
            Console.WriteLine(String.Format("Error creating custom explosion: {0}", ex.Message));
            // Fallback to default explosion
            CreateTextExplosion(arena, "BLOOP!", posX, posY, posZ, killerPlayer);
        }
    }
    
    private static void CreateTextExplosion(Arena arena, string text, short x, short y, short z, Player from)
    {
        // One projectile per visible letter (the Letters items), laid out by KillFont: each glyph advances by its own
        // width plus a fixed gap, and the phrase is centred on the spot (it used to start there, at a fixed 10 px per letter).

        // Who can see it: players and spectators near the spot, worked out once for the whole phrase.
        List<Player> audience = arena.getPlayersAndSpecInRange(x, y, PHRASE_AUDIENCE_RANGE);
        if (audience == null || audience.Count == 0)
            return;

        foreach (KeyValuePair<ItemInfo.Projectile, int> glyph in KillFont.Layout(text, x))
        {
            // Create the explosion projectile using the same method as Albert's EMP
            SC_Projectile letterExplosion = new SC_Projectile
            {
                projectileID = (short)glyph.Key.id,
                playerID = (ushort)from._id,
                posX = (short)glyph.Value,
                posY = y,
                posZ = z,
                yaw = from._state.yaw
            };

            // Send the explosion to the players who can see it
            foreach (Player p in audience)
            {
                p._client.sendReliable(letterExplosion);
            }
        }
    }
}

/// <summary>
/// Works out which class a player is ACTUALLY playing.
///
/// Replaces `player._skills.First().Value.skill.Name`, which was used in four places and is not
/// deterministic: Dictionary enumeration order is unspecified, so .First() returns whichever entry
/// the hash buckets happen to yield. That is fine only while a player holds exactly one skill, and
/// they frequently hold more - Referee/Staff sit alongside the class, and HandleSwapCommand
/// deliberately adds a base skill next to the swapped one.
///
/// Ground truth is the player's base VEHICLE: a class skill declares DefaultVehicleId, and the class
/// you are playing is the one whose vehicle you are sitting in.
/// </summary>
public static class CTFClass
{
    /// <summary>Real player classes live in rpg categories "Classes", "Classes CTFX" and
    /// "Classes - Premades". Referee/Staff are "Unknown" and event classes are "Event Class", so a
    /// prefix test on "Classes" excludes exactly the skills that caused the mis-attribution.</summary>
    private static bool IsClassSkill(Assets.SkillInfo skill)
    {
        return skill != null
            && skill.Category != null
            && skill.Category.StartsWith("Classes", StringComparison.OrdinalIgnoreCase);
    }

    /// <summary>The SkillInfo the player is actually playing, or null.</summary>
    public static Assets.SkillInfo Resolve(Player player)
    {
        if (player == null || player._skills == null || player._skills.Count == 0)
            return null;

        int vehicleId = -1;
        if (player._baseVehicle != null && player._baseVehicle._type != null)
            vehicleId = player._baseVehicle._type.Id;

        Assets.SkillInfo byVehicle = null;
        Assets.SkillInfo anyClass = null;
        Assets.SkillInfo anySkill = null;

        foreach (Player.SkillItem item in player._skills.Values)
        {
            Assets.SkillInfo skill = item.skill;
            if (skill == null)
                continue;

            // Lowest SkillId wins each tier, so the answer never depends on hash order.
            if (anySkill == null || skill.SkillId < anySkill.SkillId)
                anySkill = skill;

            if (!IsClassSkill(skill))
                continue;

            if (anyClass == null || skill.SkillId < anyClass.SkillId)
                anyClass = skill;

            if (vehicleId >= 0 && skill.DefaultVehicleId == vehicleId)
            {
                if (byVehicle == null || skill.SkillId < byVehicle.SkillId)
                    byVehicle = skill;
            }
        }

        return byVehicle ?? anyClass ?? anySkill;
    }

    /// <summary>The played class name, or "Unknown". Never null.</summary>
    public static string ResolveName(Player player)
    {
        Assets.SkillInfo skill = Resolve(player);
        return skill != null && skill.Name != null ? skill.Name : "Unknown";
    }
}

public class WebIntegration
{
    private static readonly HttpClient httpClient = new HttpClient();
    //private const string API_ENDPOINT = "http://localhost:3000/api/game-data";
    private const string API_ENDPOINT = "https://freeinf.org/api/game-data";
    
    public static async Task SendGameDataToWebsite(Arena arena, string baseUsed)
    {
        try
        {
            // Determine game type based on arena name
            string gameType = DetermineGameType(arena._name);
            
            // Get all players in the arena
            var players = arena.Players.ToList();
            var gameDataPlayers = new List<PlayerData>();
            
            // Determine which team is offense/defense for OvD games
            bool titanIsOffense = false;
            //if (gameType == "OvD")
            //{
                titanIsOffense = DetermineOffenseTeam(players, arena);
            //}
            
            // Process each player
            foreach (Player player in players)
            {
                string actualTeamName = player._team._name;
                string teamType = DeterminePlayerTeamType(player);
                string className = player._baseVehicle._type.Name;
                bool isOffense = DetermineIsOffense(teamType, titanIsOffense, gameType);
                string weapon = GetSpecialWeapon(player);
                
                gameDataPlayers.Add(new PlayerData
                {
                    alias = player._alias,
                    team = actualTeamName,
                    teamType = teamType,
                    className = className,
                    isOffense = isOffense,
                    weapon = weapon
                });
            }
            
            // Manually construct JSON string (no external libraries needed)
            string jsonData = BuildJsonString(arena._name, gameType, baseUsed, gameDataPlayers);
            
            // Send to API
            var content = new StringContent(jsonData, System.Text.Encoding.UTF8, "application/json");
            
            var response = await httpClient.PostAsync(API_ENDPOINT, content);
            
            if (response.IsSuccessStatusCode)
            {
                //Console.WriteLine("Game data sent successfully to website");
            }
            else
            {
                //Console.WriteLine(String.Format("Failed to send game data: {0}", response.StatusCode));
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine(String.Format("Error sending game data: {0}", ex.Message));
        }
    }
    
    private static string DetermineGameType(string arenaName)
    {
        if (arenaName.Contains("OvD"))
            return "OvD";
        else if (arenaName.Contains("Arena 1"))
            return "Pub";
        else if (arenaName.Contains("Mix"))
            return "Mix";
        else if (arenaName.Contains("Duel"))
            return "Dueling";
        else if (arenaName.Contains("CTF"))
            return "CTF";
        else
            return "Unknown";
    }
    
    private static string DeterminePlayerTeamType(Player player)
    {
        if (player._team._name.Contains(" T"))
            return "Titan";
        else if (player._team._name.Contains(" C"))
            return "Collective";
        else
            return "Unknown";
    }
    
    private static bool DetermineOffenseTeam(List<Player> players, Arena arena)
    {
        // First, try to find the team with a Squad Leader - that team is offense
        foreach (Player player in players)
        {
            // Resolve properly: .First() here meant a Squad Leader who also held Referee could be
            // missed entirely, dropping this through to the player-count fallback and labelling the
            // wrong team as offense for the whole game record.
            string primarySkill = CTFClass.ResolveName(player);
            
            if (primarySkill == "Squad Leader")
            {
                return player._team._name.Contains(" T"); // Return true if Titan has Squad Leader
            }
        }
        
        // If no Squad Leader found, use a consistent fallback based on team balance
        // Count players on each team type (excluding Dueler players)
        int titanCount = 0;
        int collectiveCount = 0;
        
        foreach (Player player in players)
        {
            // Skip Dueler players from team counting
            if (CTFClass.ResolveName(player) == "Dueler") continue;
            
            if (player._team._name.Contains(" T"))
                titanCount++;
            else if (player._team._name.Contains(" C"))
                collectiveCount++;
        }
        
        // Make the larger team defense (more common in OvD), smaller team offense
        // If equal, default to Titan = offense
        if (titanCount > collectiveCount)
            return false; // Titan = defense (larger team)
        else
            return true;  // Titan = offense (smaller or equal team)
    }
    
    private static bool DetermineIsOffense(string teamType, bool titanIsOffense, string gameType)
    {
        // For OvD games, use the Squad Leader logic
        if (gameType == "OvD")
        {
            if (teamType == "Titan")
                return titanIsOffense;
            else
                return !titanIsOffense;
        }
        
        // For CTF games, assume teams alternate offense/defense
        if (gameType == "CTF")
        {
            if (teamType == "Titan")
                return titanIsOffense;
            else
                return !titanIsOffense;
        }
        
        // For other game types (Pub, Mix, Duel, Unknown), still try to separate teams
        // Don't default everyone to offense - use the same logic
        if (teamType == "Titan")
            return titanIsOffense;
        else
            return !titanIsOffense;
    }
    
    private static string GetSpecialWeapon(Player player)
    {
        // Check for special weapons based on player's current equipment
        // You may need to adapt this based on your specific weapon detection system
        
        if (player._baseVehicle != null && player._baseVehicle._type != null)
        {
            string vehicleType = player._baseVehicle._type.Name;
            if (vehicleType.Contains("CAW"))
                return "CAW";
            else if (vehicleType.Contains("SG"))
                return "SG";
        }
        
        // Alternative: Check player's inventory or equipped items
        // You may need to implement this based on your specific system
        
        return null; // Return null if no special weapon
    }
    
    private static string BuildJsonString(string arenaName, string gameType, string baseUsed, List<PlayerData> players)
    {
        var json = new System.Text.StringBuilder();
        json.Append("{");
        
        // Add basic properties
        json.AppendFormat("\"arenaName\":\"{0}\",", EscapeJsonString(arenaName));
        json.AppendFormat("\"gameType\":\"{0}\",", EscapeJsonString(gameType));
        json.AppendFormat("\"baseUsed\":\"{0}\",", EscapeJsonString(baseUsed));
        
        // Add players array
        json.Append("\"players\":[");
        
        for (int i = 0; i < players.Count; i++)
        {
            var player = players[i];
            json.Append("{");
            json.AppendFormat("\"alias\":\"{0}\",", EscapeJsonString(player.alias));
            json.AppendFormat("\"team\":\"{0}\",", EscapeJsonString(player.team));
            json.AppendFormat("\"teamType\":\"{0}\",", EscapeJsonString(player.teamType));
            json.AppendFormat("\"class\":\"{0}\",", EscapeJsonString(player.className));
            json.AppendFormat("\"isOffense\":{0},", player.isOffense.ToString().ToLower());
            
            if (string.IsNullOrEmpty(player.weapon))
            {
                json.Append("\"weapon\":null");
            }
            else
            {
                json.AppendFormat("\"weapon\":\"{0}\"", EscapeJsonString(player.weapon));
            }
            
            json.Append("}");
            
            if (i < players.Count - 1)
            {
                json.Append(",");
            }
        }
        
        json.Append("]");
        json.Append("}");
        
        return json.ToString();
    }
    
    private static string EscapeJsonString(string input)
    {
        if (string.IsNullOrEmpty(input))
            return "";
            
        return input.Replace("\\", "\\\\")
                   .Replace("\"", "\\\"")
                   .Replace("\n", "\\n")
                   .Replace("\r", "\\r")
                   .Replace("\t", "\\t");
    }
}

// Simple test program to send sample game data to your website
// Run this to test the integration before implementing with real game data

public class TestGameData
{
    private static readonly HttpClient httpClient = new HttpClient();
    //private const string API_ENDPOINT = "http://localhost:3000/api/game-data";
    private const string API_ENDPOINT = "https://freeinf.org/api/game-data";
    
    public static async Task Main(string[] args)
    {
        Console.WriteLine("Sending test game data to website...");
        
        // Create sample game data similar to what your actual game would send
        var testGameData = new
        {
            arenaName = "OvD Arena",
            gameType = "OvD",
            baseUsed = "Test Base Alpha",
            players = new[]
            {
                // Offense Team (Titan)
                new { alias = "Herthbul", team = "Titan", @class = "Squad Leader", isOffense = true, weapon = (string)null },
                new { alias = "Dinobot", team = "Titan", @class = "Heavy Weapons", isOffense = true, weapon = (string)null },
                new { alias = "jay", team = "Titan", @class = "Infantry", isOffense = true, weapon = (string)null },
                new { alias = "iron", team = "Titan", @class = "Infantry", isOffense = true, weapon = (string)null },
                new { alias = "Angelus", team = "Titan", @class = "Infantry", isOffense = true, weapon = (string)null },
                
                // Defense Team (Collective)
                new { alias = "Dilatory", team = "Collective", @class = "Field Medic", isOffense = false, weapon = (string)null },
                new { alias = "albert", team = "Collective", @class = "Combat Engineer", isOffense = false, weapon = (string)null },
                new { alias = "Axidus", team = "Collective", @class = "Heavy Weapons", isOffense = false, weapon = (string)null },
                new { alias = "Greed", team = "Collective", @class = "Infantry", isOffense = false, weapon = "CAW" },
                new { alias = "Silly Wanker", team = "Collective", @class = "Infantry", isOffense = false, weapon = "SG" }
            }
        };
        
        try
        {
            // Convert to JSON using our manual JSON builder
            string jsonData = BuildJsonString(testGameData);
            Console.WriteLine("Sending data:");
            Console.WriteLine(jsonData);
            
            // Send to API
            var content = new StringContent(jsonData, System.Text.Encoding.UTF8, "application/json");
            var response = await httpClient.PostAsync(API_ENDPOINT, content);
            
            if (response.IsSuccessStatusCode)
            {
                string responseContent = await response.Content.ReadAsStringAsync();
                Console.WriteLine(String.Format("✅ Success! Server response: {0}", responseContent));
                Console.WriteLine("Check your website at http://localhost:3000 to see the updated player list!");
            }
            else
            {
                string errorContent = await response.Content.ReadAsStringAsync();
                Console.WriteLine(String.Format("❌ Failed to send data. Status: {0}", response.StatusCode));
                Console.WriteLine(String.Format("Error: {0}", errorContent));
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine(String.Format("❌ Exception occurred: {0}", ex.Message));
        }
        
        Console.WriteLine("\nPress any key to exit...");
        Console.ReadKey();
    }

    private static string BuildJsonString(object testGameData)
    {
        var json = new System.Text.StringBuilder();
        json.Append("{");
        json.AppendFormat("\"arenaName\":\"{0}\",", ((TestGameDataObject)testGameData).arenaName);
        json.AppendFormat("\"gameType\":\"{0}\",", ((TestGameDataObject)testGameData).gameType);
        json.AppendFormat("\"baseUsed\":\"{0}\",", ((TestGameDataObject)testGameData).baseUsed);
        json.Append("\"players\":[");

        var players = ((TestGameDataObject)testGameData).players;
        for (int i = 0; i < players.Length; i++)
        {
            var player = players[i];
            json.Append("{");
            json.AppendFormat("\"alias\":\"{0}\",", player.alias);
            json.AppendFormat("\"team\":\"{0}\",", player.team);
            json.AppendFormat("\"class\":\"{0}\",", player.@class);
            json.AppendFormat("\"isOffense\":{0},", player.isOffense.ToString().ToLower());
            
            if (player.weapon == null)
            {
                json.Append("\"weapon\":null");
            }
            else
            {
                json.AppendFormat("\"weapon\":\"{0}\"", player.weapon);
            }
            
            json.Append("}");
            
            if (i < players.Length - 1)
            {
                json.Append(",");
            }
        }
        
        json.Append("]");
        json.Append("}");
        
        return json.ToString();
    }
}

