        /// <summary>The flag victory countdown: the team that holds every flag and the milliseconds left before it wins (false = no countdown running).</summary>
        internal bool MiniVictoryClock(out Team holder, out int msLeft)
        {
            holder = null; msLeft = 0;
            if (winningTeam == null || winningTeamTick <= 0) return false;
            holder = winningTeam;
            msLeft = Math.Max(0, unchecked(winningTeamTick - Environment.TickCount));
            return true;
        }

        /// <summary>A MiniTP bot took a flag (the script-side state change a player's pickup makes): run the script's own flag rule, which aborts a running victory countdown.</summary>
        internal void MiniFlagChanged(Arena.FlagState fs)
        {
            try { OnFlagChange(fs); } catch (Exception ex) { Console.WriteLine("[MiniTP] flag change: " + ex.Message); }
        }

        /// <summary>A MiniTP engineer rebuilds one of its base's turrets (the event builds them once, BuildMiniTPTurrets; nothing replaced a destroyed one): the same vehicle, spot and team the event used.</summary>
        internal bool MiniBuildTurret(string kind, int tx, int ty, int side)
        {
            try
            {
                if (currentEventType != EventType.MiniTP) return false;
                string teamName = side == 0 ? "Titan Militia" : "Collective";
                Team team = null;
                foreach (Team tm in arena.Teams) if (tm._name == teamName) { team = tm; break; }
                if (team == null) return false;
                return BuildServerTurretAtLocation(kind, (short)(tx * 16), (short)(ty * 16), team);
            }
            catch (Exception ex) { Console.WriteLine("[MiniTP] turret rebuild: " + ex.Message); return false; }
        }

        /// <summary>
        /// MiniTP green portals (Travis 11-07: the bots never set them up). A green portal is a Hide spawner of the level's LIO ("WP tp A7a" ...) that fires only
        /// when a REAL player stands within its MaxPlayerDistance (getPlayersInRange: bots are not players), so a bot standing on the spot builds nothing. This does
        /// what the hide does - the same vehicle, team, spot and announcement - once a bot has stood there. False when one already stands in the hide's box.
        /// </summary>
        internal bool MiniTPBuildGreenPortal(int hideId)
        {
            if (currentEventType != EventType.MiniTP) return false;
            return GreenPortalBuild(hideId);
        }

        /// <summary>
        /// Travis 11-11: "the enemy portals only activate if it's on the opposing team, the hide does any player". The four green-portal hides (WP tp A7a/A7b/D7a/D7b) fired for a
        /// player of EITHER team (the engine's hideVehicle only asks getPlayersInRange), so a defender could build the enemy's portal in his own base and farm it. The engine's own
        /// attempts are switched off for those four (their Probability is 0 while this script runs: hideSpawn skips a 0-probability hide) and this poll does the trigger instead: a
        /// LIVING player of the hide's AssignFrequency team (the team the portal is built for) inside its MaxPlayerDistance of the spot, while a game runs, then the same build the
        /// bots use (GreenPortalBuild: player-count window, one portal per spot, MaxTypeInlevel, MinPlayerDistance, the hide's vehicle, team, relative id and announcement).
        /// </summary>
        static readonly int[] GreenHideIds = { 501, 513, 514, 515 };
        int _greenHideAt;
        internal int GreenHideBuilds;

        private void GreenHideStep(int now)
        {
            if (now - _greenHideAt < 0) return;
            _greenHideAt = now + 400;
            try
            {
                if (arena == null || arena._hides == null) return;
                foreach (var hs in arena._hides)
                {
                    if (Array.IndexOf(GreenHideIds, hs.Hide.GeneralData.Id) < 0) continue;
                    if (hs.Hide.HideData.Probability != 0) hs.Hide.HideData.Probability = 0;       // the engine never fires it again (asset data: the same for every arena of the zone)
                    if (!arena._bGameRunning) continue;
                    Team team = arena.getTeamByID(hs.Hide.HideData.AssignFrequency);
                    if (team == null) continue;
                    int lx = arena._server._assets.Level.OffsetX * 16, ly = arena._server._assets.Level.OffsetY * 16;
                    short cx = (short)(hs.Hide.GeneralData.OffsetX - lx), cy = (short)(hs.Hide.GeneralData.OffsetY - ly);
                    int r = hs.Hide.HideData.MaxPlayerDistance > 0 && hs.Hide.HideData.MaxPlayerDistance < 99999 ? hs.Hide.HideData.MaxPlayerDistance : 30;
                    bool ours = false;
                    foreach (Player p in arena.getPlayersInRange(cx, cy, r, true))
                        if (p != null && p._team == team && !p.IsSpectator) { ours = true; break; }
                    if (ours && GreenPortalBuild(hs.Hide.GeneralData.Id)) GreenHideBuilds++;
                }
            }
            catch (Exception ex) { Console.WriteLine("green hide step: " + ex.Message); }
        }

        /// <summary>
        /// Travis 11-11: "turrets killing players don't report kills in the kill feed in MiniTP, a long standing bug". ROOT CAUSE (live engine d59680df, decompiled): ScriptArena routes a
        /// computer kill ONLY from Logic_Rewards.calculateTurretKillRewards, which returns at once when the turret has no _creator. Player-built turrets have one (normal TP), but the
        /// MiniTP base turrets (BuildServerTurretAtLocation), green portals and every script-built computer are made with no owner, so the kill packet was never sent. Player.Death
        /// runs just before that branch with the same packet: an ownerless computer's kill is routed here, the plain way the engine routes any other death.
        /// </summary>
        private void RouteOwnerlessComputerKill(Player victim, Helpers.KillType killType, CS_VehicleDeath update)
        {
            try
            {
                if (victim == null || update == null || killType != Helpers.KillType.Computer) return;
                Computer comp = null;
                foreach (Vehicle v in arena.Vehicles)
                    if (v != null && v._id == update.killerPlayerID) { comp = v as Computer; break; }
                if (comp == null || comp._creator != null) return;        // an owned turret: the engine routes it with the owner's reward
                Helpers.Player_RouteKill(arena.Players, update, victim, 0, 0, 0, 0);
            }
            catch (Exception ex) { Console.WriteLine("turret kill feed: " + ex.Message); }
        }

        private bool GreenPortalBuild(int hideId)
        {
            try
            {
                foreach (var hs in arena._hides)
                {
                    if (hs.Hide.GeneralData.Id != hideId) continue;
                    VehInfo type = AssetManager.Manager.getVehicleByID(-hs.Hide.HideData.HideId);
                    if (type == null) return false;
                    int lx = arena._server._assets.Level.OffsetX * 16, ly = arena._server._assets.Level.OffsetY * 16;
                    short cx = (short)(hs.Hide.GeneralData.OffsetX - lx), cy = (short)(hs.Hide.GeneralData.OffsetY - ly);
                    int w2 = hs.Hide.GeneralData.Width / 2 + 8, h2 = hs.Hide.GeneralData.Height / 2 + 8;
                    // the hide's own conditions (ArenaLio.hideSpawn / hideVehicle), as far as a bot can meet them: the player-count window, the cap of this vehicle in the level,
                    // and no real player standing inside the hide's MinPlayerDistance (the bot itself stands on the spot, which is what the MaxPlayerDistance asks of a real player)
                    int pc = arena.PlayerCount;
                    if (pc > hs.Hide.HideData.MaxPlayers || pc < hs.Hide.HideData.MinPlayers) return false;
                    int sameType = 0;
                    foreach (Vehicle v in arena.Vehicles)
                    {
                        if (v == null || v._type != type || v.IsDead) continue;       // a destroyed portal does not count as one standing there
                        sameType++;
                        if (Math.Abs(v._state.positionX - cx) <= w2 && Math.Abs(v._state.positionY - cy) <= h2)
                            return false;
                    }
                    if (hs.Hide.HideData.MaxTypeInlevel != -1 && sameType >= hs.Hide.HideData.MaxTypeInlevel) return false;
                    if (hs.Hide.HideData.MinPlayerDistance != 0 && arena.getPlayersInRange(cx, cy, hs.Hide.HideData.MinPlayerDistance, true).Count > 0) return false;
                    Team team = arena.getTeamByID(hs.Hide.HideData.AssignFrequency);
                    short pX = cx, pY = cy;
                    for (int tries = 0; tries < 10; tries++)
                    {
                        pX = cx; pY = cy;
                        Helpers.randomPositionInArea(arena, ref pX, ref pY, (short)hs.Hide.GeneralData.Width, (short)hs.Hide.GeneralData.Height);
                        if (!arena.getTile(pX, pY).Blocked) break;
                    }
                    Helpers.ObjectState st = new Helpers.ObjectState();
                    st.positionX = pX; st.positionY = pY;
                    Vehicle spawn = arena.newVehicle(type, team, null, st);
                    if (spawn == null) return false;
                    if (hs.Hide.HideData.RelativeId != 0) spawn.relativeID = hs.Hide.HideData.RelativeId;
                    if (hs.Hide.HideData.HideAnnounce != null && hs.Hide.HideData.HideAnnounce.Length > 0)
                        arena.sendArenaMessage(hs.Hide.HideData.HideAnnounce);
                    return true;
                }
            }
            catch (Exception ex) { Console.WriteLine("MiniTP green portal: " + ex.Message); }
            return false;
        }

        /// <summary>
        /// The enemy (green) portal a team may warp to - ONE rule for players (the warp-group-200 portal) and bots (CTFXMini): a Computer that a hide spawned (RelativeId 292), ALIVE (a
        /// destroyed portal is never a target, Travis 11-08: "bots are warping to destroyed green portals"), standing in the team's own enemy base (Collective builds at D7, Titan at A7),
        /// the one NEARER THE FLAGS first (veh 436 "green2": A7b / D7b), else the farther one (veh 413: A7a / D7a). Null = none is up.
        /// </summary>
        internal Vehicle MiniTPEnemyPortal(bool collectiveTeam)
        {
            Vehicle best = null;
            foreach (Vehicle v in arena.Vehicles)
            {
                if (v == null || v._type == null || v._type.Type != VehInfo.Types.Computer || v.relativeID != 292 || v.IsDead) continue;
                int vx = v._state.positionX, vy = v._state.positionY;
                bool mine = collectiveTeam ? (vx >= 1090 * 16 && vx <= 1140 * 16 && vy >= 570 * 16 && vy <= 620 * 16)
                                           : (vx >= 991 * 16 && vx <= 1015 * 16 && vy >= 630 * 16 && vy <= 669 * 16);
                if (!mine) continue;
                if (best == null || (v._type.Id == 436 && best._type.Id != 436)) best = v;
            }
            return best;
        }

        /// <summary>
        /// CTF:X / MiniTP server-side bots (optional add-on, looked up by name so this file compiles without it). Pub only: the
        /// manager is one per zone and takes the first arena that attaches. At init it attaches; when the arena's event changes it
        /// re-evaluates which profile (CTF:X, or MiniTP when MiniTP/MiniTPBots.txt is enabled) should run and keeps the running one
        /// when that is the same, so a CTF:X-only zone is not disturbed by event changes.
        /// </summary>
        private void CtfxAttachBots(bool eventChange)
        {
            if (!CtfxPubArena) return;
            try
            {
                Type ctfxType = typeof(Script_CTF).Assembly.GetType("InfServer.Script.GameType_CTF.CTFXBotManager");
                if (ctfxType == null)
                    ctfxType = Type.GetType("InfServer.Script.GameType_CTF.CTFXBotManager");
                if (ctfxType == null)
                    foreach (System.Reflection.Assembly ctfxAsm in AppDomain.CurrentDomain.GetAssemblies())
                    {
                        ctfxType = ctfxAsm.GetType("InfServer.Script.GameType_CTF.CTFXBotManager");
                        if (ctfxType != null)
                            break;
                    }
                if (ctfxType == null) return;
                System.Reflection.MethodInfo m = eventChange ? ctfxType.GetMethod("EventChanged") : ctfxType.GetMethod("Attach");
                if (m != null)
                    m.Invoke(null, new object[] { this, arena });
            }
            catch (Exception ex) { Console.WriteLine("CTF:X bots attach failed: " + ex.Message); }
        }

