        // League match arenas (Travis 10-26): freeinf.org's match automation names them "<LEAGUE> <AWAY>-<HOME>" (CTFDL, CTFPL, OVDL); hand-made ones
        // carry the tag too. Champion items and every item skin are off there from the moment the arena opens.
        private static readonly string[] LeagueArenaTags = { "CTFDL", "CTFPL", "OVDL" };
        private static bool IsLeagueArena(string name) { return name != null && LeagueArenaTags.Any(t => name.IndexOf(t, StringComparison.OrdinalIgnoreCase) >= 0); }
        // Item skins in this arena (Travis 10-26): *skins on|off (refs). Off = everybody holds the stock items (catalogue skins and Rainbow CAW alike).
        private bool skinsEnabled = true;

        private int secondOvertimeTimer;
        private Dictionary<Player, bool> disallowClassChange = new Dictionary<Player, bool>();
        private Dictionary<Player, string> queuedClassSwap = new Dictionary<Player, string>();
        private bool _playerStatsEnabled = true;
        // ?auto family. All keyed by ALIAS on purpose: persistentBuilds is, so a player who leaves
        // and rejoins keeps autobuy with their build instead of losing one and not the other - and a
        // string key cannot pin a Player object graph the way the old Player-keyed tables did.
        private Dictionary<string, bool> autoBuyEnabled = new Dictionary<string, bool>(StringComparer.OrdinalIgnoreCase);
        // Auto-drop is ON by default (the whole point is removing drop macros); ?ad opts out.
        // ?ad, when typed: true/false. Absent = follow the default (on with a preset build or premade,
        // off with a custom list or nothing bought) - see AutoDropEnabledFor.
        private Dictionary<string, bool> autoDropOverride = new Dictionary<string, bool>(StringComparer.OrdinalIgnoreCase);
        // Aliases that typed ?ap OFF - a preset buy must not switch autopickup back on for them.
        private HashSet<string> autoPickupOff = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        // ?autopickup: alias -> item name -> keep-topped-up-to quantity. Present == enabled.
        private Dictionary<string, Dictionary<string, int>> autoPickupItems = new Dictionary<string, Dictionary<string, int>>(StringComparer.OrdinalIgnoreCase);
        // The class each autopickup list was set as: a class change clears it (AutoPickupClassChanged).
        private Dictionary<string, string> autoPickupClass = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        // Aliases whose ?ap list was typed by hand - a new loadout must not overwrite it.
        private HashSet<string> autoPickupCustom = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        // Of those, the lists taken from what they carried (?ap alone with no build, Travis 10-26: ?buy macros): their own, but a deliberate
        // drop still lowers them, so an over-buy-and-drop macro never hoovers its team drop back up.
        private HashSet<string> autoPickupCarry = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        // What the player DELIBERATELY dropped (?drop, ?bwd, the drop key) since their last loadout
        // change, item -> quantity. A legacy buy macro over-buys on purpose so the paired drop
        // macro can leave tranq / sentry / pistol ammo for the team (Travis, 2026-09-13); autopickup
        // must not hoover those straight back up. Alias-keyed, cleared on the next buy and on leave.
