        private Dictionary<string, bool> jumpTrooperDeathboardPreference = new Dictionary<string, bool>();
        
        
        // Auto-occupy pending operations tracking (using string keys to avoid memory leaks)
        private Dictionary<string, int> pendingAutoOccupy = new Dictionary<string, int>();
        private Dictionary<string, int> autoOccupyRetryCount = new Dictionary<string, int>();
        // ?v (Travis 2026-10-24): whether THIS death respawns them on their vehicle - set when they die from OccupyTriggers, flipped
        // by ?v while dead, used once at the respawn. A queued occupy remembers its trigger and whether it needs the pack item (every
        // trigger but game start: the vehicle the item would make anyway, just without the key); a warp item used by them, or a
        // summon from a teammate, drops it (playerWarpItem) so a frantic warp on respawn is never answered with a pack. The last
        // vehicle auto-occupy made per player is kept by id (never a Vehicle across ticks) so a new one replaces it.
        private Dictionary<string, bool> occupyThisLife = new Dictionary<string, bool>();
        private Dictionary<string, OccupyWhen> pendingOccupyWhen = new Dictionary<string, OccupyWhen>();
        private HashSet<string> pendingOccupyNeedsPack = new HashSet<string>();
        private Dictionary<string, ushort> autoOccupyVehicle = new Dictionary<string, ushort>();
        private Dictionary<string, int> occupyHintAt = new Dictionary<string, int>();
        private const int OCCUPY_RESPAWN_DELAY = 800;    // ms after the respawn: the spawn warp and the autobuy top-up land first
        private const int OCCUPY_HINT_EVERY = 600000;    // the "?v: respawn on your pack" reminder, at most every 10 minutes
        // Auto-occupy waits for the pack's own prefire, like pressing its key (Travis 10-25): itm prefireDelay x 10 ms = 5 s for every pack
        // and board. Then the vehicle is made and entered in one go: no human reaction time and no extra delay, so it is never faster than
        // a perfect manual use, and never slower.
        private const int OCCUPY_PREFIRE_FALLBACK_MS = 5000;
        private Dictionary<string, int> occupyFxAt = new Dictionary<string, int>();     // when the prefire effect and sound start
        // ?v without ?ao (Travis 10-29): sent alive when it cannot ride now (no pack on them, or a game start is coming), it is armed for the next
        // respawn or game start, whichever comes first. A ?v respawn buys the pack when they carry none ("single use if it can": FPack / HBoard; a
        // JT's Drop Pack or Deathboard) and still waits the pack's prefire. A ?v game start needs the pack on them: 1 s, no buy, a warning without.
        private HashSet<string> occupyArmed = new HashSet<string>();
        private HashSet<string> occupyBuyAtRespawn = new HashSet<string>();   // this death's ?v respawn buys the pack if they carry none
        private HashSet<string> pendingOccupyBuys = new HashSet<string>();    // a queued occupy that buys the pack when it fires
