        /// <summary>
        /// Champion items are item skins since 10-27 (Travis: off by default like every skin, the player turns them on): each group joins the
        /// CTFSkins.cs catalogue as a champion set, so ?skin lists them, ?skin / ?champ switch them (saved) and the 1 Hz sweep swaps them.
        /// The option key players see per group is ChampKey. anjro's own SiG goes in first so it wins his OVDL1 SiG.
        /// </summary>
        private static void AddChampionSkins()
        {
            Skins.AddChampionGroup("OVDL1 (anjro)", "ovdl1", new[] { "anjro" }, new Dictionary<string, int> { { "SiG Arms m2 AS", 3073 } });
            foreach (var champGroup in champGroups)
                Skins.AddChampionGroup(champGroup.Item1, ChampKey(champGroup.Item1), champGroup.Item2, champGroup.Item3);
            // extra looks of a champion item (10-27): the Rainbow CAW's Stream / Prism remakes, the Care Bearmer's Braid remake
            Skins.AddChampionLooks("OVDL1 Rainbow CAW looks", ovdl1Champs, new[] { "Kuchler A6 CAW" }, "stream", "Rainbow Caw Stream", "prism", "Rainbow Caw Prism");
            Skins.AddChampionLooks("Season 1 Care Bearmer looks", s1Champs, s1Conversions.Where(kv => kv.Value == CARE_BEARMER).Select(kv => kv.Key).ToArray(),
                "carebearmer", "CareBearmer");   // the remade Care Bearmer (Travis 10-27: s1 = the classic Care Bearmer, carebearmer = the remake)
        }

        private static string ChampKey(string group)
        {
            switch (group)
            {
                case "Season 1": case "Chuckie's": return "s1";
                case "Season 2": return "s2";
                case "Season 3": return "s3";
                case "OVDL1": return "ovdl1";
                case "CTFDL4": return "dl4";
                default: return group.ToLower().Replace(" ", "");
            }
        }

