        private static Dictionary<int, string> _champStock;   // champion item id -> the stock item it is converted from (every group, + anjro's SiG)
        private static Dictionary<int, string> ChampStock()
        {
            if (_champStock != null)
                return _champStock;
            var m = new Dictionary<int, string>();
            foreach (var champGroup in champGroups)
                foreach (var kv in champGroup.Item3)
                    if (!m.ContainsKey(kv.Value))
                        m[kv.Value] = kv.Key;
            m[3073] = "SiG Arms m2 AS";   // anjro's own SiG (his "OVDL1 (anjro)" skin set: AddChampionSkins)
            m[3060] = "DropPack Blaster";   // the ChUcKdaPaCk's gun, should one ever sit in an inventory
            m[1312] = "Needler";   // the retired Needler (SubZero): builds and champion-off treat it as the Needler
            m[CARE_BEARMER_BRAID] = "Medic Beamer";   // back to the class's own beamer (BeamerFor), like the Care Bearmer
            return _champStock = m;
        }

        /// <summary>the stock item a build buys for a champion item (champion items are not for sale; ?champ turns the stock item back into
        /// it), null for anything else</summary>
        private static ItemInfo ChampBuildStock(Player p, ItemInfo item)
        {
            string stock;
            if (item == null || !ChampStock().TryGetValue(item.id, out stock))
                return null;
            return AssetManager.Manager.getItemByName(IsCareBearmer(item.id) ? BeamerFor(p) : stock);
        }

        /// <summary>the class beamer a Care Bearmer goes back to: the one the player's class can use (the Medic Beamer if none can)</summary>
        private static string BeamerFor(Player p)
        {
            foreach (var kv in s1Conversions.Where(kv => kv.Value == CARE_BEARMER))
            {
                ItemInfo beamer = AssetManager.Manager.getItemByName(kv.Key);
                if (beamer != null && Logic_Assets.SkillCheck(p, beamer.skillLogic))
                    return kv.Key;
            }
            return "Medic Beamer";
        }

        /// <summary>The player's champion items become their stock items (the stock item is added first; whatever does not fit is lost
        /// rather than kept as a champion item). Tells the player what changed. True when something was swapped.</summary>
        private bool RevertChampItems(Player p)
        {
            if (p == null || p._inventory == null)
                return false;
            var back = new List<string>();
            foreach (var kv in ChampStock())
            {
                int n = p.getInventoryAmount(kv.Key);
                if (n <= 0 || Skins.KeepsWithoutChampion(p, kv.Key, skinsEnabled))
                    continue;   // ...but a skin they own outside the champion groups stays (a Rainbow CAW perk owner's Rainbow Caw)
                ItemInfo champ = AssetManager.Manager.getItemByID(kv.Key), stock = AssetManager.Manager.getItemByName(IsCareBearmer(kv.Key) ? BeamerFor(p) : kv.Value);
                if (champ == null)
                    continue;
                int given = 0;
                if (stock != null)
                    for (int k = n; k > 0 && given == 0; k--)
                        if (p.inventoryModify(false, stock, k))
                            given = k;
                p.inventoryModify(false, champ, -n);
                back.Add(champ.name + " -> " + (stock != null && given > 0 ? stock.name : "(no room)"));
            }
            if (back.Count == 0)
                return false;
            p.syncInventory();
            p.sendMessage(0, "*Champion items are off here, back to standard: " + string.Join(", ", back));
            return true;
        }

        private void LaunchFireworks(Player player)
        {
            // Duration of the fireworks display in milliseconds
            int displayDuration = 5000;
            // Interval between each firework launch in milliseconds
            int fireworkInterval = 200;

            // Firework item IDs
            short smallFireworkID = 3041;
            short largeFireworkID = 3040;

            // Random number generator
            Random random = new Random();
            DateTime endTime = DateTime.Now.AddMilliseconds(displayDuration);

            // Declare timer variable first
            System.Threading.Timer fireworkTimer = null;

            // Create timer callback
            fireworkTimer = new System.Threading.Timer((e) =>
            {
                // Check if display time is over
                if (DateTime.Now >= endTime)
                {
                    // Stop the timer
                    fireworkTimer.Dispose();
                    return;
                }

                // Determine if we should launch a small or large firework
                bool launchSmallFirework = random.NextDouble() < 0.7; // 70% chance for small firework

                // Choose the firework item ID based on the random chance
                short fireworkID = launchSmallFirework ? smallFireworkID : largeFireworkID;

                // Generate random positions within a specified radius around the player
                short radius = 100; // Radius around the player
                short angle = (short)(random.Next(360) * 256 / 360); // Random angle in degrees
                short distance = (short)(random.Next(radius + 1)); // Random distance within the radius
                short playerX = player._state.positionX;
                short playerY = player._state.positionY;
                short playerZ = player._state.positionZ;

                // Calculate new position based on angle and distance
                short newX = (short)(playerX + (short)(distance * Math.Cos(angle * Math.PI / 128)));
                short newY = (short)(playerY + (short)(distance * Math.Sin(angle * Math.PI / 128)));
                short newZ = playerZ; // Keep Z position the same

                byte yaw = 0; // Direction, set to 0 if not needed
                ushort creator = 0; // No specific creator, set to 0 or assign as appropriate

                // Send the projectile explosion effect to all players
                Helpers.Player_RouteExplosion(arena.Players, fireworkID, newX, newY, newZ, yaw, creator);

            }, null, 0, fireworkInterval); // Start immediately, repeat every fireworkInterval milliseconds
        }

        private void UpdateTurretOwnership(string flagName, Team newOwner)
        {
            var fs = arena.getFlag(flagName);
            if (fs == null || newOwner == null) return;

            // Identify turrets near the flag location and update ownership
            var turrets = arena.Vehicles.Where(v => v is Computer && 
                                                    Math.Abs(v._state.positionX - fs.posX) < 200 &&
                                                    Math.Abs(v._state.positionY - fs.posY) < 200);

            foreach (var turret in turrets)
            {
                turret._team = newOwner;
                Helpers.Vehicle_ResetState(turret._creator, false, false, false); // Assuming _creator is the player that owns the turret
            }
        }

