            public static readonly Dictionary<string, string> skillAliases = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
            {
                { "inf", "Infantry" },
                { "infil", "Infiltrator" },
                { "hvy", "Heavy Weapons" },
                { "eng", "Combat Engineer" },
                { "med", "Field Medic" },
                { "jt", "Jump Trooper" },
