        /// <summary>
        /// Performs script initialization
        /// </summary>
        public bool init(IEventObject invoker)
        {
            arena = invoker as Arena;
            CFG = arena._server._zoneConfig;
            AddChampionSkins();   // once per zone run (CTFSkins.cs ignores a group it already has)
            if (IsLeagueArena(arena._name))
            {   // a league match: champion items and item skins off from the start (refs can still use *skins / *champItems)
                isChampEnabled = false;
                skinsEnabled = false;
            }

            // Every other gametype (USL, TDM, Hockey, etc.) sets this so the core mod commands
            // *timer/%gametimer (InfServer/Game/Commands/Mod/Basic.cs `timer`, Chat/Communication.cs
            // `gameTimer`) know which ticker slot is "the" game clock - they read/write
            // arena.playtimeTickerIdx, which defaults to 0 and CTF never set. ApplyOvdGameTimer
            // places the OvD match clock on ticker index 1 (see its own comment for why NOT index
            // 3), so without this a host's *timer command was silently writing to an unused ticker
            // slot instead of the running match clock - it looked like it did nothing.
            arena.playtimeTickerIdx = 1;

            _flags = new List<Arena.FlagState>();
            minPlayers = 2;
            victoryHoldTime = CFG.flag.victoryHoldTime;
            preGamePeriod = CFG.flag.startDelay;

            killStreaks = new Dictionary<string, PlayerStreak>();
            explosives = new Dictionary<string, int>();

            // Resolve the premade kits now rather than lazily, so a mistyped item name is reported in
            // the zone log at startup instead of silently shorting somebody's loadout mid-game.
            PremadeKits();

            bases = new Dictionary<string, Base>();

            for (int i = 0; i < explosiveList.Length; i++)
            {
                explosives.Add(explosiveList[i], explosiveAliveTimes[i]);
            }

            foreach (Arena.FlagState fs in arena._flags.Values)
            {	//Determine the minimum number of players
                if (fs.flag.FlagData.MinPlayerCount < minPlayers)
                { minPlayers = fs.flag.FlagData.MinPlayerCount; }

                //Register our flag change events
                fs.TeamChange += OnFlagChange;
            }

            //Public flags carry MinPlayerCount 0, which used to leave minPlayers at 0.
            //A "0 player" threshold is never unmet, so the arena would start a game with
            //nobody in it, bail out of StartGame, and immediately try again.
            if (minPlayers < 1)
            { minPlayers = 1; }

            gameState = GameState.Init;

            bases["A7"] = new Base(19, 463, 32, 473);
