        /// <summary>
        /// Configures the arena for a 5v5 / OvD game on one base: moves the Bridge3 flag there and
        /// assigns it to the owning side, parks the other flags out of the way, spawns the base
        /// resources and runs the fixed drops. Extracted from the *setup mod command so the OvD
        /// flow can run exactly the setup a host would otherwise have typed by hand.
        ///
        /// Base ownership is fixed by the map: D7/F6/F5 are Titan bases, A7/A5/B6/H4/B8 are
        /// Collective. Whichever side owns the chosen base is the side that DEFENDS it.
        /// </summary>
        /// <param name="baseName">Base name, e.g. "D7". Case insensitive.</param>
        /// <param name="notify">Who to send the "not recognized" list to, or null for silence.</param>
        /// <returns>True if the base was recognised and the arena was set up.</returns>
        public bool SetupBase(string baseName, Player notify, bool announce = true)
        {
            // NOTE: the extracted body declares its own local `baseKey`, so the parameter must not
            // share that name.
            string payload = (baseName ?? "").Trim();
            Player player = notify;   // the extracted body reports through this


                if (!bases.ContainsKey(payload.ToUpper()))
                {
                    player.sendMessage(-1, "That base is not recognized, Options are: ");
                    foreach (string key in bases.Keys)
                        player.sendMessage(0, key);

                    return true;
                }

                isSD = false;
                isSecondOvertime = false;
                overtimeStart = 0;
                secondOvertimeStart = 0;
                is5v5 = true;
                Base defense = bases[payload.ToUpper()];

                // arena.itemSpawn(arena._server._assets.getItemByName("Fuel Canister"), 600, defense.x, defense.y, 0, null);
                // arena.itemSpawn(arena._server._assets.getItemByName("Ammo MG"), 1250, defense.x, defense.y, 0, null);
                // arena.itemSpawn(arena._server._assets.getItemByName("Light HE"), 250, defense.x, defense.y, 0, null);
                // arena.itemSpawn(arena._server._assets.getItemByName("Heavy HE"), 100, defense.x, defense.y, 0, null);
                // arena.itemSpawn(arena._server._assets.getItemByName("Ammo Pistol"), 2500, defense.x, defense.y, 0, null);

                // arena.itemSpawn(arena._server._assets.getItemByName("AP Mine"), 25, defense.x, defense.y, 0, null);
                // arena.itemSpawn(arena._server._assets.getItemByName("Plasma Mine"), 25, defense.x, defense.y, 0, null);
                // arena.itemSpawn(arena._server._assets.getItemByName("Bullet Mine"), 100, defense.x, defense.y, 0, null);

                // arena.itemSpawn(arena._server._assets.getItemByName("rocket"), 200, defense.x, defense.y, 0, null);
                // arena.itemSpawn(arena._server._assets.getItemByName("tranq"), 50, defense.x, defense.y, 0, null);

                // arena.itemSpawn(arena._server._assets.getItemByName("sentry"), 5, defense.x, defense.y, 0, null);

                // Minerals are placed AFTER the defending team is resolved below - see SpawnBaseMinerals.


                

                //arena.itemSpawn(arena._server._assets.getItemByID(23), 2, defense.x, defense.y, 100, null);

                //arena.itemSpawn(arena._server._assets.getItemByID(10), 2, defense.x, defense.y, 100, null);
                //arena.itemSpawn(arena._server._assets.getItemByID(11), 1, defense.x, defense.y, 100, null);
                //arena.itemSpawn(arena._server._assets.getItemByID(9), 1, defense.x, defense.y, 100, null);
                Arena.FlagState flag = arena.getFlag("Bridge3");

                flag.posX = defense.flagX;
                flag.posY = defense.flagY;
                flag.oldPosX = defense.flagX;
                flag.oldPosY = defense.flagY;

                // Set flag ownership based on base location. The side rule is shared with the mix
                // manager (IsTitanSideTeam): it used to be Contains(" T") / Contains(" C"), which
                // never matched the pub teams "Titan Militia" / "Collective" - so a hand-run *setup
                // in pub left the base flag NEUTRAL and the minerals had no team to go to.
                string baseKey = payload.ToUpper();
                bool? titanOwned = CTFMatchRules.BaseIsTitanOwned(baseKey);
                if (titanOwned == true)
                {
                    flag.team = arena.Teams.FirstOrDefault(t => IsTitanSideTeam(t) && t.ActivePlayerCount > 0);
                }
                else if (titanOwned == false)
                {
                    flag.team = arena.Teams.FirstOrDefault(t => IsCollectiveSideTeam(t) && t.ActivePlayerCount > 0);
                }
                string mineralNote = SpawnBaseMinerals(defense, flag.team);

                // Park every non-base flag somewhere inaccessible AND make sure it is UNOWNED.
                //
                // Leaving them on the map is deliberate: it is what stops the normal CTF victory
                // condition from applying. OnFlagChange declares a winner when one team holds every
                // ACTIVE flag, so with these four sitting neutral and unreachable that can never be
                // true, and the OvD is decided by the offence breaking the base within the clock
                // instead of by a 90 second countdown.
                //
                // Clearing .team is the part that was missing. Parking them while they still
                // belonged to whoever held them in the previous game meant assigning the base flag
                // to that same side satisfied "all flags, one team" the instant setup ran.
                Arena.FlagState[] parked = new Arena.FlagState[]
                {
                    arena.getFlag("Bridge1"),
                    arena.getFlag("Hill201"),
                    arena.getFlag("Hill86"),
                    arena.getFlag("Bridge2"),
                };

                foreach (Arena.FlagState pf in parked)
                {
                    if (pf == null)
                        continue;
                    pf.posX = 50 * 16;
                    pf.posY = 30 * 16;
                    pf.team = null;      // neutral - this is what keeps the victory rule unsatisfiable
                    Helpers.Object_Flags(arena.Players, pf);
                }

                Helpers.Object_Flags(arena.Players, flag);
                //Store the base used in a global variable
                baseUsed = payload.ToUpper();
                ManageFixedDropLocations();
                WebIntegration.SendGameDataToWebsite(arena, baseUsed);
                if (announce)
                {
                    arena.sendArenaMessage(String.Format("&Minerals, flag, and drops spawned at {0}", payload.ToUpper()));
                    arena.sendArenaMessage("*" + mineralNote);
                }
                else if (flag.team != null)
                {
                    // The OvD manager prints the match lines; the mineral note only matters to the
                    // side that gets the minerals, so it goes to them and nobody else.
                    foreach (Player tp in flag.team.ActivePlayers.ToList())
                        tp.sendMessage(0, "*" + mineralNote);
                }
            return true;
        }

        #region ?phrase (Travis 10-25)
        // Who has the kill-phrase perk = who has a phrase from the site. They can change it here (1-12 characters, the site's own rule:
        // letters, numbers, spaces and ! ? . -; the font cannot draw _ yet, so it is refused); the change is kept as an override
        // (PhraseExplosionManager) that the site can read, and shown to them alone as a preview.
        private readonly Dictionary<string, int> phraseChangedAt = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
        private const int PHRASE_COOLDOWN_MS = 15000;
        // The preview (?phrase test, and the one after a change) sends letter packets to the caller alone; it is limited so it cannot be used
        // to spam them: one preview per player per 10 s (test and the after-change preview share the clock), only in the dropship
        // (terrain 4, the same test the shop and ?swap use), never as a spectator or while dead. Kills and *testphrase are not affected.
        private const int PHRASE_PREVIEW_COOLDOWN_MS = 10000;
        private readonly Dictionary<string, int> phrasePreviewAt = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);

        /// <summary>0 = shown, 1 = not here (spectator, dead or outside the dropship), 2 = too soon (secondsToWait set)</summary>
        private int TryPhrasePreview(Player player, string text, out int secondsToWait)
        {
            secondsToWait = 0;
            if (player.IsSpectator || player.IsDead || arena.getTerrainID(player._state.positionX, player._state.positionY) != 4)
                return 1;
            int last, now = Environment.TickCount;
            if (phrasePreviewAt.TryGetValue(player._alias, out last) && unchecked(now - last) >= 0 && unchecked(now - last) < PHRASE_PREVIEW_COOLDOWN_MS)
            {
                secondsToWait = Math.Max(1, (PHRASE_PREVIEW_COOLDOWN_MS - unchecked(now - last) + 999) / 1000);
                return 2;
            }
            phrasePreviewAt[player._alias] = now;
            ExplosionHelper.ShowPhraseTo(player, text, player._state.positionX, player._state.positionY, player._state.positionZ);
            return 0;
        }

        private void HandlePhraseCommand(Player player, string payload)
        {
            string site = PhraseExplosionManager.GetSitePhrase(player._alias);
            if (site == null)
            {
                player.sendMessage(-1, "Custom kill phrases come with the kill-phrase perk from the freeinf.org shop. Once you have it, ?phrase changes it here.");
                return;
            }
            string current = PhraseExplosionManager.GetCachedPhrase(player._alias);
            string text = (payload ?? "").Trim();
            while (text.Contains("  ")) text = text.Replace("  ", " ");
            if (text.Length == 0 || text.Equals("show", StringComparison.OrdinalIgnoreCase))
            {
                player.sendMessage(0, "&Your kill phrase: " + current);
                player.sendMessage(0, "*?phrase <text> changes it (1-12 characters: letters, numbers, spaces and ! ? . -).  ?phrase test shows it to you.  ?phrase reset goes back to the site's.");
                return;
            }
            if (text.Equals("test", StringComparison.OrdinalIgnoreCase))
            {
                int wait;
                int shown = TryPhrasePreview(player, current, out wait);
                if (shown == 1)
                    player.sendMessage(-1, "PHRASE TEST WORKS ONLY IN THE DROPSHIP");
                else if (shown == 2)
                    player.sendMessage(-1, String.Format("WAIT {0} S FOR THE NEXT PREVIEW", wait));
                return;
            }
            if (text.Equals("reset", StringComparison.OrdinalIgnoreCase))
            {
                PhraseExplosionManager.SetOverride(player._alias, null);
                Console.WriteLine("[phrase] " + player._alias + " reset to the site's phrase");
                player.sendMessage(0, "&Your kill phrase is back to the one on the site: " + site);
                return;
            }
            if (text.Length > 12)
            {
                player.sendMessage(-1, "Kill phrases are 1-12 characters (that was " + text.Length + ").");
                return;
            }
            foreach (char c in text)
            {
                bool ok = (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == ' ' || c == '!' || c == '?' || c == '.' || c == '-';
                if (!ok)
                {
                    player.sendMessage(-1, "Kill phrases can use letters, numbers, spaces and ! ? . - only" + (c == '_' ? " (the lettering has no _ yet)." : "."));
                    return;
                }
            }
            int last, now = Environment.TickCount;
            if (phraseChangedAt.TryGetValue(player._alias, out last) && unchecked(now - last) < PHRASE_COOLDOWN_MS && unchecked(now - last) >= 0)
            {
                player.sendMessage(-1, "Give it a few seconds before the next change.");
                return;
            }
            phraseChangedAt[player._alias] = now;
            text = text.ToUpperInvariant();
            PhraseExplosionManager.SetOverride(player._alias, text);
            Console.WriteLine(String.Format("[phrase] {0} set '{1}' (site had '{2}')", player._alias, text, site));
            player.sendMessage(0, "&Kill phrase set: " + text + "  (it is what your kills spell from now on; ?phrase reset goes back to the site's)");
            int waitSet;
            if (TryPhrasePreview(player, text, out waitSet) != 0)
                player.sendMessage(0, "&Preview skipped: ?phrase test shows it, in the dropship, one preview every 10 s.");
        }
        #endregion

        #region Flag-safe mineral drops (Travis 10-25)
        // *flagdrop (ON by default, `*flagdrop off` = engine behaviour): a MINERAL drop (?drop, or a client drop 129..143 px out) made within FlagSafeDistance
        // (PrizeDistance + 16 px margin, the engine's square test, measured to the nearest of ALL flags) is QUEUED, not made: the items leave the inventory at
        // once and the pile is set down at the soldier's current spot as soon as they are clear (see QueuedFlagDrop below). The client drop KEY within
        // PrizeDistance is refused by the engine before any script runs and stays so. No player is ever moved by the script.
        // Not a player's choice: a wipe/class swap takes minerals away and puts them on the ground (DropMineralHere); near a flag that pile goes to the
        // nearest open floor outside the zone, and where none is found, where the soldier stands, as before.
        private bool flagSafeDrops = true;   // ON by default (Travis 10-25); *flagdrop off = the engine's own behaviour
        private const int FLAG_SAFE_MARGIN = 16;          // px beyond PrizeDistance
        private const int FLAG_SPOT_REACH = 260;          // wipe drops (DropMineralHere): the spot is at most this far from the soldier
        private const int FLAG_SPOT_MIN_EXPIRE = 60;      // the spot's terrain must keep a pile at least this many seconds (PrizeExpire)
        private const int FLAG_WARN_EVERY_MS = 1500;      // one warning per attempt (a ?drop with several items asks once per item)
        private readonly Dictionary<string, int> flagDropWarnedAt = new Dictionary<string, int>();

        private int FlagPrizeRange { get { return arena._server._zoneConfig.flag.prizeDistance; } }
        private int FlagSafeDistance { get { return FlagPrizeRange + FLAG_SAFE_MARGIN; } }

        /// <summary>Distance to the nearest flag lying on the ground, in the engine's own metric (square: the larger of |dx| and |dy|); int.MaxValue
        /// without one. A CARRIED flag does not count: the engine leaves its posX/posY at the spot it was picked up from until it is set down again,
        /// so it blocked drops at (and pushed piles away from) a spot the flag had left (Travis 10-27: "i cant drop mins while hes holding", "it
        /// reads that the flag was still there until he drops it"). An inactive flag is not on the map either.</summary>
        private int FlagDistance(int x, int y)
        {
            int best = int.MaxValue;
            foreach (Arena.FlagState fs in arena._flags.Values)
            {
                if (fs.carrier != null || !fs.bActive)
                    continue;
                int d = Math.Max(Math.Abs(fs.posX - x), Math.Abs(fs.posY - y));
                if (d < best)
                    best = d;
            }
            return best;
        }

        private bool OpenFloor(int x, int y, int minExpire)
        {
            try { return x > 16 && y > 16 && !arena.getTile(x, y).Blocked && arena.getTerrain(x, y).prizeExpire >= minExpire; }
            catch (Exception) { return false; }
        }

        /// <summary>Wipes/class swaps only (DropMineralHere): the open floor nearest the player outside every flag's safe distance, with a clear straight walk to it.</summary>
        private bool FindFlagSafeSpot(Player player, out short sx, out short sy)
        {
            sx = player._state.positionX; sy = player._state.positionY;
            int px = sx, py = sy, safe = FlagSafeDistance + 4;
            for (int r = 8; r <= FLAG_SPOT_REACH; r += 4)
                for (int a = 0; a < 32; a++)
                {
                    double ang = a * Math.PI / 16.0;
                    int x = px + (int)Math.Round(Math.Cos(ang) * r), y = py + (int)Math.Round(Math.Sin(ang) * r);
                    if (FlagDistance(x, y) < safe || !OpenFloor(x, y, FLAG_SPOT_MIN_EXPIRE))
                        continue;
                    bool clear = true;
                    for (int d = 8; d < r && clear; d += 8)
                        clear = OpenFloor(px + (int)Math.Round(Math.Cos(ang) * d), py + (int)Math.Round(Math.Sin(ang) * d), 0);
                    if (!clear)
                        continue;
                    sx = (short)x; sy = (short)y;
                    return true;
                }
            return false;
        }

        private void WarnFlagTooClose(Player player, int dist)
        {   // once per attempt (a ?drop with several items asks once per item)
            int now = Environment.TickCount, last;
            if (flagDropWarnedAt.TryGetValue(player._alias, out last) && now - last < FLAG_WARN_EVERY_MS)
                return;
            flagDropWarnedAt[player._alias] = now;
            player.sendMessage(-1, String.Format("DROP QUEUED - MOVE {0} MORE PIXELS FROM THE FLAG, IT DROPS WHEN YOU CLEAR IT", Math.Max(1, FlagSafeDistance - dist)));
        }

        /// <summary>The engine's ?drop deletes the pile it has just made when ANY flag's posX/posY is within PrizeDistance of the soldier (a carried
        /// flag too, at the spot it was picked up from; an inactive one too). True when that would happen here though no flag lies there: the
        /// script then sets the pile down itself. Not on a floor that keeps no piles (PrizeExpire 1 or less: ?drop puts nothing down there).</summary>
        private bool EngineEatsDropHere(Player player)
        {
            int x = player._state.positionX, y = player._state.positionY, r = FlagPrizeRange;
            if (arena.getTerrain(x, y).prizeExpire <= 1)
                return false;
            foreach (Arena.FlagState fs in arena._flags.Values)
                if ((fs.carrier != null || !fs.bActive) && Math.Abs(fs.posX - x) <= r && Math.Abs(fs.posY - y) <= r)
                    return true;
            return false;
        }

        // A mineral drop made too near a flag is QUEUED: the items leave the inventory at once (so the soldier is not left overweight), the entry
        // (player, item, exact quantity, team and class at the time, tick) waits in flagDropQueue, and PollQueuedFlagDrops (1 Hz, nothing to do while the
        // queue is empty) sets the pile down at the soldier's CURRENT position as soon as they are clear of EVERY flag's safe distance, exact quantity,
        // stacked like the engine does. Items are never lost: every way the entry can end gives them back to the inventory (death, spectating, leaving
        // the arena, a game start/end/reset, a team or class change, 60 s without getting clear). A floor that deletes dropped piles at once (PrizeExpire <= 1)
        // makes it wait (and time out). A spawn that fails keeps the entry and tries again. Entries cannot survive a zone shutdown (script memory).
        private class QueuedFlagDrop
        {
            public Player player; public int teamId; public string skill; public int itemId; public int quantity; public int queuedAt; public bool floorNoted;
            public int apBefore;   // the ?autopickup target for this item before the queue's first drop (-1 = not followed), to undo the bookkeeping on a give-back
        }
        private readonly List<QueuedFlagDrop> flagDropQueue = new List<QueuedFlagDrop>();
        private const int FLAG_QUEUE_TIMEOUT_MS = 60000;

        /// <summary>True = the drop was taken over (Player.ItemDrop returns false: the engine does nothing); false = not ours, the engine carries on.</summary>
        private bool HandleMineralDrop(Player player, ItemInfo item, object quantity)
        {
            if (!flagSafeDrops || player == null || item == null || !IsMineral(item.id) || player._team == null || player.IsSpectator || player.IsDead)
                return false;
            if (FlagPrizeRange <= 0)
                return false;
            int dist = FlagDistance(player._state.positionX, player._state.positionY);
            bool engineEats = dist >= FlagSafeDistance && EngineEatsDropHere(player);
            if (dist >= FlagSafeDistance && !engineEats)
                return false;
            int q = Convert.ToInt32(quantity);
            if (q <= 0)
                return false;
            if (q > 32000 || player.getInventoryAmount(item.id) < q || !player.inventoryModify(item, -q))
            {   // nothing taken: nothing to queue
                player.sendMessage(-1, "DROP CANCELLED - NOTHING TAKEN");
                return true;
            }
            int apBefore = FollowedPickupTarget(player, item);
            if (engineEats)
            {   // no flag on the ground near them, but a carried flag was picked up within PrizeDistance of here: ?drop would put the pile down and
                // delete it again (the engine still counts that spot), so the script sets it down here itself (Travis 10-27: "it drops if it still
                // has a carrier"). A spawn that fails leaves it queued: the 1 Hz poll tries again.
                QueuedFlagDrop direct = new QueuedFlagDrop { player = player, teamId = (int)player._team._id, skill = GetPrimarySkillName(player), itemId = item.id, quantity = q, queuedAt = Environment.TickCount, apBefore = apBefore };
                flagDropQueue.Add(direct);
                ItemDropBookkeeping(player, item, q);
                SetDownQueued(direct, player._state.positionX, player._state.positionY);
                return true;
            }
            QueuedFlagDrop e = flagDropQueue.Find(x => x.player == player && x.itemId == item.id);
            if (e != null && e.quantity + q <= 32000)
                e.quantity += q;   // same item again: merged, the oldest clock keeps running
            else
                flagDropQueue.Add(new QueuedFlagDrop { player = player, teamId = (int)player._team._id, skill = GetPrimarySkillName(player), itemId = item.id, quantity = q, queuedAt = Environment.TickCount, apBefore = apBefore });
            ItemDropBookkeeping(player, item, q);   // a deliberate drop for ?autopickup, exactly as on the engine path: it must not top the soldier up from this pile
            WarnFlagTooClose(player, dist);
            try { Console.WriteLine(String.Format("[flagdrop] {0}: {1} x{2} queued at {3},{4} ({5} px from a flag)", player._alias, item.name, q, player._state.positionX / 16, player._state.positionY / 16, dist)); }
            catch (Exception) { }
            return true;
        }

        /// <summary>Gives a queued entry back to the inventory (never drops it near a flag). Anything the inventory refuses is set down by DropMineralHere.</summary>
        private void ReturnQueuedEntry(QueuedFlagDrop e, string why)
        {
            flagDropQueue.Remove(e);
            ItemInfo item = null;
            try { item = arena._server._assets.getItemByID(e.itemId); } catch (Exception) { }
            if (item == null || e.player == null)
                return;
            int before = e.player.getInventoryAmount(e.itemId);
            e.player.inventoryModify(item, e.quantity);   // weight is not enforced on a give
            int got = e.player.getInventoryAmount(e.itemId) - before;
            if (got < e.quantity)
                DropMineralHere(e.player, item, e.quantity - got);
            try { UndoDropBookkeeping(e.player, item, e.quantity, e.apBefore); } catch (Exception) { }   // not dropped after all: ?autopickup follows it again
            if (why != null)
                try { e.player.sendMessage(0, String.Format("DROP CANCELLED ({0}) - {1} {2} BACK IN YOUR INVENTORY", why, e.quantity, item.name)); } catch (Exception) { }
            try { Console.WriteLine(String.Format("[flagdrop] {0}: {1} x{2} given back ({3})", e.player._alias, item.name, e.quantity, why ?? "left")); } catch (Exception) { }
        }

        /// <summary>What ?autopickup follows for this item right now: the loadout target, or -1 (no list, a hand-typed list, or not on it).</summary>
        private int FollowedPickupTarget(Player player, ItemInfo item)
        {
            Dictionary<string, int> following;
            int target;
            if (autoPickupItems.TryGetValue(player._alias, out following) && !autoPickupCustom.Contains(player._alias) && following.TryGetValue(item.name, out target))
                return target;
            return -1;
        }

        /// <summary>Reverses ItemDropBookkeeping for a queued drop that was given back: the dropped count goes down again and the followed target is restored.</summary>
        private void UndoDropBookkeeping(Player player, ItemInfo item, int quantity, int apBefore)
        {
            Dictionary<string, int> dropped;
            int had;
            if (autoPickupDropped.TryGetValue(player._alias, out dropped) && dropped.TryGetValue(item.name, out had))
            {
                if (had - quantity > 0)
                    dropped[item.name] = had - quantity;
                else
                    dropped.Remove(item.name);
            }
            Dictionary<string, int> following;
            int target;
            if (apBefore > 0 && autoPickupItems.TryGetValue(player._alias, out following) && !autoPickupCustom.Contains(player._alias)
                && (!following.TryGetValue(item.name, out target) || target < apBefore))
                following[item.name] = apBefore;
        }

        private void ReturnQueuedDrops(Player player, string why)
        {
            if (flagDropQueue.Count == 0)
                return;
            foreach (QueuedFlagDrop e in flagDropQueue.Where(x => x.player == player).ToList())
                ReturnQueuedEntry(e, why);
        }

        private void ReturnAllQueuedDrops(string why)
        {
            foreach (QueuedFlagDrop e in flagDropQueue.ToList())
                ReturnQueuedEntry(e, why);
        }

        private void PollQueuedFlagDrops()
        {
            if (flagDropQueue.Count == 0)
                return;
            int now = Environment.TickCount;
            foreach (QueuedFlagDrop e in flagDropQueue.ToList())
            {
                try
                {
                    Player p = e.player;
                    if (p == null || p._arena != arena || p._team == null || !arena.Players.Contains(p))
                    { ReturnQueuedEntry(e, null); continue; }
                    if (p.IsSpectator) { ReturnQueuedEntry(e, "SPECTATING"); continue; }
                    if (p.IsDead) { ReturnQueuedEntry(e, "DEAD"); continue; }
                    if ((int)p._team._id != e.teamId) { ReturnQueuedEntry(e, "TEAM CHANGE"); continue; }
                    if (GetPrimarySkillName(p) != e.skill) { ReturnQueuedEntry(e, "CLASS CHANGE"); continue; }
                    short x = p._state.positionX, y = p._state.positionY;
                    if (FlagDistance(x, y) >= FlagSafeDistance)
                    {
                        if (arena.getTerrain(x, y).prizeExpire <= 1)
                        {   // clear of the flags, but this floor deletes a dropped pile at once: wait (or time out and give them back)
                            if (!e.floorNoted) { e.floorNoted = true; p.sendMessage(-1, "DROP WAITING - THIS FLOOR CANNOT HOLD A PILE, MOVE ON"); }
                        }
                        else if (SetDownQueued(e, x, y))
                            continue;
                    }
                    if (unchecked(now - e.queuedAt) >= FLAG_QUEUE_TIMEOUT_MS)
                        ReturnQueuedEntry(e, "TOO LONG");
                }
                catch (Exception ex)
                {   // the entry stays and is tried again next second
                    try { Console.WriteLine("[flagdrop] queued drop retry: " + ex.Message); } catch (Exception) { }
                }
            }
        }

        // Flag zones (Travis 10-26: "a pile of ammo very close to a flag ... prevented players from being able to pick [the flag] up automatically" - the
        // reason for the PrizeDistance in the first place): nothing may lie within PrizeDistance of a flag on the ground, whatever put it there (a drop
        // aimed from outside the radius, a death drop, a flag set down next to a pile, a script spawn). 4 Hz while *flagdrop is on: a MINERAL pile (not
        // buyable) is moved to the nearest open floor clear of every flag; any other pile is removed, as the engine does when a flag is dropped on it.
        // Carried flags are skipped. A flag about to land (its carrier dies or drops it) would delete the minerals around it: RescueMineralsAround first.
        private const int FLAG_ZONE_EVERY_MS = 250;
        private const int FLAG_RESCUE_REACH = 480;        // px a mineral pile may travel to get clear (straight walk over open floor)
        private const int FLAG_RESCUE_RETRY_MS = 5000;    // a pile with no clear spot is tried again after this long
        private int _flagZoneAt;
        private readonly Dictionary<ushort, int> _flagZoneNoSpot = new Dictionary<ushort, int>();

        private void PollFlagZones(int now)
        {
            if (unchecked(now - _flagZoneAt) < FLAG_ZONE_EVERY_MS)
                return;
            _flagZoneAt = now;
            if (!flagSafeDrops || FlagPrizeRange <= 0 || arena._flags.Count == 0 || arena._items.Count == 0)
                return;
            int r = FlagPrizeRange;
            List<Arena.ItemDrop> inside = null;
            foreach (Arena.FlagState fs in arena._flags.Values)
            {
                if (!fs.bActive || fs.carrier != null)
                    continue;
                foreach (Arena.ItemDrop d in arena._items.Values)
                    if (Math.Abs(d.positionX - fs.posX) <= r && Math.Abs(d.positionY - fs.posY) <= r)
                    {
                        if (inside == null)
                            inside = new List<Arena.ItemDrop>();
                        if (!inside.Contains(d))
                            inside.Add(d);
                    }
            }
            if (inside == null)
                return;
            foreach (Arena.ItemDrop d in inside)
            {
                if (!arena._items.ContainsKey(d.id))
                    continue;
                if (IsMineral(d.item.id))
                {
                    int triedAt;
                    if (_flagZoneNoSpot.TryGetValue(d.id, out triedAt) && unchecked(now - triedAt) < FLAG_RESCUE_RETRY_MS)
                        continue;
                    if (MoveMineralPileClear(d, 0, 0, 0, "within " + r + " px of a flag"))
                        _flagZoneNoSpot.Remove(d.id);
                    else
                        _flagZoneNoSpot[d.id] = now;
                    continue;
                }
                Helpers.Object_ItemDropUpdate(arena.Players, d.id, 0);
                arena._items.Remove(d.id);
                try { Console.WriteLine(String.Format("[flagzone] {0} x{1} at {2},{3} removed (within {4} px of a flag){5}", d.item.name, d.quantity, d.positionX / 16, d.positionY / 16, r, d.owner != null ? ", dropped by " + d.owner._alias : "")); }
                catch (Exception) { }
            }
        }

        /// <summary>?d / ?bwd's excess drop next to a flag (flag zones): a non-mineral pile there would be removed at once, so it is not made and the
        /// items stay with the player. Minerals go through the queue in Player.ItemDrop as before.</summary>
        private bool RefuseDropNearFlag(Player player, ItemInfo item)
        {
            if (!flagSafeDrops || FlagPrizeRange <= 0 || player == null || item == null || IsMineral(item.id))
                return false;
            int dist = FlagDistance(player._state.positionX, player._state.positionY);
            if (dist >= FlagSafeDistance)
                return false;
            int now = Environment.TickCount, last;
            if (!flagDropWarnedAt.TryGetValue(player._alias, out last) || now - last >= FLAG_WARN_EVERY_MS)
            {
                flagDropWarnedAt[player._alias] = now;
                player.sendMessage(-1, String.Format("TOO CLOSE TO THE FLAG - MOVE {0} MORE PIXELS TO DROP", Math.Max(1, FlagSafeDistance - dist)));
            }
            return true;
        }

        /// <summary>A flag is about to be set down at cx,cy (its carrier died or dropped it): the engine deletes every pile within PrizeDistance of where it
        /// lands, so the mineral piles within radius are moved clear first.</summary>
        /// <param name="landing">A flag really lands here (a carrier sets it down): the engine deletes a pile left inside, so the last resort (the
        /// dropship) is allowed, and if even that fails the pile is lifted off for the landing and put back (HoldOverFlagLanding).</param>
        private void RescueMineralsAround(int cx, int cy, int radius, string why, Team side = null, bool landing = false)
        {
            if (!flagSafeDrops || FlagPrizeRange <= 0)
                return;
            foreach (Arena.ItemDrop d in arena._items.Values.Where(i => IsMineral(i.item.id) && Math.Abs(i.positionX - cx) <= radius && Math.Abs(i.positionY - cy) <= radius).ToList())
                if (!MoveMineralPileClear(d, cx, cy, radius, why, landing, side) && landing)
                    HoldOverFlagLanding(d, why);
        }

        // The final safety net, reached only when even the dropship spawn failed (the arena's item limit, or a map without the TP dropship): the pile
        // is taken off the map for the landing, so the engine has nothing to delete, and put back where it was 100 ms later. PollFlagZones moves it
        // from there once there is room (it never deletes a mineral).
        private class HeldPile { public Arena.ItemDrop d; public int heldAt; public int tries; }
        private readonly List<HeldPile> _heldOverLanding = new List<HeldPile>();

        private void HoldOverFlagLanding(Arena.ItemDrop d, string why)
        {
            if (!arena._items.ContainsKey(d.id))
                return;
            Helpers.Object_ItemDropUpdate(arena.Players, d.id, 0);
            arena._items.Remove(d.id);
            _heldOverLanding.Add(new HeldPile { d = d, heldAt = Environment.TickCount });
            try { Console.WriteLine(String.Format("[flagzone] {0} x{1} at {2},{3}: held over the flag landing ({4}), back in 100 ms [held]", d.item.name, d.quantity, d.positionX / 16, d.positionY / 16, why)); }
            catch (Exception) { }
        }

        private void PutBackHeldPiles(int now)
        {
            if (_heldOverLanding.Count == 0)
                return;
            foreach (HeldPile h in _heldOverLanding.ToList())
            {
                if (unchecked(now - h.heldAt) < 100)
                    continue;
                Arena.ItemDrop back = null;
                try { back = arena.itemSpawn(h.d.item, (ushort)h.d.quantity, h.d.positionX, h.d.positionY, 0, h.d.freq, h.d.owner); }
                catch (Exception) { }
                if (back == null && ++h.tries < 600)
                    continue;   // tried again every poll, about 3 s
                _heldOverLanding.Remove(h);
                try { Console.WriteLine(String.Format("[flagzone] {0} x{1} {2} at {3},{4} [held]", h.d.item.name, h.d.quantity, back != null ? "put back" : "COULD NOT be put back", h.d.positionX / 16, h.d.positionY / 16)); }
                catch (Exception) { }
            }
        }

        /// <summary>The middle of the four exit warp pads of the pile's side's dropship, where WarpToSideDropship sends players (pads at x 679/685,
        /// y 447/472 Titan and y 601/626 Collective in ctfdls4.lio). The side is the pile's team, else its dropper's, else the one given (the
        /// carrier's). False off the TP dropship floor (terrain 4), or for a team on neither side.</summary>
        private bool DropshipPadsMiddle(Arena.ItemDrop d, Team side, out short sx, out short sy)
        {
            sx = d.positionX; sy = d.positionY;
            Team t = null;
            try { t = arena.getTeamByID(d.freq); } catch (Exception) { }
            if (!IsTitanSideTeam(t) && !IsCollectiveSideTeam(t))
                t = d.owner != null && d.owner._team != null && (IsTitanSideTeam(d.owner._team) || IsCollectiveSideTeam(d.owner._team)) ? d.owner._team : side;
            if (IsTitanSideTeam(t)) { sx = 682 * 16; sy = 7352; }
            else if (IsCollectiveSideTeam(t)) { sx = 682 * 16; sy = 9816; }
            else return false;
            return OpenFloor(sx, sy, 0) && arena.getTerrainID(sx, sy) == 4;
        }

        /// <summary>Moves a mineral pile to the nearest open floor (straight walk from the pile, PrizeExpire long enough) clear of every flag and, with
        /// avoidR > 0, of the square of half-size avoidR (+ margin) around avoidX,avoidY. Stacks onto a clear pile of the same item within 50 px. False = no spot.</summary>
        /// <summary>The nearest open floor to px,py where ok(x, y) holds: rings out to FLAG_RESCUE_REACH, a straight walk over open floor, PrizeExpire long enough.</summary>
        private bool FindClearFloor(int px, int py, Func<int, int, bool> ok, out short sx, out short sy)
        {
            string tier;
            return FindClearFloor(px, py, ok, out sx, out sy, out tier);
        }

        /// <param name="tier">"line": in a straight walk from px,py; "walk": only around the walls (FindWalkableFloor, batch 5).</param>
        private bool FindClearFloor(int px, int py, Func<int, int, bool> ok, out short sx, out short sy, out string tier)
        {
            tier = "line";
            sx = (short)px; sy = (short)py;
            for (int r = 8; r <= FLAG_RESCUE_REACH; r += 8)
                for (int a = 0; a < 32; a++)
                {
                    double ang = a * Math.PI / 16.0;
                    int x = px + (int)Math.Round(Math.Cos(ang) * r), y = py + (int)Math.Round(Math.Sin(ang) * r);
                    if (!ok(x, y) || !OpenFloor(x, y, FLAG_SPOT_MIN_EXPIRE))
                        continue;
                    bool clear = true;
                    for (int st = 8; st < r && clear; st += 8)
                        clear = OpenFloor(px + (int)Math.Round(Math.Cos(ang) * st), py + (int)Math.Round(Math.Sin(ang) * st), 0);
                    if (!clear)
                        continue;
                    sx = (short)x; sy = (short)y;
                    return true;
                }
            tier = "walk";
            return FindWalkableFloor(px, py, ok, FLAG_RESCUE_REACH, out sx, out sy);
        }

        /// <summary>FindClearFloor's second try (batch 5): the nearest tile by WALK from px,py (4-way over open tiles, so no cutting a wall corner),
        /// out to reach px each way, whose centre keeps a pile (PrizeExpire long enough) and passes ok. The straight-line search finds nothing from a
        /// pile in a walled pocket: the 10-27 base at 524..526,117 has walls east and south and pillars north, so with the carrier standing on the
        /// piles no straight line got clear and the landing flag deleted them.</summary>
        private bool FindWalkableFloor(int px, int py, Func<int, int, bool> ok, int reach, out short sx, out short sy)
        {
            sx = (short)px; sy = (short)py;
            int tx0 = px / 16, ty0 = py / 16, n = reach / 16, side = 2 * n + 1;
            bool[] seen = new bool[side * side];
            Queue<int> open = new Queue<int>();
            seen[n * side + n] = true;
            open.Enqueue(n * side + n);
            while (open.Count > 0)
            {
                int cell = open.Dequeue(), dx = cell % side - n, dy = cell / side - n;
                int cx = (tx0 + dx) * 16 + 8, cy = (ty0 + dy) * 16 + 8;
                if ((dx != 0 || dy != 0) && ok(cx, cy) && OpenFloor(cx, cy, FLAG_SPOT_MIN_EXPIRE))
                {
                    sx = (short)cx; sy = (short)cy;
                    return true;
                }
                for (int k = 0; k < 4; k++)
                {
                    int nx = dx + (k == 0 ? 1 : k == 1 ? -1 : 0), ny = dy + (k == 2 ? 1 : k == 3 ? -1 : 0);
                    if (nx < -n || nx > n || ny < -n || ny > n)
                        continue;
                    int next = (ny + n) * side + (nx + n);
                    if (seen[next])
                        continue;
                    seen[next] = true;
                    if (OpenFloor((tx0 + nx) * 16 + 8, (ty0 + ny) * 16 + 8, 0))
                        open.Enqueue(next);
                }
            }
            return false;
        }

        // Where a pile goes, nearest first (Travis 10-27, after a flag drop deleted the tox: "I'd really prefer to solve this in it dropping in the
        // area"; the dropship is "LAST RESORT"), each move logged with its tier:
        //   [line]     the nearest open floor clear of the zone in a straight walk from the pile (the 10-26 rule);
        //   [walk]     the nearest one around the walls (FindWalkableFloor), same 480 px reach: the 10-27 loss was a pile in a walled pocket;
        //   [further]  the same walk out to FLAG_RESCUE_FAR;
        //   [dropship] only for a pile a landing flag would delete (lastResort): the middle of the exit warp pads in its team's dropship.
        private const int FLAG_RESCUE_FAR = 960;

        private bool MoveMineralPileClear(Arena.ItemDrop d, int avoidX, int avoidY, int avoidR, string why, bool lastResort = false, Team side = null)
        {
            int px = d.positionX, py = d.positionY, safe = FlagSafeDistance + 4;
            Func<int, int, bool> clearOfFlags = (cx, cy) => FlagDistance(cx, cy) >= safe
                && (avoidR <= 0 || Math.Max(Math.Abs(cx - avoidX), Math.Abs(cy - avoidY)) > avoidR + FLAG_SAFE_MARGIN);
            short sx, sy;
            string tier;
            bool found = FindClearFloor(px, py, clearOfFlags, out sx, out sy, out tier);
            if (!found && FindWalkableFloor(px, py, clearOfFlags, FLAG_RESCUE_FAR, out sx, out sy))
            {
                found = true;
                tier = "further";
            }
            if (!found && lastResort && DropshipPadsMiddle(d, side, out sx, out sy))
            {
                found = true;
                tier = "dropship";
            }
            if (found)
                {
                    int x = sx, y = sy;
                    Arena.ItemDrop pile = arena.getItemInRange(d.item, (short)x, (short)y, 50);
                    Arena.ItemDrop placed = pile;
                    if (pile != null && pile.id != d.id && clearOfFlags(pile.positionX, pile.positionY) && pile.quantity + d.quantity <= 32000)
                    {
                        pile.quantity = (short)(pile.quantity + d.quantity);
                        Helpers.Object_ItemDropUpdate(arena.Players, pile.id, (ushort)pile.quantity);
                    }
                    else if ((placed = arena.itemSpawn(d.item, (ushort)d.quantity, (short)x, (short)y, 0, d.freq, d.owner)) == null)
                        return false;
                    if (tier == "dropship")
                        placed.tickExpire = 0;   // the dropship floor keeps a pile 10 s; minerals there never expire (pollItemExpiration does it at 1 Hz too)
                    Helpers.Object_ItemDropUpdate(arena.Players, d.id, 0);
                    arena._items.Remove(d.id);
                    try { Console.WriteLine(String.Format("[flagzone] {0} x{1} moved from {2},{3} to {4},{5} ({6}) [{7}]", d.item.name, d.quantity, px / 16, py / 16, x / 16, y / 16, why, tier)); }
                    catch (Exception) { }
                    return true;
                }
            try { Console.WriteLine(String.Format("[flagzone] {0} x{1} at {2},{3}: no clear floor within {4} px ({5}), left there", d.item.name, d.quantity, px / 16, py / 16, FLAG_RESCUE_FAR, why)); }
            catch (Exception) { }
            return false;
        }

        /// <summary>Sets the queued pile down at x,y (exact quantity, stacked onto a pile within 50 px that is itself clear of the flags). False = nothing happened, the entry stays.</summary>
        private bool SetDownQueued(QueuedFlagDrop e, short x, short y)
        {
            Player p = e.player;
            ItemInfo item = arena._server._assets.getItemByID(e.itemId);
            if (item == null)
                return false;
            Arena.ItemDrop pile = arena.getItemInRange(item, x, y, 50);
            bool stacked = pile != null && FlagDistance(pile.positionX, pile.positionY) >= FlagSafeDistance && pile.quantity + e.quantity <= 32000;
            if (stacked)
            {
                pile.quantity = (short)(pile.quantity + e.quantity);
                Helpers.Object_ItemDropUpdate(arena.Players, pile.id, (ushort)pile.quantity);
            }
            else
            {
                pile = arena.itemSpawn(item, (ushort)e.quantity, x, y, 0, (int)p._team._id, p);
                if (pile == null)
                    return false;
            }
            flagDropQueue.Remove(e);
            p.sendMessage(0, String.Format("DROPPED {0} x {1}", e.quantity, item.name));
            try { Console.WriteLine(String.Format("[flagdrop] {0}: {1} x{2} set down at {3},{4} after {5} ms, pile now {6}", p._alias, item.name, e.quantity, x / 16, y / 16, unchecked(Environment.TickCount - e.queuedAt), pile.quantity)); }
            catch (Exception) { }
            return true;
        }
        #endregion

        #region Base minerals (who already has them, who gets them directly)

        private const int MINERAL_TSO = 2005;   // Tsolvy Crystals - medics
        private const int MINERAL_TOX = 2009;   // Titanium Oxide  - engineers
        private const int MINERAL_STACK = 150;  // what a base setup provides; also the item cap, so a
                                                // prize of 150 tops the player up to exactly full
        // Every "Resources" item in ctfpl.itm: Tsolvy Crystals, Pandora's Element, Titanium Oxide.
        private static readonly int[] MINERAL_IDS = { MINERAL_TSO, 2007, MINERAL_TOX };
        private static bool IsMineral(int itemId) { return Array.IndexOf(MINERAL_IDS, itemId) >= 0; }

        /// <summary>
        /// Puts minerals on the ground where the player stands, for their own team (the same drop ?d
        /// makes), so a wipe or class swap never just deletes them.
        /// </summary>
        private void DropMineralHere(Player player, ItemInfo item, int amount)
        {
            if (player == null || item == null || amount <= 0 || player.IsSpectator || player._team == null) return;
            try
            {
                short dx = player._state.positionX, dy = player._state.positionY;
                if (flagSafeDrops && FlagPrizeRange > 0 && FlagDistance(dx, dy) < FlagSafeDistance)
                    FindFlagSafeSpot(player, out dx, out dy);   // none found: where they stand, as before (never deleted)
                player._arena.itemSpawn(item, (ushort)Math.Min(amount, ushort.MaxValue), dx, dy, 0, (int)player._team._id, player);
            }
            catch (Exception ex) { Console.WriteLine("[Minerals] Drop for " + player._alias + " failed: " + ex.Message); }
        }

        /// <summary>
        /// Before anything that wipes the inventory (?wipe, ?swap): takes the player's minerals and drops
        /// them at their feet. Tells them what went down. Spectators carry nothing worth dropping.
        /// </summary>
        public void DropMineralsBeforeWipe(Player player)
        {
            if (player == null || player.IsSpectator || player._arena == null) return;
            var dropped = new List<string>();
            foreach (int id in MINERAL_IDS)
            {
                int n = player.getInventoryAmount(id);
                if (n <= 0) continue;
                ItemInfo item = player._server._assets.getItemByID(id);
                if (item == null) continue;
                player.inventoryModify(item, -n);
                DropMineralHere(player, item, n);
                dropped.Add(n + " " + item.name);
            }
            if (dropped.Count > 0)
                player.sendMessage(0, "~Dropped your minerals here first: " + String.Join(", ", dropped.ToArray()) + ".");
        }

        // A base was set up with no medic on the defending team: the Tso stack is owed to the first
        // player on that team who becomes one. Null when nothing is owed. Cleared at Game.End/Reset.
        private Team pendingTsoTeam = null;

        /// <summary>The class a player is credited with for the stats row: the one they spent the
        /// most of the game as (booked time plus the open session), falling back to the skill
        /// resolver for someone with no booked time at all.</summary>
        private string ResolveMainClassForStats(Player p)
        {
            var spread = SnapshotClassPlayTimes(p);
            string main = spread.Any() ? spread.OrderByDescending(x => x.Value).First().Key : "Unknown";
            if (main == "Unknown") main = GetPrimarySkillName(p);
            return main;
        }

        #region Live snapshot host (ILiveSnapshotHost - what the site's live feed asks this script)

        public string GameKey { get { return "ctf"; } }

        /// <summary>The base in play when known, else the level file without its extension.</summary>
        public string MapKey
        {
            get
            {
                if (!String.IsNullOrEmpty(baseUsed) && baseUsed != "Unknown") return baseUsed;
                string lvl = CFG != null && CFG.level != null ? (CFG.level.lvlFile ?? "") : "";
                int dot = lvl.LastIndexOf('.');
                return dot > 0 ? lvl.Substring(0, dot) : lvl;
            }
        }

        public string ClassOf(Player p) { return CTFClass.ResolveName(p); }

        /// <summary>The canonical side rule (IsTitanSideTeam / IsCollectiveSideTeam); spec and np are their own sides.</summary>
        public string SideOf(Team t)
        {
            if (t == null || t._name == null) return "other";
            if (t.IsSpec) return "spec";
            if (t._name.Equals("np", StringComparison.OrdinalIgnoreCase)) return "np";
            if (IsTitanSideTeam(t)) return "T";
            if (IsCollectiveSideTeam(t)) return "C";
            return "other";
        }

        public bool IsCaptain(Player p)
        {
            if (p == null || p._alias == null || _mixManager == null || !_mixManager.IsActive) return false;
            string[] caps = _mixManager.CaptainAliases;
            if (caps == null) return false;
            foreach (string c in caps)
                if (c != null && c.Equals(p._alias, StringComparison.OrdinalIgnoreCase)) return true;
            return false;
        }

        /// <summary>Headline for the site: an OvD / mix being organized or running, a pub game, or idle; the clock from the playtime ticker.</summary>
        public void FillState(LiveSnapshotState st, int now)
        {
            LiveMixInfo mi = _mixManager != null ? _mixManager.LiveInfo(now) : null;
            st.Running = arena._bGameRunning;
            if (mi != null && _mixManager.IsOrganizing)
            {
                st.Mode = "draft";
                st.Phase = mi.Phase;
                st.Label = mi.Label + " draft: " + (mi.Phase == "CaptainSignup" ? "captain signup" : mi.Phase == "BaseSelect" ? "base pick" : mi.Phase == "Picking" ? "picking" : "starting");
            }
            else if (mi != null && mi.Phase == "Running")
            {
                st.Running = true;
                st.Mode = mi.Label == "OvD" ? "ovd" : "mix";
                st.Phase = "Running";
                st.Label = mi.Label + (mi.Base != null ? " @ " + mi.Base : "");
            }
            else if (arena._bGameRunning)
            {
                // No draft session owns this game, so the arena's NAME says what is being played here
                // (Travis, 2026-09-13: the ovd arena is never a pub game; pubs live in Arena 1).
                string an = arena._name ?? "";
                bool ovdArena = an.IndexOf("ovd", StringComparison.OrdinalIgnoreCase) >= 0;
                bool mixArena = an.IndexOf("mix", StringComparison.OrdinalIgnoreCase) >= 0;
                st.Mode = ovdArena ? "ovd" : mixArena ? "mix" : "pub";
                st.Phase = "Running";
                st.Label = (ovdArena ? "OvD" : mixArena ? "Mix" : "Pub game") + (!String.IsNullOrEmpty(baseUsed) && baseUsed != "Unknown" ? " @ " + baseUsed : "");
            }
            else
            {
                st.Mode = "idle";
                st.Label = arena.PlayerCount < minPlayers ? "Not enough players" : "Waiting for a game";
            }

            Arena.TickerInfo ti;
            if (arena._tickers != null && arena._tickers.TryGetValue(arena.playtimeTickerIdx, out ti) && ti != null && ti.customTicker == null)
            {
                int left = ti.timer - now;
                if (left > 0 && (ti.message ?? "").IndexOf("Time", StringComparison.OrdinalIgnoreCase) >= 0)
                    st.TimeLeftMs = left;
            }
            if (arena._bGameRunning)
            {
                int started = ovdMatchStartTick ?? arena._tickGameStarted;
                if (started > 0) st.ElapsedMs = Math.Max(0, now - started);
            }
            if (winningTeam != null && winningTeamTick > 0)
            {
                st.WinningTeam = winningTeam._name;
                st.VictoryInMs = Math.Max(0, winningTeamTick - now);
            }
            foreach (Team t in arena.ActiveTeams.OrderBy(t => t._id).Take(4))
                st.Score.Add(new LiveScoreEntry { Team = t._name, Side = SideOf(t), Kills = t._currentGameKills });
        }

        /// <summary>"mix" (mix / OvD session) and "flags" members; each written as "key":value followed by a comma.</summary>
        public void AppendExtras(System.Text.StringBuilder sb, int now)
        {
            LiveMixInfo mi = _mixManager != null ? _mixManager.LiveInfo(now) : null;
            if (mi != null) { sb.Append("\"mix\":"); LiveSnapshotPublisher.AppendMix(sb, mi); sb.Append(','); }
            if (_flags != null && _flags.Count > 0)
            {
                List<string[]> rows = new List<string[]>();
                foreach (Arena.FlagState fs in _flags)
                {
                    if (fs == null || !fs.bActive) continue;
                    string name = "flag";
                    try { if (fs.flag != null && fs.flag.GeneralData.Name != null) name = fs.flag.GeneralData.Name.Trim('\"'); } catch { }
                    rows.Add(new string[] { name, fs.team != null ? fs.team._name : null, fs.carrier != null ? fs.carrier._alias : null });
                }
                if (rows.Count > 0)
                {
                    sb.Append("\"flags\":");
                    LiveSnapshotPublisher.AppendFlags(sb, rows);
                    sb.Append(',');
                }
            }
        }

        /// <summary>A spectator's view resolves the per-player tickers the way the site should show them.</summary>
        public Player TickerViewpoint()
        {
            foreach (Player p in arena.Players)
                if (p != null && p.IsSpectator) return p;
            return arena.Players.FirstOrDefault(p => p != null);
        }

        #endregion

        /// <summary>
        /// True for the winning team AND for that squad's other team. League matches give every squad two
        /// teams, "GOL C" (playing) and "GOL T" (its bench in spec); the bench is part of the squad and shares
        /// its result. Pairs are recognised by name: the same text before a trailing " T" / " C".
        /// </summary>
        public static bool IsSquadOfWinner(Team t, Team winner)
        {
            if (t == null || winner == null) return false;
            if (t == winner) return true;
            string a = t._name, b = winner._name;
            if (a == null || b == null || a.Length < 3 || b.Length < 3) return false;
            bool aSided = a.EndsWith(" T") || a.EndsWith(" C");
            bool bSided = b.EndsWith(" T") || b.EndsWith(" C");
            return aSided && bSided
                && a.Substring(0, a.Length - 2).Equals(b.Substring(0, b.Length - 2), StringComparison.OrdinalIgnoreCase);
        }

        /// <summary>Side of a team by name: "Newfie T", "MOON T", "Titan Militia" are Titan side.</summary>
        public static bool IsTitanSideTeam(Team t)
        {
            if (t == null || t._name == null) return false;
            return t._name.EndsWith(" T") || t._name.IndexOf("Titan", StringComparison.OrdinalIgnoreCase) >= 0;
        }

        /// <summary>Side of a team by name: "AE C", "MOON C", "Collective" are Collective side.</summary>
        public static bool IsCollectiveSideTeam(Team t)
        {
            if (t == null || t._name == null) return false;
            return t._name.EndsWith(" C") || t._name.IndexOf("Collective", StringComparison.OrdinalIgnoreCase) >= 0;
        }

        /// <summary>
        /// Puts the base minerals where they are actually useful. The old behaviour - 150 Tso and
        /// 150 Tox dropped on the resource pile - stays the fallback, but:
        ///  - if every defending engineer already holds a full Tox stack, no Tox is dropped
        ///    (support players often arrive from the previous game still stocked, and a second
        ///    stack on the ground is clutter the attackers can steal);
        ///  - Tso goes STRAIGHT to the defending medic instead of the floor; with no medic yet it is
        ///    held and prized to whoever on that team becomes one (PollPendingTso, 1Hz).
        /// With no defending team resolved (e.g. *setup in an empty arena) both drop as before.
        /// Returns a one-line note for the arena so the host can see what happened.
        /// </summary>
        private string SpawnBaseMinerals(Base defense, Team defTeam)
        {
            pendingTsoTeam = null;
            if (defTeam == null)
            {
                arena.itemSpawn(arena._server._assets.getItemByID(MINERAL_TSO), MINERAL_STACK, defense.x, defense.y, 100, null);
                arena.itemSpawn(arena._server._assets.getItemByID(MINERAL_TOX), MINERAL_STACK, defense.x, defense.y, 100, null);
                return "Tso and Tox on the ground (no defending team resolved)";
            }

            List<Player> roster = defTeam.ActivePlayers.Where(p => p != null && !p.IsSpectator).ToList();
            List<Player> engineers = roster.Where(p => CTFClass.ResolveName(p) == "Combat Engineer").ToList();
            List<Player> medics = roster.Where(p => CTFClass.ResolveName(p) == "Field Medic").ToList();
            var notes = new List<string>();

            // Titanium Oxide: ground drop unless the engineer(s) are already full.
            if (engineers.Count > 0 && engineers.All(e => e.getInventoryAmount(MINERAL_TOX) >= MINERAL_STACK))
                notes.Add(String.Format("Tox not dropped - {0} already full",
                    String.Join("/", engineers.Select(e => e._alias).ToArray())));
            else
            {
                arena.itemSpawn(arena._server._assets.getItemByID(MINERAL_TOX), MINERAL_STACK, defense.x, defense.y, 100, null);
                notes.Add("Tox on the ground");
            }

            // Tsolvy Crystals: to the medic, not the floor.
            Player needy = medics.FirstOrDefault(m => m.getInventoryAmount(MINERAL_TSO) < MINERAL_STACK);
            if (needy != null)
            {
                PrizeTso(needy, "base setup");
                notes.Add("Tso to " + needy._alias);
            }
            else if (medics.Count > 0)
                notes.Add(String.Format("Tso not dropped - {0} already full",
                    String.Join("/", medics.Select(m => m._alias).ToArray())));
            else
            {
                pendingTsoTeam = defTeam;
                notes.Add("Tso held for a " + defTeam._name + " medic - prized the moment someone switches");
            }
            return String.Join(". ", notes.ToArray());
        }

        private void PrizeTso(Player medic, string why)
        {
            medic.inventoryModify(MINERAL_TSO, MINERAL_STACK);   // server caps at the item max, so this means "fill up"
            medic.sendMessage(0, String.Format("&You are the medic - {0} Tsolvy Crystals prized to you ({1}).", MINERAL_STACK, why));
        }

        /// <summary>1Hz: deliver an owed Tso stack the moment a defender becomes a medic.</summary>
        private void PollPendingTso()
        {
            if (pendingTsoTeam == null)
                return;
            if (pendingTsoTeam.ActivePlayerCount == 0)
            {   // the team left; nobody to owe it to
                pendingTsoTeam = null;
                return;
            }
            Player medic = pendingTsoTeam.ActivePlayers
                .FirstOrDefault(p => p != null && !p.IsSpectator && CTFClass.ResolveName(p) == "Field Medic");
            if (medic == null)
                return;
            if (medic.getInventoryAmount(MINERAL_TSO) < MINERAL_STACK)
                PrizeTso(medic, "base setup - you switched to medic");
            pendingTsoTeam = null;
        }

        #endregion

        #region Arena tips (hourly feature rotation from ArenaTips.txt)

        // One line an hour so people learn the commands exist without being spammed. The file is
        // re-read whenever its timestamp changes, so a tip can be added per patch WITHOUT a restart
        // (scripts only compile at boot). Format: one message per line, first character is the usual
        // colour code (& * ! ~); "|" splits one tip into several lines sent together; lines starting
        // with "//" and blank lines are ignored.
        private static readonly string ARENA_TIPS_PATH = System.IO.Path.Combine("scripts", "GameTypes", "CTF", "ArenaTips.txt");
        private const int TIPS_FIRST_MS = 10 * 60 * 1000;      // first tip 10 minutes after boot
        private const int TIPS_INTERVAL_MS = 60 * 60 * 1000;   // then one an hour
        private const int TIPS_RETRY_MS = 60 * 1000;           // arena too quiet / a draft is on: look again in a minute
        private const int TIPS_MIN_PLAYERS = 4;                // no point telling an empty arena
        private List<string> _arenaTips = new List<string>();
        private DateTime _arenaTipsMtime = DateTime.MinValue;
        private int _arenaTipIndex = 0;
        private int _arenaTipsNextTick = 0;

        private void ReloadArenaTipsIfChanged()
        {
            try
            {
                if (!System.IO.File.Exists(ARENA_TIPS_PATH))
                {
                    _arenaTips.Clear();
                    _arenaTipsMtime = DateTime.MinValue;
                    return;
                }
                DateTime mtime = System.IO.File.GetLastWriteTimeUtc(ARENA_TIPS_PATH);
                if (mtime == _arenaTipsMtime)
                    return;
                _arenaTips = System.IO.File.ReadAllLines(ARENA_TIPS_PATH)
                    .Select(l => l.TrimEnd())
                    .Where(l => l.Trim().Length > 0 && !l.TrimStart().StartsWith("//"))
                    .ToList();
                _arenaTipsMtime = mtime;
                if (_arenaTipIndex >= _arenaTips.Count)
                    _arenaTipIndex = 0;
                Console.WriteLine(String.Format("CTF tips: {0} tip(s) loaded from ArenaTips.txt", _arenaTips.Count));
            }
            catch (Exception ex)
            {
                Console.WriteLine("CTF tips: could not read ArenaTips.txt - " + ex.Message);
            }
        }

        private void PollArenaTips(int now)
        {
            if (_arenaTipsNextTick == 0)
            {
                _arenaTipsNextTick = now + TIPS_FIRST_MS;
                return;
            }
            if (now - _arenaTipsNextTick < 0)   // tick-wrap safe
                return;
            ReloadArenaTipsIfChanged();
            if (_arenaTips.Count == 0)
            {
                _arenaTipsNextTick = now + TIPS_INTERVAL_MS;
                return;
            }
            // Never talk over a draft, and never to an empty room - try again shortly instead.
            if ((_mixManager != null && _mixManager.IsOrganizing) || arena.PlayersIngame.Count() < TIPS_MIN_PLAYERS)
            {
                _arenaTipsNextTick = now + TIPS_RETRY_MS;
                return;
            }
            SendNextArenaTip();
            _arenaTipsNextTick = now + TIPS_INTERVAL_MS;
        }

        private string SendNextArenaTip()
        {
            if (_arenaTips.Count == 0)
                return null;
            string tip = _arenaTips[_arenaTipIndex % _arenaTips.Count];
            _arenaTipIndex = (_arenaTipIndex + 1) % _arenaTips.Count;
            foreach (string line in tip.Split('|'))
            {
                string msg = line.Trim();
                if (msg.Length > 0)
                    arena.sendArenaMessage(msg);
            }
            return tip;
        }

        #endregion

        #region Armory (stand on a tile to pick your build / class / base) - ArmoryTiles.txt

        // The map already has the armory drawn at ~584,526: a store pad with build names spelled on
        // the floor (CAW, SG, DOUBLE RG, LMG RPG AC, MG AC, MML AC, DOUBLE BR, PACK, FOOT...), a class
        // row to the south and CHOOSE BASE to the north. Nothing ever wired the tiles up. This does:
        // each line of ArmoryTiles.txt is a tile rectangle -> action, the file is hot-reloaded, and
        // *armory set <kind> <name> writes a cell where the mod is standing so the layout can be
        // corrected in-game without a restart.
        //   build <name>  - set as your build: bought now, re-bought every respawn (autobuy on)
        //   class <alias> - ?swap to that class (inf/hvy/med/eng/sl/jt/infil)
        //   base <name>   - during an OvD base pick, the defending captain's ?base <name>
        private class ArmoryCell
        {
            public short X1, Y1, X2, Y2;
            public string Kind, Arg;
            public string Key { get { return Kind + ":" + Arg + "@" + X1 + "," + Y1; } }
            public bool Contains(int tx, int ty) { return tx >= X1 && tx <= X2 && ty >= Y1 && ty <= Y2; }
        }
        private class ArmoryStand { public string CellKey; public int Polls; public bool Fired; }

        private static readonly string ARMORY_TILES_PATH = System.IO.Path.Combine("scripts", "GameTypes", "CTF", "ArmoryTiles.txt");
        private const int ARMORY_DWELL_POLLS = 2;         // consecutive 1Hz sightings on a cell before it fires (walk-through safe)
        private const int ARMORY_RELOAD_EVERY = 10;       // polls between mtime checks
        private List<ArmoryCell> _armoryCells = new List<ArmoryCell>();
        private DateTime _armoryMtime = DateTime.MinValue;
        private int _armoryReloadCountdown = 0;
        private int _armoryMinX, _armoryMinY, _armoryMaxX, _armoryMaxY;   // tile bbox of all cells
        private Dictionary<string, ArmoryStand> _armoryStanding = new Dictionary<string, ArmoryStand>(StringComparer.OrdinalIgnoreCase);

        private void ReloadArmoryIfChanged(bool force = false)
        {
            try
            {
                if (!System.IO.File.Exists(ARMORY_TILES_PATH))
                {
                    _armoryCells.Clear();
                    _armoryMtime = DateTime.MinValue;
                    return;
                }
                DateTime mtime = System.IO.File.GetLastWriteTimeUtc(ARMORY_TILES_PATH);
                if (!force && mtime == _armoryMtime)
                    return;
                var cells = new List<ArmoryCell>();
                foreach (string raw in System.IO.File.ReadAllLines(ARMORY_TILES_PATH))
                {
                    string line = ArmoryStripComment(raw);
                    if (line.Length == 0)
                        continue;
                    int eq = line.IndexOf('=');
                    if (eq <= 0)
                        continue;
                    string[] xy = line.Substring(0, eq).Split(',');
                    string[] act = line.Substring(eq + 1).Trim().Split(new char[] { ' ' }, 2, StringSplitOptions.RemoveEmptyEntries);
                    short x1, y1, x2, y2;
                    if (xy.Length != 4 || act.Length != 2
                        || !short.TryParse(xy[0].Trim(), out x1) || !short.TryParse(xy[1].Trim(), out y1)
                        || !short.TryParse(xy[2].Trim(), out x2) || !short.TryParse(xy[3].Trim(), out y2))
                    {
                        Console.WriteLine("CTF armory: skipped bad line: " + line);
                        continue;
                    }
                    string kind = act[0].ToLower();
                    if (kind != "build" && kind != "class" && kind != "base")
                    {
                        Console.WriteLine("CTF armory: unknown action '" + kind + "' in: " + line);
                        continue;
                    }
                    cells.Add(new ArmoryCell
                    {
                        X1 = Math.Min(x1, x2), X2 = Math.Max(x1, x2), Y1 = Math.Min(y1, y2), Y2 = Math.Max(y1, y2),
                        Kind = kind, Arg = act[1].Trim()
                    });
                }
                _armoryCells = cells;
                _armoryMtime = mtime;
                if (cells.Count > 0)
                {
                    _armoryMinX = cells.Min(c => c.X1); _armoryMaxX = cells.Max(c => c.X2);
                    _armoryMinY = cells.Min(c => c.Y1); _armoryMaxY = cells.Max(c => c.Y2);
                }
                Console.WriteLine(String.Format("CTF armory: {0} cell(s) loaded from ArmoryTiles.txt", cells.Count));
            }
            catch (Exception ex)
            {
                Console.WriteLine("CTF armory: could not read ArmoryTiles.txt - " + ex.Message);
            }
        }

        /// <summary>A line without its trailing "// ..." comment, trimmed. Empty for comment-only lines.</summary>
        private static string ArmoryStripComment(string raw)
        {
            string line = raw ?? "";
            int cm = line.IndexOf("//");
            if (cm >= 0)
                line = line.Substring(0, cm);
            line = line.Trim();
            return line.StartsWith("#") ? "" : line;
        }

        /// <summary>True when this file line defines kind+name (ignoring its comment).</summary>
        private static bool ArmoryLineIs(string raw, string kind, string arg)
        {
            string line = ArmoryStripComment(raw);
            int eq = line.IndexOf('=');
            if (eq < 0)
                return false;
            string[] act = line.Substring(eq + 1).Trim().Split(new char[] { ' ' }, 2, StringSplitOptions.RemoveEmptyEntries);
            return act.Length == 2 && act[0].Equals(kind, StringComparison.OrdinalIgnoreCase) && act[1].Trim().Equals(arg, StringComparison.OrdinalIgnoreCase);
        }

        private ArmoryCell ArmoryCellAt(int tx, int ty)
        {
            if (tx < _armoryMinX || tx > _armoryMaxX || ty < _armoryMinY || ty > _armoryMaxY)
                return null;
            foreach (ArmoryCell c in _armoryCells)
                if (c.Contains(tx, ty))
                    return c;
            return null;
        }

        /// <summary>1Hz. Cheap: a bbox reject for everyone not on the pad, then a handful of rectangles.</summary>
        private void PollArmory()
        {
            if (--_armoryReloadCountdown <= 0)
            {
                _armoryReloadCountdown = ARMORY_RELOAD_EVERY;
                ReloadArmoryIfChanged();
            }
            if (_armoryCells.Count == 0)
                return;
            foreach (Player p in arena.PlayersIngame.ToList())
            {
                if (p == null || p.IsSpectator || p.IsDead)
                    continue;
                ArmoryCell cell = ArmoryCellAt(p._state.positionX / 16, p._state.positionY / 16);
                if (cell == null)
                {
                    _armoryStanding.Remove(p._alias);
                    continue;
                }
                ArmoryStand stand;
                if (!_armoryStanding.TryGetValue(p._alias, out stand) || stand.CellKey != cell.Key)
                {
                    stand = new ArmoryStand { CellKey = cell.Key };
                    _armoryStanding[p._alias] = stand;
                }
                stand.Polls++;
                if (!stand.Fired && stand.Polls >= ARMORY_DWELL_POLLS)
                {
                    stand.Fired = true;   // once per visit - step off and back on to repeat
                    ArmoryTrigger(p, cell);
                }
            }
        }

        private void ArmoryTrigger(Player player, ArmoryCell cell)
        {
            switch (cell.Kind)
            {
                case "build":
                    if (!buildSets.ContainsKey(cell.Arg.ToLower()))
                    {
                        player.sendMessage(-1, String.Format("Armory: '{0}' is not a build this zone knows (tile at {1},{2}).", cell.Arg, cell.X1, cell.Y1));
                        return;
                    }
                    // WipeAndBuy swaps class if the build needs it, buys it, stores it as the persistent
                    // build (clearing any premade) and turns autobuy on for preset builds.
                    player.sendMessage(0, String.Format("&Armory: {0} - {1}", cell.Arg, buildSets[cell.Arg.ToLower()].Item2.TrimStart('*')));
                    WipeAndBuy(player, cell.Arg.ToLower(), true);
                    player.sendMessage(0, "*Bought now and re-bought every respawn. ?ab turns the re-buy off; stand on another tile to switch.");
                    break;

                case "class":
                    if (!CommandHandler.skillAliases.ContainsKey(cell.Arg))
                    {
                        player.sendMessage(-1, String.Format("Armory: '{0}' is not a class alias (tile at {1},{2}).", cell.Arg, cell.X1, cell.Y1));
                        return;
                    }
                    commandHandler.HandleSwapCommand(player, cell.Arg, CFG, this, true, false);
                    break;

                case "base":
                    if (_mixManager != null && _mixManager.IsActive)
                        _mixManager.HandleChatCommand(player, "base", cell.Arg);   // the defending captain's ?base, same rules
                    else
                        player.sendMessage(0, String.Format("Base {0}: the defending captain picks it during an OvD (?base {0}); a ref can set it up with *ovd base {0}.", cell.Arg));
                    break;
            }
        }

        /// <summary>*armory set &lt;kind&gt; &lt;name&gt; [w h]: write/replace the cell for kind+name at the mod's tile.</summary>
        private void ArmoryWriteCell(Player mod, string kind, string arg, int w, int h)
        {
            int tx = mod._state.positionX / 16, ty = mod._state.positionY / 16;
            string newLine = String.Format("{0},{1},{2},{3} = {4} {5}", tx, ty, tx + w - 1, ty + h - 1, kind, arg);
            var lines = System.IO.File.Exists(ARMORY_TILES_PATH)
                ? System.IO.File.ReadAllLines(ARMORY_TILES_PATH).ToList()
                : new List<string>();
            int idx = lines.FindIndex(l => ArmoryLineIs(l, kind, arg));
            if (idx >= 0)
                lines[idx] = newLine;   // the old comment goes with the old guess
            else
                lines.Add(newLine);
            System.IO.File.WriteAllLines(ARMORY_TILES_PATH, lines.ToArray());
            ReloadArmoryIfChanged(true);
            mod.sendMessage(0, String.Format("Armory: {0} {1} -> {2}x{3} at {4},{5} ({6}).", kind, arg, w, h, tx, ty, idx >= 0 ? "replaced" : "added"));
        }

        #endregion


        #region OvD match setup (timer + starting positions)

        // Attacker start position per base, loaded from OvDSpawns.txt. Defence starts inside the
        // base on the resource pile; offence starts at that base's entry point (e.g. A7 is entered
        // from the A3 elevator), which is map knowledge that does not belong hard-coded in here.
        private Dictionary<string, Tuple<short, short>> _ovdAttackerSpawns;
        private static readonly string OVD_SPAWNS_PATH = System.IO.Path.Combine("scripts", "GameTypes", "CTF", "OvDSpawns.txt");

        /// <summary>
        /// (Re)reads OvDSpawns.txt. Called at init and again at every OvD launch, so positions can
        /// be filled in or corrected live without restarting the zone.
        /// Format: `BASE = tileX,tileY`, # comments, blank values simply mean "not set yet".
        /// </summary>
        public void LoadOvdSpawns()
        {
            _ovdAttackerSpawns = new Dictionary<string, Tuple<short, short>>(StringComparer.OrdinalIgnoreCase);
            try
            {
                if (!System.IO.File.Exists(OVD_SPAWNS_PATH))
                    return;

                foreach (string raw in System.IO.File.ReadAllLines(OVD_SPAWNS_PATH))
                {
                    string line = (raw ?? "").Trim();
                    if (line.Length == 0 || line.StartsWith("#"))
                        continue;
                    int eq = line.IndexOf('=');
                    if (eq <= 0)
                        continue;

                    string key = line.Substring(0, eq).Trim();
                    string val = line.Substring(eq + 1).Trim();

                    // Allow a trailing comment on the value line, e.g. "B6 = 153,349  # shares B8".
                    // Without this the comment is parsed as part of the Y coordinate and the whole
                    // entry is silently dropped.
                    int hash = val.IndexOf('#');
                    if (hash >= 0)
                        val = val.Substring(0, hash).Trim();

                    if (key.Length == 0 || val.Length == 0)
                        continue;   // declared but not filled in yet

                    string[] xy = val.Split(',');
                    short tx, ty;
                    if (xy.Length == 2 && short.TryParse(xy[0].Trim(), out tx) && short.TryParse(xy[1].Trim(), out ty))
                        _ovdAttackerSpawns[key] = new Tuple<short, short>(tx, ty);
                }
            }
            catch { /* unreadable file just means no attacker spawns are configured */ }
        }

        /// <summary>Attacker start tile for a base, if one has been configured.</summary>
        public bool TryGetAttackerSpawn(string baseName, out short tileX, out short tileY)
        {
            tileX = 0; tileY = 0;
            if (_ovdAttackerSpawns == null)
                LoadOvdSpawns();
            Tuple<short, short> t;
            if (_ovdAttackerSpawns == null || String.IsNullOrEmpty(baseName)
                || !_ovdAttackerSpawns.TryGetValue(baseName.Trim(), out t))
                return false;
            tileX = t.Item1; tileY = t.Item2;
            return true;
        }

        /// <summary>
        /// The OvD game clock. Deliberately ticker index 1, NOT index 3:
        /// UpdateCTFTickers() rewrites index 3 every PollCTF with the per-player "Personal Score"
        /// line, so a clock placed there is destroyed within a tick and takes its gameEnd callback
        /// with it. Index 1 is otherwise only used by the victory countdown, by which point the
        /// game is ending regardless.
        /// </summary>
        public void ApplyOvdGameTimer(int minutes)
        {
            // OvD never calls gameStart (the base setup has to survive), so this is the whistle:
            // start the class clocks and the game-length clock here or the whole draft would be
            // billed into the spread and the match length.
            ovdMatchStartTick = Environment.TickCount;
            ResetClassPlayTimes();
            arena.setTicker(1, 1, minutes * 60 * 100, "Time Left: ",
delegate ()
                {
                    arena.sendArenaMessage("&Time! The match is over.", 30);
                    arena.gameEnd();
                }
            );
        }

        /// <summary>
        /// Puts an OvD lineup where it belongs at match start.
        ///
        /// DEFENCE: the WHOLE team is warped to the base's drop/flag vicinity - the same coordinate
        /// SetupBase spawns the flag and resource stacks on. Called as soon as the base is CHOSEN,
        /// not at launch, so defence has the full setup window to build before offence arrives.
        /// Simplified from a Combat Engineer/Field Medic-only warp: singling out two classes meant
        /// nobody moved at all if the roster hadn't locked in those specific classes yet by the
        /// moment the base was chosen (silently - no message, no error), which is exactly what
        /// looked like "defence never made it into the base" from a live match.
        ///
        /// OFFENCE: everyone is warped to the base's configured attacker entry point. If that base
        /// has no entry configured yet the warp is skipped and the arena is told, rather than
        /// dumping the attackers somewhere wrong.
        /// </summary>
        public int PositionOvdDefense(string baseName, Team defense, bool announce = true)
        {
            string key = (baseName ?? "").Trim().ToUpper();
            if (!bases.ContainsKey(key) || defense == null)
                return 0;

            Base b = bases[key];
            int moved = 0;
            foreach (Player p in defense.ActivePlayers.ToList())
            {
                WarpPlayerToExactLocation(p, b.x / 16, b.y / 16);
                moved++;
            }
            if (announce && moved > 0)
                arena.sendArenaMessage(String.Format("&Defence ({0}) placed at {1} - start building.", moved, key));
            return moved;
        }

        /// <summary>
        /// Stages the offence at the base's entry point. Deliberately at LAUNCH rather than at base
        /// selection, so attackers cannot wander in during the defence's setup window.
        /// </summary>
        public int PositionOvdOffense(string baseName, Team offense, bool announce = true)
        {
            string key = (baseName ?? "").Trim().ToUpper();
            if (!bases.ContainsKey(key) || offense == null)
                return 0;

            LoadOvdSpawns();   // pick up edits made since the last match

            short ax, ay;
            if (!TryGetAttackerSpawn(key, out ax, out ay))
            {
                // Always said - it is actionable (OvDSpawns.txt), whoever asked.
                arena.sendArenaMessage(String.Format("!No attacker start position configured for {0} - offence spawns normally. (scripts/GameTypes/CTF/OvDSpawns.txt)", key));
                return 0;
            }

            int moved = 0;
            foreach (Player p in offense.ActivePlayers.ToList())
            {
                WarpPlayerToExactLocation(p, ax, ay);
                moved++;
            }
            if (announce && moved > 0)
                arena.sendArenaMessage(String.Format("*Offence ({0}) staged at the {1} entry point.", moved, key));
            return moved;
        }

        /// <summary>Both halves, for callers that want the whole placement at once.</summary>
        public void PositionOvdPlayers(string baseName, Team defense, Team offense)
        {
            PositionOvdDefense(baseName, defense);
            PositionOvdOffense(baseName, offense);
        }

        #endregion


        /// <summary>
        /// Clears the decks: puts EVERYONE on the "np" (not playing) team so the next game starts
        /// from a clean opt-in. This is the same thing the end-of-game handler does for OvD arenas
        /// (see EndGame), factored out so opening a mix or an OvD can do it too - otherwise the
        /// pool inherits whoever happened to be standing around and ?p means nothing.
        ///
        /// Players then type ?p to come back to the spec team and enter the pool.
        /// </summary>
        public void SpecAllToNotPlaying(string announcement)
        {
            if (arena.getTeamByName("np") == null)
                return;   // zone has no np team - nothing sensible to do

            foreach (Player p in arena.Players.ToList())
            {
                if (p == null)
                    continue;
                p.spec("np");
            }

            if (!String.IsNullOrEmpty(announcement))
                arena.sendArenaMessage(announcement, 30);
        }


        /// <summary>
        /// Clears the decks for a draft WITHOUT opting anyone out: everyone goes to the plain
        /// spectator team, which leaves them eligible for the pool. This is the opt-OUT model
        /// (Travis, 2026-09-12): everyone present is in the pool by default and ?np is the way
        /// out. SpecAllToNotPlaying is the opt-IN version and is still what the end-of-game
        /// handler uses. Players already sitting on np are left there - they said no.
        /// </summary>
        public void SpecAllToSpectators()
        {
            foreach (Player p in arena.Players.ToList())
            {
                if (p == null)
                    continue;
                if (p._team != null && p._team._name.Equals("np", StringComparison.OrdinalIgnoreCase))
                    continue;
                if (p.IsSpectator)
                    continue;
                p.spec("spec");
            }
        }

        /// <summary>
        /// Called when a mix/OvD session opens. Cancels any pending "Next game:" countdown and parks
        /// the game-state machine, so a queued gameStart cannot fire in the middle of a draft and
        /// flagReset() away the base setup. poll() then skips game-state management entirely while
        /// CTFMixManager.SuppressAutoStart is true.
        /// </summary>
        /// <summary>True only while StartGameQuietly() is inside arena.gameStart(): the OvD manager
        /// starting the game it needs under a match, which is bookkeeping, not news.</summary>
        private bool quietGameStart;

        /// <summary>arena.gameStart() without "Game has started!" / "All players have been healed".</summary>
        public void StartGameQuietly()
        {
            quietGameStart = true;
            try { arena.gameStart(); }
            finally { quietGameStart = false; }
        }

        public void HoldAutomaticGameStart()
        {
            arena.setTicker(1, 3, 0, "");            // kill a pending "Next game:" callback
            gameState = GameState.NotEnoughPlayers;  // a resting state; poll() will not advance it
        }

        /// <summary>
        /// The counterpart to HoldAutomaticGameStart, for a session that ends while a game is still
        /// live (*mix off mid-match, a cancelled draft over a running pub game). The hold parked the
        /// state machine in NotEnoughPlayers; left there with a game running, the next poll walks
        /// Init -> PreGame -> gameStart() and restarts the live game underneath everyone.
        /// </summary>
        public void ReleaseAutomaticGameStart()
        {
            if (arena._bGameRunning && gameState != GameState.ActiveGame)
                gameState = GameState.ActiveGame;
        }

        /// <summary>The base names this map supports for 5v5 / OvD, e.g. A7, D7, F6.</summary>
        public List<string> GetBaseNames()
        {
            return bases == null ? new List<string>() : bases.Keys.ToList();
        }

        #region Build table accessors (used by CTFRoles.cs)
        // buildSets is the zone's own build table, built in init() from `buildInputs`. Role
        // preferences validate against it so the role vocabulary and the ?build vocabulary can
        // never drift apart - adding a build to the zone makes it a selectable role for free.
        // Tuple layout: (items, description, buyCommand, classType, contributedBy).

        /// <summary>Canonical build name for a player-typed one, or null if it is not a build.</summary>
        public string ResolveBuildName(string name)
        {
            if (buildSets == null || String.IsNullOrEmpty(name))
                return null;
            string key = name.Trim().ToLower();
            return buildSets.ContainsKey(key) ? key : null;
        }

        /// <summary>The class a build belongs to (e.g. "Infantry"), or null.</summary>
        public string GetBuildClass(string name)
        {
            if (buildSets == null || String.IsNullOrEmpty(name))
                return null;
            Tuple<List<Tuple<string, ushort>>, string, string, string, string> data;
            return buildSets.TryGetValue(name.Trim().ToLower(), out data) ? data.Item4 : null;
        }

        /// <summary>Every build grouped by its class, for the ?role list catalogue.</summary>
        public Dictionary<string, List<string>> AllBuildsByClass()
        {
            var result = new Dictionary<string, List<string>>(StringComparer.OrdinalIgnoreCase);
            if (buildSets == null)
                return result;
            foreach (var kv in buildSets)
            {
                if (IsPrivateBuild(kv.Key))
                    continue;
                string cls = kv.Value.Item4;
                if (String.IsNullOrEmpty(cls))
                    cls = "Other";
                if (!result.ContainsKey(cls))
                    result[cls] = new List<string>();
                result[cls].Add(kv.Key);
            }
            foreach (var key in result.Keys.ToList())
                result[key].Sort(StringComparer.OrdinalIgnoreCase);
            return result;
        }
        #endregion


