        /// <summary>
        /// Detects the required class for a custom item list based on item combinations
        /// </summary>
        private string DetectRequiredClassForItems(string itemList, string currentClass)
        {
            if (string.IsNullOrWhiteSpace(itemList))
                return null;

            // Split the item list by commas and normalize each item
            string[] items = itemList.Split(',');
            var normalizedItems = new List<string>();
            var originalItems = new List<string>(); // Keep original items for @ prefix checking
            
            foreach (string item in items)
            {
                // Remove quantity specifiers (e.g., ":250", "#100") and normalize
                string cleanItem = item.Trim().ToLower();
                string originalItem = cleanItem; // Keep original for @ prefix checking
                
                if (cleanItem.Contains(":"))
                    cleanItem = cleanItem.Substring(0, cleanItem.IndexOf(":"));
                if (cleanItem.Contains("#"))
                    cleanItem = cleanItem.Substring(0, cleanItem.IndexOf("#"));
                
                // Store original item before removing @ prefix
                originalItems.Add(originalItem.Trim());
                
                if (cleanItem.StartsWith("@"))
                    cleanItem = cleanItem.Substring(1);
                
                normalizedItems.Add(cleanItem.Trim());
            }

            // Infantry Item detection list (expanded with common aliases and items)
            if (normalizedItems.Any(item => item == "kuchler a6 caw" || item == "caw" || 
                item == "flamethrower" || item == "fl" || 
                item == "sig arms m2 as" || item == "sg" || item == "sg2" ||
                (item == "maklov g2 acw" && currentClass != "Captain" && currentClass != "Sergeant")))
            {
                return "Infantry";
            }

            // Heavy Weapons: Item list contains heavy weapons (but exclude @ prefixed items like @mg)
            bool hasHeavyWeapon = false;
            for (int i = 0; i < normalizedItems.Count; i++)
            {
                string item = normalizedItems[i];
                string originalItem = originalItems[i];
                
                if ((item == "kamenev ac mk2" || item == "maklov ac mk2" || item == "ac" || item == "ac2" || item == "ac3" || // AC variants
                    item == "kamenev sc mk2" || item == "unittech sc 99r" || item == "sc" || item == "sc2" || // SC variants
                    item == "kuchler lmg249a" || item == "maklov lmg mk6" || item == "steiner mg94k" || item == "mg" || item == "lmg" || // MG/LMG variants
                    item == "micro missile launcher" || item == "mini missile launcher" || item == "mml" || item == "mml2" || // Missile launchers
                    item == "rpg") && // RPG
                    !originalItem.StartsWith("@"))
                {
                    hasHeavyWeapon = true;
                    break;
                }
            }
            
            if (hasHeavyWeapon)
            {
                return "Heavy Weapons";
            }

            // Field Medic: Item list contains "Medikit"
            if (normalizedItems.Any(item => item == "medikit" || item == "m" || item == "m2" || item == "medic beamer"))
            {
                return "Field Medic";
            }

            // Squad Leader: Item list contains "SL Beamer"
            if (normalizedItems.Any(item => item == "sl beamer" || item == "squad leader"))
            {
                return "Squad Leader";
            }

            // Combat Engineer: Item list contains "Engy Beamer"
            if (normalizedItems.Any(item => item == "engy beamer" || item == "engineer" || 
                item == "tbox" || item == "turret box" || item == "repair" || item == "Engineer Repair Kit"))
            {
                return "Combat Engineer";
            }

            // Infiltrator: Item list contains "Blink Generator"
            if (normalizedItems.Any(item => item == "blink generator" || item == "blink" || 
                item == "cloak" || item == "pr" || item == "pulse rifle"))
            {
                return "Infiltrator";
            }

            // Jump Trooper: Item list contains ("Maklov GL 8a" or "Kuchler GL MK II") and not already Captain or Sergeant
            if (normalizedItems.Any(item => (item == "maklov gl 8a" || item == "kuchler gl mk ii" || 
                 item == "gl" || item == "drop")) && 
                currentClass != "Captain" && currentClass != "Sergeant")
            {
                return "Jump Trooper";
            }

            return null; // No specific class detected
        }

        /// <summary>
        /// Maps class names to skill aliases for the swap command
        /// </summary>
        // ---------------------------------------------------------------------------------------------
        // Contributed builds: scripts/GameTypes/CTF/Builds.txt (server-written, never pushed).
        //   name<TAB>class<TAB>owner<TAB>?buy string<TAB>description<TAB>public|private
        // The hardcoded table in init() is the default set. Every built-in is LOCKED except the player-named
        // ones in EDITABLE_BUILT_IN; a locked build can only be changed by a Sysop (level 5). Anyone can add
        // a new build (named <alias>-<name>), and only its owner or a Sysop can edit or delete it. buildSets
        // is per arena, so the rows live in statics and each arena re-applies them when the version moves.
        // A build grants its items directly (no store check), so saving validates every item: it must exist,
        // be store-buyable, and not be a finite resource - but NOT be tied to the saver's class or skills.
        // A private build stays in buildSets (so autobuy and loadouts work for its owner) but only its owner
        // can buy, list or look it up. Rows without the 6th column (pre-10-17) are public.
        // ---------------------------------------------------------------------------------------------
        private static readonly string BUILDS_PATH = System.IO.Path.Combine("scripts", "GameTypes", "CTF", "Builds.txt");
        private static readonly HashSet<string> EDITABLE_BUILT_IN = new HashSet<string>(StringComparer.OrdinalIgnoreCase) { "slherth", "slbonds", "medbonds" };
        private const int BUILD_MAX_ITEMS = 40, BUILD_MAX_QTY = 2000, BUILD_MAX_PER_ALIAS = 12;
        private static readonly object _buildLock = new object();
        private static readonly Dictionary<string, string[]> _customRows = new Dictionary<string, string[]>(StringComparer.OrdinalIgnoreCase); // name -> class, owner, ?buy, description, public|private
        private static int _customVersion = 1;
        private static bool _customLoaded;
        private int _customApplied;
        private Dictionary<string, Tuple<List<Tuple<string, ushort>>, string, string, string, string>> _builtInBuilds;
        private HashSet<string> _builtInItemNames;

        private static readonly Dictionary<string, string> BUILD_CLASS_TOKENS = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
        {
            { "inf", "Infantry" }, { "hvy", "Heavy Weapons" }, { "heavy", "Heavy Weapons" }, { "med", "Field Medic" },
            { "sl", "Squad Leader" }, { "eng", "Combat Engineer" }, { "infil", "Infiltrator" }, { "jt", "Jump Trooper" }
        };

        private static bool IsSysop(Player p)
        {
            return p.PermissionLevel >= Data.PlayerPermission.Sysop || p.PermissionLevelLocal >= Data.PlayerPermission.Sysop;
        }

        // Called once from init(), right after buildSets is created.
        private void InitCustomBuilds()
        {
            _builtInBuilds = new Dictionary<string, Tuple<List<Tuple<string, ushort>>, string, string, string, string>>(buildSets);
            _builtInItemNames = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (var b in _builtInBuilds.Values)
                foreach (var it in b.Item1)
                    _builtInItemNames.Add(it.Item1);

            lock (_buildLock)
            {
                if (!_customLoaded)
                {
                    _customLoaded = true;
                    try
                    {
                        if (System.IO.File.Exists(BUILDS_PATH))
                        {
                            foreach (string raw in System.IO.File.ReadAllLines(BUILDS_PATH))
                            {
                                string line = raw.Trim();
                                if (line.Length == 0 || line[0] == '#') continue;
                                string[] f = line.Split('\t');
                                if (f.Length < 5) continue;
                                string name = f[0].Trim().ToLower();
                                if (IsLockedBuiltIn(name)) continue;       // a stale row can never override a locked default
                                string vis = f.Length > 5 && f[5].Trim().Equals("private", StringComparison.OrdinalIgnoreCase) ? "private" : "public";
                                _customRows[name] = new[] { f[1].Trim(), f[2].Trim(), f[3].Trim(), f[4].Trim(), vis };
                            }
                        }
                    }
                    catch (Exception ex) { Console.WriteLine("Builds.txt load failed: " + ex.Message); }
                    _customVersion++;
                }
            }
            SyncCustomBuilds();
        }

        private bool IsLockedBuiltIn(string name)
        {
            return _builtInBuilds != null && _builtInBuilds.ContainsKey(name) && !EDITABLE_BUILT_IN.Contains(name);
        }

        private static bool IsPrivateBuild(string name)
        {
            string[] row;
            lock (_buildLock)
                return name != null && _customRows.TryGetValue(name.Trim(), out row) && row[4] == "private";
        }

        // True when the name is somebody else's private build: it then acts as if it didn't exist for this player.
        private static bool IsHiddenBuild(Player player, string name)
        {
            string[] row;
            lock (_buildLock)
                return name != null && _customRows.TryGetValue(name.Trim(), out row) && row[4] == "private"
                    && !row[1].Equals(player._alias, StringComparison.OrdinalIgnoreCase);
        }

        // ?b / ?bw / ?bwd / ?d gate: refuses a request that names another player's private build.
        private bool RefusePrivateBuild(Player player, string payload)
        {
            if (string.IsNullOrWhiteSpace(payload)) return false;
            foreach (string request in payload.Split(','))
            {
                string name = request.Split(':')[0].Trim();
                if (name.EndsWith(" info", StringComparison.OrdinalIgnoreCase)) name = name.Substring(0, name.Length - 5).Trim();
                if (IsHiddenBuild(player, name)) { player.sendMessage(-1, "'" + name.ToLower() + "' is a private build."); return true; }
            }
            return false;
        }

        // Rebuilds this arena's buildSets from the built-ins plus the shared rows when they changed.
        private void SyncCustomBuilds()
        {
            if (_builtInBuilds == null || _customApplied == _customVersion) return;
            lock (_buildLock)
            {
                buildSets.Clear();
                foreach (var kv in _builtInBuilds) buildSets[kv.Key] = kv.Value;
                foreach (var kv in _customRows)
                {
                    string err;
                    var items = ValidateBuildItems(kv.Value[2], out err);
                    if (items == null) continue;
                    buildSets[kv.Key.ToLower()] = new Tuple<List<Tuple<string, ushort>>, string, string, string, string>(
                        items, kv.Value[3], "?buy " + kv.Value[2], kv.Value[0], kv.Value[1]);
                }
                _customApplied = _customVersion;
            }
        }

        private void SaveCustomBuildsFile()
        {
            // caller holds _buildLock
            try
            {
                var sb = new System.Text.StringBuilder();
                sb.AppendLine("# name<TAB>class<TAB>owner<TAB>items<TAB>description<TAB>public|private - written by the zone (?bsave / ?bdel). Do not push from local.");
                foreach (var kv in _customRows.OrderBy(k => k.Key, StringComparer.OrdinalIgnoreCase))
                    sb.AppendLine(kv.Key + "\t" + kv.Value[0] + "\t" + kv.Value[1] + "\t" + kv.Value[2] + "\t" + kv.Value[3] + "\t" + kv.Value[4]);
                string tmp = BUILDS_PATH + ".tmp";
                System.IO.File.WriteAllText(tmp, sb.ToString());
                if (System.IO.File.Exists(BUILDS_PATH)) System.IO.File.Delete(BUILDS_PATH);
                System.IO.File.Move(tmp, BUILDS_PATH);
            }
            catch (Exception ex) { Console.WriteLine("Builds.txt save failed: " + ex.Message); }
        }

        // Parses "a,b:5,@mg:#100" into items, checking each is something the store would sell. Null + err on any problem.
        private List<Tuple<string, ushort>> ValidateBuildItems(string items, out string err)
        {
            err = null;
            var result = new List<Tuple<string, ushort>>();
            if (string.IsNullOrWhiteSpace(items)) { err = "no items given"; return null; }
            string[] parts = items.Split(',');
            if (parts.Length > BUILD_MAX_ITEMS) { err = "too many items (max " + BUILD_MAX_ITEMS + ")"; return null; }
            foreach (string part in parts)
            {
                string[] pq = part.Split(':');
                string name = pq[0].Trim().ToLower();
                if (name.Length == 0) { err = "empty item name"; return null; }
                if (pq.Length > 2) { err = "bad quantity in '" + part.Trim() + "'"; return null; }
                ushort qty = 1;
                if (pq.Length == 2 && (!ushort.TryParse(pq[1].Trim().TrimStart('#'), out qty) || qty == 0 || qty > BUILD_MAX_QTY))
                { err = "bad quantity in '" + part.Trim() + "' (1-" + BUILD_MAX_QTY + ")"; return null; }
                if (name == "tox" || name == "tso" || name == "pan" || buildSets.ContainsKey(name))
                { err = "'" + name + "' is not allowed in a build"; return null; }
                ItemInfo it = AssetManager.Manager.getItemByName(name);     // the same lookup the build purchase uses
                if (it == null) { err = "unknown item '" + name + "'"; return null; }
                if (FiniteResourceItemIDs.Contains(it.id)) { err = "'" + name + "' is a finite resource"; return null; }
                // Store-buyable, or an item the default builds already use (basic / nades style multi-items).
                if (it.buyPrice <= 0 && !ChampStock().ContainsKey(it.id) && Skins.StockOf(it).id == it.id && (_builtInItemNames == null || !_builtInItemNames.Contains(name)))
                { err = "'" + name + "' can't be bought from the store"; return null; }   // a champion item or a skin is fine: the build buys its stock item
                result.Add(new Tuple<string, ushort>(name, qty));
            }
            return result;
        }

        // ?bsave <name> with no item list: the player's inventory as the ?buy string ?short prints. A short form is
        // used only when it is a one-slot macro for exactly that item (builds look names up with getItemByName
        // alone); basic and nades stay grouped like ?short. Minerals are dropped quietly, other items a build
        // can't grant are skipped and named.
        private string InventoryBuildItems(Player player, List<string> skipped)
        {
            var parts = new List<string>();
            var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (var inv in player._inventory.Values.ToList())
            {
                if (inv.item == null || inv.quantity <= 0 || FiniteResourceItemIDs.Contains(inv.item.id)) continue;
                ItemInfo baseItem = ChampBuildStock(player, inv.item) ?? Skins.StockOf(inv.item);   // a skin or a champion item saves as its stock item
                string full = baseItem.name.Trim().ToLower();
                string token = full, form;
                if (commandHandler.shortCommands.TryGetValue(full, out form))
                {
                    var macro = AssetManager.Manager.getItemByName(form) as ItemInfo.MultiItem;
                    if (form == "basic" || form == "nades") token = form;
                    else if (macro != null && macro.slots.Count(s => s.value != 0) == 1 && macro.slots.First(s => s.value != 0).value == baseItem.id)
                        token = form.ToLower();
                }
                if (!seen.Add(token)) continue;
                bool grouped = token == "basic" || token == "nades";
                string entry = grouped || inv.quantity == 1 ? token : token + ":" + Math.Min((int)inv.quantity, BUILD_MAX_QTY);
                string err;
                if (ValidateBuildItems(entry, out err) == null) { skipped.Add(inv.item.name); continue; }
                parts.Add(entry);
            }
            return string.Join(",", parts);
        }

        // ?bsave name [class] [public|private] [| description]   - saves your current inventory
        // ?bsave name [class] items [public|private] [| description]   /   ?bdel name
        private void HandleBuildSave(Player player, string payload)
        {
            SyncCustomBuilds();
            string desc = null;     // null keeps an existing build's description
            int bar = (payload ?? "").IndexOf('|');
            if (bar >= 0) { desc = payload.Substring(bar + 1).Trim(); payload = payload.Substring(0, bar).Trim(); }
            if (string.IsNullOrWhiteSpace(payload))
            {
                player.sendMessage(0, "#?bsave <name>  - saves your current inventory as a build everyone can use with ?b <name>");
                player.sendMessage(0, "#  Optional: private (only you can use it) or public, then | description.  Example: ?bsave mymed private | my medic");
                player.sendMessage(0, "#?bsave <name> <inf|hvy|med|sl|eng|infil|jt> <items> [| description]  - saves a typed item list instead");
                player.sendMessage(0, "#?bdel <name>  - delete one of yours.  Example: ?bsave mymed med cmp4,emp,ssc,td,basic,nades,tranq:10");
                return;
            }
            if (desc != null)
            {
                desc = desc.Replace("\t", " ").Replace("\r", " ").Replace("\n", " ");
                if (desc.Length > 120) desc = desc.Substring(0, 120);
                if (desc.Length == 0) desc = null;
            }

            // public / private may follow the name anywhere; the last one wins. null keeps the current setting.
            string vis = null;
            foreach (Match m in Regex.Matches(payload, @"(?<=\s)(public|private)(?=\s|$)", RegexOptions.IgnoreCase))
                vis = m.Value.ToLower();
            if (vis != null) payload = Regex.Replace(payload, @"\s(public|private)(?=\s|$)", "", RegexOptions.IgnoreCase).Trim();

            string[] words = payload.Split(new[] { ' ' }, 3, StringSplitOptions.RemoveEmptyEntries);
            string typed = words[0].ToLower();
            string cls = null, items = null;
            if (words.Length >= 2 && BUILD_CLASS_TOKENS.ContainsKey(words[1])) { cls = BUILD_CLASS_TOKENS[words[1]]; if (words.Length == 3) items = words[2]; }
            else if (words.Length >= 2) items = payload.Substring(payload.IndexOf(words[0], StringComparison.Ordinal) + words[0].Length).Trim();
            if (items != null) items = items.Replace("?buy ", "").Trim();

            // No item list: snapshot the inventory, as the class the player is now (unless they named one).
            bool fromInventory = items == null;
            var skipped = new List<string>();
            if (fromInventory)
            {
                items = InventoryBuildItems(player, skipped);
                if (items.Length == 0)
                {
                    player.sendMessage(-1, "Nothing in your inventory can go in a build" + (skipped.Count > 0 ? " (left out: " + string.Join(", ", skipped) + ")." : "."));
                    return;
                }
                if (cls == null)
                {
                    string current = GetPrimarySkillName(player);
                    cls = BUILD_CLASS_TOKENS.Values.FirstOrDefault(v => v.Equals(current, StringComparison.OrdinalIgnoreCase));
                }
            }

            bool sysop = IsSysop(player);
            string name = typed;
            if (!System.Text.RegularExpressions.Regex.IsMatch(typed, "^[a-z0-9_-]{2,24}$")) { player.sendMessage(-1, "Build names are 2-24 letters, numbers, - or _."); return; }
            lock (_buildLock)
            {
                string[] existing; bool isCustom = _customRows.TryGetValue(name, out existing);
                bool isBuiltIn = _builtInBuilds.ContainsKey(name);
                if (!isCustom && !isBuiltIn && !sysop)
                {
                    // New build: stored under the contributor's alias so nobody can squat a generic name.
                    string stem = new string(player._alias.ToLower().Where(c => char.IsLetterOrDigit(c)).ToArray());
                    if (stem.Length > 8) stem = stem.Substring(0, 8);
                    if (stem.Length == 0) stem = "x";
                    if (!name.StartsWith(stem + "-")) name = stem + "-" + name;
                    isCustom = _customRows.TryGetValue(name, out existing);
                    if (name.Length > 24) { player.sendMessage(-1, "That name is too long once your alias prefix is added."); return; }
                }
                string owner = isCustom ? existing[1] : (isBuiltIn ? _builtInBuilds[name].Item5 : player._alias);
                string curClass = isCustom ? existing[0] : (isBuiltIn ? _builtInBuilds[name].Item4 : null);

                if (IsLockedBuiltIn(name) && !sysop) { player.sendMessage(-1, "'" + name + "' is a default build and is locked."); return; }
                if ((isCustom || isBuiltIn) && !sysop && !owner.Equals(player._alias, StringComparison.OrdinalIgnoreCase))
                { player.sendMessage(-1, "'" + name + "' belongs to " + owner + "; only they (or a Sysop) can change it."); return; }
                if (cls == null) cls = curClass;
                if (cls == null) { player.sendMessage(-1, "A new build needs a class: inf, hvy, med, sl, eng, infil or jt."); return; }
                if (!isCustom && !sysop && _customRows.Values.Count(r => r[1].Equals(player._alias, StringComparison.OrdinalIgnoreCase)) >= BUILD_MAX_PER_ALIAS)
                { player.sendMessage(-1, "You already have " + BUILD_MAX_PER_ALIAS + " saved builds; ?bdel one first."); return; }
                if (vis == null) vis = isCustom ? existing[4] : "public";
                if (vis == "private" && isBuiltIn) { player.sendMessage(-1, "'" + name + "' is a default build, so it stays public."); return; }
                if (desc == null) desc = isCustom ? existing[3] : (isBuiltIn ? _builtInBuilds[name].Item2 : "Contributed build");

                string err;
                if (ValidateBuildItems(items, out err) == null) { player.sendMessage(-1, "Build not saved: " + err + "."); return; }
                _customRows[name] = new[] { cls, owner, items, desc, vis };
                _customVersion++;
                SaveCustomBuildsFile();
                player.sendMessage(0, "&Saved build '" + name + "' (" + cls + ", " + (vis == "private" ? "private - only you can use it" : "public")
                    + (fromInventory ? ") from your inventory" : ")") + ". Use it with ?b " + name + " or ?bw " + name + ".");
                if (fromInventory) player.sendMessage(0, "*?buy " + items);
                if (skipped.Count > 0) player.sendMessage(-1, "@Left out (a build can't give these): " + string.Join(", ", skipped));
            }
            SyncCustomBuilds();
        }

        private void HandleBuildDelete(Player player, string payload)
        {
            SyncCustomBuilds();
            string name = (payload ?? "").Trim().ToLower();
            lock (_buildLock)
            {
                string[] row;
                if (!_customRows.TryGetValue(name, out row)) { player.sendMessage(-1, "No saved build named '" + name + "' (default builds can't be deleted here)."); return; }
                if (!IsSysop(player) && !row[1].Equals(player._alias, StringComparison.OrdinalIgnoreCase))
                { player.sendMessage(-1, "'" + name + "' belongs to " + row[1] + "."); return; }
                _customRows.Remove(name);
                _customVersion++;
                SaveCustomBuildsFile();
                player.sendMessage(0, "&Deleted build '" + name + "'" + (_builtInBuilds.ContainsKey(name) ? " (back to the default)." : "."));
            }
            SyncCustomBuilds();
        }

        private string MapClassNameToSkillAlias(string className)
        {
            if (string.IsNullOrEmpty(className))
                return null;
                
            switch (className.ToLower())
            {
                case "infantry":
                    return "inf";
                case "heavy weapons":
                    return "hvy";  // Fixed: was "hw", should be "hvy" to match skillAliases dictionary
                case "field medic":
                    return "med";
                case "squad leader":
                    return "sl";
                case "combat engineer":
                    return "eng";
                case "infiltrator":
                    return "infil";
                case "jump trooper":
                    return "jt";
                default:
                    return null;
            }
        }

        /// <summary>
        /// Forces a player to leave their current vehicle safely
        /// </summary>
        private void ForcePlayerLeaveVehicle(Player player)
        {
            if (player._occupiedVehicle != null)
            {
                player._occupiedVehicle.playerLeave(true);
            }
        }

        /// <summary>
        /// ?b/?bw/?bwd used to run the build on Task.Run, so resetInventory, inventoryModify and class swaps edited
        /// the player off the arena thread while the arena serialized the same inventory (SC_Inventory "Collection
        /// was modified" in handlePlayerWarp). The purchase lookup now reads a file, so the async build chain never
        /// suspends: queued with arena.handleEvent it runs to completion on the arena thread. Faults are logged.
        /// </summary>
        private static void LogBuildFault(Task build, string what)
        {
            if (!build.IsCompleted)
            {
                build.ContinueWith(t => LogBuildFault(t, what));
                return;
            }
            if (build.IsFaulted)
                Console.WriteLine(String.Format("Error handling {0}: {1}", what, build.Exception.GetBaseException().Message));
        }

        /// <param name="asLoadout">True from the wipe-and-buy paths (?bw / ?bwd / autobuy / armory): the list is the player's
        /// whole loadout, so it is stored for autobuy (when they turn it on with ?ab) even when it is a custom item list. A
        /// plain ?b with a custom list is a purchase on top and leaves the stored loadout alone - otherwise a "?b @mg:250"
        /// top-up would become the next recall's entire rebuy.</param>
        public async Task HandleBuildCommand(Player player, string buildName, bool ignoreStoreCheck = false, bool asLoadout = false)
        {
            SyncCustomBuilds();
            // The item loop below changes the inventory unsynced and sends it once at the end (was one full 409-byte
            // inventory packet per item, 10-15 per build, on every autobuy respawn).
            bool invDirty = false;
            
            // Get the player's current class (needed for both list and buy operations)
            string playerClass = GetPrimarySkillName(player);
            bool classChanged = false;

            // Check for "list" payload - allow from anywhere for all players
            if (buildName.Equals("list", StringComparison.OrdinalIgnoreCase))
            {
                // Handle listing all builds for player's class (available from anywhere)
                var buildsForClass = buildSets
                    .Where(b => b.Value.Item4.Equals(playerClass, StringComparison.OrdinalIgnoreCase) && !IsHiddenBuild(player, b.Key))
                    .ToList();

                if (buildsForClass.Count > 0)
                {
                    player.sendMessage(0, "&Available builds for your class '" + playerClass + "':");
                    foreach (var build in buildsForClass)
                    {
                        string buildNameToDisplay = build.Key;
                        string description = build.Value.Item2;
                        string contributedBy = build.Value.Item5;

                        // Use different starting characters in player.sendMessage to format nicely
                        player.sendMessage(0, "*" + buildNameToDisplay + ": " + description + " (Contributed By: " + contributedBy + (IsPrivateBuild(build.Key) ? ", private" : "") + ")");
                    }
                }
                else
                {
                    player.sendMessage(-1, "No builds available for your class '" + playerClass + "'.");
                }
                return;
            }

            // Can you buy from this location? (Item restrictions are always enforced regardless of ignoreStoreCheck)
            if ((player._arena.getTerrain(player._state.positionX, player._state.positionY).storeEnabled) || (player.IsSpectator && player._server._zoneConfig.arena.spectatorStore) || ignoreStoreCheck)
            {

                // Auto-switch class logic
                string requiredClass = null;
                
                // Check if it's a preset build
                if (buildSets.ContainsKey(buildName.ToLower()))
                {
                    var buildData = buildSets[buildName.ToLower()];
                    requiredClass = buildData.Item4; // Class is stored in Item4
                }
                else
                {
                    // Check if it's a custom item list
                    requiredClass = DetectRequiredClassForItems(buildName, playerClass);
                }

                // Perform class switch if needed
                if (!string.IsNullOrEmpty(requiredClass) && !playerClass.Equals(requiredClass, StringComparison.OrdinalIgnoreCase))
                {
                    // Map the class name to the skill alias expected by the swap command
                    string skillAlias = MapClassNameToSkillAlias(requiredClass);
                    
                    if (player.IsDead)
                    {
                        // Queue the class swap for when the player respawns
                        queuedClassSwap[player] = skillAlias;
                        player.sendMessage(0, String.Format("You are dead. Your class will be changed to {0} when you respawn.", requiredClass));
                        classChanged = true;
                    }
                    else
                    {
                        // Class change is gated on the 500 energy like ?swap / F11 (ignoreEnergy false);
                        // if the swap was refused, stop here rather than buying a build for the wrong class.
                        commandHandler.HandleSwapCommand(player, skillAlias, CFG, this, true, false);
                        if (!GetPrimarySkillName(player).Equals(requiredClass, StringComparison.OrdinalIgnoreCase))
                            return;
                        // Update the current player class after the swap
                        playerClass = requiredClass;
                        classChanged = true;
                    }
                }

                // Force player to leave vehicle only if class actually changed
                if (classChanged && !player.IsSpectator)
                {
                    ForcePlayerLeaveVehicle(player);
                }

                // Auto-enable autobuy for preset builds (but don't disable it if already enabled)
                if (buildSets.ContainsKey(buildName.ToLower()))
                {
                    // Check if autobuy is currently disabled
                    bool currentlyEnabled = autoBuyEnabled.ContainsKey(player._alias) && autoBuyEnabled[player._alias];
                    if (!currentlyEnabled)
                    {
                        autoBuyEnabled[player._alias] = true;
                        player.sendMessage(0, "AutoBuy has been automatically enabled for this preset build.");
                    }
                    // Auto-drop follows OnDefaultLoadout, so it is on from here without a flag.
                    // Auto-pickup comes on too, following this build - unless they typed ?ap off.
                    EnableAutoPickupForDefaultLoadout(player);
                }

                if (string.IsNullOrWhiteSpace(buildName))
                {
                    // List the description of the different payloads available
                    player.sendMessage(0, "#------------------------");
                    player.sendMessage(0, "~?build <buildName> ---- Applies the specified build.");
                    player.sendMessage(0, "~?build list ---- Lists all builds available for your class.");
                    player.sendMessage(0, "~?build <buildName> info ---- Displays information about a specific build.");
                    player.sendMessage(0, "~?build random ---- Selects a random build for your class.");
                    player.sendMessage(0, "#------------------------");
                    player.sendMessage(0, "~?b <buildName> ---- short for ?build");
                    player.sendMessage(0, "~?bw <buildName> ---- wipes inventory, then purchases build");
                    player.sendMessage(0, "~?bsave <name> ---- saves your current inventory as a build (?bsave alone for options); ?bdel <name> deletes it");
                    player.sendMessage(0, "~?bwd <buildName> ---- wipes inventory, purchases build + excess ammo for drops (then use command ?d to drop excess ammo)");
                    player.sendMessage(0, "~?d ---- drops excess ammo after using ?bwd <buildName> command");
                    player.sendMessage(0, "#------------------------");
                    return;
                }

                // Check for "info" payload
                if (buildName.EndsWith(" info", StringComparison.OrdinalIgnoreCase))
                {
                    // Get the build name without the " info" suffix
                    string buildNameWithoutInfo = buildName.Substring(0, buildName.Length - 5).Trim();

                    if (buildSets.ContainsKey(buildNameWithoutInfo.ToLower()))
                    {
                        var buildData = buildSets[buildNameWithoutInfo.ToLower()];

                        string description = buildData.Item2;
                        string buyCommand = buildData.Item3;
                        string classType = buildData.Item4;
                        string contributedBy = buildData.Item5;

                        // Display the build information using player.sendMessage and string formatting
                        player.sendMessage(0, "#------------------------");
                        player.sendMessage(0, "Build Name: " + buildNameWithoutInfo + "       Contributed By: " + contributedBy);
                        player.sendMessage(0, "&" + description);
                        player.sendMessage(0, "*" + buyCommand);
                        player.sendMessage(0, "#------------------------");
                    }
                    else
                    {
                        player.sendMessage(-1, "Build '" + buildNameWithoutInfo + "' not found.");
                    }
                    return;
                }

                // Check if the buildName is "random"
                if (buildName.Equals("random", StringComparison.OrdinalIgnoreCase))
                {
                    var availableBuilds = buildSets
                        .Where(b => b.Value.Item4.Equals(playerClass, StringComparison.OrdinalIgnoreCase) && !IsHiddenBuild(player, b.Key))
                        .ToList();

                    if (availableBuilds.Count > 0)
                    {
                        // Select a random build
                        var randomBuild = availableBuilds[new Random().Next(availableBuilds.Count)];
                        buildName = randomBuild.Key;
                        player.sendMessage(0, "Selected random build: " + buildName);
                    }
                    else
                    {
                        player.sendMessage(-1, "No available builds for your class.");
                        return;
                    }
                }

                // Now proceed to handle the buildName, which may include multiple items/builds, split by commas
                // Split the buildName by commas to handle multiple items
                string[] itemRequests = buildName.Split(',');

                foreach (string request in itemRequests)
                {
                    // Split each request by colon to separate item name and quantity
                    string[] parts = request.Split(':');
                    string itemName = parts[0].Trim().ToLower(); // Normalize item name
                    string quantitySpecifier = parts.Length > 1 ? parts[1].Trim() : "1"; // Default quantity is additive 1



                    // Check if it's a build
                    if (buildSets.ContainsKey(itemName))
                    {
                        // Handle build logic
                        player.sendMessage(0, "*Found build: " + itemName + ". Processing items...");
                        var buildData = buildSets[itemName];
                        List<Tuple<string, ushort>> buildItems = buildData.Item1;

                        bool containsPowercell = buildItems.Any(item => 
                            item.Item1.Equals("cellh", StringComparison.OrdinalIgnoreCase) ||
                            item.Item1.Equals("cellm", StringComparison.OrdinalIgnoreCase) ||
                            item.Item1.Equals("celll", StringComparison.OrdinalIgnoreCase) ||
                            item.Item1.Equals("heavy powercell", StringComparison.OrdinalIgnoreCase) ||
                            item.Item1.Equals("medium powercell", StringComparison.OrdinalIgnoreCase) ||
                            item.Item1.Equals("light powercell", StringComparison.OrdinalIgnoreCase));

                        // Add to the player's energy the amount from the 'extraCapacity' property on the item based on cell type
                        if (containsPowercell)
                            {
                                // Map shortened names to full names if needed
                                string fullItemName = itemName;
                                if (itemName.Equals("cellh", StringComparison.OrdinalIgnoreCase))
                                    fullItemName = "Heavy PowerCell";
                                else if (itemName.Equals("cellm", StringComparison.OrdinalIgnoreCase))
                                    fullItemName = "Medium PowerCell";
                                else if (itemName.Equals("celll", StringComparison.OrdinalIgnoreCase))
                                    fullItemName = "Light PowerCell";
                                
                                // Get the actual powercell item with the proper name
                                ItemInfo actualItem = AssetManager.Manager.getItemByName(itemName);
                                if (fullItemName != itemName)
                                    actualItem = AssetManager.Manager.getItemByName(fullItemName);
                                
                                // Get the item info for the powercell's extraCapacity property
                                ItemInfo.UtilityItem powercell = actualItem as ItemInfo.UtilityItem;
                                if (powercell != null)
                                {
                                    // a new cell adds room, not energy (Travis 10-24): this refilled them on every build with a cell
                                    //player.sendMessage(0, string.Format("~{0} energy added to your energy.", energyToAdd));
                                }
                            }

                        // Bundles in the build (@mg:180, nades, basic, rgs1...) count as what is inside them: one target per item for
                        // the whole build, plain entries of the same item added in, so a top-up never stacks another bundle on top.
                        Dictionary<int, int> bundleTargets = BundleTargets(player, buildItems);
                        foreach (var item in buildItems)
                        {
                            ItemInfo prize = AssetManager.Manager.getItemByName(item.Item1);
                            if (prize != null && IsPlainBundle(prize))
                                continue;   // applied after the loop
                            if (prize != null)
                            {
                                // Check for product conversions (like Rainbow CAW) in builds too
                                try
                                {
                                    string convertedItemName = skinsEnabled ? await ProductPurchaseManager.GetConvertedItemName(player._alias, prize.name) : prize.name;   // *skins off: no perk conversions
                                    
                                    // If conversion happened, get the new item
                                    if (!convertedItemName.Equals(prize.name, StringComparison.OrdinalIgnoreCase))
                                    {
                                        ItemInfo convertedItem = AssetManager.Manager.getItemByName(convertedItemName);
                                        if (convertedItem != null)
                                        {
                                            prize = convertedItem;
                                            player.sendMessage(0, string.Format("&Converted to {0}! (Premium Product)", convertedItemName));
                                        }
                                    }
                                }
                                catch (Exception ex)
                                {
                                    Console.WriteLine(string.Format("Error checking product conversion in build for {0}: {1}", player._alias, ex.Message));
                                    // Continue with original item if conversion fails
                                }

                                if (FiniteResourceItemIDs.Contains(prize.id))
                                {
                                    continue;
                                }

                                int desiredQuantity = item.Item2;
                                int fromBundles;
                                if (bundleTargets.TryGetValue(prize.id, out fromBundles))
                                {
                                    desiredQuantity += fromBundles;
                                    bundleTargets.Remove(prize.id);
                                }
                                int currentQuantity = player.getInventoryAmount(prize.id);

                                // By default, apply fixed quantity logic
                                if (currentQuantity < desiredQuantity)
                                {
                                    // Award the difference to reach the desired quantity
                                    int amountToAdd = desiredQuantity - currentQuantity;
                                    int hg = HardEconomy.Grant(player, prize, amountToAdd);       // TP Hard: charged, skill-checked
                                    if (hg > 0) { player.inventoryModify(false, prize, hg); invDirty = true; }
                                }
                                else if (currentQuantity > desiredQuantity)
                                {
                                    // Remove the excess to match the desired quantity
                                    int amountToRemove = currentQuantity - desiredQuantity;
                                    player.inventoryModify(false, prize, -amountToRemove); invDirty = true;
                                    player.sendMessage(0, "~" + amountToRemove + "x" + prize.name + " has been removed to match the desired quantity of " + desiredQuantity + ".");
                                }
                            }
                            else
                            {
                                player.sendMessage(-1, "@Failed to find item " + item.Item1 + ".");
                            }
                        }
                        foreach (var bt in bundleTargets)
                            if (SetItemQuantity(player, bt.Key, HardEconomy.Target(player, bt.Key, bt.Value)))
                                invDirty = true;
                    }
                    else
                    {
                        // Handle store item logic
                        // First, try to find the item as-is (this handles Multi-Items like "caw")
                        ItemInfo storeItem = AssetManager.Manager.getItemByName(itemName);
                        
                        // If not found, try to convert short command to full item name
                        if (storeItem == null)
                        {
                            var shortToFullMapping = commandHandler.shortCommands.FirstOrDefault(kvp => 
                                kvp.Value.Equals(itemName, StringComparison.OrdinalIgnoreCase));
                            
                            if (!shortToFullMapping.Equals(default(KeyValuePair<string, string>)))
                            {
                                string fullItemName = shortToFullMapping.Key;
                                storeItem = AssetManager.Manager.getItemByName(fullItemName);
                            }
                        }
                        if (storeItem != null)
                        {
                            storeItem = ChampBuildStock(player, storeItem) ?? Skins.StockOf(storeItem);   // a champion item or a skin: buy its stock item (?champ / the skin sweep turn it back)

                            // Check if this item is purchasable from the store (buyPrice > 0)
                            if (storeItem.buyPrice <= 0)
                            {
                                player.sendMessage(-1, String.Format("Item '{0}' cannot be purchased from the store.", storeItem.name));
                                continue;
                            }

                            // Check if this is a restricted item that shouldn't be purchasable
                            if (FiniteResourceItemIDs.Contains(storeItem.id))
                            {
                                player.sendMessage(-1, String.Format("Item '{0}' cannot be purchased from the store.", storeItem.name));
                                continue;
                            }

                            // Also check for restricted item shorthand names
                            if (itemName.Equals("tox", StringComparison.OrdinalIgnoreCase) ||
                                itemName.Equals("tso", StringComparison.OrdinalIgnoreCase) ||
                                itemName.Equals("pan", StringComparison.OrdinalIgnoreCase))
                            {
                                player.sendMessage(-1, String.Format("Item '{0}' cannot be purchased from the store.", itemName));
                                continue;
                            }

                            // Check for product conversions (like Rainbow CAW)
                            string finalItemName = storeItem.name;
                            try
                            {
                                // Get converted item name based on player's purchases
                                finalItemName = skinsEnabled ? await ProductPurchaseManager.GetConvertedItemName(player._alias, storeItem.name) : storeItem.name;   // *skins off: no perk conversions
                                
                                // If conversion happened, get the new item
                                if (!finalItemName.Equals(storeItem.name, StringComparison.OrdinalIgnoreCase))
                                {
                                    ItemInfo convertedItem = AssetManager.Manager.getItemByName(finalItemName);
                                    if (convertedItem != null)
                                    {
                                        storeItem = convertedItem;
                                        player.sendMessage(0, string.Format("&Converted to {0}! (Premium Product)", finalItemName));
                                    }
                                }
                            }
                            catch (Exception ex)
                            {
                                Console.WriteLine(string.Format("Error checking product conversion for {0}: {1}", player._alias, ex.Message));
                                // Continue with original item if conversion fails
                            }
                                      
                            // Determine if the command specifies fixed quantity or additive quantity
                            bool isFixed = quantitySpecifier.StartsWith("#");
                            int quantity;
                            if (!int.TryParse(quantitySpecifier.TrimStart('#'), out quantity))
                            {   // a throw here would skip the one inventory sync at the end of the loop
                                player.sendMessage(-1, String.Format("Bad quantity '{0}' for {1}.", quantitySpecifier, itemName));
                                continue;
                            }

                            int bundleSet = isFixed ? SetBundleQuantity(player, storeItem, quantity) : -1;
                            if (bundleSet >= 0)
                            {   // a bundle (@mg, nades, rgs1...): each item inside it set to its share, not N more bundles
                                if (bundleSet > 0) invDirty = true;
                            }
                            else if (isFixed)
                            {
                                // Fixed quantity logic: Match the exact quantity, removing excess if necessary
                                int currentQuantity = player.getInventoryAmount(storeItem.id);

                                if (currentQuantity < quantity)
                                {
                                    // Award the difference to reach the desired quantity
                                    int amountToAdd = quantity - currentQuantity;
                                    { int hg = HardEconomy.Grant(player, storeItem, amountToAdd); if (hg > 0) { player.inventoryModify(false, storeItem, hg); invDirty = true; } }
                                }
                                else if (currentQuantity > quantity)
                                {
                                    // Remove the excess to match the desired quantity
                                    int amountToRemove = currentQuantity - quantity;
                                    player.inventoryModify(false, storeItem, -amountToRemove); invDirty = true;
                                    player.sendMessage(0, "~" + amountToRemove + "x" + storeItem.name + " has been removed to match the desired quantity of " + quantity + ".");
                                }
                            }
                            else
                            {
                                // Additive quantity logic: Just add the amount to inventory
                                { int hg = HardEconomy.Grant(player, storeItem, quantity); if (hg > 0) { player.inventoryModify(false, storeItem, hg); invDirty = true; } }
                            }
                            
                            // Check if this is a powercell purchase and handle energy addition
                            bool isPowercell = itemName.Equals("cellh", StringComparison.OrdinalIgnoreCase) ||
                                             itemName.Equals("cellm", StringComparison.OrdinalIgnoreCase) ||
                                             itemName.Equals("celll", StringComparison.OrdinalIgnoreCase) ||
                                             itemName.Equals("heavy powercell", StringComparison.OrdinalIgnoreCase) ||
                                             itemName.Equals("medium powercell", StringComparison.OrdinalIgnoreCase) ||
                                             itemName.Equals("light powercell", StringComparison.OrdinalIgnoreCase);

                            // Add to the player's energy the amount from the 'extraCapacity' property on the item based on cell type
                            if (isPowercell)
                            {
                                // Map shortened names to full names if needed
                                string fullItemName = itemName;
                                if (itemName.Equals("cellh", StringComparison.OrdinalIgnoreCase))
                                    fullItemName = "Heavy PowerCell";
                                else if (itemName.Equals("cellm", StringComparison.OrdinalIgnoreCase))
                                    fullItemName = "Medium PowerCell";
                                else if (itemName.Equals("celll", StringComparison.OrdinalIgnoreCase))
                                    fullItemName = "Light PowerCell";
                                
                                // Get the actual powercell item with the proper name
                                ItemInfo actualItem = storeItem;
                                if (fullItemName != itemName)
                                    actualItem = AssetManager.Manager.getItemByName(fullItemName);
                                
                                // Get the item info for the powercell's extraCapacity property
                                ItemInfo.UtilityItem powercell = actualItem as ItemInfo.UtilityItem;
                                if (powercell != null)
                                {
                                    // a new cell adds room, not energy (Travis 10-24): buying, dropping and rebuying one refilled them
                                    //player.sendMessage(0, string.Format("~{0} energy added to your energy.", energyToAdd));
                                }
                            }
                        }
                        else
                        {
                            player.sendMessage(-1, "Item '" + itemName + "' not found.");
                        }
                    }
                }
                if (invDirty)
                    player.syncInventory();
                HardEconomy.Summarize(player);        // TP Hard: what the build cost / could not be bought
                // Also check for product purchase conversions (champion items and the Rainbow CAW are item skins now: the sweep below)
                await ConvertProductPurchaseItems(player);
                
                // Process cosmetic item conversions for specific players (works regardless of champion item status)
                ProcessCosmeticItemConversions(player);
                
                // Save the loadout for auto buy: a preset build, or a custom item list bought as a whole loadout
                // (asLoadout). Always overwrite the previous one.
                if (asLoadout || buildSets.ContainsKey(buildName.ToLower()))
                {
                    string dummy;
                    persistentBuilds.TryRemove(player._alias, out dummy);
                    persistentBuilds.TryAdd(player._alias, buildName); // Save the build string (preset name or custom items)
                    // ...for the class it is bought as - or, bought while dead, the class the queued swap will make them.
                    string forClass = GetPrimarySkillName(player), queued, queuedName;
                    if (player.IsDead && queuedClassSwap.TryGetValue(player, out queued) && CommandHandler.skillAliases.TryGetValue(queued, out queuedName))
                        forClass = queuedName;
                    persistentBuildClass[player._alias] = forClass;

                    // A persistent build and a premade both want to own the respawn loadout, and BOTH run
                    // in playerSpawn - the premade tops its kit up, then WipeAndBuy wipes the inventory
                    // and buys the build, silently defeating the premade. Whichever the player chose most
                    // recently should win: buying a premade already clears persistentBuilds (via
                    // PlayerShopSkillPurchase), so setting a build must clear the premade.
                    premadeActiveSetup.Remove(player._alias.ToLower());

                    // ?autopickup follows the loadout, so it follows this one from now on.
                    RefreshAutoPickupForLoadout(player);
                    // ...and a preset build switches it on now that the build is saved. The call before the purchase saw the
                    // OLD loadout - none at all after a class change (?bw med from another class) - so it stayed off (Eric
                    // 10-24: rockets came back as a heavy, tranqs never did as a medic). Does nothing when it is already on.
                    if (buildSets.ContainsKey(buildName.ToLower()))
                        EnableAutoPickupForDefaultLoadout(player);
                }
            }
            else
            {
                player.sendMessage(-1, "You cannot purchase builds from this location");
            }
            
            return;
        }

        private void WipeInventory(Player player, string payload)
        {
            int terrainID = player._arena.getTerrainID(player._state.positionX, player._state.positionY);
            if (terrainID == 4 || terrainID == 3 || terrainID == 1 || terrainID == 2 || player.IsSpectator){
                DropMineralsBeforeWipe(player);
                player.resetInventory(true);
                player.sendMessage(0, "Your inventory has been wiped.");
            } else {
                player.sendMessage(0, "Cannot wipe inventory from this location.");
            }
            return;
        }

        // Dictionary to remember the last used build for each player
        private Dictionary<Player, string> lastUsedBuild = new Dictionary<Player, string>();
        


        // Wipes inventory, then buys the build
        // ?bw / ?bwd: the energy a player had when the wipe ran (Travis 10-24). The wipe dropped them to the class's base pool even
        // with a PowerCell, and a build with a cell refilled them; now they keep what they had, capped at the new loadout's pool
        // (base + its cells): a cell they already carried keeps its extra energy, a new one only adds room, never energy.
        private Dictionary<Player, short> energyBeforeWipe = new Dictionary<Player, short>();

        private void RestoreEnergyAfterBuild(Player player)
        {
            short before;
            if (player == null || !energyBeforeWipe.TryGetValue(player, out before))
                return;
            energyBeforeWipe.Remove(player);
            if (player.IsDead || player.IsSpectator || player._baseVehicle == null || player._baseVehicle._type == null)
                return;
            int pool = player._baseVehicle._type.EnergyMax;
            foreach (var inv in player._inventory.Values)
            {
                var util = inv.item as ItemInfo.UtilityItem;
                if (util != null && util.extraCapacity > 0 && inv.quantity > 0)
                    pool += util.extraCapacity;
            }
            player.setEnergy((short)Math.Max(0, Math.Min((int)before, Math.Min(pool, (int)short.MaxValue))));
        }

        /// <summary>A multi-item that only hands out items (no cash, energy, health, repair or experience): @mg, nades, basic, rgs1...</summary>
        private static bool IsPlainBundle(ItemInfo item)
        {
            var multi = item as ItemInfo.MultiItem;
            return multi != null && multi.Cash == 0 && multi.Energy == 0 && multi.Health == 0 && multi.Repair == 0 && multi.Experience == 0
                && multi.slots.Any(sl => sl.value != 0);
        }

        /// <summary>
        /// What N of a bundle holds, per item: each slot is one of that item per bundle, skipping what the player's class may not
        /// carry (the engine skips those too) and the finite minerals. A multi-item is never held itself, so counting it always
        /// read 0 and every #N or build top-up stacked N more bundles (Travis 10-24: 120 Ammo MG, ?b @mg:#120 = 240).
        /// </summary>
        private Dictionary<int, int> BundleShares(Player player, ItemInfo item, int bundles)
        {
            var shares = new Dictionary<int, int>();
            var multi = item as ItemInfo.MultiItem;
            if (multi == null || bundles <= 0)
                return shares;
            foreach (var slot in multi.slots)
            {
                if (slot.value == 0 || FiniteResourceItemIDs.Contains(slot.value))
                    continue;
                ItemInfo inner = AssetManager.Manager.getItemByID(slot.value);
                if (inner == null || !InfServer.Logic.Logic_Assets.SkillCheck(player, inner.skillLogic))
                    continue;
                shares[slot.value] = (shares.ContainsKey(slot.value) ? shares[slot.value] : 0) + bundles;
            }
            return shares;
        }

        private Dictionary<int, int> BundleTargets(Player player, List<Tuple<string, ushort>> buildItems)
        {
            var targets = new Dictionary<int, int>();
            foreach (var entry in buildItems)
            {
                ItemInfo item = AssetManager.Manager.getItemByName(entry.Item1);
                if (item == null || !IsPlainBundle(item))
                    continue;
                foreach (var kv in BundleShares(player, item, entry.Item2))
                    targets[kv.Key] = (targets.ContainsKey(kv.Key) ? targets[kv.Key] : 0) + kv.Value;
            }
            return targets;
        }

        /// <summary>Sets the player's count of one item (unsynced). True when it changed.</summary>
        private bool SetItemQuantity(Player player, int itemId, int target)
        {
            ItemInfo item = AssetManager.Manager.getItemByID(itemId);
            if (item == null)
                return false;
            int have = player.getInventoryAmount(itemId);
            if (have == target)
                return false;
            player.inventoryModify(false, item, target - have);
            if (have > target)
                player.sendMessage(0, "~" + (have - target) + "x" + item.name + " has been removed to match the desired quantity of " + target + ".");
            return true;
        }

        /// <summary>?b <bundle>:#N: each item inside the bundle set to N bundles' worth. -1 = not a plain bundle (handled as before),
        /// 0 = already there, 1 = changed.</summary>
        private int SetBundleQuantity(Player player, ItemInfo item, int bundles)
        {
            if (!IsPlainBundle(item))
                return -1;
            bool changed = false;
            foreach (var kv in BundleShares(player, item, bundles))
            {
                int want = kv.Value;
                if (HardEconomy.On)
                {   // TP Hard: only what the player can pay for goes in; taking items out is always free
                    int cur = player.getInventoryAmount(kv.Key);
                    ItemInfo bi = player._server._assets.getItemByID(kv.Key);
                    if (want > cur && bi != null) want = cur + HardEconomy.Grant(player, bi, want - cur);
                }
                changed |= SetItemQuantity(player, kv.Key, want);
            }
            return changed ? 1 : 0;
        }

        private async Task WipeAndBuy(Player player, string buildName, bool ignoreStoreCheck = false)
        {
            SyncCustomBuilds();
            
            // PRE-SWAP: Do class swapping BEFORE inventory operations to avoid race condition
            string playerClass = GetPrimarySkillName(player);
            string requiredClass = null;
            bool classChanged = false;
            
            // Check if it's a preset build
            if (buildSets.ContainsKey(buildName.ToLower()))
            {
                var buildData = buildSets[buildName.ToLower()];
                requiredClass = buildData.Item4; // Class is stored in Item4
            }
            else if (!string.IsNullOrWhiteSpace(buildName) && buildName.ToLower() != "random")
            {
                // Check if it's a custom item list
                requiredClass = DetectRequiredClassForItems(buildName, playerClass);
            }

            // Perform class switch BEFORE inventory wipe if needed
            if (!string.IsNullOrEmpty(requiredClass) && !playerClass.Equals(requiredClass, StringComparison.OrdinalIgnoreCase))
            {
                string skillAlias = MapClassNameToSkillAlias(requiredClass);
                
                if (!string.IsNullOrEmpty(skillAlias) && CommandHandler.skillAliases.ContainsKey(skillAlias))
                {
                    if (player.IsDead)
                    {
                        queuedClassSwap[player] = skillAlias;
                        player.sendMessage(0, String.Format("You are dead. Your class will be changed to {0} when you respawn.", requiredClass));
                        classChanged = true;
                    }
                    else
                    {
                        // Gated on the 500 energy like ?swap / F11; a refused swap aborts the build.
                        commandHandler.HandleSwapCommand(player, skillAlias, CFG, this, true, false);
                        if (!GetPrimarySkillName(player).Equals(requiredClass, StringComparison.OrdinalIgnoreCase))
                            return;
                        playerClass = requiredClass; // Update for the rest of the process
                        classChanged = true;
                        
                        // Auto-occupy on a class change (the Swap trigger; the pack is checked when it fires, after the build)
                        InitiateAutoOccupy(player, "class change from build command");
                    }
                }
            }
            
            // Force player to leave vehicle only if class actually changed
            if (classChanged && !player.IsSpectator)
            {
                ForcePlayerLeaveVehicle(player);
            }
            
            int terrainID = player._arena.getTerrainID(player._state.positionX, player._state.positionY);
            if (terrainID == 4 || terrainID == 3 || terrainID == 1 || terrainID == 2 || player.IsSpectator || ignoreStoreCheck){
                // Take note of the items and their quantities before resetting the inventory
                Dictionary<int, int> itemsToGiveBack = new Dictionary<int, int>();
                HashSet<int> itemsToDeprive = new HashSet<int> { 2005, 2007, 2009, 9, 10, 11 };
                foreach (int itemID in itemsToDeprive)
                {
                    int currentCount = player.getInventoryAmount(itemID);
                    itemsToGiveBack.Add(itemID, currentCount);
                }

                // Wipe + give-backs go out as ONE inventory packet (each synced call sent the full 409-byte inventory,
                // even for a give-back of 0).
                energyBeforeWipe[player] = player._state.energy;   // RestoreEnergyAfterBuild puts it back once the build is in
                HardEconomy.NoteWipe(player);                                  // TP Hard: what is held now is not charged again
                player.resetInventory(false);
                player.sendMessage(0, "Your inventory has been wiped.");

                // Give back the items and their quantities after resetting the inventory
                foreach (var item in itemsToGiveBack)
                {
                    ItemInfo itemInfo = player._server._assets.getItemByID(item.Key);
                    if (itemInfo != null && item.Value > 0)
                    {
                        player.inventoryModify(false, itemInfo, item.Value);
                        // A mineral that didn't fit back (weight / class limits) goes on the ground, not into the void.
                        int shortBy = item.Value - player.getInventoryAmount(item.Key);
                        if (IsMineral(item.Key) && shortBy > 0) DropMineralHere(player, itemInfo, shortBy);
                    }
                }
                player.syncInventory();
                        } else {
                player.sendMessage(0, "Cannot wipe inventory from this location.");
                return;
            }

            // Handle the case where buildName is "random"
            if (string.IsNullOrWhiteSpace(buildName) || buildName.ToLower() == "random")
            {
                await HandleBuildCommand(player, "random");
                RestoreEnergyAfterBuild(player);
                
                return;
            }

            if (ignoreStoreCheck){
                await HandleBuildCommand(player, buildName, true, true);
            } else {
                await HandleBuildCommand(player, buildName, false, true);
            }
            RestoreEnergyAfterBuild(player);
            
            
            
            return;
        }

        // Wipes inventory, buys the build, and fills up all possible ammo types to their maximum
        private async Task WipeBuyAndMaxAmmo(Player player, string buildName)
        {
            int terrainID = player._arena.getTerrainID(player._state.positionX, player._state.positionY);
            if (terrainID == 4 || terrainID == 3 || terrainID == 1 || terrainID == 2 || player.IsSpectator){
                // Take note of the items and their quantities before resetting the inventory
                Dictionary<int, int> itemsToGiveBack = new Dictionary<int, int>();
                HashSet<int> itemsToDeprive = new HashSet<int> { 2005, 2007, 2009, 2, 9, 10, 11 };
                foreach (int itemID in itemsToDeprive)
                {
                    int currentCount = player.getInventoryAmount(itemID);
                    itemsToGiveBack.Add(itemID, currentCount);
                }

                // Wipe + give-backs go out as ONE inventory packet (each synced call sent the full 409-byte inventory,
                // even for a give-back of 0).
                energyBeforeWipe[player] = player._state.energy;   // RestoreEnergyAfterBuild puts it back once the build is in
                HardEconomy.NoteWipe(player);                                  // TP Hard: what is held now is not charged again
                player.resetInventory(false);
                player.sendMessage(0, "Your inventory has been wiped.");

                // Give back the items and their quantities after resetting the inventory
                foreach (var item in itemsToGiveBack)
                {
                    ItemInfo itemInfo = player._server._assets.getItemByID(item.Key);
                    if (itemInfo != null && item.Value > 0)
                    {
                        player.inventoryModify(false, itemInfo, item.Value);
                        // A mineral that didn't fit back (weight / class limits) goes on the ground, not into the void.
                        int shortBy = item.Value - player.getInventoryAmount(item.Key);
                        if (IsMineral(item.Key) && shortBy > 0) DropMineralHere(player, itemInfo, shortBy);
                    }
                }
                player.syncInventory();
            } else {
                player.sendMessage(0, "Cannot wipe inventory from this location.");
                return;
            }
            
            // Store build name
            lastUsedBuild[player] = buildName.ToLower();
            //player.sendMessage(0, "~Build name stored: " + buildName.ToLower());

            // Handle the case where buildName is "random"
            if (string.IsNullOrWhiteSpace(buildName) || buildName.ToLower() == "random")
            {

                await HandleBuildCommand(player, "random");
                RestoreEnergyAfterBuild(player);
                MaxOutAmmo(player);
                return;
            }

            // Buy the build
            await HandleBuildCommand(player, buildName, false, true);
            RestoreEnergyAfterBuild(player);

            // Fill up all possible ammo types to their maximum (free: not in TP Hard, ?bwd is then ?bw)
            if (!HardEconomy.On) MaxOutAmmo(player);
            return;
        }

        // Fill the player's inventory with the maximum allowed ammo for each type in maxAmmoQuantities
        private void MaxOutAmmo(Player player)
        {
            foreach (var ammoType in maxAmmoQuantities)
            {
                string ammoName = ammoType.Key;
                int maxQuantity = ammoType.Value;

                // Get the current quantity the player has for this ammo type
                ItemInfo ammoItem = AssetManager.Manager.getItemByName(ammoName);
                if (ammoItem != null)
                {
                    int currentQuantity = player.getInventoryAmount(ammoItem.id);

                    // Calculate how much more ammo to give to reach the max
                    int amountToAdd = maxQuantity - currentQuantity;

                    if (amountToAdd > 0)
                    {
                        player.inventoryModify(ammoItem, amountToAdd);
                        //player.sendMessage(0, "~Maxed out ammo: Awarded " + amountToAdd + "x" + ammoName + ".");
                    }
                    else
                    {
                        //player.sendMessage(0, "~Ammo already maxed: " + currentQuantity + "x" + ammoName + ".");
                    }
                }
                else
                {
                    player.sendMessage(-1, "@Ammo type '" + ammoName + "' not found.");
                }
            }
            return;
        }

        /// <summary>
        /// ?dm (Travis 10-26): the ?bwd / ?d drop written out as the two old-school macro lines for players who keep their own buy macros - a ?buy of
        /// what ?bwd adds on top of the build (each maxAmmoQuantities item up to its max, minus what the build gives, so never more than the item's
        /// max) and the ?drop that leaves exactly that for the team. The build stays. No build: counted from what they carry. Items their class
        /// cannot buy are left out, so the ?buy line never fails.
        /// </summary>
        private void HandleDropMacroCommand(Player player)
        {
            if (player.IsSpectator)
            {
                player.sendMessage(-1, "?dm works once you are in the game.");
                return;
            }
            string source;
            bool fromBuild = CurrentLoadout(player, out source) != null;
            Dictionary<int, int> inBuild = fromBuild ? LoadoutItemCounts(player) : null;
            var parts = new List<string>();
            var cannot = new List<string>();
            foreach (var kv in maxAmmoQuantities)
            {
                ItemInfo it = AssetManager.Manager.getItemByName(kv.Key);
                if (it == null)
                    continue;
                int base0;
                if (fromBuild)
                    inBuild.TryGetValue(it.id, out base0);
                else
                    base0 = Skins.HeldWithSkins(player, it.id);   // a held skin counts as its stock item (batch 5)
                int extra = kv.Value - base0;
                if (extra <= 0)
                    continue;
                if (!Logic_Assets.SkillCheck(player, it.skillLogic))
                {
                    cannot.Add(kv.Key);
                    continue;
                }
                parts.Add(kv.Key + ":" + extra);
            }
            string label = fromBuild ? (source ?? "your build") : "from what you carry";
            if (parts.Count == 0)
            {
                player.sendMessage(0, "?dm: " + label + " already holds the most of every drop item; there is nothing extra to buy and drop.");
                return;
            }
            string list = string.Join(", ", parts);
            player.sendMessage(0, String.Format("&Drop macro ({0}; the ?bwd / ?d amounts). Add the ?buy as a 2nd line under your buy macro, then use the ?drop at the base:", label));
            player.sendMessage(0, "?buy " + list);
            player.sendMessage(0, "?drop " + list);
            if (cannot.Count > 0)
                player.sendMessage(0, "*Left out, your class can't buy them: " + string.Join(", ", cannot) + ".");
        }

        // ?drop by a base name (Travis 10-28: "the golden tranq, i had it, but i couldn't drop tranq"). ?drop is the ENGINE's command: it looks
        // each name up as that item and refuses a player holding none of it ("You do not have any (Tranq) to drop.") before any script runs, and
        // a skin holder never holds the stock item. So the arena's own ?drop handler is wrapped: an entry naming a stock item the player holds too
        // few of is spread over what they hold of it - the stock item first, then its skins and champion items (CTFSkins.cs StockAndSkins), each
        // by its own name - and the engine's ?drop then runs exactly as before. The pile is the skin itself, as the drop key leaves it; whoever
        // picks it up gets their own pick or the stock item (playerItemPickup). A skin named on its own, "all", unknown names and bad amounts are
        // left to the engine untouched.
        private bool _dropWrapped;

        private void WrapDropCommand()
        {
            _dropWrapped = true;
            var reg = arena._commandRegistrar;
            InfServer.Game.Commands.HandlerDescriptor h;
            if (reg == null || reg._chatCommands == null || !reg._chatCommands.TryGetValue("drop", out h) || h.handler == null)
            {
                Console.WriteLine("[drop] the engine's ?drop handler was not found: base names of skins are not resolved in " + arena._name);
                return;
            }
            Action<Player, Player, string, int> engineDrop = h.handler;
            h.handler = (p, recipient, payload, bong) =>
            {
                string resolved = payload;
                try { resolved = ResolveSkinDrops(p, payload); }
                catch (Exception ex) { Console.WriteLine("[drop] skin names: " + ex.Message); }
                engineDrop(p, recipient, resolved, bong);
            };
            reg._chatCommands["drop"] = h;
        }

        /// <summary>The ?drop list with every stock item the player holds too few of spread over the stock item and the skins they hold of it.</summary>
        private static string ResolveSkinDrops(Player p, string payload)
        {
            if (p == null || payload == null || payload.Trim().Equals("all", StringComparison.OrdinalIgnoreCase))
                return payload;
            var entries = new List<string>();
            bool changed = false;
            foreach (string entry in payload.Split(new[] { ',' }, StringSplitOptions.RemoveEmptyEntries))
            {
                string[] parts = entry.Trim().Split(':');
                ItemInfo item = AssetManager.Manager.getItemByName(parts[0].Trim());
                List<ItemInfo> family = item == null ? null : Skins.StockAndSkins(item);
                int want = 1;
                if (family == null || family.Count < 2 || (parts.Length > 1 && !Int32.TryParse(parts[1].Trim().TrimStart('#'), out want)) || want <= 0
                    || HoldsEnough(p, item, want))
                {
                    entries.Add(entry);
                    continue;
                }
                var spread = new List<string>();
                int left = want;
                foreach (ItemInfo it in family)
                {
                    int n = Math.Min(left, p.getInventoryAmount(it.id));
                    if (n <= 0) continue;
                    spread.Add(it.name + ":" + n);
                    left -= n;
                    if (left <= 0) break;
                }
                if (spread.Count == 0)
                    entries.Add(entry);   // holds none of it: the engine's own answer
                else
                {
                    entries.AddRange(spread);
                    changed = true;
                }
            }
            return changed ? String.Join(",", entries) : payload;
        }

        private static bool HoldsEnough(Player p, ItemInfo item, int amount)
        {
            return p.getInventoryAmount(item.id) >= amount;   // holds enough of the stock item itself: dropped as before
        }

        private void DropUnusedItems(Player player, string buildName)
        {
            // Check if the player is in spectator mode, dead, and not null
            if (player.IsDead || player.IsSpectator)
            {
                player.sendMessage(-1, "Cannot be in spec or dead while attempting to drop items.");
                return;
            }

            // If no build name is provided, use the last used build
            if (string.IsNullOrWhiteSpace(buildName))
            {
                if (lastUsedBuild.ContainsKey(player))
                {
                    // Retrieve the last used build
                    buildName = lastUsedBuild[player];
                }
                else
                {
                    player.sendMessage(-1, "Please specify a build name or use a build first.");
                    return;
                }
            }

            // Convert buildName to lowercase for case-insensitive matching
            buildName = buildName.ToLower();

            // Check if the build exists
            if (buildSets.ContainsKey(buildName))
            {

                var buildData = buildSets[buildName];
                List<Tuple<string, ushort>> buildItems = buildData.Item1;

                // Track the ammo used by the build
                Dictionary<string, int> usedAmmo = new Dictionary<string, int>();

                // Iterate through the build items and record their quantities
                foreach (var item in buildItems)
                {
                    // Normalize the ammo name for case-insensitive matching
                    string ammoName = item.Item1.ToLower();

                    // Only consider items listed in the maxAmmoQuantities dictionary
                    if (maxAmmoQuantities.ContainsKey(ammoName))
                    {
                        usedAmmo[ammoName] = item.Item2;
                    }
                }

                // Collect excess ammo to drop
                List<Tuple<string, int>> itemsToDrop = new List<Tuple<string, int>>();

                // Iterate through all items in maxAmmoQuantities
                foreach (var ammoType in maxAmmoQuantities.Keys)
                {
                    // Normalize the ammo type for case-insensitive matching
                    string normalizedAmmoType = ammoType.ToLower();

                    // What the player holds of it: the stock item and any skin or champion item of it (batch 5: a Golden Tranq is their
                    // "tranq"), the stock item first. The excess is dropped from them in that order, each by its own name.
                    var held = Skins.StockAndSkins(AssetManager.Manager.getItemByName(normalizedAmmoType))
                        .Select(it => player._inventory.Values.FirstOrDefault(i => i.item.id == it.id))
                        .Where(i => i != null && i.quantity > 0).ToList();

                    // If the item is in the player's inventory
                    if (held.Count > 0)
                    {
                        int currentQuantity = held.Sum(i => (int)i.quantity);

                        // Get the quantity used by the build, if any
                        int usedQuantity = usedAmmo.ContainsKey(normalizedAmmoType) ? usedAmmo[normalizedAmmoType] : 0;

                        // Not in the build: all of it; in the build: the excess
                        int toDrop = usedQuantity == 0 ? currentQuantity : currentQuantity - usedQuantity;
                        foreach (var inv in held)
                        {
                            if (toDrop <= 0) break;
                            int n = Math.Min(toDrop, (int)inv.quantity);
                            itemsToDrop.Add(new Tuple<string, int>(inv.item.name.ToLower(), n));
                            toDrop -= n;
                        }
                    }
                }

                // Now drop all the collected items
                foreach (var item in itemsToDrop)
                {
                    string ammoType = item.Item1;
                    int excess = item.Item2;

                    // Find the item in the player's inventory
                    var inventoryItem = player._inventory.Values.FirstOrDefault(i => i.item.name.ToLower() == ammoType);

                    if (inventoryItem != null)
                    {
                        if (RefuseDropNearFlag(player, inventoryItem.item))
                            continue;   // flag zones: it would be removed at once, so it stays with the player
                        // Spawn the item on the map at the player's location
                        if (!player._arena.exists("Player.ItemDrop") || (bool)player._arena.callsync("Player.ItemDrop", false, player, inventoryItem.item, excess))
                        {
                            // Drop the item onto the map based on terrain settings and nearby item stacking
                            //if (player._arena.getTerrain(player._state.positionX, player._state.positionY).prizeExpire > 1)
                            //{
                                if (player._arena.getItemCountInRange(inventoryItem.item, player._state.positionX, player._state.positionY, 150) > 0)
                                {
                                    // Stack with nearby items if present
                                    player._arena.itemStackSpawn(inventoryItem.item, (ushort)excess, player._state.positionX, player._state.positionY, 50, player);
                                }
                                else
                                {
                                    // Spawn a new item drop
                                    player._arena.itemSpawn(inventoryItem.item, (ushort)excess, player._state.positionX, player._state.positionY, 0, (int)player._team._id, player);
                                }

                                // Remove the excess from the player's inventory
                                player.inventoryModify(inventoryItem.item, -excess);
                                // player.sendMessage(0, "~Dropped " + excess + "x" + inventoryItem.item.name + " (excess).");
                            //}
                        }
                    }
                }
            }
            else
            {
                player.sendMessage(-1, "Build not found. Available builds are: " + string.Join(", ", buildSets.Keys.Where(k => !IsHiddenBuild(player, k))));
            }
            return;
        }

        public void CountItemsOnSpecificTerrain(Arena arena)
        {
            // Define item IDs of interest
            HashSet<int> targetItemIDs = new HashSet<int> { 2005, 2009 }; // Tox, Tso, Pandora's

            // Define counters for each dropship area
            Dictionary<string, Dictionary<int, int>> dropshipItemCounts = new Dictionary<string, Dictionary<int, int>>()
            {
                { "Titan Dropship", new Dictionary<int, int> { { 2005, 0 }, { 2009, 0 } } },
                { "Collective Dropship", new Dictionary<int, int> { { 2005, 0 }, { 2009, 0 } } }
            };

            // Iterate through all items currently in the arena
            foreach (var item in arena._items.Values)
            {
                // Fetch the item's current position and multiply by 16
                int itemX = item.positionX;
                int itemY = item.positionY;

                // Check the terrain at the item's position
                int terrainID = arena.getTerrainID(itemX, itemY);

                // Only consider items on terrain ID 4
                if (terrainID == 4 && targetItemIDs.Contains(item.item.id))
                {
                    int itemQuantity = item.quantity; // Assuming quantity holds the correct value

                    // Check if the item is within Titan Dropship boundaries
                    if (itemX >= 608 * 16 && itemX <= 699 * 16 && itemY >= 440 * 16 && itemY <= 478 * 16)
                    {
                        dropshipItemCounts["Titan Dropship"][item.item.id] += itemQuantity;
                    }
                    // Check if the item is within Collective Dropship boundaries
                    else if (itemX >= 607 * 16 && itemX <= 699 * 16 && itemY >= 591 * 16 && itemY <= 633 * 16)
                    {
                        dropshipItemCounts["Collective Dropship"][item.item.id] += itemQuantity;
                    }
                }
            }

            // Send the counts as arena messages
            string titanMessage = string.Format(
                "~Titan Dropship Mineral Counts: TOX: {0}, TSO: {1}",
                dropshipItemCounts["Titan Dropship"][2009],
                dropshipItemCounts["Titan Dropship"][2005]
            );

            string collectiveMessage = string.Format(
                "@Collective Dropship Mineral Counts: TOX: {0}, TSO: {1}",
                dropshipItemCounts["Collective Dropship"][2009],
                dropshipItemCounts["Collective Dropship"][2005]
            );

            // Send the formatted messages to the arena
            arena.sendArenaMessage(titanMessage);
            arena.sendArenaMessage(collectiveMessage);
            return;
        }

