        // Debounce for the F11 skill shop: if the client fires the same skill-purchase request
        // repeatedly (double-click, or a resend while a prior request is still being denied), the
        // second one is dropped instead of being reprocessed. Skill purchases route through
        // Arena.poll()'s event queue, which has no exception handling around it - so a flood of
        // rapid-fire requests is also a flood of chances for any bug in this handler to throw and
        // take the whole arena tick loop down with it. Keyed by Player, so it MUST be cleared on
        // Player.Leave or it leaks (see the _projectileOwners incident).
        private Dictionary<Player, int> _lastSkillShopRequestTick = new Dictionary<Player, int>();
        private const int SkillShopDebounceMs = 150;

        // Helper method to retrieve the primary skill name from the player's skills dictionary
        /// <summary>
        /// The class the player is actually playing. This used to return the first entry of an
        /// unordered dictionary ("assuming the primary skill is the first entry"), which is wrong
        /// for anyone holding more than one skill - a ref, or anyone ?swap gave a base skill to.
        /// </summary>
        private string GetPrimarySkillName(Player player)
        {
            return CTFClass.ResolveName(player);
        }
        // Define the non-expiring item IDs
        HashSet<int> nonExpiringItemIDs = new HashSet<int> { 2005, 2007, 2009, 2, 9, 10, 11 }; // Tox, Tso, Steron Injection, AutoGuns (premades)

        // quantity-1 piles that may stay on the ground, ONE combined limit of SINGLE_DROP_CAP per player: 2001 Ammo MG, 1014 AP Mine, 1020 Plasma Mine,
        // 1029 Bullet Mine (ids from ctfpl.itm). Sentry, Stim Pack and the other whitelisted ids below are untouched.
        private static readonly int[] SINGLE_CAPPED_IDS = { 2001, 1014, 1020, 1029 };
        private const int SINGLE_DROP_CAP = 3;   // the group's total per player; also each mineral type's own quantity-1 limit per player
        private readonly Dictionary<ushort, int> singleDropSeen = new Dictionary<ushort, int>();   // pile id -> tick first seen (oldest goes first)

        public void pollItemExpiration()
        {
            // Iterate through all items currently in the arena that are within the x/y of 610,440 > 700,640 and isn't alright at a tickExpire of 0
            foreach (var item in arena._items.Values.Where(i => nonExpiringItemIDs.Contains(i.item.id) && i.positionX >= (610 * 16) && i.positionX <= (700 * 16) && i.positionY >= (440 * 16) && i.positionY <= (640 * 16) && i.tickExpire != 0)) 
            {
                //debug message and ++ iteration count so I know how many items its having to loop through
                //arena.sendArenaMessage(string.Format("Item ID {0}: {1} drops", item.item.id, item.quantity));
                item.tickExpire = 0;
            }

            // Delete minerals (2005, 2007, 2009) if the quantity stack is less than 4
            // Create a list of items to remove to avoid modifying collection during enumeration
            // Round 2c (Travis 10-25): a mineral pile of ANY size survives. This used to delete every pile of 4 or fewer, which also destroyed small
            // legitimate drops. Still purged as before: quantity-1 piles nobody dropped (no owner). A player's own quantity-1 piles are capped below.
            var itemsToRemove = arena._items.Values
                .Where(i => IsMineral(i.item.id) && i.quantity == 1 && i.owner == null)
                .ToList();

            //More items to remove, all items that are quantity of 1 except item ID 23 (Sentry), 15 (Energizer), 47 (Stim Pack), 1 (Hoverboard), Autoguns, repulsor charge, steron injection
            var itemsToRemove2 = arena._items.Values
                .Where(i => i.quantity == 1 && !IsMineral(i.item.id) && !Array.Exists(SINGLE_CAPPED_IDS, id => id == i.item.id) && !new[] { 23, 15, 47, 1, 2, 1049, 9, 10, 11 }.Contains(i.item.id))
                .ToList();

            itemsToRemove.AddRange(itemsToRemove2);

            // Single drops are meant to stay, with limits (Travis 10-25), per player, quantity-1 piles only, the player's OLDEST own removed first;
            // other players' piles and piles nobody dropped (no owner) are never touched:
            //  * Ammo MG, AP Mine, Plasma Mine and Bullet Mine are ONE group: together they may total SINGLE_DROP_CAP on the ground.
            //  * Each mineral (Tso, Pandora's, Tox) has its own count of SINGLE_DROP_CAP. Mineral piles of 2 or more are not capped here.
            var singles = arena._items.Values.Where(i => i.quantity == 1 && (Array.Exists(SINGLE_CAPPED_IDS, id => id == i.item.id) || IsMineral(i.item.id))).ToList();
            foreach (ushort gone in singleDropSeen.Keys.Where(id => !singles.Any(i => i.id == id)).ToList())
                singleDropSeen.Remove(gone);
            int seenNow = Environment.TickCount;
            foreach (var i in singles)
                if (!singleDropSeen.ContainsKey(i.id)) singleDropSeen[i.id] = seenNow;
            foreach (var mine in singles.Where(i => i.owner != null).GroupBy(i => i.owner._alias + "|" + (IsMineral(i.item.id) ? i.item.id.ToString() : "singles")))
            {
                var surplus = mine.OrderBy(i => singleDropSeen[i.id]).ThenBy(i => i.id).Take(Math.Max(0, mine.Count() - SINGLE_DROP_CAP)).ToList();
                if (surplus.Count > 0)
                    itemsToRemove.AddRange(surplus);
            }

            //Next set of items to remove is Ammo MG stacks less than 50
            // var itemsToRemove3 = arena._items.Values
            //     .Where(i => i.item.id == 2001 && i.quantity < 50)
            //     .ToList();

            // itemsToRemove.AddRange(itemsToRemove3);

            // Now safely remove the items
            foreach (var item in itemsToRemove)
            {
                //Update the players of the status..
                Helpers.Object_ItemDropUpdate(arena.Players, item.id, 0);
                arena._items.Remove(item.id);
            }
            return;
        }

