        public void pollFlagBug()
        {
            // Loop through each flag in the current map
            foreach (var flag in currentMap.Flags)
            {
                // Retrieve the flag object from the arena using the flag's nameinf
                var fs = arena.getFlag(flag.Item1);  // flag.Item1 is the flag name

                if (flag.Item1.Equals("sdFlag", StringComparison.OrdinalIgnoreCase))
                {
                    continue;
                }

                if (fs != null)
                {
                    // Check if the flag's current position is (0, 0)
                    // If 0,0, its bugged, lets respawn it to its default position!
                    if (fs.posX == 0 && fs.posY == 0 && fs.carrier == null)
                    {
                        // The player is carrying this flag and its coordinates are (0, 0)
                        // Reset the flag's position to its original coordinates
                        fs.posX = (short)(flag.Item2 * 16);  // flag.Item2 is X coordinate
                        fs.posY = (short)(flag.Item3 * 16);  // flag.Item3 is Y coordinate

                        fs.bActive = true;      // Ensure the flag is active
                        fs.carrier = null;      // Clear the carrier
                        fs.team = null;         // Reset the team if necessary

                        // Update the flag's status for all players
                        Helpers.Object_Flags(arena.Players, fs);

                        // Since a player can carry only one flag, we can exit the loop
                        break;
                    }
                }
            }
            return;
        }

        /// <summary>
        /// Smart polling for dueling tiles - only checks when there are potential duelers
        /// </summary>
        // Ranked duel pads (tiles 775,517 / 784,517). OFF by default (*duelpads on|off): while on, every in-game player
        // gets a pool task each second, someone standing on a pad is re-told "Waiting for opponent" every second, and a
        // matched duel warps and resets players from pool threads.
        private bool _duelPadsOn = false;

        public void pollDuelingTiles()
        {
            if (!_duelPadsOn)
                return;
            try
            {
                // Only check if there are at least 2 players who could potentially duel
                var potentialDuelers = arena.PlayersIngame.Where(p => 
                    !GetPrimarySkillName(p).Equals("Dueler", StringComparison.OrdinalIgnoreCase) || 
                    GetPrimarySkillName(p).Equals("Dueler", StringComparison.OrdinalIgnoreCase)).ToList();
                
                if (potentialDuelers.Count < 2)
                    return; // Not enough players to duel
                
                // Check each player's position for tile proximity
                foreach (var player in potentialDuelers)
                {
                    if (player._state != null)
                    {
                        // Convert player position to tile coordinates
                        short tileX = (short)(player._state.positionX / 16);
                        short tileY = (short)(player._state.positionY / 16);
                        
                        // Use the existing dueling system's tile handling
                        Task.Run(async () => {
                            try
                            {
                                await CTFGameType.DuelingSystem.HandleTileStep(player, tileX, tileY);
                                CTFGameType.DuelingSystem.HandleTileLeave(player, tileX, tileY);
                            }
                            catch (Exception ex)
                            {
                                Console.WriteLine(string.Format("Error in pollDuelingTiles for player {0}: {1}", 
                                    player._alias, ex.Message));
                            }
                        });
                    }
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine(string.Format("Error in pollDuelingTiles: {0}", ex.Message));
            }
        }

        private DateTime lastPollCheckTime = DateTime.MinValue;
        private const double pollCheckInterval = 1.0; // Interval in seconds

        /// <summary>
        /// CTF Script poll called by our arena
        /// </summary>
            public bool poll()
            {
            //Log.write(TLog.Error, "Polling arena.");

            int now = Environment.TickCount;
            if (CtfxBotsPoll != null && CtfxBotsHere) CtfxBotsPoll(now);
            GreenHideStep(now);                 // the green-portal hides fire for the team they build for only (Travis 11-11)
            if (_bountyRestoreDue.Count > 0) PollBountyRestore(now);
            //int seconds = ((Environment.TickCount - arena._tickGameStarted) / 1000);
            _lagProbe.OnPoll(now);   // poll gaps = how long this arena's thread went without a turn (*lagprobe)
            if (!_dropWrapped)
                WrapDropCommand();   // once: ?drop by a base name finds the skin the player holds (batch 5)

            // Process pending auto-occupy operations more frequently (only if needed)
            if (pendingAutoOccupy.Count > 0)
                ProcessPendingAutoOccupy();
            PollWarpExits(now);   // 20 Hz: a player who warped away vanishes for whoever could see them
            try { GoldenTranq.Poll(arena, isChampEnabled && skinsEnabled); } catch (Exception ex) { Console.WriteLine("[GoldenTranq] poll: " + ex.Message); }   // HELLO THERE on landing
            try { Subzero.Poll(arena, isChampEnabled && skinsEnabled); } catch (Exception ex) { Console.WriteLine("[Subzero] poll: " + ex.Message); }   // the next ice piece over each frozen player
            try { PutBackHeldPiles(now); } catch (Exception ex) { Console.WriteLine("[flagzone] put back: " + ex.Message); }   // piles lifted over a flag landing (last safety net)
            try { PollFlagZones(now); } catch (Exception ex) { Console.WriteLine("[flagzone] poll: " + ex.Message); }   // 4 Hz: keep every resting flag's PrizeDistance clear
            try { PollFlagReturns(now); } catch (Exception ex) { Console.WriteLine("[flagfix] poll: " + ex.Message); }   // 10 Hz: a flag back from a reset moves off another team's flag

            // Check if it's time to run less frequent polling functions
            if ((DateTime.Now - lastPollCheckTime).TotalSeconds >= pollCheckInterval)
            {
                // Stamped on entry: if anything below throws, the block waits its second instead of re-running (and
                // re-throwing) on every ~5 ms poll.
                lastPollCheckTime = DateTime.Now;
                _lagProbe.Sample(now);   // 1 Hz: per-player send rate / throttling; writes logs/LagProbe.txt once a minute
                try { PollQueuedFlagDrops(); } catch (Exception ex) { Console.WriteLine("[flagdrop] poll: " + ex.Message); }   // 1 Hz, nothing to do while the queue is empty
                pollItemExpiration();
                pollSkillCheck();
                pollFlagBug();
                pollDuelingTiles(); // Check for players on dueling tiles
                CheckVotingTimeout(); // Check voting timeout
                
                // Mix session phases. Deadlines here are 30s+ so 1Hz is ample, and this must NOT
                // ride the raw poll - ZoneArenas.handleArenas spins at ~200Hz.
                if (_mixManager != null)
                    _mixManager.Poll(now);
                if (_liveSnap != null)
                    _liveSnap.Poll(now);   // freeinf.org live snapshot (own 60s deadline inside)
                if (_matchAuto != null)
                    _matchAuto.Poll();     // league match queue (own 30s fetch deadline inside)

                // Class change timers: out of the dropship / store (or warped in) = playing the class (CTFClassGate.cs).
                foreach (Player cp in arena.PlayersIngame.ToList())
                    if (cp != null && !cp.IsDead && !OnStoreTerrain(cp))
                        ClassGate.MarkUsed(cp._alias);

                PollPendingTso();     // owed base Tso -> whoever became medic
                PollAutoPickup();     // ?ap: top up from the pile you stand on
                FlushAutoPickupDropNotices(now);
                PollArmory();         // stand on an armory tile -> build / class / base
                PollArenaTips(now);   // hourly feature line from ArenaTips.txt
                foreach (Player skinP in arena.PlayersIngame.ToList())
                    Skins.Sweep(skinP, isChampEnabled, skinsEnabled);   // item skins: owners' items in their ?skin pick (CTFSkins.cs)
                PollDuelGear();       // the Dueler AR / class only inside a ?duel
                if (arena._items.Count > _adPeakStacks)
                    _adPeakStacks = arena._items.Count;            // for *autodrop: how close this arena gets to the budget
                PhraseExplosionManager.GetCachedPhrase(null);      // picks up a rewritten PhraseCache.txt (one stat a minute)
                ProductPurchaseManager.GetPlayerProducts(null);    // same for PurchaseCache.txt

                // Update OvD Automation
// if (_ovdAutomation != null)
                //     _ovdAutomation.Update();
                    
                lastPollCheckTime = DateTime.Now;
                // Gladiator event polling
                if (currentEventType == EventType.Gladiator)
                {
                    CheckGladiatorVictory();
                }
                if (currentEventType == EventType.SUT)
                {
                    CheckSUTVictory();
                }
                // TDM event polling
                // if (currentEventType == EventType.TDM && _tdmInstance != null)
                // {
                //     // Handle bot spawning for TDM
                //     HandleTDMBotSpawning(now);
                //     
                //     // Manage existing bots
                //     ManageTDMBots(now);
                //     
                //     if (_tdmInstance.HasFinished)
                //     {
                //         arena.sendArenaMessage("Team Deathmatch event has ended. Returning to CTF gameplay.", 1);
                //         EndEvent();
                //     }
                // }
                
                // ADDED: Bot management for regular CTF mode (not just TDM)
                // if (currentEventType == EventType.Standard || currentEventType == EventType.None)
                // {
                //     // Handle bot spawning and management for regular CTF
                //     HandleCTFBotSpawning(now);
                //     ManageCTFBots(now);
                // }
                
                //arena.sendArenaMessage(string.Format("Elapsed game time: {0} seconds", seconds));
            }

            /*//////////////////////////////////////////////////
            // Game state management
            /*//////////////////////////////////////////////////

            // Check if it's time to start the first overtime and if it is not already active
            if (overtimeStart != 0 && Environment.TickCount >= overtimeStart && !isSD)
            {
                isSD = true;
                arena.sendArenaMessage("&Overtime triggered. 50% Reduced healing on both Medikits. Engineer Repairs reduced to 50 hp (unless all 5 flags held)", 30);

                overtimeStart = Environment.TickCount;

                // Schedule second overtime
                //secondOvertimeStart = overtimeStart + 10000; // 10 seconds for testing
                secondOvertimeStart = overtimeStart + (15 * 60000); // 15 minutes

                overtimeStart = 0; // Reset to avoid multiple triggers
            }

            // Check if it's time to start the second overtime
            if (isSD && !isSecondOvertime && secondOvertimeStart != 0 && Environment.TickCount >= secondOvertimeStart)
            {
                isSecondOvertime = true;
                arena.sendArenaMessage("&Second Overtime triggered. 75% Reduced healing on both Medikits. Engineer Repairs reduced to 40 hp (unless all 5 flags held). ", 30);

                secondOvertimeStart = 0; // Reset to avoid multiple triggers
            }

            if (now - lastGameCheck < Arena.gameCheckInterval)
                return true;
            lastGameCheck = now;

            //A mix/OvD draft is being organised - stand the automatic game loop down entirely.
            //Unspeccing the captains and picks pushes PlayersIngame past minPlayers, which would
            //otherwise walk Init -> PreGame -> gameStart() mid-draft. That matters because
            //StartGame() calls flagReset() + SpawnMapFlags(), which wipes the base setup ?base
            //just placed. Running is deliberately NOT suppressed - the live game polls normally.
            if (_mixManager != null && _mixManager.SuppressAutoStart)
                return true;

            //Do we have the bodies for a game? One test gates both entering the idle
            //state and leaving it, so the machine can actually rest in it.
            bool bEnoughPlayers = arena.PlayersIngame.Count() >= minPlayers;

            if (gameState == GameState.Init && !bEnoughPlayers)
            {   //Drop to idle and say so once, rather than on every poll
                gameState = GameState.NotEnoughPlayers;
                arena.setTicker(1, 3, 0, "Not Enough Players");
            }

            switch (gameState)
            {
                case GameState.NotEnoughPlayers:
                    //Sit here until someone shows up. This used to fall straight back to
                    //Init, which bounced us right back here on the next poll - the arena
                    //never settled and the ticker was re-stamped every game check.
                    if (bEnoughPlayers)
                    {
                        arena.setTicker(1, 3, 0, "");
                        gameState = GameState.Init;
                    }
                    break;
                case GameState.Transitioning:
                    //Do nothing while we wait
                    break;
                case GameState.ActiveGame:
                    PollCTF(now);
                    break;
                case GameState.Init:
                    Initialize();
                    break;
                case GameState.PreGame:
                    PreGame();
                    break;
                case GameState.PostGame:
                    gameState = GameState.Init;
                    break;
            }
            return true;
        }

        private void OnFlagChange(Arena.FlagState flag)
        {
            // NOTE: OvD does not need a special case here. It bypasses this rule structurally -
            // SetupBase leaves the non-base flags on the map but UNOWNED, so "one team holds every
            // active flag" can never become true and no countdown can start. An earlier version
            // short-circuited this method for OvD instead; that masked the real cause (parked flags
            // keeping their previous owner) and disabled a legitimate rule wholesale.
            Team victory = flag.team;

            //Does this team now have all the flags?
            foreach (Arena.FlagState fs in arena._flags.Values)
            {
                if (fs.bActive && fs.team != flag.team)
                {   //Not all flags are captured yet
                    victory = null;
                    break;
                }
            }

            if (!gameWon)
            {   //All flags captured?
                if (victory != null)
                {   //Yep
                    winningTeamTick = (Environment.TickCount + (victoryHoldTime * 10));
                    winningTeamNotify = 0;
                    winningTeam = victory;
                    flagMode = CTFMode.XSeconds;
                }
                else
                {   //Aborted?
                    if (winningTeam != null)
                    {   //Yep
                        winningTeam = null;
                        winningTeamTick = 0;
                        flagMode = CTFMode.Aborted;
                    }
                }
            }
            
            // Update steron boost status based on flag changes
            UpdateSteronBoostStatus();
        }



        #endregion

        #region Script Functions

       public static void scrambleSpecificTeams(Arena arena, List<Team> teamsToScramble, bool alertArena, Script_CTF script)
        {
            // Ensure the arena and teams are valid
            if (arena == null || teamsToScramble == null || teamsToScramble.Count != 2)
                throw new ArgumentException("Invalid arena or teams passed.");

            List<Player> playersToScramble = new List<Player>();

            // Manually collect players on the teamsToScramble
            foreach (var player in arena.PlayersIngame) // Assuming PlayersIngame gives all players in the arena
            {
                // Ensure player is on one of the teamsToScramble and is not a Dueler
                if (teamsToScramble.Contains(player._team) && 
                    !script.GetPrimarySkillName(player).Equals("Dueler", StringComparison.OrdinalIgnoreCase))
                {
                    playersToScramble.Add(player); // Add player to the list
                }
            }

            // Shuffle players randomly using arena's random generator
            var shuffledPlayers = playersToScramble.OrderBy(plyr => arena._rand.Next(0, 500)).ToList();

            // Distribute players back into the two teams evenly
            for (int i = 0; i < shuffledPlayers.Count; i++)
            {
                Team team = teamsToScramble[i % teamsToScramble.Count]; // Rotate between teamA and teamB
                if (shuffledPlayers[i]._team != team) // Only move if the player isn't already on the team
                {
                    team.addPlayer(shuffledPlayers[i]);
                }
            }

            foreach (var player in arena.PlayersIngame)
            {
                if (script.currentEventType == EventType.MiniTP){
                    Player playerCopy = player; // Create a copy to use in timer callback
                    System.Threading.Timer timer = null;
                    timer = new System.Threading.Timer((state) =>
                    {
                        if (playerCopy._team._name.Contains("Titan"))
                            script.WarpPlayerToRange(playerCopy, 654, 654, 518, 518);
                        else if (playerCopy._team._name.Contains("Collective"))
                            script.WarpPlayerToRange(playerCopy, 648, 648, 565, 565);
                        timer.Dispose();
                    }, null, 3000, System.Threading.Timeout.Infinite);
                }
            }

            // Notify players of the scramble
            if (alertArena)
            {
                arena.sendArenaMessage("Teams have been scrambled between " + teamsToScramble[0]._name + " and " + teamsToScramble[1]._name + "!");
            }
        }

        private bool SpawnMapPlayers()
        {
            if (currentMap != null)
            {
                // Retrieve teams from the current map
                var teamA = arena.getTeamByName(currentMap.TeamNames[0]);
                var teamB = arena.getTeamByName(currentMap.TeamNames[1]);

                foreach (var player in arena.PlayersIngame)
                {
                    string playerSkill = this.GetPrimarySkillName(player);
                    if (playerSkill.Equals("Dueler", StringComparison.OrdinalIgnoreCase))
                    {
                        continue; // Skip Dueler players
                    } 
                    else 
                    {
                        // Assign players evenly between teamA and teamB
                        if (teamA.ActivePlayerCount < teamB.ActivePlayerCount)
                        {
                            teamA.addPlayer(player);
                        }
                        else
                        {
                            teamB.addPlayer(player);
                        }
                    }
                    // if (currentEventType == EventType.MiniTP){
                    //     if (player._team._name.Contains("Titan"))
                    //         WarpPlayerToRange(player, 654, 654, 518, 518);
                    //     else if (player._team._name.Contains("Collective")) 
                    //         WarpPlayerToRange(player, 648, 648, 565, 565);
                    //     return false;
                    // }
                }

                // Scramble only teamA and teamB, leaving other teams unaffected
                scrambleSpecificTeams(arena, new List<Team> { teamA, teamB }, true, this);

                return true;
            }

            return false; // In case currentMap is null
        }

        // *flagfix (Travis 10-29: flags that come back "in their last known location" when the carrier dies to a turret, sometimes "phase out",
        // sometimes "stacked underneath a flag a player already owns" so autopickup cannot take the enemy one). A carrier killed by a computer
        // (turret, terrain, a team kill, spec/leave) gets the engine's flagResetPlayer: the flag stays at posX/posY, which the pickup set to
        // oldPos = where it was last SET DOWN. SpawnMapFlags placed the flags without touching oldPos, so a flag's first carry of a game came
        // back to the previous game's last set-down spot, or to 0,0 after a zone start (pollFlagBug put it back at spawn a second later).
        // Zone-wide staff switch, saved in FlagFixState.txt like *autooccupy (absent = on); off = exactly the old behaviour. It gates both parts:
        // the game start sets oldPos to the spawn spot, and a flag that comes back to the ground without a set-down, within the gap of a ground
        // flag owned by another team, is moved to the nearest open floor that far from every flag.
        private static readonly string FLAGFIX_STATE_PATH = System.IO.Path.Combine("scripts", "GameTypes", "CTF", "FlagFixState.txt");
        private static bool _flagFixOff, _flagFixStateLoaded;
        private static int _flagFixGap = 32;               // px between flag centres: two tiles, so standing on one is clearly nearer to it
        private static bool FlagFixOn { get { LoadFlagFixState(); return !_flagFixOff; } }
        private const int FLAG_RETURN_EVERY_MS = 100;
        private const int FLAG_SETDOWN_GRACE_MS = 1500;    // carried -> ground this soon after the carrier's own drop request = set down, not returned
        private const int FLAG_NUDGE_REACH = 96;           // px past the gap the search goes before leaving the flag where it is
        private int _flagReturnAt, _flagFixMoves;
        private readonly Dictionary<int, bool> _flagWasCarried = new Dictionary<int, bool>();
        private readonly Dictionary<int, int> _flagSetDownAt = new Dictionary<int, int>();
        private readonly List<string> _flagFixLog = new List<string>();

        /// <summary>10 Hz: a flag that went from carried to the ground without its carrier setting it down came back by a reset (turret or
        /// terrain death, team kill, spec, leave); NudgeReturnedFlag moves it off a flag of another team.</summary>
        private void PollFlagReturns(int now)
        {
            if (unchecked(now - _flagReturnAt) < FLAG_RETURN_EVERY_MS)
                return;
            _flagReturnAt = now;
            List<Arena.FlagState> returned = null;
            foreach (Arena.FlagState fs in arena._flags.Values)
            {
                int id = fs.flag.GeneralData.Id, at;
                bool carried = fs.bActive && fs.carrier != null, was;
                if (_flagWasCarried.TryGetValue(id, out was) && was && !carried && fs.bActive
                    && !(_flagSetDownAt.TryGetValue(id, out at) && unchecked(now - at) < FLAG_SETDOWN_GRACE_MS))
                    (returned ?? (returned = new List<Arena.FlagState>())).Add(fs);
                _flagWasCarried[id] = carried;
            }
            if (returned == null || !FlagFixOn)
                return;
            foreach (Arena.FlagState fs in returned)
                NudgeReturnedFlag(fs);
        }

        private static double FlagApart(Arena.FlagState o, int x, int y)
        {
            double dx = o.posX - x, dy = o.posY - y;
            return Math.Sqrt(dx * dx + dy * dy);
        }

        private static string FlagLabel(Arena.FlagState fs)
        {
            return String.Format("{0} ({1})", fs.flag.GeneralData.Name.Trim('"'), fs.team != null ? fs.team._name : "nobody's");
        }

        /// <summary>A returned flag within the gap of a ground flag owned by another team goes to the nearest spot the gap away from every flag.</summary>
        private void NudgeReturnedFlag(Arena.FlagState fs)
        {
            int gap = _flagFixGap, px = fs.posX, py = fs.posY;
            Arena.FlagState under = null;
            foreach (Arena.FlagState o in arena._flags.Values)
                if (o != fs && o.bActive && o.carrier == null && o.team != fs.team && FlagApart(o, px, py) < gap)
                {
                    under = o;
                    break;
                }
            if (under == null)
                return;
            int tid = arena.getTerrainID(px, py);
            for (int r = 4; r <= gap + FLAG_NUDGE_REACH; r += 4)
                for (int a = 0; a < 32; a++)
                {
                    double ang = a * Math.PI / 16.0;
                    int x = px + (int)Math.Round(Math.Cos(ang) * r), y = py + (int)Math.Round(Math.Sin(ang) * r);
                    if (!FlagSpotOk(fs, x, y, tid, gap))
                        continue;
                    bool clear = true;
                    for (int st = 4; st < r && clear; st += 4)
                        clear = FlagFloor(px + (int)Math.Round(Math.Cos(ang) * st), py + (int)Math.Round(Math.Sin(ang) * st));
                    if (!clear)
                        continue;
                    fs.posX = fs.oldPosX = (short)x;
                    fs.posY = fs.oldPosY = (short)y;
                    Helpers.Object_Flags(arena.Players, fs);
                    _flagFixMoves++;
                    NoteFlagFix(String.Format("{0} came back at {1},{2} on {3}: moved {4} px to {5},{6}", FlagLabel(fs), px / 16, py / 16, FlagLabel(under), r, x / 16, y / 16));
                    return;
                }
            NoteFlagFix(String.Format("{0} came back at {1},{2} on {3}: no open floor {4} px from every flag within {5} px, left there", FlagLabel(fs), px / 16, py / 16, FlagLabel(under), gap, gap + FLAG_NUDGE_REACH));
        }

        private bool FlagFloor(int x, int y)
        {
            try { return x > 16 && y > 16 && !arena.getTile(x, y).Blocked; }
            catch (Exception) { return false; }
        }

        /// <summary>A flag may go to x,y: open floor with no wall tile within 8 px ("never on top of a physic tile"), on the terrain it came back on or
        /// one it may be dropped on, and the gap away from every other flag on the ground.</summary>
        private bool FlagSpotOk(Arena.FlagState fs, int x, int y, int tid, int gap)
        {
            for (int dx = -8; dx <= 8; dx += 8)
                for (int dy = -8; dy <= 8; dy += 8)
                    if (!FlagFloor(x + dx, y + dy))
                        return false;
            int t = arena.getTerrainID(x, y);
            int[] droppable = fs.flag.FlagData.FlagDroppableTerrains;
            if (t != tid && (droppable == null || t < 0 || t >= droppable.Length || droppable[t] != 1))
                return false;
            foreach (Arena.FlagState o in arena._flags.Values)
                if (o != fs && o.bActive && o.carrier == null && FlagApart(o, x, y) < gap)
                    return false;
            return true;
        }

        private void NoteFlagFix(string line)
        {
            try { Console.WriteLine("[flagfix] " + line); } catch (Exception) { }
            _flagFixLog.Add(DateTime.UtcNow.ToString("HH:mm") + " UTC " + line);
            if (_flagFixLog.Count > 6)
                _flagFixLog.RemoveAt(0);
        }

        private static void LoadFlagFixState()
        {
            if (_flagFixStateLoaded)
                return;
            _flagFixStateLoaded = true;
            try
            {
                if (!System.IO.File.Exists(FLAGFIX_STATE_PATH))
                    return;
                foreach (string raw in System.IO.File.ReadAllLines(FLAGFIX_STATE_PATH))
                {
                    string[] kv = raw.Split(new[] { '=' }, 2);
                    if (kv.Length != 2)
                        continue;
                    string key = kv[0].Trim().ToLower(), val = kv[1].Trim().ToLower();
                    int g;
                    if (key == "enabled")
                        _flagFixOff = (val == "off" || val == "false" || val == "0");
                    else if (key == "gap" && int.TryParse(val, out g) && g >= 1 && g <= 128)
                        _flagFixGap = g;
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine("FlagFixState.txt not read: " + ex.Message);
            }
        }

        private static void SaveFlagFixState()
        {
            try
            {
                System.IO.File.WriteAllLines(FLAGFIX_STATE_PATH, new[]
                {
                    "# Written by *flagfix. enabled=on|off (zone-wide), gap=px between flags.",
                    "enabled=" + (_flagFixOff ? "off" : "on"),
                    "gap=" + _flagFixGap,
                });
            }
            catch (Exception ex)
            {
                Console.WriteLine("FlagFixState.txt not written: " + ex.Message);
            }
        }

        /// <summary>*flagfix [on|off|gap N|log] - status for any mod; changing it needs IsAutoDropStaff, like *autooccupy.</summary>
        private void FlagFixCommand(Player player, string payload)
        {
            LoadFlagFixState();
            string[] args = (payload ?? "").Trim().ToLower().Split(new[] { ' ' }, StringSplitOptions.RemoveEmptyEntries);
            bool log = args.Length > 0 && args[0] == "log";
            if (args.Length > 0 && !log)
            {
                if (!IsAutoDropStaff(player))
                {
                    player.sendMessage(-1, "Only zone staff can change flagfix.");
                    return;
                }
                int g;
                if (args[0] == "on" || args[0] == "off")
                    _flagFixOff = args[0] == "off";
                else if (args[0] == "gap" && args.Length > 1 && int.TryParse(args[1], out g) && g >= 1 && g <= 128)
                    _flagFixGap = g;
                else
                {
                    player.sendMessage(-1, "Usage: *flagfix [on|off|gap <1-128>|log]");
                    return;
                }
                SaveFlagFixState();
                Console.WriteLine(String.Format("[flagfix] {0} set {1}", player._alias, String.Join(" ", args)));
            }
            player.sendMessage(0, String.Format("Flagfix: {0} (zone-wide) | gap {1} px | returned flags moved in this arena: {2}{3}",
                _flagFixOff ? "OFF" : "ON", _flagFixGap, _flagFixMoves, log ? "" : " | *flagfix log shows the last moves"));
            if (log)
            {
                if (_flagFixLog.Count == 0)
                    player.sendMessage(0, "No returned flag has needed moving in this arena yet.");
                foreach (string line in _flagFixLog)
                    player.sendMessage(0, line);
            }
        }

        private bool SpawnMapFlags()
        {
            foreach(var flag in currentMap.Flags)
            {
                var fs = arena.getFlag(flag.Item1);

                if (fs == null)
                {
                    return false;
                }

                // Check if the flag is "sdFlag" and set it inactive
                if (flag.Item1.Equals("sdFlag", StringComparison.OrdinalIgnoreCase))
                {
                    fs.bActive = false;  // Make sure sdFlag is inactive by default
                    fs.posX = 0;         // You can position it off the map or at a default position
                    fs.posY = 0;
                    continue;            // Skip the rest of the logic for sdFlag
                }

                bool bActive = true;

                if (currentMap.RandomizeFlagLocations)
                {
                    bActive = RandomizeFlagLocation(fs);
                }
                else
                {
                    fs.posX = (short)(flag.Item2 * 16);
                    fs.posY = (short)(flag.Item3 * 16);
                    if (FlagFixOn)
                    {   // a reset on its first carry comes back here, not to last game's spot or 0,0
                        fs.oldPosX = fs.posX;
                        fs.oldPosY = fs.posY;
                    }
                }
                
                fs.bActive = bActive;
                fs.team = null;
                fs.carrier = null;

                Helpers.Object_Flags(arena.Players, fs);
            }

            return true;
        }

        //Spawn first flag
        private bool SpawnMapFlag()
        {
            var flag = currentMap.Flags[0];
            var fs = arena.getFlag(flag.Item1);
                
            if (fs == null)
            {
                return false;
            }

            bool bActive = true;

            if (currentMap.RandomizeFlagLocations)
            {
                bActive = RandomizeFlagLocation(fs);
            }
            else
            {
                fs.posX = (short)(flag.Item2 * 16);
                fs.posY = (short)(flag.Item3 * 16);
                if (FlagFixOn)
                {
                    fs.oldPosX = fs.posX;
                    fs.oldPosY = fs.posY;
                }
            }
               
            fs.bActive = bActive;
            fs.team = null;
            fs.carrier = null;

            Helpers.Object_Flags(arena.Players, fs);
            
            return true;
        }

        ///////////////////////////////////////////////////
        // Script Functions
        ///////////////////////////////////////////////////
        /// <summary>
        /// Resets all variables and initializes a new game state
        /// </summary>
        private void Initialize()
        {
            winningTeamNotify = 0;
            winningTeamTick = 0;
            winningTeam = null;
            gameWon = false;

            //We are officially initialized, pregame it.
            gameState = GameState.PreGame;
        }

        /// <summary>
        /// Our waiting period between games
        /// </summary>
        private void PreGame()
        {
            gameState = GameState.Transitioning;

            //Sit here until timer runs out
            arena.setTicker(1, 3, preGamePeriod * 100, "Next game: ",
                    delegate ()
                    {	//People leave during the countdown - re-check before committing,
                        //because ScriptArena.gameStart() flips _bGameRunning before it
                        //hands control to us and there is no clean way back out.
                        if (arena.PlayersIngame.Count() < minPlayers)
                        {
                            gameState = GameState.NotEnoughPlayers;
                            arena.setTicker(1, 3, 0, "Not Enough Players");
                            return;
                        }

                        //Trigger the game start
                        arena.gameStart();
                    }
            );
        }

        /// <summary>
        /// Resets our tickers and gamestate
        /// </summary>
        private void Reset()
        {
            //Clear any tickers that might still be active. The old guard checked for
            //Transitioning, but the only caller runs in ActiveGame, so the "Next game"
            //ticker was never actually cleared here.
            arena.setTicker(1, 3, 0, ""); //Next game / status
            arena.setTicker(4, 1, 0, ""); //Victory in x:x

            //Reset
            gameState = GameState.Init;
        }

        /// <summary>
        /// Did someone win yet? If so, set the announcement
        /// </summary>
        private void CheckWinner(int now)
        {
            //See if someone is winning
            if (winningTeam != null)
            {
                //Has XSeconds been called yet?
                if (flagMode == CTFMode.XSeconds)
                { return; }

                int tick = (int)Math.Ceiling((winningTeamTick - now) / 1000.0f);
                switch (tick)
                {
                    case 10:
                        flagMode = CTFMode.TenSeconds;
                        break;
                    case 30:
                        flagMode = CTFMode.ThirtySeconds;
                        break;
                    case 60:
                        flagMode = CTFMode.SixtySeconds;
                        break;
                    default:
                        if (tick <= 0)
                        {
                            flagMode = CTFMode.GameDone;
                        }
                        break;
                }
            }
        }

        private void SetNotifyBypass(int countdown)
        {   //If XSeconds matches one of these, it will bypass that call
            //so there is no duplicate Victory message
            switch (countdown)
            {
                case 10:
                    winningTeamNotify = 1;
                    break;
                case 30:
                    winningTeamNotify = 2;
                    break;
                case 60:
                    winningTeamNotify = 3;
                    break;
            }
        }

        /// <summary>
        /// Poll the flag state while checking for a winner
        /// </summary>
        private void PollCTF(int now)
        {
            //See if we have enough players to keep playing. Reset() only rewound our own
            //state and left arena._bGameRunning true, so the script looped
            //Init -> PreGame -> gameStart() underneath a game the arena thought was live.
            if (arena.PlayersIngame.Count() < minPlayers)
            {
                arena.sendArenaMessage("Not enough players to continue the game.");

                if (arena._bGameRunning)
                { arena.gameEnd(); }   //Game.End sets gameState to PostGame for us
                else
                { Reset(); }

                return;
            }

            CheckWinner(now);


            int countdown = winningTeamTick > 0 ? (int)Math.Ceiling((winningTeamTick - now) / 1000.0f) : 0;
            switch (flagMode)
            {
                case CTFMode.Aborted:
                    arena.setTicker(4, 1, 0, "");
                    arena.sendArenaMessage("Victory has been aborted.", CFG.flag.victoryAbortedBong);
                    flagMode = CTFMode.None;
                    break;
                case CTFMode.TenSeconds:
                    //10 second win timer
                    if (winningTeamNotify == 1) //Been notified already?
                    { break; }
                    winningTeamNotify = 1;
                    arena.sendArenaMessage(string.Format("Victory for {0} in {1} seconds!", winningTeam._name, countdown), CFG.flag.victoryWarningBong);
                    flagMode = CTFMode.None;
                    break;
                case CTFMode.ThirtySeconds:
                    //30 second win timer
                    if (winningTeamNotify == 2) //Been notified already?
                    { break; }
                    winningTeamNotify = 2;
                    arena.sendArenaMessage(string.Format("Victory for {0} in {1} seconds!", winningTeam._name, countdown), CFG.flag.victoryWarningBong);
                    flagMode = CTFMode.None;
                    break;
                case CTFMode.SixtySeconds:
                    //60 second win timer
                    if (winningTeamNotify == 3) //Been notified already?
                    { break; }
                    winningTeamNotify = 3;
                    arena.sendArenaMessage(string.Format("Victory for {0} in {1} seconds!", winningTeam._name, countdown), CFG.flag.victoryWarningBong);
                    flagMode = CTFMode.None;
                    break;
                case CTFMode.XSeconds:
                    //Initial win timer upon capturing
                    SetNotifyBypass(countdown); //Checks to see if xSeconds matches any other timers
                    arena.setTicker(4, 1, CFG.flag.victoryHoldTime, "Victory in ");
                    arena.sendArenaMessage(string.Format("Victory for {0} in {1} seconds!", winningTeam._name, countdown), CFG.flag.victoryWarningBong);
                    flagMode = CTFMode.None;
                    break;
                case CTFMode.GameDone:
                    //Game is done
                    gameWon = true;
                    
                    // Send improved game end data with most played classes and all participants
                    CTFGameType.ImprovedWebIntegration.SendGameEndDataToWebsite(arena, baseUsed, playerClassPlayTimes, 
                                                                                        playerLastClassSwitch, winningTeam);
                    
                    arena.gameEnd();
                    break;
            }

            UpdateCTFTickers();
            UpdateKillStreaks();
            UpdateFlagCarryStats(now);
        }
        /// <summary>
        /// Handles a player's produce request
        /// </summary>
        [Scripts.Event("Player.Produce")]
        public bool playerProduce(Player player, Computer computer, VehInfo.Computer.ComputerProduct product)
        {
            string[] titlesToCheck = { "SciOps", "Sergeant", "Captain", "BioChem Trooper" };
            if (currentEventType == EventType.CTFX && titlesToCheck.Contains(product.Title)){
                ChangePlayerSkill(player, product.Title);
                player.resetInventory(true);
                WarpPlayerToRange(player, 985, 997, 1117, 1129);
                //return false;
            }
            return true;
        }

        // mined stat dictionary that holds list of teams and the count of TSO and TOX mined
        private Dictionary<string, int> minedStats = new Dictionary<string, int>();
        // Per-player mining for the stats payload; minedStats above is per TEAM and cannot be
        // attributed after the fact. Keyed by Player like playerClassPlayTimes, reset with minedStats.
        private Dictionary<Player, int> minedTsoByPlayer = new Dictionary<Player, int>();
        private Dictionary<Player, int> minedToxByPlayer = new Dictionary<Player, int>();

        // Add stat method for tracking per team and per item type ("Tso" for 2005, "Tox" for 2009)
        private void AddStat(int itemId, int quantity, string teamName)
        {
            // Build the key based on item id: 2005 -> "Tso mined", 2009 -> "Tox mined"
            string key = (itemId == 2005) ? teamName + " Tso mined" : teamName + " Tox mined";
            if (!minedStats.ContainsKey(key))
                minedStats[key] = 0;
            minedStats[key] += quantity;
        }

        /// <summary>
        /// Triggered when a player requests to pick up an item
        /// </summary>
        [Scripts.Event("Player.ItemPickup")]
        public bool playerItemPickup(Player player, Arena.ItemDrop drop, ushort quantity)
        {
            var itemId = drop.item.id;
            var itemName = drop.item.name;

            // For item IDs 2005 (Tso) or 2009 (Tox), update the team's stat accordingly.
            if ((itemId == 2005 || itemId == 2009) && quantity == 5)
            {
                int terrainID = player._arena.getTerrainID(player._state.positionX, player._state.positionY);
                // Any sided team, by the zone's own suffix rule - not just the two pub teams. Live
                // rows showed mined = 0 on every OvD because "PT T" contains neither word.
                if (terrainID == 0 && player._team != null && (IsTitanSideTeam(player._team) || IsCollectiveSideTeam(player._team)))
                {
                    AddStat(itemId, quantity, player._team._name);
                    var minedBy = (itemId == 2005) ? minedTsoByPlayer : minedToxByPlayer;
                    minedBy[player] = (minedBy.ContainsKey(player) ? minedBy[player] : 0) + quantity;
//arena.sendArenaMessage(string.Format("{0} has mined 5 {1}!", player._alias, itemName));
                }
            }

            // Item skins (CTFSkins.cs): an owner picking up the stock item or a skin gets their pick; anyone else picking up a
            // skin gets the stock item. Takes the pile as the engine would, minus the bounty.
            ItemInfo skinGive = Skins.PickupItem(player, drop.item, isChampEnabled, skinsEnabled);
            if (skinGive != null && skinGive.id != drop.item.id)
            {
                if (quantity >= drop.quantity) { drop.quantity = 0; player._arena._items.Remove(drop.id); }
                else drop.quantity = (short)(drop.quantity - quantity);
                player.inventoryModify(skinGive, quantity);
                Helpers.Object_ItemDropUpdate(player._arena.Players, drop.id, (ushort)drop.quantity);
                return false;
            }

            // (the old "Tranq picked up while holding the Needler (SubZero) -> Subzero Tranq" swap is the skin pickup rule above now)
            return true;
        }

        /// <summary>
        /// Triggered when a player attempts to use a warp item
        /// </summary>
        private Dictionary<ushort, int> summonedCounts = new Dictionary<ushort, int>();
        // The other side of summonedCounts: how many summons each SQUAD LEADER performed, keyed the
        // same way. summonedCounts alone credits the passenger, never the driver.
        private Dictionary<ushort, int> summonsPerformed = new Dictionary<ushort, int>();

        /// <summary>Squad Leader Summon (35) or the medic's Teleport Summoner: both pull a teammate to the user.</summary>
        private bool IsSummonItem(ItemInfo.WarpItem item)
        {
            if (item == null)
                return false;
            if (item.id == 35)
                return true;
            return item.name != null && item.name.Equals("Teleport Summoner", StringComparison.OrdinalIgnoreCase);
        }

        [Scripts.Event("Player.WarpItem")]
        public bool playerWarpItem(Player player, ItemInfo.WarpItem item, ushort targetPlayerID, short posX, short posY)
        {
            try { GoldenTranq.OnWarpItem(player, item, isChampEnabled && skinsEnabled); } catch (Exception gtEx) { Console.WriteLine("[GoldenTranq] warp: " + gtEx.Message); }   // HELLO THERE
            // Get target player reference upfront
            Player targetPlayer = arena.Players.FirstOrDefault(p => p._id == targetPlayerID);
            DropPendingOccupyForWarp(player, item, targetPlayer);   // a warp never gets a vehicle dropped on it (a recall re-queues below)

            // if (item.warpMode == Assets.ItemInfo.WarpItem.WarpMode.Portal)
            // {

            // }

            // GetPrimarySkillName and if Combat Engineer, update computers send update
            // if (GetPrimarySkillName(player) == "Combat Engineer" || 
            //     (targetPlayer != null && GetPrimarySkillName(targetPlayer) == "Combat Engineer"))
            // {
            //     foreach (Vehicle v in arena.Vehicles)
            //     {
            //         if (v is Computer)
            //         {
            //             Computer comp = (Computer)v;
            //             comp._sendUpdate = true;
            //             comp.poll();
            //         }
            //     }
            //     // debug message to the player that they're receiving an update on turret hp
            //     //player.sendMessage(0, "Debug: Updating turret hp for player client.");
            // }

            // If player DropShip Recalling and they have a persistent build, perform wipe and buy
            if (item.id == 46){
                playersWithAutoDrops.Remove(player._alias);   // a recall restocks: the next warp to a teammate drops again
                InitiateAutoOccupy(player, "dropship recall", OccupyWhen.Recall);   // scheduled: runs once the warp has landed them
                string buildString;
                bool autoBuyOn = autoBuyEnabled.ContainsKey(player._alias) && autoBuyEnabled[player._alias], loadoutDropped = false;
                if (autoBuyOn && (buildString = AutoBuyLoadout(player, out loadoutDropped)) != null)
                {
                    HardEconomy.NoteAutobuy(player);          // TP Pub: a rebuy prints one compact line, not a warning per item
                    WipeAndBuy(player, buildString, true);
                }
                else if (autoBuyOn && !loadoutDropped && !premadeActiveSetup.ContainsKey(player._alias.ToLower()))
                    // Any class change (?swap, F11, a build that swaps class) clears the saved loadout - say so instead of nothing.
                    player.sendMessage(0, "AutoBuy is on, but there is no saved loadout to rebuy (a class change clears it): ?bw <build or items> saves one.");
            }
            // Auto-drop: the player ARRIVING at a teammate brings supplies to where they land.
            //   35 = Squad Leader Summon: the SL (player) pulls the target TO the SL.
            //   21 = Suit Teleport: the player goes TO the target.
            // The old version checked and spawned at the WARPER's origin (the dropship, which is never
            // in base bounds) and, on a summon, priced the SL's own build - so suit teleports never
            // fired and summons dropped the wrong player's differential at the SL's feet.
            if ((IsSummonItem(item) || item.id == 21) && targetPlayerID != 0 && targetPlayer != null && targetPlayer._team == player._team)
            {
                bool summon = IsSummonItem(item);
                Player arriving = summon ? targetPlayer : player;
                Player host = summon ? player : targetPlayer;
                AutoDropOnWarp(arriving, host);
            }

            // Redirect DropShip Recall for CTFX Event
            if (currentEventType == EventType.CTFX && item.id == 46){
                WarpPlayerToRange(player, 985, 997, 1117, 1129, 0);
                return false;
            }

            // Redirect DropShip Recall for TDM Event
            // if (currentEventType == EventType.TDM && _tdmInstance != null && item.id == 46){
            //     // Warp to TDM spawn with 0 energy like other events
            //     if (player._team._name.Contains("Collective"))
            //         WarpPlayerToRange(player, 1423, 1423, 541, 541, 0);
            //     else if (player._team._name.Contains("Titan"))
            //         WarpPlayerToRange(player, 1390, 1390, 541, 541, 0);
            //     return false;
            // }

            // Redirect DropShip Recall for Gladiator Event
            if (currentEventType == EventType.Gladiator && item.id == 46){
                WarpPlayerToRange(player, 900, 900, 509, 509, 0);
                return false;
            }

            if (currentEventType == EventType.MiniTP && item.id == 46){
                if (player._team._name.Contains("Titan"))
                    WarpPlayerToRange(player, 654, 654, 518, 518, 0);
                else if (player._team._name.Contains("Collective"))
                    WarpPlayerToRange(player, 648, 648, 565, 565, 0);
                return false;
            }

            var flag = arena.getFlag("Bridge3");
            // Send a message to the arena that they have been summoned if they're carrying a flag.
            // Counted for BOTH summon items; the offence-wins-by-summoning-the-carrier rule below
            // is still the Squad Leader's alone.
            if (IsSummonItem(item)){
                //If Overtime, Summoning players empowers them with a "Steron Boost OT" (unless disabled during flag victory)
                if (isSD && !steronBoostsDisabled && !isSecondOvertime && targetPlayer != null){
                    ItemInfo.UtilityItem steronBoost = AssetManager.Manager.getItemByName("Steron Boost OT") as ItemInfo.UtilityItem;
                    if (steronBoost != null){
                        targetPlayer.inventoryModify(steronBoost.id, 1);
                    }
                }

                //If second overtime, Summoning players empowers them with a "Steron Boost OT2" (unless disabled during flag victory)
                if (isSecondOvertime && !steronBoostsDisabled && targetPlayer != null){
                    ItemInfo.UtilityItem steronBoost10 = AssetManager.Manager.getItemByName("Steron Boost OT2") as ItemInfo.UtilityItem;
                    if (steronBoost10 != null){
                        targetPlayer.inventoryModify(steronBoost10.id, 1);
                    }
                }

                // Track summoned count for target player
                if (!summonedCounts.ContainsKey(targetPlayerID))
                    summonedCounts[targetPlayerID] = 0;
                summonedCounts[targetPlayerID]++;
                if (!summonsPerformed.ContainsKey(player._id))
                    summonsPerformed[player._id] = 0;
                summonsPerformed[player._id]++;

                if (is5v5 && item.id == 35){
                    if (targetPlayer != null) {
                        if (flag != null && flag.carrier == targetPlayer && baseUsed != "Unknown" && winningTeamOVD != "offense"){
                            arena.sendArenaMessage(String.Format("Offense wins! {0} has been summoned with a flag!", targetPlayer._alias));
                            winningTeamOVD = "offense";
                        }
                    }
                }
            }

            // Send a message to the arena if a player is carrying a flag and warps to a teammate or blinks
            if (player != null && is5v5) {
                // Check if player's team has a Squad Leader
                bool hasSquadLeader = player._team.ActivePlayers.Any(p => 
                    p._skills.Values.Any(s => s.skill.Name == "Squad Leader"));

                if (hasSquadLeader && flag != null && flag.carrier == player && baseUsed != "Unknown" && winningTeamOVD != "offense")
                {
                    arena.sendArenaMessage(String.Format("Offense wins! {0} has warped with a flag!", player._alias));
                    winningTeamOVD = "offense";
                }
            }

            // Test Teleport Disruptor logic working via Player.WarpItem script event
            // if (item.id == 35 || item.id == 17){ // "Teleport Summoner" and "Squad Leader Summon"
            //     Player targetPlayer = arena.Players.FirstOrDefault(p => p._id == targetPlayerID);
            //     if (targetPlayer != null){
            //         ItemInfo.UtilityItem teleportDisruptor = AssetManager.Manager.getItemByName("Teleport Disruptor") as ItemInfo.UtilityItem;
            //         if (teleportDisruptor != null){
            //             int disruptorRange = teleportDisruptor.antiWarpDistance;
            //             bool isDisrupted = arena.Players.Any(p => 
            //                 p._id != targetPlayer._id && 
            //                 p.activeUtilities.Any(u => u.activateSound != null) && 
            //                 p._state.energy > 0 && 
            //                 Math.Sqrt(
            //                     Math.Pow((p._state.positionX - targetPlayer._state.positionX) / 16, 2) + 
            //                     Math.Pow((p._state.positionY - targetPlayer._state.positionY) / 16, 2)
            //                 ) <= disruptorRange);
            //             if (isDisrupted){
            //                 player.sendMessage(-1, "The player you are trying to summon is currently being teleport disrupted.");
            //                 return false;
            //             }
            //         }
            //     }
            // }
            return true;
        }

