        /// <summary>Resolved kits: setup name -> (item, quantity). Built once, see PremadeKits().</summary>
        private Dictionary<string, List<KeyValuePair<ItemInfo, int>>> _premadeResolved;

        /// <summary>
        /// Resolves the name table into ItemInfo once and caches it, so per-spawn restocking does no
        /// name lookups at all. Anything that fails to resolve is LOGGED rather than silently
        /// skipped - getItemByName's own warning is commented out in AssetManager, so without this a
        /// typo'd item would just quietly go missing from the kit.
        /// </summary>
        private Dictionary<string, List<KeyValuePair<ItemInfo, int>>> PremadeKits()
        {
            if (_premadeResolved != null)
                return _premadeResolved;

            _premadeResolved = new Dictionary<string, List<KeyValuePair<ItemInfo, int>>>();
            List<string> problems = new List<string>();
            int resolved = 0;

            foreach (KeyValuePair<string, string> kit in premadeKits)
            {
                List<KeyValuePair<ItemInfo, int>> entries = new List<KeyValuePair<ItemInfo, int>>();

                foreach (string rawLine in kit.Value.Split('\n'))
                {
                    string line = rawLine.Trim();
                    if (line.Length == 0)
                        continue;

                    int split = line.IndexOf(' ');
                    int qty;
                    if (split < 0 || !Int32.TryParse(line.Substring(0, split), out qty))
                    {
                        problems.Add(kit.Key + " -> malformed line '" + line + "'");
                        continue;
                    }

                    string itemName = line.Substring(split).Trim();
                    ItemInfo item = arena._server._assets.getItemByName(itemName);
                    if (item == null)
                    {
                        problems.Add(kit.Key + " -> no such item '" + itemName + "'");
                        continue;
                    }

                    entries.Add(new KeyValuePair<ItemInfo, int>(item, qty));
                    resolved++;
                }

                _premadeResolved[kit.Key] = entries;
            }

            if (problems.Count > 0)
                Log.write(TLog.Warning, "CTF premades: {0} unresolved entr(ies): {1}",
                    problems.Count, String.Join(" | ", problems));
            else
                Log.write(TLog.Normal, "CTF premades: {0} kits, {1} items, all resolved.",
                    _premadeResolved.Count, resolved);

            return _premadeResolved;
        }

        /// <summary>
        /// Premade pick -> the REAL base class it converts to. Item skillLogic references base-class
        /// skills, so the player must genuinely BE the base class for their kit to be usable.
        /// </summary>
        private static readonly Dictionary<string, string> premadeSetupClass = new Dictionary<string, string>
        {
            { "Combat Engineer - Defense", "Combat Engineer" },
            { "Field Medic - Defense", "Field Medic" },
            { "Heavy Weapons - Defense: MML/AC", "Heavy Weapons" },
            { "Infantry - Defense: CAW", "Infantry" },
            { "Infantry - Defense: Shotgun", "Infantry" },
            { "Squad Leader - Offense", "Squad Leader" },
            { "Heavy Weapons - Offense: RPG/AC", "Heavy Weapons" },
            { "Infantry - Offense: Cara Armor", "Infantry" },
            { "Infantry - Offense: Dual RG", "Infantry" },
            { "Infantry - Offense: CMP6 Armor", "Infantry" },
        };

        /// <summary>
        /// alias (lowercased) -> the premade they are currently running, so it can be re-applied on
        /// spawn. Cleared in playerLeaveArena: an alias-keyed dictionary that outlives the player is
        /// exactly the ghost-state pattern behind the autoOccupy crash.
        /// </summary>
        private Dictionary<string, string> premadeActiveSetup = new Dictionary<string, string>();

        /// <summary>
        /// Grants the shortfall of a premade kit. Idempotent - safe to call on every spawn.
        /// </summary>
        private void premadeApplySetup(Player player, string setupName, bool announce)
        {
            if (HardEconomy.On) return;                  // TP Hard: no free premade kits
            if (player == null || setupName == null)
                return;

            List<KeyValuePair<ItemInfo, int>> kit;
            if (!PremadeKits().TryGetValue(setupName, out kit))
                return;

            // One inventory packet for the whole kit (a synced inventoryModify sends the full 409-byte inventory per item).
            bool changed = false;
            foreach (KeyValuePair<ItemInfo, int> entry in kit)
            {
                int need = entry.Value - player.getInventoryAmount(entry.Key.id);
                if (need <= 0)
                    continue;
                // One item per slot: the respawn top-up never puts a kit armor on next to another armor (or any slotted
                // utility next to another of its slot). An armor the player chose since the kit (?b) stays; they never wear two.
                int slot = SlotCategory(entry.Key);
                if (slot >= 0 && player._inventory.Values.Any(ii => ii.item != null && ii.item.id != entry.Key.id && ii.quantity > 0 && SlotCategory(ii.item) == slot))
                    continue;
                player.inventoryModify(false, entry.Key, need);
                changed = true;
            }
            if (changed)
                player.syncInventory();

            if (announce)
                player.sendMessage(0, String.Format("&{0} applied - it re-applies every respawn. Buy another setup to switch.", setupName));
        }

        /// <summary>
        /// The premade half of a skill purchase. Called from PlayerShopSkillPurchase BEFORE anything
        /// else, because the conversion changes the player's class - so the anti-abuse vehicle reset
        /// and warp further down that handler act on the final class, not the old one.
        /// </summary>
        private void premadeHandleSkillPurchase(Player player, SkillInfo skill)
        {
            if (player == null || skill == null || skill.Name == null)
                return;

            // Runs for EVERY skill purchase, premade or not. Picking any other class has to end the
            // old kit's auto-restock, or the next spawn re-grants it for a class that cannot use it.
            // A premade's autopickup list waits for the kit (below): worked out now, the player still holds the premade's
            // own skill, every kit weapon fails its class check and its ammo was listed as "no weapon uses it" (10-24).
            bool isPremade = premadeKits.ContainsKey(skill.Name);
            premadeOnClassChanged(player, skill.Name, !isPremade);

            if (isPremade)
            {
                // CONVERT the pick into the REAL base class via the zone's own event runner - the
                // same mechanism the cfg uses to class every new player (FirstTimeSkillSetup:
                // "addskill=Infantry"). wipeskill first clears the premade marker and any leftovers,
                // so the player genuinely IS the base class and all item skillLogic (%3|3 etc.)
                // passes. Soup found skillModify alone did NOT take (live 2026-08-08: kit granted
                // but "not the infantry class or class 3").
                string baseClass;
                if (premadeSetupClass.TryGetValue(skill.Name, out baseClass))
                {
                    // wipeskill strips EVERY skill the player holds - including Staff (8) and
                    // Referee (14). A ref buying a premade would silently lose their ref powers, so
                    // privileged players get the addskill WITHOUT the wipe. Everyone else gets the
                    // clean wipe, which is what makes the class conversion reliable.
                    bool privileged = player._skills.Values.Any(sk => sk.skill.SkillId == 8
                                                                   || sk.skill.SkillId == 14);
                    Logic_Assets.RunEvent(player, privileged
                        ? "addskill=" + baseClass
                        : "wipeskill,addskill=" + baseClass);
                }

                // Picking a premade REPLACES the loadout, the way a ?bw does (WipeAndBuy): it used to top the kit up over
                // whatever the last build left, so a custom ?bw's CMP6 plus the Cara kit's Carapace meant two armors on every
                // respawn (ScrubEraser, 2026-10-24). The newest choice wins; minerals are kept as WipeAndBuy keeps them.
                WipeForNewLoadout(player);
                premadeApplySetup(player, skill.Name, true);
                RefreshAutoPickupForLoadout(player);
                EnableAutoPickupForDefaultLoadout(player);
            }
        }

        /// <summary>The ?bw wipe (WipeAndBuy) for a premade pick: everything goes but the minerals and the items it keeps.</summary>
        private void WipeForNewLoadout(Player player)
        {
            var keep = new Dictionary<int, int>();
            foreach (int itemID in new[] { 2005, 2007, 2009, 9, 10, 11 })
                keep[itemID] = player.getInventoryAmount(itemID);
            player.resetInventory(false);
            foreach (var kv in keep)
            {
                ItemInfo info = player._server._assets.getItemByID(kv.Key);
                if (info == null || kv.Value <= 0)
                    continue;
                player.inventoryModify(false, info, kv.Value);
                int shortBy = kv.Value - player.getInventoryAmount(kv.Key);
                if (IsMineral(kv.Key) && shortBy > 0) DropMineralHere(player, info, shortBy);
            }
        }

        /// <summary>The slot a slotted utility fills (every armor is category 10, one allowed), else -1.</summary>
        private static int SlotCategory(ItemInfo item)
        {
            var u = item as ItemInfo.UtilityItem;
            return u != null && u.maxSlotted > 0 ? u.maxSlottedCategoryCode : -1;
        }

        /// <summary>
        /// Single point of truth for "the player's class changed". Call from EVERY class-change path.
        ///
        /// There are two of them - PlayerShopSkillPurchase (F11) and HandleSwapCommand (?swap) - and
        /// hooking only the first is what caused the reported bug: swapping to a plain base class
        /// left the player still flagged as running their premade, so playerSpawn re-granted that kit
        /// for a class that could not carry it (overweight, unqualified).
        ///
        /// If the new pick is itself a premade it replaces the old one; anything else clears the flag.
        /// </summary>
        public void premadeOnClassChanged(Player player, string newSkillName, bool autoPickupNow = true)
        {
            if (player == null)
                return;

            string key = player._alias.ToLower();
            if (newSkillName != null && premadeKits.ContainsKey(newSkillName))
                premadeActiveSetup[key] = newSkillName;
            else
                premadeActiveSetup.Remove(key);

            // ?autopickup follows the loadout, and a premade IS a loadout. A plain class change is
            // not: the build it clears is usually about to be replaced by WipeAndBuy, which
            // re-derives when it persists the new one.
            if (autoPickupNow && premadeActiveSetup.ContainsKey(key))
            {
                RefreshAutoPickupForLoadout(player);
                EnableAutoPickupForDefaultLoadout(player);
            }
        }
        #endregion // TP2 premade setups

        // REMOVED 2026-08-30: SetupEquipmentSkills and its 13 HandleBuildCommand kit checks.
        //
        // Every id it tested (18, 20, 22-27, 29-33) was deleted from ctfpl.rpg in Soup's update, so
        // no player could hold one and the method was a guaranteed no-op. The "Classes - Premades"
        // region above does the same job - kit on class pick, restock on respawn - driven by the new
        // rpg entries (ids 40-49) and its own loadout table. All five call sites were removed with it.
        //
        // Deliberately KEPT: playersWithAutoDrops / ClearAutoDropTracking below. Despite sitting next
        // to this code they serve the auto-drop system (Squad Leader Summon / Suit Teleport inside
        // owned flag bounds), not the equipment setups, and that is still a live feature.

        // Track players who have already received auto-drops to prevent duplicates
        private HashSet<string> playersWithAutoDrops = new HashSet<string>();

        /// <summary>
        /// Clears auto-drop tracking for a specific player
        /// </summary>
        private void ClearAutoDropTracking(Player player)
        {
            playersWithAutoDrops.Remove(player._alias);
        }

        /// <summary>
        /// Checks if a player is within the bounds of a flag owned by their team
        /// </summary>
        private bool IsPlayerInOwnedFlagBounds(Player player)
        {
            // Check if player is within any of the base areas defined in ManageFixedDropLocations
            // and if their team owns a flag in that area
            var playerX = player._state.positionX;
            var playerY = player._state.positionY;

            // Define base boundaries (same as in ManageFixedDropLocations)
            var baseBounds = new[]
            {
                new { Name = "A7", MinX = 3 * 16, MaxX = 73 * 16, MinY = 432 * 16, MaxY = 514 * 16 },
                new { Name = "D7", MinX = 255 * 16, MaxX = 324 * 16, MinY = 419 * 16, MaxY = 506 * 16 },
                new { Name = "F5", MinX = 368 * 16, MaxX = 434 * 16, MinY = 321 * 16, MaxY = 399 * 16 },
                new { Name = "F6", MinX = 379 * 16, MaxX = 479 * 16, MinY = 439 * 16, MaxY = 508 * 16 },
                new { Name = "A5", MinX = 3 * 16, MaxX = 76 * 16, MinY = 315 * 16, MaxY = 385 * 16 },
                new { Name = "B8", MinX = 128 * 16, MaxX = 212 * 16, MinY = 556 * 16, MaxY = 628 * 16 }
            };

            foreach (var bounds in baseBounds)
            {
                // Check if player is within this base area
                if (playerX >= bounds.MinX && playerX <= bounds.MaxX && 
                    playerY >= bounds.MinY && playerY <= bounds.MaxY)
                {
                    // Check if team owns any flag in this area
                    foreach (var flag in arena._flags.Values)
                    {
                        if (flag.posX >= bounds.MinX && flag.posX <= bounds.MaxX &&
                            flag.posY >= bounds.MinY && flag.posY <= bounds.MaxY &&
                            flag.team == player._team)
                        {
                            return true;
                        }
                    }
                }
            }

            return false;
        }

        /// <summary>
        /// Checks if a player has Squad Leader skill
        /// </summary>
        private bool IsSquadLeader(Player player)
        {
            return player._skills.Values.Any(s => s.skill.Name == "Squad Leader");
        }

        /// <summary>
        /// Squad Leader specific items with max quantities
        /// </summary>
        private static Dictionary<string, int> squadLeaderItems = new Dictionary<string, int>
        {
            { "stim pack", 1 },
            { "haywire grenade", 4 },
            { "grapeshot mine", 5 },
            { "ap mine", 5 }
        };

        /// <summary>
        /// Legacy entry (the *testdrop mod command): the differential at the player's own feet.
        /// </summary>
        private void SpawnBuildDifferentialItems(Player player, bool isSquadLeaderScenario = false)
        {
            List<Tuple<string, int>> items = ComputeBuildDifferential(player, isSquadLeaderScenario);
            int spawned = SpawnStacksAt(items, player._state.positionX, player._state.positionY, player);
            playersWithAutoDrops.Add(player._alias);
            player.sendMessage(0, String.Format("Auto-drop: spawned {0} stack(s).", spawned));
        }

        /// <summary>
        /// What the player's build leaves room for: for every item type in their build, max minus
        /// what they carry (or the Squad Leader support kit when arriving at an SL). Pure - spawns nothing.
        /// </summary>
        /// <summary>
        /// The build-table preset the player is on, for the auto-drop extras: the last ?bwd build, else the preset
        /// ?b / ?bw stored in persistentBuilds. Only ?bwd ever set lastUsedBuild, so without the second source a
        /// ?b / ?bw player's extras were never computed (the SkillId guesses below point at skills that no longer
        /// exist on live: "Unable to get skill by ID: 18 / 20"). Null when they are on no preset.
        /// </summary>
        private string DropBuildFor(Player player)
        {
            string name;
            if (lastUsedBuild.TryGetValue(player, out name) && !String.IsNullOrEmpty(name))
                return name;
            if (persistentBuilds.TryGetValue(player._alias, out name) && !String.IsNullOrEmpty(name) && buildSets.ContainsKey(name.ToLower()))
                return name.ToLower();
            return null;
        }

        private List<Tuple<string, int>> ComputeBuildDifferential(Player player, bool isSquadLeaderScenario = false)
        {
            List<Tuple<string, int>> itemsToSpawn = new List<Tuple<string, int>>();
            string dropType;

            if (isSquadLeaderScenario)
            {
                // Squad Leader scenario - use specialized items
                dropType = "Squad Leader support";
                
                foreach (var itemType in squadLeaderItems)
                {
                    string itemName = itemType.Key;
                    int maxQuantity = itemType.Value;

                    ItemInfo item = AssetManager.Manager.getItemByName(itemName);
                    if (item != null)
                    {
                        int currentQuantity = player.getInventoryAmount(item.id);
                        int differential = maxQuantity - currentQuantity;

                        if (differential > 0)
                        {
                            itemsToSpawn.Add(new Tuple<string, int>(itemName, differential));
                        }
                    }
                }
            }
            else
            {
                // Normal scenario - calculate build differential
                dropType = "build differential";
                
                // Get player's last used build or current build
                string buildName = DropBuildFor(player);
                if (buildName == null)
                {
                    buildName = "";
                    // Try to determine build from current skills
                    if (player._skills.Values.Any(s => s.skill.SkillId == 32))
                        buildName = "dinfcaw";
                    else if (player._skills.Values.Any(s => s.skill.SkillId == 33))
                        buildName = "dinf";
                    else if (player._skills.Values.Any(s => s.skill.SkillId == 31))
                        buildName = "oinfcara";
                    else if (player._skills.Values.Any(s => s.skill.SkillId == 29))
                        buildName = "oinf";
                    else if (player._skills.Values.Any(s => s.skill.SkillId == 18))
                        buildName = "ohvy";
                    else if (player._skills.Values.Any(s => s.skill.SkillId == 20))
                        buildName = "dhvy";
                    else if (player._skills.Values.Any(s => s.skill.SkillId == 30))
                        buildName = "hvyMG";
                    else if (player._skills.Values.Any(s => s.skill.SkillId == 22))
                        buildName = "slstandard";
                    else if (player._skills.Values.Any(s => s.skill.SkillId == 23))
                        buildName = "jtstandard";
                    else if (player._skills.Values.Any(s => s.skill.SkillId == 24))
                        buildName = "footjt";
                    else if (player._skills.Values.Any(s => s.skill.SkillId == 25))
                        buildName = "medstandard";
                    else if (player._skills.Values.Any(s => s.skill.SkillId == 26))
                        buildName = "engstandard";
                    else if (player._skills.Values.Any(s => s.skill.SkillId == 27))
                        buildName = "infilstandard";
                }

                if (!string.IsNullOrEmpty(buildName) && buildSets.ContainsKey(buildName))
                {
                    var buildData = buildSets[buildName];
                    List<Tuple<string, ushort>> buildItems = buildData.Item1;

                    // Track the ammo used by the build
                    Dictionary<string, int> usedAmmo = new Dictionary<string, int>();

                    // Iterate through the build items and record their quantities
                    foreach (var item in buildItems)
                    {
                        string ammoName = item.Item1.ToLower();
                        if (maxAmmoQuantities.ContainsKey(ammoName))
                        {
                            usedAmmo[ammoName] = item.Item2;
                        }
                    }

                    // Calculate what's missing to reach max quantities for items in the build
                    foreach (var ammoType in maxAmmoQuantities.Keys)
                    {
                        string normalizedAmmoType = ammoType.ToLower();
                        
                        // Only consider items that are actually in the player's build
                        if (usedAmmo.ContainsKey(normalizedAmmoType))
                        {
                            int maxQuantity = maxAmmoQuantities[ammoType];
                            
                            ItemInfo ammoItem = AssetManager.Manager.getItemByName(ammoType);
                            if (ammoItem != null)
                            {
                                int currentQuantity = player.getInventoryAmount(ammoItem.id);
                                int differential = maxQuantity - currentQuantity;

                                if (differential > 0)
                                {
                                    itemsToSpawn.Add(new Tuple<string, int>(ammoType, differential));
                                }
                            }
                        }
                    }
                }
            }

            return itemsToSpawn;
        }

        #region Auto-drop on warp (the arriving player brings supplies)

        private const int AUTODROP_FLAG_RANGE = 40 * 16;   // destination must be within 40 tiles of a flag the team holds
        private const int AUTODROP_LAND_POLL_MS = 150;     // the warp hook runs BEFORE the move; look for the landing this often
        private const int AUTODROP_LAND_SETTLE_MS = 600;   // still on the server's placeholder spot after this = landed there
        private const int AUTODROP_LAND_TIMEOUT_MS = 4000; // not near the host by then = the warp never happened
        private const int AUTODROP_LAND_RANGE = 25 * 16;   // landed farther than this from the host = the warp never happened
        private const int AUTODROP_STIM_HP = 40;           // stims drop on a squad leader at this health or less (TakeStimForSL)
        private const int AUTODROP_AREA_FULL_PLAYERS = 4;  // an item is topped up to this many players' worth (its max) per area
        // SL kits stay sparse (Travis, 2026-10-16): an SL summons every 20-50 s and cannot use a kit per summon.
        private const int AUTODROP_SL_KIT_EVERY_MS = 60000; // one kit per squad leader per minute
        private const int AUTODROP_SL_AREA_PLAYERS = 1;     // and one player's worth of each kit item per area
        private readonly Dictionary<string, int> _slKitAt = new Dictionary<string, int>();   // SL alias -> TickCount of the last kit

        // ---- Stack management (Travis, 2026-10-16) ------------------------------------------------------------
        // The 10-07 bundle rewrite flooded arenas with STACKS. The server's own cap (maxArenaItems 10000) was never
        // hit, but play broke down at a few hundred stacks - finicky pickups, mine spawns not showing. Quantities are
        // not the problem (a stack can be large), the number of stacks is. So autodrop:
        //  1. always drops the sentry and 10 tranqs - no cap - and tops every other item up, item by item, to
        //     AUTODROP_AREA_FULL_PLAYERS players' worth in the area (AutoDropAreaCap);
        //  2. adds to a pile within pickup reach instead of making another stack beside it, however big that pile is;
        //  3. never makes a NEW stack once the arena holds the budget - it may still add to existing piles;
        //  4. can be switched off zone-wide by staff (*autodrop off), saved across restarts.
        // Expiry stays the terrain's own PrizeExpire (pollItemExpiration's small-stack cleanup is untouched).
        // *trimitems is the emergency soft reset when an arena is already flooded.
        private const int AUTODROP_AREA_RANGE = 400;       // px around the landing spot that counts as "the drop"
        private const int AUTODROP_STACK_RANGE = 87;       // px = ItemPickupDistance: closer than this, add to that pile
        private static readonly string AUTODROP_STATE_PATH = System.IO.Path.Combine("scripts", "GameTypes", "CTF", "AutoDropState.txt");
        private static bool _autoDropOff;                  // zone-wide (every arena), staff-only, persisted
        private static int _autoDropBudget = 200;          // arena stacks; below the 300-500 where trouble was seen
        private static bool _autoDropStateLoaded;
        // This arena's tally since it opened, for *autodrop.
        private int _adEvents, _adNewStacks, _adMerged, _adSkippedStocked, _adRefusedBudget, _adPeakStacks;
        private string _lastAutoDropOutcome = "";   // what the last auto-drop decided, item by item - *testwarpdrop prints it

        // The drops that matter most regardless of build (Travis, 2026-09-11): a spare sentry and 10
        // tranqs. Class/build-specific extras can come later without touching the mechanism.
        private static readonly List<Tuple<string, int>> autoDropAlways = new List<Tuple<string, int>>
        {
            Tuple.Create("sentry", 1),
            Tuple.Create("tranq", 10),
        };

        // The defensive drop (Travis, 2026-10-16; since 10-17 every time, each at its max minus what the player's build
        // gives): these maxes, listed TOP of the pile first - sentry on top, then tranq, Ammo MG, rocket, pistol ammo, then
        // the mines. Maxes match the *ovd base supply table.
        private static readonly List<Tuple<string, int>> autoDropDefense = new List<Tuple<string, int>>
        {
            Tuple.Create("sentry", 1),
            Tuple.Create("tranq", 10),
            Tuple.Create("ammo mg", 250),
            Tuple.Create("rocket", 40),
            Tuple.Create("ammo pistol", 500),
            Tuple.Create("plasma mine", 5),
            Tuple.Create("ap mine", 5),
            Tuple.Create("bullet mine", 20),
        };

        /// <summary>
        /// True when the player is running a DEFAULT loadout - a premade (F11) or a preset build from
        /// the build table. A custom ?b / ?bw item list is not one. The auto features (buy, drop,
        /// pickup) switch themselves on for default loadouts only; on a custom list the player types
        /// ?ab / ?ad / ?ap if they want them (Travis, 2026-09-12).
        /// </summary>
        /// <summary>
        /// The saved loadout autobuy rebuys, or null. A loadout belongs to the class it was bought for: after a class change
        /// by any route (?swap, F11, a mod's prize) it is dropped instead of rebought, because rebuying it would swap the
        /// player straight back (Travis, 2026-10-17). The next ?bw / preset build saves a new one.
        /// </summary>
        private string AutoBuyLoadout(Player player, out bool dropped)
        {
            dropped = false;
            string build, forClass, dummy;
            if (player == null || !persistentBuilds.TryGetValue(player._alias, out build) || String.IsNullOrEmpty(build))
                return null;
            string now = GetPrimarySkillName(player);
            if (now == "Unknown" || !persistentBuildClass.TryGetValue(player._alias, out forClass) || forClass.Equals(now, StringComparison.OrdinalIgnoreCase))
                return build;
            persistentBuilds.TryRemove(player._alias, out dummy);
            persistentBuildClass.TryRemove(player._alias, out dummy);
            dropped = true;
            player.sendMessage(0, String.Format("AutoBuy: you are {0} now, so your {1} loadout ({2}) was cleared. ?bw a build for this class to save a new one.",
                now, forClass, build));
            return null;
        }

        private bool OnDefaultLoadout(Player p)
        {
            if (p == null)
                return false;
            if (premadeActiveSetup.ContainsKey(p._alias.ToLower()))
                return true;
            string buildString;
            return persistentBuilds.TryGetValue(p._alias, out buildString)
                && !String.IsNullOrEmpty(buildString) && buildSets.ContainsKey(buildString.ToLower());
        }

        private bool AutoDropEnabledFor(Player p)
        {
            if (p == null)
                return false;
            LoadAutoDropState();
            if (_autoDropOff)
                return false;
            return AutoDropPreference(p);
        }

        /// <summary>The player's own choice (?ad, else on for a default loadout), whatever the zone-wide switch says.</summary>
        private bool AutoDropPreference(Player p)
        {
            bool chosen;
            if (autoDropOverride.TryGetValue(p._alias, out chosen))
                return chosen;
            return OnDefaultLoadout(p);
        }

        /// <summary>Terrain a player can buy on: the dropship (id 4) or any store-enabled terrain.</summary>
        private bool OnStoreTerrain(Player p)
        {
            if (p == null)
                return false;
            if (arena.getTerrainID(p._state.positionX, p._state.positionY) == 4)
                return true;
            var terrain = arena.getTerrain(p._state.positionX, p._state.positionY);
            return terrain != null && terrain.storeEnabled;
        }

        /// <summary>Within range of a flag this player's team holds (carried flags do not count).</summary>
        private bool NearOwnedFlag(Player p, short x, short y)
        {
            if (p == null || p._team == null)
                return false;
            foreach (Arena.FlagState f in arena._flags.Values)
            {
                if (f == null || f.team != p._team || f.carrier != null)
                    continue;
                if (Math.Abs(f.posX - x) <= AUTODROP_FLAG_RANGE && Math.Abs(f.posY - y) <= AUTODROP_FLAG_RANGE)
                    return true;
            }
            return false;
        }

        /// <summary>
        /// `arriving` is being warped to `host` (summoned by an SL, or suit-teleporting to a teammate).
        /// If the destination is near a flag the team holds, drop what the arriving player's build
        /// leaves room for - plus the always-drops - where they land. Once per life; ?ad opts out.
        /// A defensive drop needs a flag the team holds nearby; a drop on a squad leader goes wherever the SL is.
        /// </summary>
        private void AutoDropOnWarp(Player arriving, Player host, bool deferred = true)
        {
            AutoDropOnWarp(arriving, host == null ? null
                : new AutoDropHost { Name = host._alias, SquadLeader = IsSquadLeader(host), State = host._state, Dead = () => host.IsDead }, deferred);
        }

        /// <summary>The teammate an auto-drop warp goes to - a player, or a bot (CTF:X bots now, OvD bots later): only what the drop reads.</summary>
        internal sealed class AutoDropHost
        {
            public string Name;
            public bool SquadLeader;
            public Helpers.ObjectState State;   // live: the position at the warp, the health for the SL stim
            public Func<bool> Dead;
        }

        /// <summary>
        /// A warp between a player and a bot teammate - the player teleporting to the bot, or the bot summoning the player -
        /// drops by the same rules as one to a player. Call it BEFORE the warp, as the engine calls Player.WarpItem.
        /// </summary>
        internal void AutoDropOnWarpToBot(Player arriving, Bot host, string name, bool squadLeader)
        {
            if (host != null)
                AutoDropOnWarp(arriving, new AutoDropHost { Name = name, SquadLeader = squadLeader, State = host._state, Dead = () => host.IsDead });
        }

        private void AutoDropOnWarp(Player arriving, AutoDropHost host, bool deferred = true)
        {
            _lastAutoDropOutcome = "not run";
            if (arriving == null || host == null || arriving.IsSpectator || arriving.IsDead)
            {
                _lastAutoDropOutcome = "stopped: arriving player is dead or spectating";
                return;
            }
            if (!AutoDropEnabledFor(arriving) || playersWithAutoDrops.Contains(arriving._alias))
            {
                _lastAutoDropOutcome = _autoDropOff ? "stopped: autodrop is OFF zone-wide"
                    : playersWithAutoDrops.Contains(arriving._alias) ? "stopped: already dropped this life" : "stopped: player has it off (?ad)";
                return;
            }
            // This replicates the buy-and-drop trip: you bought at the dropship and are bringing it
            // in. A warp from anywhere else is not that trip, so nothing appears (Travis, 2026-09-12).
            // The warp item fires BEFORE the move, so the arriving player still stands at the origin.
            if (!OnStoreTerrain(arriving))
            {
                _lastAutoDropOutcome = "stopped: not warping from the dropship/store";
                return;
            }
            // Warping to a squad leader is an offensive push: the SL kit only, never the base's sentry and tranqs, and
            // wherever the SL is - no flag needed. The stim only while the SL is hurt (AUTODROP_STIM_HP or less).
            // Anywhere else is defense, near a flag the team holds: the defensive set every time, each item at its max minus
            // what the arriving player's build gives (Travis, 2026-10-17). An arriving engineer keeps the sentry, a medic the tranqs.
            bool offense = host.SquadLeader;
            short x = host.State.positionX, y = host.State.positionY;
            if (!offense && !NearOwnedFlag(arriving, x, y))
            {
                _lastAutoDropOutcome = "stopped: destination not near a flag the team holds";
                return;
            }
            // The SL kit is limited to one per squad leader per minute; the stim is not (see TakeStimForSL).
            int kitAt;
            bool kitDue = offense && !(_slKitAt.TryGetValue(host.Name, out kitAt) && unchecked(Environment.TickCount - kitAt) < AUTODROP_SL_KIT_EVERY_MS);
            string arrivingClass = CTFClass.ResolveName(arriving);
            var wanted = new List<Tuple<string, int>>();
            if (offense)
            {
                if (kitDue)
                    wanted.AddRange(ComputeBuildDifferential(arriving, true).Where(t => t.Item1 != "stim pack"));
            }
            else
            {
                // Every time, each item up to its max minus what the arriving player's BUILD gives (Travis, 2026-10-17: a
                // build with 180 Ammo MG drops 70 - what buying the max would have left over). Not minus what they carry,
                // and no area ceiling (PlaceAutoDrop capByArea false) - those left only the sentry and tranqs. No build =
                // the full set.
                Dictionary<int, int> inBuild = LoadoutItemCounts(arriving);
                foreach (var d in autoDropDefense)
                {
                    if ((d.Item1 == "sentry" && arrivingClass == "Combat Engineer") || (d.Item1 == "tranq" && arrivingClass == "Field Medic"))
                        continue;
                    ItemInfo info = AssetManager.Manager.getItemByName(d.Item1);
                    int fromBuild;
                    int need = d.Item2 - (info != null && inBuild.TryGetValue(info.id, out fromBuild) ? fromBuild : 0);
                    if (need > 0)
                        wanted.Add(Tuple.Create(d.Item1, need));
                }
            }

            _adEvents++;
            playersWithAutoDrops.Add(arriving._alias);   // once per life even if nothing spawned - no retry spam
            bool kitSet = kitDue && wanted.Count > 0;
            if (kitSet)
                _slKitAt[host.Name] = Environment.TickCount;
            string build = DropBuildFor(arriving) ?? "none";
            Action<short, short> drop = (lx, ly) =>
            {
                // A stim for a hurt SL goes on top of the pile, out of the arriving player's own inventory.
                var list = wanted;
                bool stimTaken = offense && TakeStimForSL(arriving, host, lx, ly);
                if (stimTaken)
                    list = new[] { Tuple.Create("stim pack", 1) }.Concat(wanted).ToList();
                int refusedBefore = _adRefusedBudget;
                List<Tuple<string, int>> placed = PlaceAutoDrop(list, lx, ly, arriving, offense ? AUTODROP_SL_AREA_PLAYERS : AUTODROP_AREA_FULL_PLAYERS, offense);
                // Say so when the arena-wide stack budget held items back - otherwise a drop by an empty spot just never comes.
                if (_adRefusedBudget > refusedBefore)
                    arriving.sendMessage(-1, String.Format("Auto-drop: {0} item(s) held back - this arena already has {1} item stacks on the ground (limit {2}).",
                        _adRefusedBudget - refusedBefore, arena._items.Count, _autoDropBudget));
                if (stimTaken && !placed.Any(t => t.Item1 == "stim pack"))
                    arriving.inventoryModify(AssetManager.Manager.getItemByName("stim pack"), 1);   // not placed: give it back
                if (offense && placed.Count == 0)
                    playersWithAutoDrops.Remove(arriving._alias);   // nothing came of this summon: the next one may drop
                _lastAutoDropOutcome = String.Format("build {0}, {1} drop, wanted [{2}] -> {3}", build,
                    !offense ? "defense" : kitDue ? "offense (to SL)" : "offense (to SL, kit on cooldown)",
                    String.Join(", ", list.Select(t => t.Item1 + " " + t.Item2).ToArray()), _lastAutoDropOutcome);
                if (placed.Count > 0)
                    arriving.sendMessage(0, String.Format("Auto-drop: {0} left for the team where you landed by {1}. ?ad turns this off.",
                        String.Join(", ", placed.Select(t => t.Item2 + " " + t.Item1).ToArray()), host.Name));
            };
            if (!deferred)
            {
                drop(x, y);
                return;
            }
            // The server moves the player AFTER this hook, to a random spot within the warp item's accuracy radius of
            // the host. So drop a moment later, where they actually landed. No landing (antiwarp, a refused summon,
            // died on the way) = no drop, and the once-per-life slot is given back.
            // The server parks the player on the host's spot as it sends the warp, but the client keeps reporting the
            // old spot until that reliable packet arrives (a second or more on CTF's lossy streams), and those reports
            // overwrite it - one look at 600 ms saw the dropship and dropped nothing. So look every AUTODROP_LAND_POLL_MS:
            // landed = near the host and off the placeholder spot, or still on it after AUTODROP_LAND_SETTLE_MS.
            _lastAutoDropOutcome = "waiting for the landing";
            int warpedAt = Environment.TickCount;
            arena.addDelayedAction(AUTODROP_LAND_POLL_MS, s =>
            {
                int waited = unchecked(Environment.TickCount - warpedAt);
                short lx = arriving._state.positionX, ly = arriving._state.positionY;
                bool gone = arriving._arena != arena || arriving.IsSpectator || arriving.IsDead;
                bool near = Math.Abs(lx - x) <= AUTODROP_LAND_RANGE && Math.Abs(ly - y) <= AUTODROP_LAND_RANGE;
                if (!gone && near && (lx != x || ly != y || waited >= AUTODROP_LAND_SETTLE_MS))
                {
                    drop(lx, ly);
                    return false;   // once
                }
                if (!gone && waited < AUTODROP_LAND_TIMEOUT_MS)
                    return true;    // not landed yet: look again
                playersWithAutoDrops.Remove(arriving._alias);
                if (kitSet)
                    _slKitAt.Remove(host.Name);
                _lastAutoDropOutcome = "stopped: the player did not land near the host";
                return false;
            }, null);
        }

        /// <summary>Legacy entry (*testdrop): same rails as a real auto-drop. Returns how many items were placed.</summary>
        private int SpawnStacksAt(List<Tuple<string, int>> stacks, short x, short y, Player owner)
        {
            return PlaceAutoDrop(stacks, x, y, owner).Count;
        }

        /// <summary>
        /// Puts an auto-drop on the ground at (x,y) under the stack rules (see AUTODROP_AREA_RANGE). The always-drops
        /// (sentry, tranq) always go down; every other item is topped up to its area ceiling. Each item goes onto a
        /// pile within pickup reach when there is one, however large; a new stack is made only while the arena is
        /// under budget. Returns what was actually placed.
        /// </summary>
        /// <summary>
        /// Stims for a hurt squad leader (Travis, 2026-10-16): the SL's area should hold 1 stim at AUTODROP_STIM_HP hp,
        /// plus 1 for every further 10 hp missing (10 hp = 4 stims). Each arriving player gives at most one, and only
        /// from their own inventory - a stim is never spawned. True when one was taken (the caller drops or returns it).
        /// </summary>
        private bool TakeStimForSL(Player arriving, AutoDropHost sl, short x, short y)
        {
            ItemInfo stim = AssetManager.Manager.getItemByName("stim pack");
            int hp = sl.State.health;
            if (stim == null || sl.Dead() || hp > AUTODROP_STIM_HP)
                return false;
            int need = 1 + (AUTODROP_STIM_HP - hp) / 10;
            if (arena.getItemCountInRange(stim, x, y, AUTODROP_AREA_RANGE) >= need || arriving.getInventoryAmount(stim.id) < 1)
                return false;
            return arriving.inventoryModify(stim, -1);
        }

        private static int AutoDropAreaCap(string name, int players)
        {
            var d = autoDropDefense.FirstOrDefault(t => t.Item1 == name);
            int max = d != null ? d.Item2 : squadLeaderItems.ContainsKey(name) ? squadLeaderItems[name] : 1;
            return players * Math.Max(1, max);
        }

        /// <param name="capByArea">False for the defensive set, which goes down in full every time (still onto nearby piles,
        /// still within the arena stack budget); the SL kit and the legacy *testdrop keep the area ceiling.</param>
        private List<Tuple<string, int>> PlaceAutoDrop(List<Tuple<string, int>> stacks, short x, short y, Player owner, int areaPlayers = AUTODROP_AREA_FULL_PLAYERS, bool capByArea = true)
        {
            var placed = new List<Tuple<string, int>>();
            var outcome = new List<string>();
            int freq = (owner != null && owner._team != null) ? (int)owner._team._id : -1;
            // Flag zones (10-26): nothing may lie within PrizeDistance of a flag on the ground, so a drop that would land there goes down on the
            // nearest open floor just outside it (the team keeps it) instead of being removed a moment later
            if (flagSafeDrops && FlagPrizeRange > 0 && FlagDistance(x, y) < FlagSafeDistance)
            {
                short cx, cy;
                if (FindClearFloor(x, y, (fx, fy) => FlagDistance(fx, fy) >= FlagSafeDistance + 4, out cx, out cy))
                {
                    try { Console.WriteLine(String.Format("[flagzone] autodrop moved from {0},{1} to {2},{3}", x / 16, y / 16, cx / 16, cy / 16)); } catch (Exception) { }
                    x = cx;
                    y = cy;
                }
            }
            // The list is top of the pile first and the client draws the newest stack on top, so lay it bottom-up.
            foreach (var s in Enumerable.Reverse(stacks))
            {
                if (s.Item2 <= 0)
                    continue;
                ItemInfo item = AssetManager.Manager.getItemByName(s.Item1);
                if (item == null)
                    continue;

                // The always-drops (sentry, tranq) are never held back. Every other item is topped up, item by item,
                // to its area ceiling (AutoDropAreaCap) - it drops every time until the area is full of THAT item, so
                // nothing is ever short while another item is plentiful (Travis, 2026-10-16).
                int qty = s.Item2;
                bool always = !capByArea
                    || s.Item1 == "stim pack"   // its count is decided by TakeStimForSL (the SL's missing hp)
                    || autoDropAlways.Any(a => a.Item1.Equals(s.Item1, StringComparison.OrdinalIgnoreCase));
                if (!always)
                {
                    int present = arena.getItemCountInRange(item, x, y, AUTODROP_AREA_RANGE);
                    int room = AutoDropAreaCap(s.Item1, areaPlayers) - present;
                    if (room <= 0)
                    {
                        _adSkippedStocked++;
                        outcome.Add(String.Format("{0} full ({1} here)", s.Item1, present));
                        continue;
                    }
                    qty = Math.Min(qty, room);
                }

                Arena.ItemDrop pile = NearestPile(item, x, y, AUTODROP_STACK_RANGE, freq);
                if (pile != null && flagSafeDrops && FlagPrizeRange > 0 && FlagDistance(pile.positionX, pile.positionY) < FlagSafeDistance)
                    pile = null;   // a pile inside a flag zone is going away: start a new one here
                if (pile != null)
                {
                    // Re-lay the pile with the combined amount, so it takes its place in this drop's order (a pile
                    // updated in place stays under everything spawned after it). Same stack count. If the new pile
                    // cannot be made, the old one is updated in place instead - nothing is lost.
                    if (arena.itemSpawn(item, (ushort)Math.Min(ushort.MaxValue, pile.quantity + qty), pile.positionX, pile.positionY, 0, pile.freq, owner) != null)
                    {
                        Helpers.Object_ItemDropUpdate(arena.Players, pile.id, 0);
                        arena._items.Remove(pile.id);
                    }
                    else
                    {
                        pile.quantity = (short)(pile.quantity + qty);
                        Helpers.Object_ItemDropUpdate(arena.Players, pile.id, (ushort)pile.quantity);
                    }
                    _adMerged++;
                    outcome.Add(String.Format("{0} +{1} onto pile", s.Item1, qty));
                }
                else if (arena._items.Count >= _autoDropBudget)
                {
                    _adRefusedBudget++;
                    outcome.Add(String.Format("{0} refused (arena {1} >= budget {2})", s.Item1, arena._items.Count, _autoDropBudget));
                    continue;
                }
                else
                {
                    if (arena.itemSpawn(item, (ushort)qty, x, y, 0, freq, owner) == null)
                    {
                        outcome.Add(String.Format("{0} spawn failed", s.Item1));
                        continue;
                    }
                    _adNewStacks++;
                    outcome.Add(String.Format("{0} +{1} new stack", s.Item1, qty));
                }
                placed.Add(Tuple.Create(s.Item1, qty));
            }
            outcome.Reverse();   // report top of the pile first, as the list was given
            placed.Reverse();
            _lastAutoDropOutcome = outcome.Count == 0 ? "nothing wanted" : String.Join(", ", outcome.ToArray());
            return placed;
        }

        /// <summary>The closest pile of this item within range that the team may use (its own or unowned).</summary>
        private Arena.ItemDrop NearestPile(ItemInfo item, short x, short y, int range, int freq)
        {
            Arena.ItemDrop best = null;
            long bestDist = long.MaxValue;
            foreach (Arena.ItemDrop d in arena._items.Values)
            {
                if (d.item != item || (d.freq != -1 && d.freq != freq))
                    continue;
                int dx = Math.Abs(d.positionX - x), dy = Math.Abs(d.positionY - y);
                if (dx > range || dy > range)
                    continue;
                long dist = (long)dx * dx + (long)dy * dy;
                if (dist < bestDist)
                {
                    bestDist = dist;
                    best = d;
                }
            }
            return best;
        }

        private static void LoadAutoDropState()
        {
            if (_autoDropStateLoaded)
                return;
            _autoDropStateLoaded = true;
            try
            {
                if (!System.IO.File.Exists(AUTODROP_STATE_PATH))
                    return;
                foreach (string raw in System.IO.File.ReadAllLines(AUTODROP_STATE_PATH))
                {
                    string[] kv = raw.Split(new[] { '=' }, 2);
                    if (kv.Length != 2)
                        continue;
                    string key = kv[0].Trim().ToLower(), val = kv[1].Trim().ToLower();
                    int n;
                    if (key == "enabled")
                        _autoDropOff = (val == "off" || val == "false" || val == "0");
                    else if (key == "budget" && int.TryParse(val, out n) && n >= 50)
                        _autoDropBudget = n;
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine("AutoDropState.txt not read: " + ex.Message);
            }
        }

        private static void SaveAutoDropState()
        {
            try
            {
                System.IO.File.WriteAllLines(AUTODROP_STATE_PATH, new[]
                {
                    "# Written by *autodrop. enabled=on|off (zone-wide), budget = arena stacks before autodrop stops making new ones.",
                    "enabled=" + (_autoDropOff ? "off" : "on"),
                    "budget=" + _autoDropBudget,
                });
            }
            catch (Exception ex)
            {
                Console.WriteLine("AutoDropState.txt not written: " + ex.Message);
            }
        }

        /// <summary>
        /// Who may switch autodrop or trim items: a zone mod anywhere, or anyone granted mod (*grant, *auth) in a
        /// public arena. A private arena's owner is a mod there too (a temporary grant), but must not be able to
        /// switch autodrop off for the whole zone.
        /// </summary>
        private bool IsAutoDropStaff(Player p)
        {
            if (p.PermissionLevel >= Data.PlayerPermission.ArenaMod)
                return true;
            return p.PermissionLevelLocal >= Data.PlayerPermission.ArenaMod && !arena._name.StartsWith("#");
        }

        /// <summary>
        /// *autodrop [on|off|budget N] - status for any mod; changing it needs IsAutoDropStaff.
        /// </summary>
        private void AutoDropCommand(Player player, string payload)
        {
            LoadAutoDropState();
            string[] args = (payload ?? "").Trim().ToLower().Split(new[] { ' ' }, StringSplitOptions.RemoveEmptyEntries);
            if (args.Length > 0)
            {
                if (!IsAutoDropStaff(player))
                {
                    player.sendMessage(-1, "Only zone staff can change autodrop.");
                    return;
                }
                int n;
                if (args[0] == "off" || args[0] == "on")
                    _autoDropOff = args[0] == "off";
                else if (args[0] == "budget" && args.Length > 1 && int.TryParse(args[1], out n) && n >= 50 && n <= 5000)
                    _autoDropBudget = n;
                else
                {
                    player.sendMessage(-1, "Usage: *autodrop [on|off|budget <50-5000>]");
                    return;
                }
                SaveAutoDropState();
                Console.WriteLine(String.Format("[autodrop] {0} set {1}", player._alias, payload));
            }
            player.sendMessage(0, String.Format("Autodrop: {0} (zone-wide) | budget {1} stacks | this arena {2} stacks now, peak {3}",
                _autoDropOff ? "OFF" : "ON", _autoDropBudget, arena._items.Count, Math.Max(_adPeakStacks, arena._items.Count)));
            player.sendMessage(0, String.Format("This arena: {0} drops -> {1} new stacks, {2} added to piles, {3} skipped (area stocked), {4} refused (over budget)",
                _adEvents, _adNewStacks, _adMerged, _adSkippedStocked, _adRefusedBudget));
        }

        // Mined only (Tso / Tox / Pandora / Unilennium - support classes heal and build turrets with them) plus Steron
        // Injection, which pollItemExpiration keeps from expiring alongside the autoguns.
        private static readonly HashSet<int> TRIM_PROTECTED_IDS = new HashSet<int> { 2005, 2007, 2009, 2010, 2 };

        /// <summary>Items *trimitems never removes: the minerals, Steron, and anything that is an autogun.</summary>
        private static bool IsTrimProtected(ItemInfo item)
        {
            return item != null && (TRIM_PROTECTED_IDS.Contains(item.id)
                || (item.name ?? "").IndexOf("autogun", StringComparison.OrdinalIgnoreCase) >= 0);
        }

        /// <summary>
        /// *trimitems - emergency soft reset of ground stacks in this arena.
        ///   *trimitems                       stacks per item type
        ///   *trimitems all [pct]             remove pct% (default 80) of EVERY item type's stacks, farthest from
        ///                                    players first; stacks within pickup reach of a live player are kept
        ///   *trimitems <item name|id> [pct]  remove pct% (default 100) of that item's stacks
        ///   add "preview" to see the counts without removing anything. Removing is staff-only.
        /// Never trimmed, in any mode: the minerals and the autoguns (see IsTrimProtected).
        /// </summary>
        private void TrimItemsCommand(Player player, string payload)
        {
            string[] args = (payload ?? "").Trim().Split(new[] { ' ' }, StringSplitOptions.RemoveEmptyEntries);
            bool preview = args.Any(a => a.Equals("preview", StringComparison.OrdinalIgnoreCase));
            var words = args.Where(a => !a.Equals("preview", StringComparison.OrdinalIgnoreCase)).ToList();
            var byType = arena._items.Values.Where(d => d != null && d.item != null).GroupBy(d => d.item).ToList();

            if (words.Count == 0)
            {
                player.sendMessage(0, String.Format("{0} stacks: {1}", arena._items.Count, String.Join(", ",
                    byType.OrderByDescending(g => g.Count()).Take(12)
                        .Select(g => g.Key.name + " " + g.Count() + (IsTrimProtected(g.Key) ? " (kept)" : "")).ToArray())));
                player.sendMessage(0, "Usage: *trimitems all [pct=80] | *trimitems <item name|id> [pct=100]  (+ preview). Minerals and autoguns are never trimmed.");
                return;
            }

            // A trailing number is the percent: "*trimitems ammo mg 50".
            int pct = -1, parsed;
            bool hasPct = false;
            if (words.Count > 1 && int.TryParse(words[words.Count - 1], out parsed))
            {
                pct = parsed;
                hasPct = true;
            }
            string what = String.Join(" ", (hasPct ? words.Take(words.Count - 1) : words).ToArray());
            bool all = what.Equals("all", StringComparison.OrdinalIgnoreCase);
            if (pct < 0)
                pct = all ? 80 : 100;
            if (pct < 1 || pct > 100)
            {
                player.sendMessage(-1, "Percent must be 1-100.");
                return;
            }

            List<IGrouping<ItemInfo, Arena.ItemDrop>> targets;
            if (all)
                targets = byType.Where(g => !IsTrimProtected(g.Key)).ToList();
            else
            {
                int id;
                ItemInfo item = int.TryParse(what, out id) ? AssetManager.Manager.getItemByID(id) : AssetManager.Manager.getItemByName(what);
                if (item == null)
                {
                    player.sendMessage(-1, "No item called '" + what + "'.");
                    return;
                }
                if (IsTrimProtected(item))
                {
                    player.sendMessage(-1, item.name + " is protected: minerals and autoguns are never trimmed.");
                    return;
                }
                targets = byType.Where(g => g.Key == item).ToList();
            }

            if (!preview && !IsAutoDropStaff(player))
            {
                player.sendMessage(-1, "Only zone staff can remove items. Add 'preview' to see the counts.");
                return;
            }

            // Where live players are, so a soft reset never pulls a pile out from under someone.
            var standing = arena.PlayersIngame.Where(p => p != null && !p.IsDead)
                .Select(p => Tuple.Create((int)p._state.positionX, (int)p._state.positionY)).ToList();
            Func<Arena.ItemDrop, long> nearestPlayer = d => standing.Count == 0 ? long.MaxValue : standing.Min(s =>
                (long)(s.Item1 - d.positionX) * (s.Item1 - d.positionX) + (long)(s.Item2 - d.positionY) * (s.Item2 - d.positionY));
            long keep2 = (long)AUTODROP_STACK_RANGE * AUTODROP_STACK_RANGE;

            var remove = new List<Arena.ItemDrop>();
            var report = new List<string>();
            foreach (var g in targets.OrderByDescending(g => g.Count()))
            {
                var pool = g.Select(d => Tuple.Create(d, nearestPlayer(d)))
                    .Where(t => !all || t.Item2 > keep2)
                    .OrderByDescending(t => t.Item2).Select(t => t.Item1).ToList();
                int n = (int)Math.Ceiling(g.Count() * pct / 100.0);
                n = Math.Min(n, pool.Count);
                if (n <= 0)
                    continue;
                remove.AddRange(pool.Take(n));
                report.Add(String.Format("{0} {1}/{2}", g.Key.name, n, g.Count()));
            }

            if (!preview)
            {
                foreach (Arena.ItemDrop d in remove)
                {
                    Helpers.Object_ItemDropUpdate(arena.Players, d.id, 0);
                    arena._items.Remove(d.id);
                }
                Console.WriteLine(String.Format("[trimitems] {0} removed {1} stacks in {2}: {3}", player._alias, remove.Count, arena._name, payload));
            }
            int kept = byType.Where(g => IsTrimProtected(g.Key)).Sum(g => g.Count());
            player.sendMessage(0, String.Format("{0}{1} of {2} stacks ({3}%): {4} | {5} left, {6} minerals/autoguns never touched",
                preview ? "PREVIEW - would remove " : "Removed ", remove.Count, arena._items.Count + (preview ? 0 : remove.Count), pct,
                report.Count == 0 ? "nothing matched" : String.Join(", ", report.Take(8).ToArray()) + (report.Count > 8 ? ", ..." : ""),
                arena._items.Count - (preview ? remove.Count : 0), kept));
        }

        #endregion

        #region ?autopickup (restored from the 2025-08-27 build)

        /// <summary>1Hz: top players up from piles they are standing on, to their build's quantities.</summary>
        private void PollAutoPickup()
        {
            foreach (Player p in arena.PlayersIngame.ToList())
            {
                if (p == null || p.IsDead || p.IsSpectator)
                    continue;
                Dictionary<string, int> wanted;
                bool listed = autoPickupItems.TryGetValue(p._alias, out wanted);
                if (listed && AutoPickupClassChanged(p))
                    continue;
                if (!listed && RestoreSavedAutoPickup(p))
                    continue;   // a remembered ?ap list for this class (CTFAutoPickupPrefs.cs): from the next poll
                // Engineers always top up to one Sentry from a pile they stand on, whatever the build or ?ap (Travis 10-24: zero
                // weight, the most important replenishable item); their own ?ap sentry number wins when it is higher. A Sentry
                // they dropped themselves is left alone until their next buy, like every drop (handing one to a teammate).
                Dictionary<string, int> droppedByThem;
                if (GetPrimarySkillName(p) == "Combat Engineer"
                    && !(autoPickupDropped.TryGetValue(p._alias, out droppedByThem) && droppedByThem.ContainsKey("sentry")))
                {
                    if (!listed)
                        wanted = ENGINEER_PICKUP;
                    else if (!wanted.ContainsKey("sentry"))
                        wanted = new Dictionary<string, int>(wanted, StringComparer.OrdinalIgnoreCase) { { "sentry", 1 } };
                }
                else if (!listed)
                    continue;
                ProcessPlayerAutoPickup(p, wanted);
            }
        }

        /// <summary>Round 5: the engine's manual-pickup rule (skill/class logic of the item), enforced for autopickup even though the zone cfg allows unqualified manual pickup.</summary>
        private static bool AutoPickupQualifies(Player p, ItemInfo info)
        {
            return info != null && Logic_Assets.SkillCheck(p, info.skillLogic);
        }

        private static readonly Dictionary<string, int> ENGINEER_PICKUP = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase) { { "sentry", 1 } };

        private void SetAutoPickupList(Player player, Dictionary<string, int> wanted)
        {
            autoPickupItems[player._alias] = wanted;
            autoPickupClass[player._alias] = GetPrimarySkillName(player);
        }

        /// <summary>
        /// A class change clears the autopickup list (Travis, 2026-10-17: an engineer's ?ap sentry is no use to a heavy). A
        /// typed ?ap list is dropped (autopickup off); one following the loadout is emptied until the next build refills it
        /// (RefreshAutoPickupForLoadout). True when it cleared.
        /// </summary>
        private bool AutoPickupClassChanged(Player p)
        {
            string was, now = GetPrimarySkillName(p);
            if (now == "Unknown" || !autoPickupClass.TryGetValue(p._alias, out was) || was.Equals(now, StringComparison.OrdinalIgnoreCase))
                return false;
            autoPickupClass.Remove(p._alias);
            bool hadOwn = autoPickupCustom.Contains(p._alias);
            autoPickupCustom.Remove(p._alias);
            autoPickupCarry.Remove(p._alias);
            if (RestoreSavedAutoPickup(p))
                return true;   // their remembered list for the new class (CTFAutoPickupPrefs.cs)
            if (hadOwn)
            {
                autoPickupItems.Remove(p._alias);
                p.sendMessage(0, "AutoPickup: your ?ap list is for your old class (it comes back when you go back). ?ap <items> sets one for this class.");
            }
            else
            {
                autoPickupItems[p._alias] = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
                p.sendMessage(0, "AutoPickup: you changed class, so it will follow your next build.");
            }
            return true;
        }

        private void ProcessPlayerAutoPickup(Player player, Dictionary<string, int> itemsToPickup)
        {
            short px = player._state.positionX, py = player._state.positionY;
            var nearby = arena._items.Values
                .Where(d => d != null && d.item != null
                    && Math.Abs(d.positionX - px) <= AUTOPICKUP_RANGE && Math.Abs(d.positionY - py) <= AUTOPICKUP_RANGE)
                .ToList();
            foreach (var drop in nearby)
            {
                int target;
                if (!itemsToPickup.TryGetValue(drop.item.name, out target))
                    continue;
                // Round 5: never take a pile the picker's class cannot use (a team's ?ap sentry swept the other team's drops); it stays untouched.
                if (!AutoPickupQualifies(player, drop.item))
                    continue;
                int have = Skins.HeldWithSkins(player, drop.item.id);   // a skin counts as its stock item (an owner's stock count is always 0)
                if (have >= target)
                    continue;
                int take = Math.Min(target - have, (int)drop.quantity);
                if (take <= 0)
                    continue;
                player.inventoryModify(drop.item, take);
                if (take >= drop.quantity)
                {
                    Helpers.Object_ItemDropUpdate(arena.Players, drop.id, 0);
                    arena._items.Remove(drop.id);
                }
                else
                {
                    drop.quantity = (short)(drop.quantity - take);
                    Helpers.Object_ItemDropUpdate(arena.Players, drop.id, (ushort)drop.quantity);
                }
                player.sendMessage(0, String.Format("AutoPickup: {0}x {1}", take, drop.item.name));
            }
        }

        private static readonly HashSet<string> autoPickupable = new HashSet<string>(StringComparer.OrdinalIgnoreCase)
        {
            "heavy he", "light he", "ammo pistol", "ammo rifle", "ammo shotgun", "ammo mg",
            "rocket", "ap mine", "plasma mine", "tranq", "sentry",
            "stim pack", "haywire grenade", "grapeshot mine",
            "Tsolvy Crystals", "Titanium Oxide"
        };

        /// <summary>"rocket:20, ammo mg:#120, sentry" -> list. Accepts @short names from the ?short table and a # before the number.
        /// An item with no quantity counts as 1 (Travis, 2026-10-17: ?ap sentry == ?ap sentry:1).</summary>
        private List<Tuple<string, int>> ParseCustomItemList(string itemList)
        {
            var items = new List<Tuple<string, int>>();
            if (String.IsNullOrEmpty(itemList))
                return items;
            foreach (string part in itemList.Split(','))
            {
                string t = part.Trim();
                int colon = t.LastIndexOf(':');
                if (t.Length == 0 || colon == 0)
                    continue;
                string name = (colon < 0 ? t : t.Substring(0, colon)).Trim().TrimStart('@');
                var shortHit = commandHandler.shortCommands.FirstOrDefault(kvp => kvp.Value.Equals("@" + name, StringComparison.OrdinalIgnoreCase));
                if (!shortHit.Equals(default(KeyValuePair<string, string>)))
                    name = shortHit.Key;
                int qty = 1;
                if (colon < 0 || (int.TryParse(t.Substring(colon + 1).Trim().TrimStart('#'), out qty) && qty > 0))
                    items.Add(Tuple.Create(name, qty));
            }
            return items;
        }

        /// <summary>
        /// Something a player would want topped up from a pile: the consumables whitelist above, or
        /// anything the zone's item table types as AMMO. Guns, armour, utilities and the like are
        /// never picked up even if they are in the loadout.
        /// </summary>
        /// <summary>A [Shortened Macros] item that holds one real item (pM = Plasma Mine, aM = AP Mine, grM / gM = Grapeshot Mine) stands for that item:
        /// ?ap pm:5 tops up Plasma Mines. Anything else comes back as it was.</summary>
        private static string ResolveShortMacroItem(string name)
        {
            var multi = AssetManager.Manager.getItemByName(name) as ItemInfo.MultiItem;
            if (multi == null)
                return name;
            var ids = multi.slots.Where(sl => sl.value > 0).Select(sl => sl.value).Distinct().ToList();
            ItemInfo inner = ids.Count == 1 ? AssetManager.Manager.getItemByID(ids[0]) : null;
            return inner != null ? inner.name : name;
        }

        private bool IsAutoPickupable(string itemName)
        {
            if (String.IsNullOrEmpty(itemName))
                return false;
            if (autoPickupable.Contains(itemName))
                return true;
            ItemInfo info = AssetManager.Manager.getItemByName(itemName);
            return info != null && info.itemType == ItemInfo.ItemType.Ammo;
        }

        /// <summary>
        /// The player's CURRENT loadout as item -> quantity, and where it came from. Whichever they
        /// chose most recently wins, because buying a premade clears persistentBuilds and setting a
        /// build clears the premade: the premade kit (F11 "Classes - Premades"), else the ?b / ?bw /
        /// ?bwd build - a preset name from the build table or the custom item list they typed. Null
        /// when the player has bought nothing this session.
        /// </summary>
        /// <summary>
        /// How many of each item (by id) the player's loadout gives - macros and bundles opened the way the server opens
        /// them (applyMultiItem: each slot times the quantity, and a slot their class can't use gives nothing, like Basic's
        /// sentry for a non-engineer). Empty without a loadout. The defensive autodrop subtracts this from each max.
        /// </summary>
        private Dictionary<int, int> LoadoutItemCounts(Player player)
        {
            var counts = new Dictionary<int, int>();
            string source;
            var loadout = CurrentLoadout(player, out source);
            if (loadout == null)
                return counts;
            foreach (var entry in loadout)
            {
                ItemInfo item = AssetManager.Manager.getItemByName(entry.Item1);
                if (item == null)
                {   // a ?short form the item file does not name: the purchase maps it to the full name the same way
                    var hit = commandHandler.shortCommands.FirstOrDefault(kvp => kvp.Value.Equals(entry.Item1, StringComparison.OrdinalIgnoreCase));
                    if (hit.Key != null)
                        item = AssetManager.Manager.getItemByName(hit.Key);
                }
                if (item == null)
                    continue;
                var multi = item as ItemInfo.MultiItem;
                var gives = multi == null ? new List<ItemInfo> { item }
                    : multi.slots.Where(s => s.value != 0).Select(s => AssetManager.Manager.getItemByID(s.value))
                        .Where(sub => sub != null && Logic_Assets.SkillCheck(player, sub.skillLogic)).ToList();
                foreach (ItemInfo sub in gives)
                {
                    int had;
                    counts.TryGetValue(sub.id, out had);
                    counts[sub.id] = had + entry.Item2;
                }
            }
            return counts;
        }

        private List<Tuple<string, int>> CurrentLoadout(Player player, out string source)
        {
            source = null;
            if (player == null)
                return null;

            string setup;
            List<KeyValuePair<ItemInfo, int>> kit;
            if (premadeActiveSetup.TryGetValue(player._alias.ToLower(), out setup)
                && PremadeKits().TryGetValue(setup, out kit))
            {
                source = "from your premade " + setup;
                return kit.Select(e => Tuple.Create(e.Key.name, e.Value)).ToList();
            }

            string buildString;
            if (persistentBuilds.TryGetValue(player._alias, out buildString) && !String.IsNullOrEmpty(buildString))
            {
                if (buildSets.ContainsKey(buildString.ToLower()))
                {
                    source = "from your stored build";
                    return buildSets[buildString.ToLower()].Item1.Select(it => Tuple.Create(it.Item1, (int)it.Item2)).ToList();
                }
                var custom = ParseCustomItemList(buildString);
                if (custom.Count > 0)
                {
                    source = "from your last ?b list";
                    return custom;
                }
            }
            return null;
        }

        /// <summary>
        /// What ?autopickup keeps topped up: the ammo and single-use consumables IN THE PLAYER'S
        /// LOADOUT, at the loadout's quantities, plus the class mineral for a medic / engineer.
        ///
        /// Empty when they have no loadout. It used to fall back to every ammo type at its maximum,
        /// which made a bare ?autopickup hoover 250 Ammo MG onto a class that cannot fire it
        /// (Travis, 2026-09-12: "definitely a bad default"). Nothing bought = nothing to follow.
        /// </summary>
        private Dictionary<string, int> DeriveAutoPickupItemsFromBuild(Player player, out string source, out string skipped)
        {
            var derived = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
            skipped = null;
            List<Tuple<string, int>> loadout = CurrentLoadout(player, out source);
            if (loadout == null)
                return derived;

            // Safeguards (Travis, 2026-09-13): a legacy macro buys pistol ammo with no pistol, tranq
            // with no Needler and five plasma mines it never carries, purely so the paired ?drop
            // macro can leave them for the team. Ammo is only followed when a weapon the player can
            // fire consumes it, nothing is followed that their class fails the skill check for,
            // and whatever they deliberately dropped since this buy is off the list.
            HashSet<int> usableAmmo = UsableAmmoIds(player, loadout);
            Dictionary<string, int> dropped;
            autoPickupDropped.TryGetValue(player._alias, out dropped);

            var why = new List<string>();
            foreach (var raw in loadout)
            {
                var it = Tuple.Create(ResolveShortMacroItem(raw.Item1), raw.Item2);   // pM:5 in a build = 5 Plasma Mines
                if (it.Item2 <= 0 || !IsAutoPickupable(it.Item1))
                    continue;
                ItemInfo info = AssetManager.Manager.getItemByName(it.Item1);
                string reason = null;
                if (info != null && !Logic_Assets.SkillCheck(player, info.skillLogic))
                    reason = "not for your class";
                else if (info != null && info.itemType == ItemInfo.ItemType.Ammo && !usableAmmo.Contains(info.id))
                    reason = "no weapon uses it";
                int qty = it.Item2;
                int gone;
                if (reason == null && dropped != null && dropped.TryGetValue(it.Item1, out gone))
                {
                    qty -= gone;
                    if (qty <= 0)
                        reason = "you dropped it";
                }
                // Mines (Travis 10-26): nobody carries a full stack all game, it is bought to drop; a build with the item's max follows 1 (fewer than the
                // max = the build's own amount). A typed ?ap plasma mine:5 is the player's own and still wins.
                if (reason == null && info != null && String.Equals(info.category, "Mines", StringComparison.OrdinalIgnoreCase)
                    && info.maxAllowed != 0 && it.Item2 >= Math.Abs(info.maxAllowed))
                    qty = Math.Min(qty, 1);
                if (reason != null)
                {
                    why.Add(it.Item1 + " (" + reason + ")");
                    continue;
                }
                derived[it.Item1] = qty;
            }
            if (why.Count > 0)
                skipped = String.Join(", ", why.ToArray());

            // The class mineral is not in any buy macro, but a medic / engineer with a loadout
            // wants it topped up from the base pile all the same.
            string cls = CTFClass.ResolveName(player);
            if (cls == "Field Medic" && !derived.ContainsKey("Tsolvy Crystals"))
                derived["Tsolvy Crystals"] = 150;
            // Titanium Oxide weighs too much for an engineer to carry the full 150 all game
            // (Travis, 2026-09-12): 50 by default; ?ap titanium oxide:150 if they really want it.
            else if (cls == "Combat Engineer" && !derived.ContainsKey("Titanium Oxide"))
                derived["Titanium Oxide"] = 50;
            return derived;
        }

        /// <summary>
        /// The ammo ids something the player can actually fire consumes: every non-ammo item in the
        /// loadout plus whatever else is in their inventory, minus anything their class fails the
        /// skill check for. Pistol ammo with no pistol, or tranq with no (usable) Needler, is not here.
        /// </summary>
        private HashSet<int> UsableAmmoIds(Player player, List<Tuple<string, int>> loadout)
        {
            var ids = new HashSet<int>();
            var names = new List<string>(loadout.Select(l => l.Item1));
            if (player._inventory != null)
                names.AddRange(player._inventory.Values.Where(i => i != null && i.item != null).Select(i => i.item.name));
            foreach (string name in names)
            {
                ItemInfo info = AssetManager.Manager.getItemByName(name);
                if (info == null || info.itemType == ItemInfo.ItemType.Ammo)
                    continue;
                int ammoId, perShot;
                if (!info.getAmmoType(out ammoId, out perShot) || ammoId <= 0)
                    continue;
                if (!Logic_Assets.SkillCheck(player, info.skillLogic))
                    continue;
                ids.Add(ammoId);
            }
            return ids;
        }

        private Dictionary<string, int> DeriveAutoPickupItemsFromBuild(Player player, out string source)
        {
            string skipped;
            return DeriveAutoPickupItemsFromBuild(player, out source, out skipped);
        }

        private static string ApList(Dictionary<string, int> wanted)
        {
            return String.Join(", ", wanted.Select(kv => kv.Key + ":" + kv.Value).ToArray());
        }

        private Dictionary<string, int> DeriveAutoPickupItemsFromBuild(Player player)
        {
            string ignored;
            return DeriveAutoPickupItemsFromBuild(player, out ignored);
        }

        /// <summary>
        /// A default loadout (preset build / premade) was just bought: switch autopickup on for it,
        /// the way autobuy switches itself on - unless the player has typed ?ap off, or already runs
        /// a hand-typed ?ap list.
        /// </summary>
        private void EnableAutoPickupForDefaultLoadout(Player player)
        {
            if (player == null || autoPickupOff.Contains(player._alias) || autoPickupCustom.Contains(player._alias))
                return;
            if (autoPickupItems.ContainsKey(player._alias))
                return;   // already on - RefreshAutoPickupForLoadout keeps it current
            autoPickupDropped.Remove(player._alias);   // a new kit: the last kit's deliberate drops no longer apply
            if (RestoreSavedAutoPickup(player))
                return;   // a list they set themselves for this class wins over the build's
            string source, skipped;
            var wanted = DeriveAutoPickupItemsFromBuild(player, out source, out skipped);
            if (wanted.Count == 0)
                return;
            SetAutoPickupList(player, wanted);
            player.sendMessage(0, String.Format("AutoPickup ON for this loadout: {0}.{1} Stand on a pile to top up; ?ap turns it off.",
                ApList(wanted), skipped != null ? " Skipped " + skipped + "." : ""));
        }

        /// <summary>
        /// The loadout changed (new build bought, premade picked or dropped). If autopickup is on
        /// and following the loadout, re-derive so it never keeps topping up the OLD kit's ammo.
        /// A custom ?ap list is the player's own and is left alone.
        /// </summary>
        private void RefreshAutoPickupForLoadout(Player player)
        {
            if (player == null || !autoPickupItems.ContainsKey(player._alias) || autoPickupCustom.Contains(player._alias))
                return;
            autoPickupDropped.Remove(player._alias);   // a new kit: the last kit's deliberate drops no longer apply
            string source, skipped;
            var wanted = DeriveAutoPickupItemsFromBuild(player, out source, out skipped);
            // Nothing to follow RIGHT NOW is usually a transient: WipeAndBuy swaps class first
            // (which clears the stored build) and persists the new build a moment later. Keep the
            // list as it is and let the persist call re-derive; never switch the player off here.
            if (wanted.Count == 0)
                return;
            SetAutoPickupList(player, wanted);
            player.sendMessage(0, String.Format("AutoPickup now follows your new loadout: {0}{1}",
                ApList(wanted), skipped != null ? ". Skipped " + skipped : ""));
        }

        private void HandleAutoPickupCommand(Player player, string payload)
        {
            if (player.IsSpectator)
            {
                player.sendMessage(-1, "Spectators cannot use autopickup.");
                return;
            }
            string arg = (payload ?? "").Trim();
            if (arg.Equals("off", StringComparison.OrdinalIgnoreCase) || arg.Equals("disable", StringComparison.OrdinalIgnoreCase)
                || (arg.Length == 0 && autoPickupItems.ContainsKey(player._alias)))
            {
                autoPickupItems.Remove(player._alias);
                autoPickupOff.Add(player._alias);   // and a preset buy will not switch it back on
                autoPickupCarry.Remove(player._alias);
                string offClass = GetPrimarySkillName(player);
                bool forgot = AutoPickupPrefs.Forget(player._alias, offClass);   // remembered lists (CTFAutoPickupPrefs.cs): off forgets this class's
                player.sendMessage(0, "AutoPickup is now DISABLED." + (forgot ? " Your saved " + offClass + " list is forgotten." : ""));
                return;
            }
            Dictionary<string, int> wanted;
            string source, skipped = null;
            if (arg.Length == 0)
            {
                wanted = DeriveAutoPickupItemsFromBuild(player, out source, out skipped);
                if (wanted.Count == 0)
                {   // no build (?buy macros, Travis 10-26): follow what they carry right now, as their own list
                    wanted = CarriedAutoPickupItems(player);
                    if (wanted.Count == 0)
                    {
                        player.sendMessage(-1, "AutoPickup: you carry nothing it can top up and have no build. Buy a premade (F11) or a build (?bw <name>) first, or name items: ?ap rocket:20, ammo mg:120");
                        return;
                    }
                    source = "what you carry now";
                    autoPickupCustom.Add(player._alias);
                    autoPickupCarry.Add(player._alias);
                    autoPickupOff.Remove(player._alias);
                    AutoPickupPrefs.Set(player._alias, GetPrimarySkillName(player), wanted, true);
                    SetAutoPickupList(player, wanted);
                    player.sendMessage(0, String.Format("AutoPickup ENABLED ({0}): {1}. Remembered for your {2}. Stand on a pile to top up. ?ap again turns it off.",
                        source, ApList(wanted), GetPrimarySkillName(player)));
                    return;
                }
                autoPickupCustom.Remove(player._alias);
                autoPickupCarry.Remove(player._alias);
                autoPickupOff.Remove(player._alias);
            }
            else
            {
                wanted = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
                bool cannotUse = false;
                foreach (var parsed in ParseCustomItemList(arg))
                {
                    var it = Tuple.Create(ResolveShortMacroItem(parsed.Item1), parsed.Item2);   // ?ap pm:5 = Plasma Mine
                    if (IsAutoPickupable(it.Item1))
                    {
                        ItemInfo apInfo = AssetManager.Manager.getItemByName(it.Item1);
                        if (apInfo != null && !AutoPickupQualifies(player, apInfo))
                        {   // Round 5: not for this class - refused, whoever's pile it would have been
                            cannotUse = true;
                            continue;
                        }
                        wanted[it.Item1] = it.Item2;
                    }
                }
                source = "custom list";
                if (cannotUse)
                    player.sendMessage(-1, "YOUR CLASS CANNOT USE THAT ITEM");
                if (wanted.Count == 0)
                {
                    if (cannotUse)
                        return;
                    player.sendMessage(-1, "Nothing pickupable in that list. Format: ?autopickup rocket:20, ammo mg:120  - or ?autopickup alone to follow your loadout.");
                    return;
                }
                autoPickupCustom.Add(player._alias);
                autoPickupCarry.Remove(player._alias);
                autoPickupOff.Remove(player._alias);
                AutoPickupPrefs.Set(player._alias, GetPrimarySkillName(player), wanted, false);
                source = "custom list, remembered for your " + GetPrimarySkillName(player);
            }
            SetAutoPickupList(player, wanted);
            player.sendMessage(0, String.Format("AutoPickup ENABLED ({0}): {1}.{2} Stand on a pile to top up. ?ap again turns it off.",
                source, ApList(wanted), skipped != null ? " Skipped " + skipped + "." : ""));
        }

        /// <summary>?ap alone with no build: what the player carries now that autopickup handles and their class can use, at the amounts held.</summary>
        private Dictionary<string, int> CarriedAutoPickupItems(Player player)
        {
            var wanted = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
            if (player == null || player._inventory == null)
                return wanted;
            foreach (var inv in player._inventory.Values.ToList())
                if (inv != null && inv.item != null && inv.quantity > 0 && IsAutoPickupable(inv.item.name) && AutoPickupQualifies(player, inv.item))
                    wanted[inv.item.name] = inv.quantity;
            return wanted;
        }

        /// <summary>The player's remembered ?ap list for the class they are now (CTFAutoPickupPrefs.cs) switched on. True when it did.</summary>
        private bool RestoreSavedAutoPickup(Player p)
        {
            if (p == null || autoPickupOff.Contains(p._alias))
                return false;
            string cls = GetPrimarySkillName(p);
            if (cls == "Unknown")
                return false;
            bool carry;
            Dictionary<string, int> saved = AutoPickupPrefs.Get(p._alias, cls, out carry);
            if (saved == null)
                return false;
            var wanted = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
            foreach (var kv in saved)
            {
                ItemInfo info = AssetManager.Manager.getItemByName(kv.Key);
                if (info != null && IsAutoPickupable(kv.Key) && AutoPickupQualifies(p, info))
                    wanted[kv.Key] = kv.Value;
            }
            if (wanted.Count == 0)
                return false;
            autoPickupCustom.Add(p._alias);
            if (carry) autoPickupCarry.Add(p._alias); else autoPickupCarry.Remove(p._alias);
            SetAutoPickupList(p, wanted);
            p.sendMessage(0, String.Format("AutoPickup: your saved {0} list is on: {1}. ?ap off forgets it.", cls, ApList(wanted)));
            return true;
        }

