        private bool AutoSummonEnabledFor(Player player)
        {
            if (player == null)
                return false;
            bool chosen;
            if (autoSummonOverride.TryGetValue(player._alias, out chosen))
                return chosen;
            return player._skills.Values.Any(s => s.skill.SkillId == 31 || s.skill.SkillId == 29);
        }

