                    player._state.energy = 1000;
                    //arena.sendArenaMessage(string.Format("Reset bounty for {0} to {1}", player._alias, CFG.bounty.start));
                    //Update his client to reflect bty change
                    player.syncState();
                }
                return false;
            }
            // Check for queued class swap. It goes BEFORE autobuy, so autobuy acts for the class the player respawns as
            // (it used to rebuy the old class's loadout first). The swap clears the saved loadout; one bought FOR the new
            // class while dead (a ?bw that queued this swap, see HandleBuildCommand) is put back.
            if (queuedClassSwap.ContainsKey(player))
            {
                string keepBuild = null, keepClass = null;
                bool hadLoadout = persistentBuilds.TryGetValue(player._alias, out keepBuild) && persistentBuildClass.TryGetValue(player._alias, out keepClass);
                string skillName = queuedClassSwap[player];
                commandHandler.HandleSwapCommand(player, skillName, CFG, this, true, true);
                queuedClassSwap.Remove(player);
                player.sendMessage(0, string.Format("Your class has been changed to: {0}", skillName));
                if (hadLoadout && keepClass.Equals(GetPrimarySkillName(player), StringComparison.OrdinalIgnoreCase))
                    persistentBuilds[player._alias] = keepBuild;
            }

            string buildString;
            bool loadoutDropped;
            if (autoBuyEnabled.ContainsKey(player._alias) && autoBuyEnabled[player._alias] && (buildString = AutoBuyLoadout(player, out loadoutDropped)) != null)
            {
                HardEconomy.NoteAutobuy(player);              // TP Pub: a rebuy prints one compact line, not a warning per item
                WipeAndBuy(player, buildString, true);
            }

            // Summon request on spawn. Default ON for offense infantry builds (skills 31/29) - that
            // was the old unconditional behaviour - but ?as / ?autosummon now lets anyone turn it on
            // or off for themselves.
            if (AutoSummonEnabledFor(player))
            {
                // Send "Requesting Summon" message to all players on the same team
                foreach (Player teammate in player._team.ActivePlayers)
                {
                    SC_Chat pkt = new SC_Chat
                    {
                        chatType = Helpers.Chat_Type.Team,
                        bong = 27,
                        from = player._alias,
                        message = "XXXXXXX"
                    };
                    teammate._client.sendReliable(pkt);
                }
            }

            return true;
        }
        // Dictionary to track class play times for each player
        private Dictionary<Player, Dictionary<string, int>> playerClassPlayTimes = new Dictionary<Player, Dictionary<string, int>>();
        
        // Dictionary to track when each player last switched classes
        private Dictionary<Player, int> playerLastClassSwitch = new Dictionary<Player, int>();

        /// <summary>
        /// Sends ordered class play time messages to the player
        /// </summary>
        private void SendOrderedPlayTimes(Player player)
        {
            if (!playerClassPlayTimes.ContainsKey(player))
                return;

            // Get current time to calculate current class time
            int currentTick = Environment.TickCount;
            var playTimes = new Dictionary<string, int>(playerClassPlayTimes[player]);

            // Add time for current class if player has one
            // Bill the session to the class actually being played, not whatever .First() returned.
            Assets.SkillInfo playedSkill2 = CTFClass.Resolve(player);
            string currentSkill = playedSkill2 != null ? playedSkill2.Name : null;
            if (currentSkill != null)
            {
                int sessionTime = Math.Max(0, currentTick - playerLastClassSwitch[player]);
                if (!playTimes.ContainsKey(currentSkill))
                    playTimes[currentSkill] = 0;
                playTimes[currentSkill] += sessionTime;
            }

            // Order play times from highest to lowest
            var orderedTimes = playTimes
                .OrderByDescending(x => x.Value)
                .ToList();

            // Calculate total time
            double totalSeconds = orderedTimes.Sum(x => x.Value) / 1000.0;

            // Send header message
            player.sendMessage(-1, string.Format("&Total Time: {0:F1} seconds | Class Swaps: {1}", totalSeconds,
                playerClassSwaps.ContainsKey(player) ? playerClassSwaps[player] : 0));

            // Send individual class times
            foreach (var entry in orderedTimes)
            {
                double seconds = entry.Value / 1000.0;
                player.sendMessage(0, string.Format("*{0}: {1:F1} seconds", entry.Key, seconds));
            }
        }

        // Dictionary to track class swaps for each player
        private Dictionary<Player, int> playerClassSwaps = new Dictionary<Player, int>();

        /// <summary>
        /// Triggered when a player's purchase is successful
        /// </summary>
        [Scripts.Event("Shop.SkillPurchase")]
        public bool PlayerShopSkillPurchase(Player from, SkillInfo skill)
        {
            // This handler is reachable from the F11 skill shop, which routes through
            // Arena.poll()'s event queue - and that queue has NO exception handling around it
            // (unlike Events.trigger()). Any exception thrown in here propagates straight up and
            // takes down the whole arena tick loop, which is what got reported as class changes
            // crashing the game and disconnecting people. Everything below is wrapped so a bug here
            // gets logged instead of taking the zone down.
            try
            {
                // Premades run FIRST: the conversion does a wipeskill, which clears the legacy
                // equipment-setup skills that SetupEquipmentSkills below keys off - so the kit cannot be
                // overwritten by a stale legacy build, and the vehicle reset further down sees the
                // player's final class.
                premadeHandleSkillPurchase(from, skill);

                // The purchase went through: charge it the way ?swap does (energy mode) and start the
                // cooldown (cooldown mode). The client no longer charges, SkillScreenEnergyNeeded is 0 in the cfg.
                if (ClassGate.IsClassSkill(skill))
                {
                    int gateCost = ClassGate.EnergyCost;
                    if (gateCost > 0)
                        from._state.energy = (short)Math.Max(0, from._state.energy - gateCost);
                    ClassGateCommit(from, skill.Name);
                }

                // This removes the ability to abuse teleport beacon bugs during class change
                Vehicle vehicle = from._occupiedVehicle ?? from._baseVehicle;
                if (vehicle != null)
                {
                    vehicle._state.positionX = from._state.positionX;
                    vehicle._state.positionY = from._state.positionY;
                    vehicle._state.velocityX = 0;
                    vehicle._state.velocityY = 0;
                    vehicle._state.yaw = from._state.yaw;
                    vehicle._state.direction = Helpers.ObjectState.Direction.None;
                    vehicle._state.energy = 1000;
                    vehicle._state.health = 1000;
                    vehicle._tickDead = 0;
                    vehicle.update(false);
                }

                // Warp in place. The third argument is the landing RADIUS, not health: health (1000 after the reset above) made a
                // 1000 px box, so the client dropped an F11 class change up to 500 px away, out of the dropship (fearlesschicken 11-01).
                // 0 = this exact spot, as ?swap / ?bw leave you. Energy and the invulnerability argument are unchanged.
                from.warp(Helpers.ResetFlags.ResetAll, from._state, 0, from._state.energy, (byte)from._state.yaw);

                // Remove persistent builds from this player
                string dummy;
                persistentBuilds.TryRemove(from._alias, out dummy);

                // Update class swap count for player
                if (!playerClassSwaps.ContainsKey(from))
                    playerClassSwaps[from] = 0;
                playerClassSwaps[from]++;

                // Infiltrator announcement
                bool withinGracePeriod = lastAnnouncementTimes.ContainsKey(from) &&
                                                           (DateTime.Now - lastAnnouncementTimes[from]).TotalSeconds < AnnouncementGracePeriod;

                // Announce the player's skill change if it is Infiltrator, not within the grace period,
                // and the player is not on team "np"
                if (skill.Name == "Infiltrator" && !withinGracePeriod && from._team != null && from._team._name.ToLower() != "np" && !arena._name.Contains("Arena 1") && !arena._name.Contains("Public1"))
                {
                    // Make the actual announcement
                    if (from._alias == "YAH" || from._alias == "JACKIE"){
                        arena.sendArenaMessage("#SWITCHING CLASS IN UPPERCASE ------ TEAM " + from._team._name.ToUpper() + " ------ " + from._alias + ".", 14);
                    } else {
                        arena.sendArenaMessage("#CLOAKERS ------ TEAM " + from._team._name + " ------ " + from._alias + ".", 14);
                    }

                    // Update the last announcement time for the player
                    lastAnnouncementTimes[from] = DateTime.Now;
                }

                // Box 0: without it the box was health = 1000 (the reset above) and Arena 1 scattered you up to 500 px (TP batch 9).
                if (currentEventType == EventType.CTFX){
                    WarpPlayerToRange(from, 985, 997, 1117, 1129, -1, 0);
                    return false;
                }
                if (currentEventType == EventType.MiniTP){
                    if (from._team._name.Contains("Titan"))
                        WarpPlayerToRange(from, 654, 654, 518, 518, -1, 0);
                    else if (from._team._name.Contains("Collective"))
                        WarpPlayerToRange(from, 648, 648, 565, 565, -1, 0);
                    return false;
                }

                // Auto-occupy after a skill purchase (the Swap trigger)
                InitiateAutoOccupy(from, "skill purchase");

                return true;
            }
            catch (Exception ex)
            {
                Console.WriteLine(String.Format("Error in PlayerShopSkillPurchase for {0} (skill {1}): {2}",
                    from == null ? "?" : from._alias, skill == null ? "?" : skill.Name, ex));
                return true;
            }
        }
        /// <summary>
        /// Updates the play time tracking for a player's skill
        /// </summary>
        /// <summary>
        /// Observes a player's class each poll and bills play time to whatever they were ACTUALLY
        /// playing, however the change happened.
        ///
        /// UpdateSkillPlayTime only fires on ?swap and the F11 shop. Class also changes via ?bw, mod
        /// prize/skill grants, and the premade conversion's RunEvent - none of which have a script
        /// hook. Watching the resolved class instead of hooking each mutation catches all of them,
        /// including any route added later.
        ///
        /// Bills to the PREVIOUS class, because by the time the poll sees it the change has already
        /// happened - the elapsed session belongs to what they were playing before.
        /// </summary>
        /// <summary>
        /// Zeroes every player's class spread and restarts their clock, keeping every key in place
        /// (?classtime indexes playerClassSwaps directly, so a Clear() here would open a
        /// KeyNotFound window until the next poll re-initialised the player).
        /// </summary>
        /// <summary>
        /// Tick the OvD match clock started at; null outside an OvD match. See ApplyOvdGameTimer -
        /// arena._tickGameStarted predates the whole draft in OvD.
        /// </summary>
        private int? ovdMatchStartTick = null;

        private void ResetClassPlayTimes()
        {
int now = Environment.TickCount;
            foreach (var pl in playerClassPlayTimes.Keys.ToList())
                playerClassPlayTimes[pl] = new Dictionary<string, int>();
            foreach (var pl in playerClassSwaps.Keys.ToList())
                playerClassSwaps[pl] = 0;
            foreach (var pl in playerLastClassSwitch.Keys.ToList())
                playerLastClassSwitch[pl] = now;
        }

        /// <summary>
        /// The class spread with the OPEN session included, in milliseconds. playerClassPlayTimes
        /// only receives time when a class ENDS (ReconcileClassPlayTime bills on change), so at
        /// Game.End the class a player is currently in - usually the one they played longest - has
        /// nothing booked since their last switch. ?classtime already added it; the stats writer
        /// did not, which is how a 3-minute opener could outrank a 12-minute finisher as MainClass.
        /// Pure: does not mutate the trackers.
        /// </summary>
        private Dictionary<string, int> SnapshotClassPlayTimes(Player player)
        {
            var spread = new Dictionary<string, int>();
            Dictionary<string, int> booked;
            if (playerClassPlayTimes.TryGetValue(player, out booked))
                foreach (var kv in booked)
                    spread[kv.Key] = kv.Value;

            int sessionStart;
            if (!playerLastClassSwitch.TryGetValue(player, out sessionStart))
                return spread;

            // Bill the open session to the class the reconciler is currently billing, exactly as it
            // would on the next change; fall back to resolving it if the poll has not seen them yet.
            string current;
            if (!playerLastSkillNames.TryGetValue(player, out current) || current == null)
                current = CTFClass.ResolveName(player);
            if (current == null || current == "Unknown")
                return spread;

            int open = Math.Max(0, Environment.TickCount - sessionStart);
            if (open > 0)
            {
                if (!spread.ContainsKey(current))
                    spread[current] = 0;
                spread[current] += open;
            }
            return spread;
        }

        private void ReconcileClassPlayTime(Player player)
        {
if (player == null || player.IsSpectator || player._team == null || player._team.IsSpec)
                return;

            int now = Environment.TickCount;
            string current = CTFClass.ResolveName(player);

            if (!playerClassPlayTimes.ContainsKey(player))
                playerClassPlayTimes[player] = new Dictionary<string, int>();

            string billedTo;
            if (!playerLastSkillNames.TryGetValue(player, out billedTo) || billedTo == null)
            {   // First sighting - open a session. Nothing accrued yet, so nothing to bill.
                playerLastSkillNames[player] = current;
                playerLastClassSwitch[player] = now;
                return;
            }

            if (billedTo == current)
                return;

            int sessionStart;
            if (!playerLastClassSwitch.TryGetValue(player, out sessionStart))
                sessionStart = now;

            int elapsed = Math.Max(0, now - sessionStart);

            // "Unknown" is not a class - it means we could not resolve one (no skills yet, still
            // loading). Accruing to it would create a junk bucket that competes with real classes
            // when the site picks MostPlayedClass.
            if (elapsed > 0 && billedTo != "Unknown")
            {
                if (!playerClassPlayTimes[player].ContainsKey(billedTo))
                    playerClassPlayTimes[player][billedTo] = 0;
                playerClassPlayTimes[player][billedTo] += elapsed;
            }

            playerLastSkillNames[player] = current;
            playerLastClassSwitch[player] = now;
        }

        private void UpdateSkillPlayTime(Player player, SkillInfo newSkill = null)
        {
            // Don't update play time for spectators (either on spec team or in spec vehicle)
            if (player._team.IsSpec || (player._baseVehicle != null && player._baseVehicle._type.Name.Contains("Spectator")))
                return;

            // Initialize tracking for new players
            if (!playerClassPlayTimes.ContainsKey(player))
            {
                playerClassPlayTimes[player] = new Dictionary<string, int>();
                playerLastClassSwitch[player] = Environment.TickCount;
            }

            // Get current time
            int currentTick = Environment.TickCount;

            // Get the class actually being played. Was .First(), i.e. hash order - so a player who
            // also held Referee, or the extra base skill ?swap adds, could have their time billed to
            // the wrong class.
            Assets.SkillInfo playedSkill = CTFClass.Resolve(player);
            string currentSkill = playedSkill != null ? playedSkill.Name : null;

            if (currentSkill != null)
            {
                // Calculate time played in current session
                int startTime = playerLastClassSwitch[player];
                int sessionPlayTime = Math.Max(0, currentTick - startTime); // Ensure non-negative

                // Add session time to accumulated time for current skill
                if (!playerClassPlayTimes[player].ContainsKey(currentSkill))
                {
                    playerClassPlayTimes[player][currentSkill] = 0;
                }
                playerClassPlayTimes[player][currentSkill] += sessionPlayTime;

                // Send message showing total accumulated play time in seconds
                double totalSeconds = Math.Min(playerClassPlayTimes[player][currentSkill] / 1000.0,
                    (currentTick - arena._tickGameStarted) / 1000.0); // Cap at game duration
                // player.sendMessage(-1, string.Format("You played {0} for {1:F1} seconds", currentSkill, totalSeconds));
                // player.sendMessage(-1, string.Format("You have swapped {0} times", playerClassSwaps[player]));
            }

            // Reset the last switch time for the new skill
            playerLastClassSwitch[player] = currentTick;

            // Initialize play time for new skill if provided and not exists
            if (newSkill != null && !playerClassPlayTimes[player].ContainsKey(newSkill.Name))
            {
                playerClassPlayTimes[player][newSkill.Name] = 0;
            }

            // Record the class we are switching TO. ReconcileClassPlayTime compares against this, so
            // without it the poll would see a change one second later and bill the switch twice.
            if (newSkill != null)
                playerLastSkillNames[player] = newSkill.Name;
        }

        /// <summary>
        /// A player asks to get into a vehicle. Refused while they are stunned (see StunLock). Returning true lets the
        /// engine carry on exactly as it did before this handler existed. Fails open: a bug here must never trap
        /// someone out of a vehicle, and the caller (the arena event queue) catches nothing.
        /// </summary>
        [Scripts.Event("Player.EnterVehicle")]
        public bool playerEnterVehicle(Player player, Vehicle vehicle)
        {
            try { return !StunLock.Deny(player, "enter"); }
            catch (Exception ex) { Console.WriteLine("[StunLock] enter: " + ex.Message); return true; }
        }

        /// <summary>A player asks to get out of their vehicle. Refused while they are stunned.</summary>
        [Scripts.Event("Player.LeaveVehicle")]
        public bool playerLeaveVehicle(Player player, Vehicle vehicle)
        {
            try { return !StunLock.Deny(player, "exit"); }
            catch (Exception ex) { Console.WriteLine("[StunLock] exit: " + ex.Message); return true; }
        }

        // First kill or flag pickup of the current game; reset when a game starts or resets. See ClassGateRoundLive.
        private bool _roundHadAction;

        /// <summary>
        /// Is a round actually being played, so the class change cooldown should bite? False between games (the
        /// countdown, post-game, "not enough players"), during a draft or OvD setup, and in a game that is running
        /// but where nobody has taken a shot or picked up a flag yet - that is lobby sorting, not play.
        ///   - OvD match clock running (ovdMatchStartTick): live from the whistle.
        ///   - otherwise: a live game, no draft in progress, and the round has seen its first kill or flag pickup.
        /// </summary>
        internal bool ClassGateRoundLive()
        {
            if (ovdMatchStartTick != null) return true;
            if (!arena._bGameRunning || gameState != GameState.ActiveGame) return false;
            if (_mixManager != null && _mixManager.IsOrganizing) return false;
            return _roundHadAction;
        }

        /// <summary>The message that blocks this class change, or null. A swap allowed only because no round is live says so.</summary>
        internal string ClassGateBlock(Player p, string targetSkill)
        {
            string hard = HardEconomy.ClassLocked(p, targetSkill);      // TP Hard: a class needs the experience its rpg row names
            if (hard != null) return hard;
            string notice;
            string blocked = ClassGate.Check(p, targetSkill, CTFClass.ResolveName(p), ClassGateRoundLive(), out notice);
            if (notice != null) p.sendMessage(0, notice);
            return blocked;
        }

        internal void ClassGateCommit(Player p, string newSkill)
        {
            ClassGate.Commit(p, newSkill, ClassGateRoundLive());
        }

        /// <summary>
        /// Triggered when a player requests to buy a skill
        /// </summary>
        [Scripts.Event("Shop.SkillRequest")]
        public bool PlayerShopSkillRequest(Player from, SkillInfo skill)
        {
            // Debounce: this event is reachable from the F11 skill shop, which routes through
            // Arena.poll()'s event queue with no exception handling around it. A rapid-fire repeat
            // of the same request (double click, or a client resend while a prior request is still
            // being processed/denied) got reported crashing the zone and disconnecting players when
            // picking Infiltrator - dropping the repeat here means whatever the underlying trigger
            // is, it can't be fired thousands of times a second.
            int nowTick = Environment.TickCount;
            int lastTick;
            if (from != null && _lastSkillShopRequestTick.TryGetValue(from, out lastTick) && nowTick - lastTick < SkillShopDebounceMs)
                return false;
            if (from != null)
                _lastSkillShopRequestTick[from] = nowTick;

            try
            {
                // The class change rule (*classgate): energy, cooldown or nothing. Returning false here cancels
                // the purchase before the engine touches the player's skills. Buying the class you already
                // have is not a change.
                if (ClassGate.IsClassSkill(skill) && !from._skills.ContainsKey(skill.SkillId))
                {
                    string blocked = ClassGateBlock(from, skill.Name);
                    if (blocked != null)
                    {
                        from.sendMessage(-1, blocked);
                        return false;
                    }
                }

                UpdateSkillPlayTime(from, skill);

                //arena.sendArenaMessage(string.Format("Player {0} requested to buy skill {1}.", from._alias, skillName));
                if (skill.Name == "Infiltrator" && !from._arena._name.Contains("Arena 1") && !from._arena._name.Contains("Public1"))
                {
                    // Count infiltrators only on the player's team, excluding spectator vehicles.
                    // p._team can briefly be null while another player is mid-leaveArena (it is
                    // nulled before that player is pulled out of arena.Players) - guard it, since
                    // nothing between here and Arena.poll()'s event queue catches an exception.
                    int teamInfiltratorCount = arena.Players
                        .Where(p => p != null && p._team != null && p._team == from._team &&
                                   !p._team.IsSpec &&
                                   !p.IsSpectator &&
                                   p._skills.Any(s => s.Value.skill.Name == "Infiltrator"))
                        .Count();

                    if (teamInfiltratorCount >= 2)
                    {
                        from.sendMessage(-1, "Infiltrator skill purchase not allowed due to 2 infils on the team already.");
                        return false;
                    }
                }
                return true;
            }
            catch (Exception ex)
            {
                Console.WriteLine(String.Format("Error in PlayerShopSkillRequest for {0}: {1}", from == null ? "?" : from._alias, ex));
                // Fail open - a bug here should not block a legitimate class pick, and it must not
                // throw back into the unprotected caller.
                return true;
            }
        }
        // Properties to store portal redirect settings
        private string redirectSide = null;
        private string redirectBase = null;

        /// <summary>
        /// Handles a player's portal request
        /// </summary>
        [Scripts.Event("Player.Portal")]
        public bool playerPortal(Player player, LioInfo.Portal portal)
        {
            // Store vehicle state if player is in a vehicle and using specific portals
            // ushort[] portalIdsToTrack = { 66, 67 }; // Add any other portal IDs that should preserve vehicles
            
            // // Only track if the player is in a vehicle and using one of our tracked portals
            // if (player._occupiedVehicle != null && portalIdsToTrack.Any(id => id == portal.PortalData.DestinationWarpGroup))
            // {
            //     Vehicle vehicle = player._occupiedVehicle;
                
            //     // Create a VehicleState to store the important details
            //     VehicleState vehicleState = new VehicleState
            //     {
            //         PosX = player._state.positionX,
            //         PosY = player._state.positionY,
            //         Yaw = player._state.yaw,
            //         VelocityX = player._state.velocityX,
            //         VelocityY = player._state.velocityY,
            //         Energy = vehicle._state.energy,
            //         Health = vehicle._state.health,
            //         Direction = (byte)player._state.direction,
            //         VehicleTypeId = vehicle._type.Id,
            //         Team = vehicle._team
            //     };

            //     _lastOccupiedVehicle[player] = vehicleState;
                
            //     // Also store in tracking dictionary
            //     _occupiedVehicle[player] = vehicle;

            // }

            // Initialize tracking for new players if needed
            if (!playerClassPlayTimes.ContainsKey(player))
            {
                playerClassPlayTimes[player] = new Dictionary<string, int>();
                playerLastClassSwitch[player] = Environment.TickCount;
                playerClassSwaps[player] = 0;
            }

            // Check if the player's arena and event type are valid
            if (currentEventType == EventType.MiniTP)
            {
                // Replace 'desiredPortalID' with the specific portal ID you want to check
                ushort[] desiredPortalIDs = { 66, 67 }; // Titan DropShip portals

                // Check if the portal used is one of the ones we want to redirect
                if (desiredPortalIDs.Any(id => id == portal.PortalData.DestinationWarpGroup))
                {
                        if (player._team._name.Contains("Titan")) {
                            WarpPlayerToRange(player, 654, 654, 518, 518);
                        }
                        else if (player._team._name.Contains("Collective")) {
                        WarpPlayerToRange(player, 648, 648, 565, 565);
                    }
                    return false;
                }
            }

            // Check if the player's arena and event type are valid
            if (currentEventType == EventType.CTFX)
            {
                // Replace 'desiredPortalID' with the specific portal ID you want to check
                ushort[] desiredPortalIDs = { 66, 67 }; // Titan DropShip portals

                // Check if the portal used is one of the ones we want to redirect
                if (desiredPortalIDs.Any(id => id == portal.PortalData.DestinationWarpGroup))
                {
                    // Define the target position within the same arena
                    Helpers.ObjectState targetPosition = new Helpers.ObjectState();
                    targetPosition.positionX = 502; // Replace with desired X coordinate
                    targetPosition.positionY = 1422; // Replace with desired Y coordinate
                    targetPosition.positionZ = 0;    // Z coordinate, if applicable
                    targetPosition.yaw = 0;          // Facing direction, if applicable

                    // Warp the player to the new position
                    player.warp(targetPosition.positionX * 16, targetPosition.positionY * 16);
                    //WarpPlayerToExactLocation(player, targetPosition.positionX, targetPosition.positionY);

                    // Send a message to the player indicating they used a portal
                    player.sendMessage(0, "You have been redirected through a special portal!");

                    // Return false to prevent the default portal handling
                    return false;
                }
            }
            // Check if the player's arena and event type are valid
            if (currentEventType == EventType.SUT)
            {
                // Replace 'desiredPortalID' with the specific portal ID you want to check
                ushort[] desiredPortalIDs = { 66, 67 }; // Titan DropShip portals

                // Check if the portal used is one of the ones we want to redirect
                if (desiredPortalIDs.Any(id => id == portal.PortalData.DestinationWarpGroup))
                {
                    int totalPlayers = arena.PlayersIngame.Count();

                    if (totalPlayers < 10)
                        WarpPlayerToRange(player, 1180, 1270, 145, 240);

                    if (totalPlayers >= 10 && totalPlayers <= 29)
                        WarpPlayerToRange(player, 1180, 1400, 145, 270);

                    if (totalPlayers >= 30)
                        WarpPlayerToRange(player, 1070, 1540, 60, 310);

                    // Send a message to the player indicating they used a portal
                    //player.sendMessage(0, "You have been redirected to Small Unit Tactics!");

                    // Return false to prevent the default portal handling
                    return false;
                }
            }
            //arena debug message using string.format stating the portal.id
            //arena.sendArenaMessage(string.Format("Portal ID: {0}", portal.PortalData.DestinationWarpGroup));

            // Handle portal redirects based on base locations using value tuples with named elements
            bool isTitanPortal = new[] { 18, 201 }.Contains(portal.PortalData.DestinationWarpGroup);
            bool isCollectivePortal = new[] { 6, 7, 202 }.Contains(portal.PortalData.DestinationWarpGroup);

            bool shouldRedirect = (redirectSide == "titan" && isTitanPortal) || 
                                  (redirectSide == "collective" && isCollectivePortal);

            if (shouldRedirect)
            {
                if (redirectBase.Equals("d8", StringComparison.OrdinalIgnoreCase))
                {
                    WarpPlayerToRange(player, 275, 275, 601, 601);
                    return false;
                }
                else if (redirectBase.Equals("a10", StringComparison.OrdinalIgnoreCase))
                {
                    WarpPlayerToRange(player, 32, 32, 696, 696);
                    return false;
                }
                else if (redirectBase.Equals("a8", StringComparison.OrdinalIgnoreCase))
                {
                    WarpPlayerToRange(player, 28, 28, 611, 611);
                    return false;
                }
                else if (redirectBase.Equals("f8", StringComparison.OrdinalIgnoreCase))
                {
                    WarpPlayerToRange(player, 421, 421, 569, 569);
                    return false;
                }
                else if (redirectBase.Equals("b8", StringComparison.OrdinalIgnoreCase))
                {
                    WarpPlayerToRange(player, 164, 177, 570, 572);
                    return false;
                }
            }

            // Check if it's a victory portal
            bool isVictoryPortal = new[] { 4, 5, 10, 28, 30, 35 }.Contains(portal.PortalData.DestinationWarpGroup);

            // Check if the player is carrying a flag and is5v5, if true winningTeamOVD is set to offense
            bool isCarryingFlag = false;
            foreach (Arena.FlagState fs in arena._flags.Values)
            {
                if (fs.carrier == player)
                {
                    isCarryingFlag = true;
                    break;
                }
            }

            if (is5v5 && isCarryingFlag && isVictoryPortal)
            {
                // Check if there's a squad leader on the player's team
                bool hasSquadLeader = arena.Players.Any(p =>
                    p != null && p._team != null && p._team == player._team &&
                    !p._team.IsSpec &&
                    p._skills.Any(s => s.Value.skill.Name == "Squad Leader"));

                if (hasSquadLeader)
                {
                    winningTeamOVD = "offense";
                    arena.sendArenaMessage("Offense wins! Flag carrier has used portal.");
                }
            }

            //IF destination warp group is 200 (enemy portal): ONE rule for players and bots (MiniTPEnemyPortal): an ALIVE hide-spawned portal in the team's own enemy base, the one
            // nearer the flags first (veh 436 "Warp Point (green2)": A7b / D7b), else the farther one (veh 413: A7a / D7a). A destroyed portal is never a target.
            if (portal.PortalData.DestinationWarpGroup == 200)
            {
                string tn = player._team != null ? player._team._name : "";
                bool collectiveTeam = tn.StartsWith("Collective", StringComparison.Ordinal), titanTeam = tn.StartsWith("Titan Militia", StringComparison.Ordinal);
                Vehicle bestPortal = (collectiveTeam || titanTeam) ? MiniTPEnemyPortal(collectiveTeam) : null;
                if (bestPortal != null)
                {
                    player.warp(bestPortal._state.positionX, bestPortal._state.positionY);
                    return false;
                }
            }

            // Proceed with the default portal handling
            return true;
        }



        /// <summary>
        /// A deliberate drop (?drop, ?bwd, the client's drop key - the server raises this for all
        /// three) is a declaration: they bought it to leave it for the team, so autopickup must not
        /// top it straight back up. A partial drop lowers the top-up target by what was dropped;
        /// dropping the lot takes the item off the list. Remembered per alias until the next
        /// loadout change. Notices are batched so a five-item drop macro costs one line.
        /// </summary>
        [Scripts.Event("Player.ItemDrop")]
        public bool playerItemDrop(Player player, ItemInfo item, object quantity)
        {
            bool queued = false;
            try { queued = HandleMineralDrop(player, item, quantity); }   // *flagdrop: minerals near a flag are queued
            catch (Exception ex)
            {
                Log.write(TLog.Warning, "HandleMineralDrop: " + ex.Message);
                queued = true;   // never let the engine's own drop (which a flag eats) run after a failure here (nothing was taken: the items stay)
            }
            if (queued)
                return false;   // taken over (or failed safe): the engine does nothing, no bookkeeping
            return ItemDropBookkeeping(player, item, quantity);
        }

        private bool ItemDropBookkeeping(Player player, ItemInfo item, object quantity)
        {
            try
            {
                if (player == null || item == null || !IsAutoPickupable(item.name))
                    return true;
                int qty = Convert.ToInt32(quantity);
                if (qty <= 0)
                    return true;

                Dictionary<string, int> dropped;
                if (!autoPickupDropped.TryGetValue(player._alias, out dropped))
                    autoPickupDropped[player._alias] = dropped = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
                int had;
                dropped.TryGetValue(item.name, out had);
                dropped[item.name] = had + qty;

                Dictionary<string, int> following;
                if (!autoPickupItems.TryGetValue(player._alias, out following) || (autoPickupCustom.Contains(player._alias) && !autoPickupCarry.Contains(player._alias)))
                    return true;   // a hand-typed ?ap list is the player's own (a what-you-carry list still follows their drops)
                int target;
                if (!following.TryGetValue(item.name, out target))
                    return true;
                if (!autoPickupCarry.Contains(player._alias))
                {   // follows the build: the build's amount minus everything dropped since the buy (mines capped at 1, see DeriveAutoPickupItemsFromBuild)
                    string reSource, reSkipped;
                    int left;
                    if (DeriveAutoPickupItemsFromBuild(player, out reSource, out reSkipped).TryGetValue(item.name, out left) && left > 0)
                    {
                        following[item.name] = left;
                        return true;
                    }
                }
                else if (target - qty > 0)
                {
                    following[item.name] = target - qty;
                    return true;
                }
                following.Remove(item.name);
                List<string> notice;
                if (!autoPickupDropNotice.TryGetValue(player._alias, out notice))
                    autoPickupDropNotice[player._alias] = notice = new List<string>();
                if (!notice.Contains(item.name))
                    notice.Add(item.name);
                if (autoPickupDropNoticeDue == 0)
                    autoPickupDropNoticeDue = Environment.TickCount + 1500;
            }
            catch (Exception ex)
            {
                Log.write(TLog.Warning, "playerItemDrop: " + ex.Message);
            }
            return true;
        }

        /// <summary>1Hz: the batched "won't top up" line, ~1.5s after the first drop of a command.</summary>
        private void FlushAutoPickupDropNotices(int now)
        {
            if (autoPickupDropNoticeDue == 0 || now < autoPickupDropNoticeDue)
                return;
            autoPickupDropNoticeDue = 0;
            foreach (var kv in autoPickupDropNotice)
            {
                Player p = arena.getPlayerByName(kv.Key);
                if (p != null && kv.Value.Count > 0)
                    p.sendMessage(0, String.Format("AutoPickup won't top up {0} (dropped). Your next buy resets it.",
                        String.Join(", ", kv.Value.ToArray())));
            }
            autoPickupDropNotice.Clear();
        }

        // ---------------------------------------------------------------- persistent bounty (Travis 10-24, CTF:X zone)
        // A player who goes to spec, leaves the arena or drops out (a client crash) keeps his bounty: it comes back when he plays again
        // in the same arena and lasts until he dies. The engine sets bounty.start on every unspec (Player.unspec) and the CTF:X / MiniTP
        // spawns set it again, so the restore runs 1 s after he is in play. Static: a reconnect into a reopened arena still finds it.
        // Travis: "might be overpowered, I may have to finetune it later" - *keepbounty on|off switches it until the zone restarts.
        private static readonly Dictionary<string, int> _keptBounty = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
        private static bool _keepBountyOn = true;
        private readonly Dictionary<Player, int> _bountyRestoreDue = new Dictionary<Player, int>();   // cleared in playerLeaveArena
        private string KeptBountyKey(Player p) { return arena._name + "|" + p._alias; }

        /// <summary>Player.Leave (a spec, or a drop while playing): keep a bounty above the start value (zone 112: Start=0; a new
        /// player object holds 1, which is not worth a message).</summary>
        private void KeepBounty(Player p)
        {
            if (!_keepBountyOn || p == null || arena == null || p._bounty <= Math.Max(CFG.bounty.start, 1)) return;
            _keptBounty[KeptBountyKey(p)] = p._bounty;
            // a crash: the old session times out only after he has reconnected (stage: the new one was already in) - hand it over now
            foreach (Player q in arena.Players)
                if (q != p && string.Equals(q._alias, p._alias, StringComparison.OrdinalIgnoreCase)) { _bountyRestoreDue[q] = Environment.TickCount + 1000; break; }
        }

        /// <summary>Player.Enter (every unspec): a kept bounty is given back 1 s after he is in play.</summary>
        private void QueueBountyRestore(Player p)
        {
            if (_keepBountyOn && p != null && _keptBounty.ContainsKey(KeptBountyKey(p)))
                _bountyRestoreDue[p] = Environment.TickCount + 1000;
        }

        /// <summary>Player.Death: the kept bounty is gone with him.</summary>
        private void ForgetKeptBounty(Player p)
        {
            if (p == null || arena == null) return;
            _keptBounty.Remove(KeptBountyKey(p));
            _bountyRestoreDue.Remove(p);
        }

        private void PollBountyRestore(int now)
        {
            foreach (KeyValuePair<Player, int> kv in _bountyRestoreDue.ToList())
            {
                Player p = kv.Key;
                if (now - kv.Value < 0) continue;
                if (p == null || p._arena != arena) { _bountyRestoreDue.Remove(p); continue; }
                if (p.IsSpectator || p.IsDead) { if (now - kv.Value > 10000) _bountyRestoreDue.Remove(p); continue; }   // a refused join: the bounty stays kept
                _bountyRestoreDue.Remove(p);
                int b;
                string key = KeptBountyKey(p);
                if (!_keepBountyOn || !_keptBounty.TryGetValue(key, out b)) continue;
                _keptBounty.Remove(key);
                if (b <= p._bounty) continue;
                p.Bounty = b;
                p.syncState();
                p.sendMessage(0, string.Format("&Your bounty of {0} was kept while you were away - it is yours until you die.", b));
            }
        }


        // ---------------------------------------------------------------- *setbounty (Pub 11-08): a mod sets a bounty by hand
        private static string BountyOf(Player p) { return p._bounty.ToString(); }

        /// <summary>The player a mod named: the engine's recipient, else his exact name in this arena, else a UNIQUE start of a name (null + a reason when none or several).</summary>
        private Player FindBountyTarget(string name, out string why)
        {
            why = null;
            Player exact = null, only = null;
            int starts = 0;
            foreach (Player q in arena.Players)
            {
                if (q == null || q._alias == null) continue;
                if (string.Equals(q._alias, name, StringComparison.OrdinalIgnoreCase)) { exact = q; break; }
                if (q._alias.StartsWith(name, StringComparison.OrdinalIgnoreCase)) { only = q; starts++; }
            }
            if (exact != null) return exact;
            if (starts == 1) return only;
            if (starts > 1) why = "several players start with '" + name + "' - type more of the name";
            return null;
        }

        /// <summary>*setbounty [alias] [amount]</summary>
        private void SetBountyCommand(Player mod, Player recipient, string payload)
        {
            string[] t = (payload ?? "").Split(new[] { ' ' }, StringSplitOptions.RemoveEmptyEntries);
            int amount = 0;
            bool haveAmount = t.Length > 0 && int.TryParse(t[t.Length - 1], out amount);
            string name = null;
            if (recipient == null)
            {
                int nameWords = haveAmount ? t.Length - 1 : t.Length;
                if (nameWords > 0) name = string.Join(" ", t, 0, nameWords);
            }
            if (haveAmount && (amount < 0 || amount > 999999))
            {
                mod.sendMessage(-1, "A bounty is 0 to 999999.");
                return;
            }

            Player target = recipient;
            if (target == null && name == null) target = mod;               // *setbounty 500: yourself
            if (target == null)
            {
                string why;
                target = FindBountyTarget(name, out why);
                if (target == null && why != null) { mod.sendMessage(-1, why); return; }
            }

            string alias = target != null ? target._alias : name;
            string key = arena._name + "|" + alias;
            int kept;
            bool hasKept = _keptBounty.TryGetValue(key, out kept);

            if (!haveAmount)
            {
                mod.sendMessage(0, string.Format("&Bounty of {0}: {1}{2}. *setbounty {0} <amount>", alias,
                    target != null ? BountyOf(target) : "not in this arena", hasKept ? string.Format(" (kept {0})", kept) : ""));
                return;
            }

            if (target != null && target.IsDead && !target.IsSpectator)
            {
                mod.sendMessage(-1, alias + " is dead - set it again once he has respawned.");
                return;
            }
            if (target != null && !target.IsSpectator)
            {
                _keptBounty.Remove(key);
                _bountyRestoreDue.Remove(target);
                target.Bounty = amount;
                target.syncState();
                target.sendMessage(0, string.Format("&Your bounty was set to {0}.", amount));
                mod.sendMessage(0, string.Format("&{0}'s bounty is now {1}.", alias, amount));
                return;
            }

            // a spectator, or a name that is not here (after a restart): keep it for him; it is his 1 s after he is next in play
            if (!_keepBountyOn)
            {
                mod.sendMessage(-1, alias + " is not playing, and *keepbounty is off - nothing kept. *keepbounty on");
                return;
            }
            if (amount <= Math.Max(CFG.bounty.start, 1)) { _keptBounty.Remove(key); mod.sendMessage(0, "&Cleared the kept bounty of " + alias + "."); return; }
            _keptBounty[key] = amount;
            mod.sendMessage(0, string.Format("&{0} is not in play: bounty {1} is kept for him until he plays.", alias, amount));
        }

        [Scripts.Event("Player.Leave")]
        public void playerLeave(Player player)
        {
            KeepBounty(player);   // a spec, or a drop while playing (lostPlayer has already removed him, so before the check below)

            HardEconomy.NoteLeave(player);            // TP Pub: a spec or a quit stops his reward clock
            // Check if the player is still in the arena's player list
            if (player == null || arena == null || !arena.Players.Contains(player))
                return;

            // Still in the arena = a spec (their own, or a mod's *spec), not a disconnect - lostPlayer
            // removes the player from the arena BEFORE raising this. A benched mix / OvD player is
            // not auto-restored to their team when they re-enter; a dropped one still is.
            if (_mixManager != null)
                _mixManager.OnPlayerBenched(player);
            _duelSessions.Remove(player._alias);   // speccing ends a ?duel: no duel gear comes back out with them

            try
            {
                int toxCount = player.getInventoryAmount(2009);
                int tsoCount = player.getInventoryAmount(2005);
                int panCount = player.getInventoryAmount(2007);

                // Log.write(TLog.Normal, string.Format("[Debug] Player {0} leaving with Tox:{1} Tso:{2} Pan:{3}", 
                //     player._alias, toxCount, tsoCount, panCount));

                // Keep messages concise to avoid potential string length issues
                if (toxCount > 0 || tsoCount > 0 || panCount > 0)
                {
                    // Build shorter resource messages
                    var resources = new List<string>();
                    if (toxCount > 0) resources.Add(string.Format("{0}Tox", toxCount));
                    if (tsoCount > 0) resources.Add(string.Format("{0}Tso", tsoCount));
                    if (panCount > 0) resources.Add(string.Format("{0}Pan", panCount));

                    // Keep message compact
                    string message = string.Format("&{0}: {1}", player._alias, string.Join("/", resources));
                    if (message.Length <= 128) // Add length check
                    {
                        //arena.sendArenaMessage(message);
                    }
                }

                if (player._team != null)
                {
                    // Log.write(TLog.Normal, string.Format("[Debug] Player {0} team: {1}", 
                    //     player._alias, player._team._name));

                    if (player._team._name.Contains(" T"))
                    {
                        // Log.write(TLog.Normal, "[Debug] Attempting to spawn minerals for Titan player");
                        // Spawn their minerals for any they had in the Titan DropShip fixed coordinate
                        if (toxCount > 0)
                        {
                            ItemInfo item2009 = arena._server._assets.getItemByID(2009);
                            if (item2009 != null)
                            {
                                arena.itemSpawn(item2009, (ushort)toxCount, 689 * 16, 457 * 16, null);
                                //Log.write(TLog.Normal, string.Format("[Debug] Spawned {0} Tox at Titan dropship", toxCount));
                            }
                            else
                            {
                                //Log.write(TLog.Error, "[Debug] Failed to get Tox item info");
                            }
                        }
                        if (tsoCount > 0)
                        {
                            ItemInfo item2005 = arena._server._assets.getItemByID(2005);
                            if (item2005 != null)
                            {
                                arena.itemSpawn(item2005, (ushort)tsoCount, 689 * 16, 462 * 16, null);
                                //Log.write(TLog.Normal, string.Format("[Debug] Spawned {0} Tso at Titan dropship", tsoCount));
                            }
                            else
                            {
                                //Log.write(TLog.Error, "[Debug] Failed to get Tso item info");
                            }
                        }
                        if (panCount > 0)
                        {
                            ItemInfo item2007 = arena._server._assets.getItemByID(2007);
                            if (item2007 != null)
                            {
                                arena.itemSpawn(item2007, (ushort)panCount, 689 * 16, 465 * 16, null);
                                //Log.write(TLog.Normal, string.Format("[Debug] Spawned {0} Pan at Titan dropship", panCount));
                            }
                            else
                            {
                                //Log.write(TLog.Error, "[Debug] Failed to get Pan item info");
                            }
                        }
                    }
                    else if (player._team._name.Contains(" C"))
                    {
                        //Log.write(TLog.Normal, "[Debug] Attempting to spawn minerals for Collective player");
                        // Spawn their minerals for any they had in the Collective DropShip fixed coordinate
                        if (toxCount > 0)
                        {
                            ItemInfo item2009 = arena._server._assets.getItemByID(2009);
                            if (item2009 != null)
                            {
                                arena.itemSpawn(item2009, (ushort)toxCount, 689 * 16, 610 * 16, null);
                                //Log.write(TLog.Normal, string.Format("[Debug] Spawned {0} Tox at Collective dropship", toxCount));
                            }
                            else
                            {
                                //Log.write(TLog.Error, "[Debug] Failed to get Tox item info");
                            }
                        }
                        if (tsoCount > 0)
                        {
                            ItemInfo item2005 = arena._server._assets.getItemByID(2005);
                            if (item2005 != null)
                            {
                                arena.itemSpawn(item2005, (ushort)tsoCount, 689 * 16, 615 * 16, null);
                                //Log.write(TLog.Normal, string.Format("[Debug] Spawned {0} Tso at Collective dropship", tsoCount));
                            }
                            else
                            {
                                //Log.write(TLog.Error, "[Debug] Failed to get Tso item info");
                            }
                        }
                        if (panCount > 0)
                        {
                            ItemInfo item2007 = arena._server._assets.getItemByID(2007);
                            if (item2007 != null)
                            {
                                arena.itemSpawn(item2007, (ushort)panCount, 689 * 16, 618 * 16, null);
                                //Log.write(TLog.Normal, string.Format("[Debug] Spawned {0} Pan at Collective dropship", panCount));
                            }
                            else
                            {
                                //Log.write(TLog.Error, "[Debug] Failed to get Pan item info");
                            }
                        }

                        // Keep leave message short
                        // string leaveMsg = string.Format("&{0} left", player._alias);
                        // if (leaveMsg.Length <= 128)
                        // {
                        //     arena.sendArenaMessage(leaveMsg);
                        // }
                    }
                    else
                    {
                        //Log.write(TLog.Normal, string.Format("[Debug] Player {0} team name did not match expected patterns", 
                        //    player._alias));
                    }
                }
                else
                {
                    //Log.write(TLog.Normal, string.Format("[Debug] Player {0} has no team", player._alias));
                }
            }
            catch (Exception ex)
            {
                //Log.write(TLog.Error, "Error in playerLeave: " + ex.ToString());
            }
            
            /* DISABLED: Vehicle tracking through portals
            // Also clean up the last occupied vehicle entry
            if (_lastOccupiedVehicle.ContainsKey(player))
                _lastOccupiedVehicle.Remove(player);
            */
                
            // NOTE: this handler fires on EVERY spec, not only on disconnect - Player.spec() calls
            // _arena.playerLeave(), which callsyncs "Player.Leave" (ScriptArena.cs:145). Only
            // per-game state belongs here. Anything that should survive a spec (player preferences,
            // mix pool membership) is cleaned in playerLeaveArena instead.

            // Clear all player specific dictionaries.
            // A Dictionary keyed by Player pins the whole Player object graph, so EVERY
            // long-lived per-player collection has to be cleared here or the script leaks one
            // player per disconnect. Only the first five below used to be cleared.
            playerClassPlayTimes.Remove(player);
            playerLastClassSwitch.Remove(player);
            playerClassSwaps.Remove(player);
            _lastSkillShopRequestTick.Remove(player);
            _playerWeaponStats.Remove(player);
            _ebHitStats.Remove(player);
            minedTsoByPlayer.Remove(player);
            minedToxByPlayer.Remove(player);

            _lastgamePlayerWeaponStats.Remove(player);
            queuedClassSwap.Remove(player);
            playerVotes.Remove(player);
            playerScores.Remove(player);
            gladiatorPlayers.Remove(player);
            duelParticipants.Remove(player);

            // The player's own choices (the ?b/?bw build autobuy uses, ?ap, ?ad) are cleared in playerLeaveArena,
            // not here: this fires on every spec, which used to wipe them each time someone went to spectator.
            ClassGate.Forget(player._alias);
            StunLock.Forget(player._alias);
            Subzero.Forget(player._alias);   // Subzero (Tranq) ice: what is up fades on its own
            playerDamageStats.Remove(player._id);
            return;
        }

        /// <summary>
        /// Triggered when a player decides to leave the game or spectate.
        /// This ensures that any flags the player was carrying are respawned at their original locations.
        /// </summary>
        /// <summary>
        /// The player has genuinely left the arena. Unlike Player.Leave (which fires on every spec),
        /// this is the real disconnect, so it is where anything that should survive a spec gets
        /// cleaned up - player preferences and mix pool membership.
        /// </summary>
        [Scripts.Event("Player.LeaveArena")]
        public void playerLeaveArena(Player player)
        {
            if (player == null)
                return;
            _bountyRestoreDue.Remove(player);   // keyed by Player: must not outlive him (the kept bounty itself stays, by name)
            try { ReturnQueuedDrops(player, null); } catch (Exception ex) { Console.WriteLine("[flagdrop] leave arena: " + ex.Message); }   // before the server saves the player

            if (_liveSnap != null) _liveSnap.NotifyLeave(player);   // site: never list them in two arenas at once

            if (_mixManager != null)
                _mixManager.OnPlayerLeaveArena(player);

            // Preference dictionaries keyed by Player - these must outlive a spec but must NOT
            // outlive the player, or they pin the whole Player graph (see the _projectileOwners leak).
            disallowClassChange.Remove(player);
            lastUsedBuild.Remove(player);
            playerLastSkillNames.Remove(player);
            lastAnnouncementTimes.Remove(player);
            playedInPreviousMix.Remove(player);

            // Keyed by ALIAS rather than Player, so without this it grows forever and can hand a
            // returning player a stale setup. Soup's original had no cleanup for it.
            premadeActiveSetup.Remove(player._alias.ToLower());

            // The ?auto family's choices, alias-keyed - kept through a spec, dropped when they leave.
            string dummy;
            persistentBuilds.TryRemove(player._alias, out dummy);
            persistentBuildClass.TryRemove(player._alias, out dummy);
            autoPickupCustom.Remove(player._alias);
            autoPickupCarry.Remove(player._alias);
            autoPickupOff.Remove(player._alias);
            autoPickupItems.Remove(player._alias);     // the loadout it followed is gone with persistentBuilds (a remembered ?ap list comes back on return)
            autoPickupClass.Remove(player._alias);
            DropPendingOccupy(player._alias);   // nothing queued may fire on their next visit
            _warpWatch.Remove(player);
            occupyThisLife.Remove(player._alias);
            occupyHintAt.Remove(player._alias);
            occupyArmed.Remove(player._alias);
            occupyBuyAtRespawn.Remove(player._alias);
            autoOccupyVehicle.Remove(player._alias);
            energyBeforeWipe.Remove(player);
            autoPickupDropped.Remove(player._alias);
            autoPickupDropNotice.Remove(player._alias);
            autoDropOverride.Remove(player._alias);
        }

        /// <summary>
        /// Match arenas build their teams on the fly, and the engine picks a respawn warp by team id,
        /// so a placed player is left at 0,0. Sends them to their side's dropship unless they are
        /// already on dropship terrain (4). Same coordinates the OvD game-start warp uses.
        /// </summary>
        private void WarpToSideDropship(Player p)
        {
            if (p == null || p._team == null) return;
            if (arena.getTerrainID(p._state.positionX, p._state.positionY) == 4) return;
            if (IsTitanSideTeam(p._team)) p.warp(682 * 16, 459 * 16);
            else if (IsCollectiveSideTeam(p._team)) p.warp(682 * 16, 614 * 16);
        }

        [Scripts.Event("Player.LeaveGame")]
        public bool playerLeaveGame(Player player)
        {
            try { ReturnQueuedDrops(player, "SPECTATING"); } catch (Exception ex) { Console.WriteLine("[flagdrop] leave game: " + ex.Message); }   // before the minerals below are counted
            try
            {
                int toxCount = player.getInventoryAmount(2009);
                int tsoCount = player.getInventoryAmount(2005);
                int panCount = player.getInventoryAmount(2007);

                //Log.write(TLog.Normal, string.Format("[Debug] Player {0} leaving with Tox:{1} Tso:{2} Pan:{3}", 
                //    player._alias, toxCount, tsoCount, panCount));

                // Keep messages concise to avoid potential string length issues
                if (toxCount > 0 || tsoCount > 0 || panCount > 0)
                {
                    // Build shorter resource messages
                    var resources = new List<string>();
                    if (toxCount > 0) resources.Add(string.Format("{0} Tox", toxCount));
                    if (tsoCount > 0) resources.Add(string.Format("{0} Tso", tsoCount));
                    if (panCount > 0) resources.Add(string.Format("{0} Pan", panCount));

                    // Keep message compact
                    string message = string.Format("&{0}: {1}", player._alias, string.Join("/", resources));
                    if (message.Length <= 128) // Add length check
                    {
                        arena.sendArenaMessage(message);
                    }
                }

                if (player._team != null)
                {
                    //Log.write(TLog.Normal, string.Format("[Debug] Player {0} team: {1}", 
                    //    player._alias, player._team._name));

                    if (player._team._name.Contains(" T"))
                    {
                        //Log.write(TLog.Normal, "[Debug] Attempting to spawn minerals for Titan player");
                        // Spawn their minerals for any they had in the Titan DropShip fixed coordinate
                        if (toxCount > 0)
                        {
                            ItemInfo item2009 = arena._server._assets.getItemByID(2009);
                            if (item2009 != null)
                            {
                                arena.itemSpawn(item2009, (ushort)toxCount, 689 * 16, 457 * 16, null);
                                //Log.write(TLog.Normal, string.Format("[Debug] Spawned {0} Tox at Titan dropship", toxCount));
                            }
                            else
                            {
                                //Log.write(TLog.Error, "[Debug] Failed to get Tox item info");
                            }
                        }
                        if (tsoCount > 0)
                        {
                            ItemInfo item2005 = arena._server._assets.getItemByID(2005);
                            if (item2005 != null)
                            {
                                arena.itemSpawn(item2005, (ushort)tsoCount, 689 * 16, 462 * 16, null);
                                //Log.write(TLog.Normal, string.Format("[Debug] Spawned {0} Tso at Titan dropship", tsoCount));
                            }
                            else
                            {
                                //Log.write(TLog.Error, "[Debug] Failed to get Tso item info");
                            }
                        }
                        if (panCount > 0)
                        {
                            ItemInfo item2007 = arena._server._assets.getItemByID(2007);
                            if (item2007 != null)
                            {
                                arena.itemSpawn(item2007, (ushort)panCount, 689 * 16, 465 * 16, null);
                                //Log.write(TLog.Normal, string.Format("[Debug] Spawned {0} Pan at Titan dropship", panCount));
                            }
                            else
                            {
                                //Log.write(TLog.Error, "[Debug] Failed to get Pan item info");
                            }
                        }
                    }
                    else if (player._team._name.Contains(" C"))
                    {
                        //Log.write(TLog.Normal, "[Debug] Attempting to spawn minerals for Collective player");
                        // Spawn their minerals for any they had in the Collective DropShip fixed coordinate
                        if (toxCount > 0)
                        {
                            ItemInfo item2009 = arena._server._assets.getItemByID(2009);
                            if (item2009 != null)
                            {
                                arena.itemSpawn(item2009, (ushort)toxCount, 689 * 16, 610 * 16, null);
                                //Log.write(TLog.Normal, string.Format("[Debug] Spawned {0} Tox at Collective dropship", toxCount));
                            }
                            else
                            {
                                //Log.write(TLog.Error, "[Debug] Failed to get Tox item info");
                            }
                        }
                        if (tsoCount > 0)
                        {
                            ItemInfo item2005 = arena._server._assets.getItemByID(2005);
                            if (item2005 != null)
                            {
                                arena.itemSpawn(item2005, (ushort)tsoCount, 689 * 16, 615 * 16, null);
                                //Log.write(TLog.Normal, string.Format("[Debug] Spawned {0} Tso at Collective dropship", tsoCount));
                            }
                            else
                            {
                                //Log.write(TLog.Error, "[Debug] Failed to get Tso item info");
                            }
                        }
                        if (panCount > 0)
                        {
                            ItemInfo item2007 = arena._server._assets.getItemByID(2007);
                            if (item2007 != null)
                            {
                                arena.itemSpawn(item2007, (ushort)panCount, 689 * 16, 618 * 16, null);
                                //Log.write(TLog.Normal, string.Format("[Debug] Spawned {0} Pan at Collective dropship", panCount));
                            }
                            else
                            {
                                //Log.write(TLog.Error, "[Debug] Failed to get Pan item info");
                            }
                        }

                        // Keep leave message short
                        string leaveMsg = string.Format("&{0} left", player._alias);
                        if (leaveMsg.Length <= 128)
                        {
                            arena.sendArenaMessage(leaveMsg);
                        }
                    }
                    else
                    {
                        //Log.write(TLog.Normal, string.Format("[Debug] Player {0} team name did not match expected patterns", 
                            //player._alias));
                    }
                }
                else
                {
                    //Log.write(TLog.Normal, string.Format("[Debug] Player {0} has no team", player._alias));
                }
            }
            catch (Exception ex)
            {
                //Log.write(TLog.Error, "Error in playerLeave: " + ex.ToString());
            }
            if (!arena._name.Contains("Arena 1"))
                deprizeMinPremades(player, false, false); // Remove items regardless of skill

            // Loop through each flag in the current map
            foreach (var flag in currentMap.Flags)
            {
                // Retrieve the flag object from the arena using the flag's name
                var fs = arena.getFlag(flag.Item1);  // flag.Item1 is the flag name

                if (fs != null && fs.carrier == player)
                {
                    // The player is carrying this flag
                    // Reset the flag's position to its original coordinates
                    fs.posX = (short)(flag.Item2 * 16);  // flag.Item2 is X coordinate
                    fs.posY = (short)(flag.Item3 * 16);  // flag.Item3 is Y coordinate

                    fs.bActive = true;      // Ensure the flag is active
                    fs.carrier = null;      // Clear the carrier
                    fs.team = null;         // Reset the team if necessary

                    // Update the flag's status for all players
                    Helpers.Object_Flags(arena.Players, fs);

                    // Since a player can carry only one flag, we can exit the loop
                    break;
                }
            }

            return true;
        }

        /// <summary>
        /// Called when the game begins
        /// </summary>
        [Scripts.Event("Game.Start")]
        public bool StartGame()
        {
            try { ReturnAllQueuedDrops("NEW GAME"); } catch (Exception ex) { Console.WriteLine("[flagdrop] game start: " + ex.Message); }
            _roundHadAction = false;
            // Don't start if no players are actually in-game (not spectating).
            // Backstop for a game forced open some other way (*startgame). Rest in
            // NotEnoughPlayers - dropping to Init sent us straight back through
            // Initialize -> PreGame -> gameStart() and span the arena in a loop.
            if (arena.PlayersIngame.Count() < 1)
            {
                gameState = GameState.NotEnoughPlayers;
                arena.setTicker(1, 3, 0, "Not Enough Players");
                return false;
            }

            if (IsLeagueArena(arena._name)){
                // Disable champ item conversion for CTFDL / CTFPL / OVDL arenas
                isChampEnabled = false;
            }

            if (!isChampEnabled)
            {
                RemoveChampItems();   // champion items back to their stock items
            }

            if (_matchAuto != null)
                _matchAuto.OnGameStart();   // reports the game to the site as in progress

            //Reset Flags
            if (currentEventType == EventType.MiniTP)
            {
                InitializeMiniTPEvent();
            } else {
                arena.flagReset();
                SpawnMapFlags();
            }
            _flagWasCarried.Clear();   // *flagfix: every flag starts this game on the ground

            if (!isOVD && (currentEventType != EventType.MiniTP))
            {
                // Let's not disturb the teams that OvD uses.
                SpawnMapPlayers();
            }
            
            HealAll();
            
            // Trigger immediate autooccupy for all players with it enabled (no delay for game start)
            _gameStartedAt = Environment.TickCount;   // ?v: the first seconds of any start (countdown, *restart, *startgame) are the start's ride
            StartAutoOccupyForGameStart();

            gameState = GameState.ActiveGame;
            flagMode = CTFMode.None;

            ResetKiller(null);
            killStreaks.Clear();

            // Start every class clock at the whistle. The trackers were only cleared at Game.End, so
            // the draft lobby / pre-game minutes - booked to whatever class people idled as - were
            // counting toward the spread and MainClass of the game that followed.
            ResetClassPlayTimes();
            ovdMatchStartTick = null;

            //Team team1 = arena.Teams.ElementAtOrDefault(1);
//Team team2 = arena.Teams.ElementAtOrDefault(2);
            List<Team> teamsWithPlayers = arena.Teams.Where(t => t.ActivePlayers.Count() > 0).ToList();
            Team team1 = teamsWithPlayers.FirstOrDefault(t => t._name.Contains(" T") || t._name.Contains("Titan"));
            Team team2 = teamsWithPlayers.FirstOrDefault(t => t._name.Contains(" C") || t._name.Contains("Collective"));

            // Extra check to make sure everyone is in dropship at game start
            // get all players in arena, if they are not on DropShip terrain 4, warp them back to the dropship by warping them warp group 2
            if (isOVD){
                // Set over time to 30            
                ScheduleOvertime(arena._name.Equals("ovd", StringComparison.OrdinalIgnoreCase) ? 20 : 30);
                foreach (Player p in arena.PlayersIngame)
                {
                    // Skip warping if player is a Dueler
                    if (GetPrimarySkillName(p) == "Dueler")
                        continue;

                    // Get player's current terrain ID
                    int terrainID = arena.getTerrainID(p._state.positionX, p._state.positionY);
                    // If player is not on dropship terrain (ID 4), warp them to warp group 2
                    if (terrainID != 4)
                    {
                        p.sendMessage(0, "You have been warped back to the DropShip for the game start.");
                        // Get warp group 2 coordinates from LIO
                        // Warp players to fixed coordinates based on their team

                        if (p._team == team1)
                        {
                            p.warp(682 * 16, 459 * 16); // Team 1 coordinates
                        }
                        else if (p._team == team2) 
                        {
                            p.warp(682 * 16, 614 * 16); // Team 2 coordinates
                        }
                    }
                }
            }

            //string teamNames = string.Join(", ", teamsWithPlayers.Select(t => t._name));
            //arena.sendArenaMessage(string.Format("Current teams with players: {0}", teamNames), 0);
            
            int team1FieldMedicCount = team1 != null ? arena.Players.Count(p => p._team._name == team1._name && p._skills.Values.Any(s => s.skill.Name == "Field Medic")) : 0;
            int team1CombatEngineerCount = team1 != null ? arena.Players.Count(p => p._team._name == team1._name && p._skills.Values.Any(s => s.skill.Name == "Combat Engineer")) : 0;
            int team2FieldMedicCount = team2 != null ? arena.Players.Count(p => p._team._name == team2._name && p._skills.Values.Any(s => s.skill.Name == "Field Medic")) : 0;
            int team2CombatEngineerCount = team2 != null ? arena.Players.Count(p => p._team._name == team2._name && p._skills.Values.Any(s => s.skill.Name == "Combat Engineer")) : 0;

            // Debug message for team counts
            // arena.sendArenaMessage(string.Format("Team 1: Field Medics - {0}, Combat Engineers - {1}. Team 2: Field Medics - {2}, Combat Engineers - {3}.", team1FieldMedicCount, team1CombatEngineerCount, team2FieldMedicCount, team2CombatEngineerCount));

            foreach (Player p in arena.Players)
            {
                // string buildString;
                // if (persistentBuilds.TryGetValue(p._alias, out buildString))
                // {
                //     WipeAndBuy(p, buildString, true);
                // }

                string skillName = GetPrimarySkillName(p);
                PlayerStreak temp = new PlayerStreak();
                temp.lastKillerCount = 0;
                temp.lastUsedWeap = null;
                temp.lastUsedWepKillCount = 0;
                temp.lastUsedWepTick = -1;
                // Indexer, NOT .Add: Dictionary.Add THROWS on a duplicate key, and this throw
                // happens inside gameStart() during the arena poll - so one duplicate alias kills
                // the whole arena's poll loop, not just this player's streak entry.
                // Duplicates are reachable: if a player's teardown fails (see the NullReferenceException
                // in Player.leftArena) they linger in arena.Players as a ghost, and the same alias
                // reconnecting puts two entries in the list. Overwriting is the correct behaviour
                // here anyway - there is meant to be exactly one streak record per alias.
                killStreaks[p._alias] = temp;
                if (currentEventType == EventType.Gladiator){
                    WarpPlayerToSpawn(p);
                }
                if (currentEventType == EventType.CTFX){
                    WarpPlayerToRange(p, 985, 997, 1117, 1129);
                    return false;
                }
                // if (currentEventType == EventType.TDM && _tdmInstance != null){
                //     _tdmInstance.WarpPlayerToTDMSpawn(p);
                // }
                if (currentEventType == EventType.MiniTP){
                    if (p._team._name.Contains("Titan"))
                        WarpPlayerToRange(p, 654, 654, 518, 518);
                    else if (p._team._name.Contains("Collective")) 
                        WarpPlayerToRange(p, 648, 648, 565, 565);
                    return false;
                }

                Team playerTeam = p._team;
                if (!arena._name.Contains("Arena 1"))
                {
                    if (playerTeam == team1)
                    {
                        // Handling for Team 1 Field Medics
                        if (team1FieldMedicCount > 1 && skillName == "Field Medic")
                        {
                            deprizeMinPremades(p, false, false);
                            ItemInfo item2005 = arena._server._assets.getItemByID(2005);
                            ItemInfo item2007 = arena._server._assets.getItemByID(2007);
                            //arena.itemSpawn(item2005, 150, 689 * 16, 615 * 16, null);
                            arena.itemSpawn(item2005, 150, 689 * 16, 462 * 16, null);
                            arena.itemSpawn(item2007, 150, 689 * 16, 465 * 16, null);
                        }
                        else //if (skillName == "Field Medic")
                        {
                            deprizeMinPremades(p, true, false);
                        }

                        // Handling for Team 1 Combat Engineers
                        if (team1CombatEngineerCount > 1 && skillName == "Combat Engineer")
                        {
                            deprizeMinPremades(p, false, false);
                            ItemInfo item2009 = arena._server._assets.getItemByID(2009);
                            //arena.itemSpawn(item2009, 150, 689 * 16, 610 * 16, null);
                            arena.itemSpawn(item2009, 150, 689 * 16, 457 * 16, null);
                        }
                        else //if (skillName == "Combat Engineer")
                        {
                            deprizeMinPremades(p, true, false);
                        }
                    }
                    else if (playerTeam == team2)
                    {
                        // Handling for Team 2 Field Medics
                        if (team2FieldMedicCount > 1 && skillName == "Field Medic")
                        {
                            deprizeMinPremades(p, false, false);
                            ItemInfo item2005 = arena._server._assets.getItemByID(2005);
                            ItemInfo item2007 = arena._server._assets.getItemByID(2007);
                            //arena.itemSpawn(item2005, 150, 689 * 16, 615 * 16, null);
                            arena.itemSpawn(item2007, 150, 689 * 16, 618 * 16, null);
                            arena.itemSpawn(item2005, 150, 689 * 16, 615 * 16, null);
                            //arena.itemSpawn(item2005, 150, 689 * 16, 462 * 16, null);
                        }
                        else //if (skillName == "Field Medic")
                        {
                            deprizeMinPremades(p, true, false);
                        }

                        // Handling for Team 2 Combat Engineers
                        if (team2CombatEngineerCount > 1 && skillName == "Combat Engineer")
                        {
                            deprizeMinPremades(p, false, false);
                            ItemInfo item2009 = arena._server._assets.getItemByID(2009);
                            arena.itemSpawn(item2009, 150, 689 * 16, 610 * 16, null);
                            //arena.itemSpawn(item2009, 150, 689 * 16, 457 * 16, null);
                        }
                        else //if (skillName == "Combat Engineer")
                        {
                            deprizeMinPremades(p, true, false);
                        }
                    }
                }
            }
            // Reset auto-drop tracking at game start
            playersWithAutoDrops.Clear();

            //Let everyone know - unless the OvD manager is starting this game underneath a match
            if (!quietGameStart)
                arena.sendArenaMessage("Game has started!", CFG.flag.resetBong);
            return true;
        }

        private bool AreAllFlagsCapturedByOneTeam()
        {
            Team potentialWinningTeam = null;

            // Check each flag's status
            foreach (Arena.FlagState fs in arena._flags.Values)
            {
                if (fs.bActive)
                {
                    // If no team has been set yet, use the current flag's team
                    if (potentialWinningTeam == null)
                        potentialWinningTeam = fs.team;
                    else if (fs.team != potentialWinningTeam)
                    {
                        // If a flag is held by a different team, not all flags are captured
                        return false;
                    }
                }
            }

            // All flags are captured by the same team, or no active flags left
            return potentialWinningTeam != null;
        }

        /// <summary>
        /// Attempts to spawn a given flag; returns true if successful, false if no suitable location found.
        /// </summary>
        public bool RandomizeFlagLocation(Arena.FlagState fs)
        {   //Set offsets
            int levelX = arena._server._assets.Level.OffsetX * 16;
            int levelY = arena._server._assets.Level.OffsetY * 16;

            //Give it some valid coordinates
            int attempts = 0;
            do
            {   //Make sure we're not doing this infinitely
                if (attempts++ > 200)
                {
                    Log.write(TLog.Error, "Unable to satisfy flag spawn for '{0}'.", fs.flag);
                    return false;
                }

                fs.posX = (short)(fs.flag.GeneralData.OffsetX - levelX);
                fs.posY = (short)(fs.flag.GeneralData.OffsetY - levelY);
                fs.oldPosX = fs.posX;
                fs.oldPosY = fs.posY;

                //Taken from Math.cs
                //For random flag spawn if applicable
                int lowerX = fs.posX - ((short)fs.flag.GeneralData.Width / 2);
                int higherX = fs.posX + ((short)fs.flag.GeneralData.Width / 2);
                int lowerY = fs.posY - ((short)fs.flag.GeneralData.Height / 2);
                int higherY = fs.posY + ((short)fs.flag.GeneralData.Height / 2);

                //Clamp within the map coordinates
                int mapWidth = (arena._server._assets.Level.Width - 1) * 16;
                int mapHeight = (arena._server._assets.Level.Height - 1) * 16;

                lowerX = Math.Min(Math.Max(0, lowerX), mapWidth);
                higherX = Math.Min(Math.Max(0, higherX), mapWidth);
                lowerY = Math.Min(Math.Max(0, lowerY), mapHeight);
                higherY = Math.Min(Math.Max(0, higherY), mapHeight);

                //Randomly generate some coordinates!
                int tmpPosX = ((short)arena._rand.Next(lowerX, higherX));
                int tmpPosY = ((short)arena._rand.Next(lowerY, higherY));

                //Check for allowable terrain drops
                int terrainID = arena.getTerrainID(tmpPosX, tmpPosY);
                for (int terrain = 0; terrain < 15; terrain++)
                {
                    if (terrainID == terrain && fs.flag.FlagData.FlagDroppableTerrains[terrain] == 1)
                    {
                        fs.posX = (short)tmpPosX;
                        fs.posY = (short)tmpPosY;
                        fs.oldPosX = fs.posX;
                        fs.oldPosY = fs.posY;
                        break;
                    }
                }

                //Check the terrain settings
                if (arena.getTerrain(fs.posX, fs.posY).flagTimerSpeed == 0)
                    continue;

            }
            while (arena.getTile(fs.posX, fs.posY).Blocked);

            return true;
        }

        /// <summary>
        /// Called when the game ends
        /// </summary>
        [Scripts.Event("Game.End")]
        public bool EndGame()
        {
            try { ReturnAllQueuedDrops("GAME OVER"); } catch (Exception ex) { Console.WriteLine("[flagdrop] game end: " + ex.Message); }
            // Stop auto-save if it's running
            if (isAutoSaving)
            {
                isAutoSaving = false;
                autoSaveTimer.Dispose();
                autoSaveTimer = null;
            }
            // The stats writer below reads the winner, but the public-arena branch here nulls it the
            // moment it has been announced - so every Arena 1 game recorded "Loss" for BOTH teams.
            // Snapshot it first; everything below uses gameWinner.
            Team gameWinner = winningTeam;

            if (!isOVD) HardEconomy.PayGameRewards(arena, gameWinner);      // TP Pub: reward per minute played, the winners x1.5 (engine jackpot off)

            if (!isOVD)
            {
                if (winningTeam == null)
                {
                    arena.sendArenaMessage("There was no winner.");
                }
                else
                {
                    UpdateGameEndFlagStats();

                    arena.sendArenaMessage(winningTeam._name + " has won the game!");
                    winningTeam = null;
                }
            }
            else
            {
                arena.sendArenaMessage("&Game has ended, Host may either *reset to spec all, or *restart for a rematch", 3);
            }

            // Records stats for EVERY game, not just OvD.
            //
            // This was "if (isOVD && ...)", so mix and pub games never recorded anything - yet the
            // body already computes gameMode as OvD-vs-Mix by player count and has a full Mix branch
            // for side/result. The gate was simply wrong: it fenced off code written to handle both.
            // A mix launch restarts the game (gameEnd + gameStart) purely to reset scores. That
            // fires Game.End with a full arena, so without this guard every mix start wrote a junk
            // game record for whatever happened before it.
            bool mixRestartInProgress = _mixManager != null && _mixManager.SuppressGameEndStats;

            if (!mixRestartInProgress && !arena._name.Contains("#") && arena._name != "Arena 1"){
                // Was gated on "_turretStats != null && _turretStats.Any()". That check belongs to
                // the TURRET csv, but it wrapped the player stats and the website POST as well - so a
                // game in which no turret took damage recorded nothing at all, for anybody. Player
                // stats have nothing to do with turret data. (_turretStats is initialised at its
                // declaration and is never null, so nothing below needs the guard either.)
                {
                    // Create base stats directory if it doesn't exist
                    string baseStatsDir = "playerStats";
                    if (!System.IO.Directory.Exists(baseStatsDir))
                    {
                        System.IO.Directory.CreateDirectory(baseStatsDir);
                    }

                    // Export regular game stats as CSV if we have any players with stats
                    if (arena.Players.Any(p => p.StatsLastGame != null))
                    {
                        // Determine game mode based on player count
                        // Game mode by player COUNT alone labelled every small pub game "OvD" and
                        // every large one "Mix", which is false for a game the mix manager never
                        // touched - and that mislabelled data is what the ELO reads.
                        //
                        // Read the mode the manager RECORDED at launch, not its live state: Game.End
                        // runs after the session reset, so asking IsActive here always answers "no".
                        // Getting that wrong made a real 5v5 OvD record as "Pub" with side "N/A" on
                        // every row, because the side logic only runs for OvD/Mix.
                        string gameMode;
                        string authoritativeDefenseTeam = null;
                        string authoritativeOffenseTeam = null;
                        string[] captainsOnRecord = null;

                        if (_mixManager != null && _mixManager.LastGameMode != null)
                        {
                            gameMode = _mixManager.LastGameMode;
                            authoritativeDefenseTeam = _mixManager.LastDefenseTeam;
                            authoritativeOffenseTeam = _mixManager.LastOffenseTeam;
                            captainsOnRecord = _mixManager.LastCaptains;
                        }
                        else
                        {
                            // Nobody ran *ovd go / *mix for this game - which is how MOST pub OvDs are
                            // hosted (*unspec + *setup by hand). Classify from what the arena shows:
                            // a base set up by *setup, the arena name, and the two sided teams. Then
                            // work out who defended from the base's owner (or, failing that, from
                            // the rosters) so the rows carry real sides and a real result instead of
                            // "Pub" / "N/A" / "Loss" for everyone.
                            var sidedTeams = new List<CTFMatchRules.TeamFacts>();
                            foreach (Team t in arena.Teams)
                            {
                                if (t == null || t.ActivePlayerCount <= 0) continue;
                                bool titan = IsTitanSideTeam(t), coll = IsCollectiveSideTeam(t);
                                if (!titan && !coll) continue;
                                var facts = new CTFMatchRules.TeamFacts
                                {
                                    Name = t._name, TitanSide = titan, CollectiveSide = coll, Players = t.ActivePlayerCount
                                };
                                foreach (Player tp in t.ActivePlayers)
                                {
                                    if (tp == null) continue;
                                    string cls = ResolveMainClassForStats(tp);
                                    if (cls == "Squad Leader") facts.SquadLeaders++;
                                    else if (cls == "Field Medic" || cls == "Combat Engineer") facts.Support++;
                                    int summoned;
                                    if (summonedCounts.TryGetValue(tp._id, out summoned)) facts.TimesSummoned += summoned;
                                }
                                sidedTeams.Add(facts);
                            }
                            // Two populated teams on the same side ("Titan Militia" + "Newfie T") is not
                            // a match; keep the biggest of each side so a straggler cannot break the count.
                            var twoSides = sidedTeams
                                .GroupBy(f => f.TitanSide)
                                .Select(g => g.OrderByDescending(f => f.Players).First())
                                .OrderByDescending(f => f.Players)
                                .ToList();
                            bool baseWasSetUp = is5v5 && baseUsed != "Unknown";
                            gameMode = CTFMatchRules.ClassifyUnmanagedGame(arena._name, baseWasSetUp,
                                twoSides.Count, twoSides.Sum(f => f.Players));
                            if (gameMode == "OvD" && twoSides.Count == 2)
                            {
                                authoritativeDefenseTeam = CTFMatchRules.InferDefenseTeam(baseUsed, twoSides);
                                if (authoritativeDefenseTeam != null)
                                    authoritativeOffenseTeam = twoSides.First(f => f.Name != authoritativeDefenseTeam).Name;
                            }
                            // *ovd captains a,b typed for a hand-hosted game, without *ovd go.
                            if (_mixManager != null) captainsOnRecord = _mixManager.PendingCaptains;
                        }
                        // A league match arena (freeinf.org queue): record under the league's own mode ("CTFDL"),
                        // never "Pub", and never let a stale mix session label or side it.
                        string leagueMode = _matchAuto != null ? _matchAuto.LeagueGameMode : null;
                        if (leagueMode != null)
                        {
                            gameMode = leagueMode;
                            authoritativeDefenseTeam = null;
                            authoritativeOffenseTeam = null;
                        }
                        // WHICH GAMES COUNT (2026-10-02). A game only reaches player_stats / ELO when somebody won it.
                        //   - OvD: its own rules (offense breaks the base or the clock runs out) - unchanged.
                        //   - Everything else (Mix, Pub, CTFDL): the normal CTF victory, i.e. one team held every flag
                        //     for the victory timer, which is what sets winningTeam. A game ended by *endgame, the clock
                        //     or a mix restart has no winner; it used to be recorded as a Loss for EVERY player and was
                        //     most of the junk dragging win rates (about half of all Mix games) and ELO down.
                        //   - Pub also needs a real game on both sides, so a lone player or a 2-man practice in a
                        //     private/test arena no longer creates a game or moves anyone's ELO.
                        bool recordGame = true;
                        string skipReason = null;
                        if (gameMode != "OvD")
                        {
                            if (gameWinner == null)
                                { recordGame = false; skipReason = "no flag victory"; }
                            else if (gameMode == "Pub")
                            {
                                int titanSide = 0, collectiveSide = 0;
                                foreach (Team ct in arena.Teams)
                                {
                                    if (ct == null || ct.ActivePlayerCount <= 0) continue;
                                    if (IsTitanSideTeam(ct)) titanSide += ct.ActivePlayerCount;
                                    else if (IsCollectiveSideTeam(ct)) collectiveSide += ct.ActivePlayerCount;
                                }
                                if (titanSide < PUB_MIN_PLAYERS_PER_SIDE || collectiveSide < PUB_MIN_PLAYERS_PER_SIDE)
                                    { recordGame = false; skipReason = String.Format("only {0}v{1} (need {2} a side)", titanSide, collectiveSide, PUB_MIN_PLAYERS_PER_SIDE); }
                            }
                        }
                        // WAS IT PLAYED (2026-10-25), every mode: the players the rows below are written for, their kills this game
                        // (the same StatsLastGame the rows carry) and the clock the rows report (CTFMatchRules.NotPlayed).
                        if (recordGame)
                        {
                            List<Player> counted = arena.Players.Where(cp => cp != null && cp.StatsLastGame != null && cp._team != null && !cp._team.IsSpec).ToList();
                            double playedMinutes = (arena._tickGameEnded - (ovdMatchStartTick ?? arena._tickGameStarted)) / (1000.0 * 60.0);
                            string notPlayed = CTFMatchRules.NotPlayed(counted.Count, counted.Sum(cp => cp.StatsLastGame.kills), playedMinutes);
                            if (notPlayed != null) { recordGame = false; skipReason = notPlayed; }
                        }
                        if (!recordGame)
                            Console.WriteLine(String.Format("[Stats] {0} game in '{1}' not recorded: {2}.", gameMode, arena._name, skipReason));
                        bool offenseWon = winningTeamOVD == "offense";
                        string flagWinnerName = gameWinner != null ? gameWinner._name : null;
                        //arena.sendArenaMessage(string.Format("Exporting stats for game mode {0}", gameMode), 0);

                        string gameStatsPath = System.IO.Path.Combine(baseStatsDir, string.Format("game_stats_{0}_{1}.csv", DateTime.Now.ToString("MM_dd_yyyy_HH_mm_ss"), arena._name.Replace(" ", "_")));
                        using (System.IO.StreamWriter writer = new System.IO.StreamWriter(gameStatsPath))
                        {
                            writer.WriteLine("PlayerName,Team,Kills,Deaths,Captures,CarrierKills,CarryTimeSeconds,GameLengthMinutes,Result,MainClass,ClassSwaps,TurretDamage,GameMode,Side,BaseUsed,Accuracy,AvgResourceUnusedPerDeath,AvgExplosiveUnusedPerDeath,EBHits");

                            // Prepare player stats for web integration
                            var playerStatsForWeb = new List<CTFGameType.PlayerStatData>();

                            // Get teams with more than 9 players
                            var largeTeams = arena.Teams.Where(t => t.ActivePlayerCount > 9).ToList();

                            // For each large team, check their flag position against base coordinates
                            foreach (var team in largeTeams)
                            {
                                var flags = _flags.Where(f => f.team == team).ToList();
                                var flag = flags.FirstOrDefault();
                                if (flag != null)
                                {
                                    int startX = 0, endX = 0, startY = 0, endY = 0;
                                    string detectedBase = "Unknown";

                                    // Use existing case logic to check coordinates
                                    switch (baseUsed)
                                    {
                                        case "D7":
                                            startX = 255 * 16; endX = 328 * 16;
                                            startY = 435 * 16; endY = 505 * 16;
                                            if (flag.posX >= startX && flag.posX <= endX && 
                                                flag.posY >= startY && flag.posY <= endY)
                                                detectedBase = "D7";
                                            break;
                                        case "F6":
                                            startX = 375 * 16; endX = 481 * 16;
                                            startY = 435 * 16; endY = 509 * 16;
                                            if (flag.posX >= startX && flag.posX <= endX && 
                                                flag.posY >= startY && flag.posY <= endY)
                                                detectedBase = "F6";
                                            break;
                                        case "F4":
                                            startX = 367 * 16; endX = 435 * 16;
                                            startY = 224 * 16; endY = 306 * 16;
                                            if (flag.posX >= startX && flag.posX <= endX && 
                                                flag.posY >= startY && flag.posY <= endY)
                                                detectedBase = "F4";
                                            break;
                                        case "A7":
                                            startX = 255 * 16; endX = 328 * 16;
                                            startY = 435 * 16; endY = 505 * 16;
                                            if (flag.posX >= startX && flag.posX <= endX && 
                                                flag.posY >= startY && flag.posY <= endY)
                                                detectedBase = "A7";
                                            break;
                                        case "A5":
                                            startX = 4 * 16; endX = 79 * 16;
                                            startY = 305 * 16; endY = 377 * 16;
                                            if (flag.posX >= startX && flag.posX <= endX && 
                                                flag.posY >= startY && flag.posY <= endY)
                                                detectedBase = "A5";
                                            break;
                                        case "B6":
                                            startX = 128 * 16; endX = 203 * 16;
                                            startY = 432 * 16; endY = 515 * 16;
                                            if (flag.posX >= startX && flag.posX <= endX && 
                                                flag.posY >= startY && flag.posY <= endY)
                                                detectedBase = "B6";
                                            break;
                                        case "B8":
                                            startX = 128 * 16; endX = 209 * 16;
                                            startY = 554 * 16; endY = 628 * 16;
                                            if (flag.posX >= startX && flag.posX <= endX && 
                                                flag.posY >= startY && flag.posY <= endY)
                                                detectedBase = "B8";
                                            break;
                                        default:
                                            startX = 0; endX = 0;
                                            startY = 0; endY = 0;
                                            break;
                                    }
                                    // Arena message for base used for that team
                                    //arena.sendArenaMessage(string.Format("Team {0} used base {1}", team._name, detectedBase));

                                    if (detectedBase != "Unknown")
                                    {
                                        //arena.sendArenaMessage(string.Format("Team {0} is using base {1}", team._name, detectedBase));
                                    }
                                }
                            }

                            // Cache the players list to avoid potential modification during iteration
                            var players = recordGame ? arena.Players.ToList() : new List<Player>();
                            foreach (Player p in players)
                            {
                                // Guard clauses to skip invalid players
                                if (p == null || p.StatsLastGame == null || p._team == null) continue;
                                // Accept the zone's OWN team names as well as the mix/OvD convention.
                                //
                                // This used to be `Contains(" T") || Contains(" C")`, which only ever
                                // matches teams the mix manager named ("Newfie T", "Mir C"). The pub
                                // teams are "Titan Militia'" and "Collective'" - no " T", no " C" - so
                                // an ordinary game recorded NOTHING, for anyone. That is why games
                                // played without the mix automation never showed up on the site.
                                string teamName = p._team._name ?? "";
                                bool onPlayingTeam =
                                    teamName.Contains(" T") || teamName.Contains(" C")
                                    || teamName.StartsWith("Titan", StringComparison.OrdinalIgnoreCase)
                                    || teamName.StartsWith("Collective", StringComparison.OrdinalIgnoreCase);
                                if (!onPlayingTeam) continue;

                                // Skip players with Dueler class
                                string mainClass = "Unknown";
                                var classSpreadMs = SnapshotClassPlayTimes(p); // booked + open session
                                if (classSpreadMs.Any())
                                    mainClass = classSpreadMs.OrderByDescending(x => x.Value).First().Key;
                                if (mainClass == "Unknown")
{
                                    mainClass = GetPrimarySkillName(p);
                                }
                                if (mainClass == "Dueler") continue;

                                ctfPlayerProxy.player = p;
                                double gameLengthMinutes = (arena._tickGameEnded - (ovdMatchStartTick ?? arena._tickGameStarted)) / (1000.0 * 60.0);
string result = "Loss";
                                string side = "N/A";
                                
                                // If the mix manager ran this game it KNOWS which team defended,
                                // so use that instead of inferring. Everything below is guesswork -
                                // summon counts, "is this player a Squad Leader", then a fill that
                                // just balances the counts - and it is why live data carries side
                                // "N/A" on 14.1% of rows and medics recorded as offense.
                                // Only players actually ON one of the two match teams get a side.
                                // Testing "is this the defending team, else offense" labelled anyone
                                // still sitting on a pub team (Titan Militia'/Collective') as offense -
                                // seen live: 6 of 10 bots never got drafted and all six were recorded
                                // as offense. Someone who was not in the match must stay "N/A".
                                bool onMatchTeam = authoritativeDefenseTeam != null && p._team != null
                                    && (p._team._name == authoritativeDefenseTeam
                                        || p._team._name == authoritativeOffenseTeam);

                                if (onMatchTeam)
                                {
                                    side = p._team._name == authoritativeDefenseTeam ? "defense" : "offense";
                                    // Was "p._team == winningTeam" - which an OvD never sets, because
                                    // SetupBase parks the other flags neutral. Every *ovd go match
                                    // therefore recorded ten losses. Offence breaks the base or the
                                    // clock runs out: that is the whole result.
                                    result = CTFMatchRules.OvdResult(side, offenseWon, flagWinnerName,
                                        p._team._name, authoritativeDefenseTeam, authoritativeOffenseTeam);
                                }
                                else if (gameMode == "OvD")
                                {
                                    // Determine if player is on offense based on summon counts OR Squad Leader skill
                                    string skill = GetPrimarySkillName(p);
                                    if ((summonedCounts.ContainsKey(p._id) && summonedCounts[p._id] > 0) || skill == "Squad Leader")
                                    {
                                        side = "offense";
                                        result = (winningTeamOVD == "offense") ? "Win" : "Loss";
                                    }
                                    else 
                                    {
                                        // Count current offense/defense assignments to ensure 5v5
                                        int currentOffenseCount = 0;
                                        int currentDefenseCount = 0;
                                        
                                        // Count players already processed in this stats batch
                                        foreach (var existingPlayer in playerStatsForWeb)
                                        {
                                            if (existingPlayer.GameMode == "OvD")
                                            {
                                                if (existingPlayer.Side == "offense")
                                                    currentOffenseCount++;
                                                else if (existingPlayer.Side == "defense")
                                                    currentDefenseCount++;
                                            }
                                        }
                                        
                                        // Assign based on team balance - maintain 5 offense, 5 defense
                                        if (currentOffenseCount < 5 && (summonedCounts.ContainsKey(p._id) && summonedCounts[p._id] > 0))
                                        {
                                            side = "offense";
                                        }
                                        else if (currentDefenseCount < 5)
                                        {
                                            side = "defense";
                                        }
                                        else if (currentOffenseCount < 5)
                                        {
                                            side = "offense";
                                        }
                                        else
                                        {
                                            side = "defense";
                                        }
                                        
                                        result = (side == "offense" && winningTeamOVD == "offense") || 
                                                (side == "defense" && winningTeamOVD != "offense") ? "Win" : "Loss";
                                    }
                                }
                                else if (gameMode == "Mix")
                                {
                                    // Get summoned counts for this player's team only
                                    var teamPlayers = p._team.ActivePlayers.Select(player => player._id).ToList();
                                    var teamSummonedCounts = new Dictionary<ushort, int>();
                                    
                                    // Filter summoned counts to only include players from this team
                                    foreach (var entry in summonedCounts)
                                    {
                                        if (teamPlayers.Contains(entry.Key))
                                        {
                                            teamSummonedCounts[entry.Key] = entry.Value;
                                        }
                                    }
                                    
                                    if (teamSummonedCounts.Count > 0)
                                    {
                                        // Get the top 4 most summoned players from this team
                                        var top4 = teamSummonedCounts.OrderByDescending(x => x.Value).Take(4).Select(x => x.Key).ToList();
                                        side = top4.Contains(p._id) ? "offense" : "defense";
                                    }
                                    else
                                    {
                                        // Fallback if no summon data
                                        string skill = GetPrimarySkillName(p);
                                        if (skill == "Squad Leader")
                                        {
                                            side = "offense";
                                        }
                                        else if (skill == "Field Medic" || skill == "Combat Engineer")
                                        {
                                            side = "defense";
                                        }
                                    }
                                    
                                    // Determine win/loss for Mix mode (the winner's bench team shares the win)
                                    if (IsSquadOfWinner(p._team, gameWinner))
                                    {
                                        result = "Win";
                                    }
                                }
                                else
                                {
                                    // For other game modes (the winner's bench team shares the win)
                                    if (IsSquadOfWinner(p._team, gameWinner))
                                    {
                                        result = "Win";
                                    }
                                }

                                int turretDamage = playerDamageStats.ContainsKey(p._id) ? playerDamageStats[p._id] : 0;
                                int classSwaps = playerClassSwaps.ContainsKey(p) ? playerClassSwaps[p] : 0;

                                // Calculate Accuracy - get best weapon accuracy for this player.
                                // Read the LIVE table: _lastgamePlayerWeaponStats is only snapshotted
                                // from it further down this method, so at this point it still holds the
                                // PREVIOUS game - every accuracy ever posted was one game stale.
                                double accuracy = 0.0;
                                Dictionary<int, WeaponStats> weaponTable = null;
                                if (_playerWeaponStats != null && _playerWeaponStats.ContainsKey(p))
                                    weaponTable = _playerWeaponStats[p];
                                if (weaponTable != null)
                                {
                                    var weaponAccuracies = weaponTable
                                        .Where(w => w.Value != null && w.Value.ShotsFired > 0)
                                        .Select(w => (double)w.Value.ShotsLanded / w.Value.ShotsFired);
                                    if (weaponAccuracies.Any())
                                        accuracy = weaponAccuracies.Max();
                                }

                                // Schema 2: per-weapon table by item NAME (ids mean nothing to the site),
                                // the class spread in whole seconds, and the mix-manager captain flag.
                                var weaponsByName = new Dictionary<string, Dictionary<string, int>>();
                                if (weaponTable != null)
                                {
                                    foreach (var w in weaponTable)
                                    {
                                        if (w.Value == null || w.Value.ShotsFired <= 0) continue;
                                        var weaponItem = AssetManager.Manager.getItemByID(w.Key);
                                        string weaponName = weaponItem != null ? weaponItem.name : ("item " + w.Key);
                                        Dictionary<string, int> cell;
                                        if (!weaponsByName.TryGetValue(weaponName, out cell))
                                        {
                                            cell = new Dictionary<string, int> { { "fired", 0 }, { "landed", 0 } };
                                            weaponsByName[weaponName] = cell;
                                        }
                                        cell["fired"] += w.Value.ShotsFired;   // += : two ids can share a name
                                        cell["landed"] += w.Value.ShotsLanded;
                                    }
                                }
                                var classSeconds = new Dictionary<string, int>();
                                int playSeconds = 0;
                                foreach (var ct in classSpreadMs)
                                {
                                    int secs = (int)Math.Round(ct.Value / 1000.0);
                                    if (secs <= 0) continue;
                                    classSeconds[ct.Key] = secs;
                                    playSeconds += secs;
                                }
                                bool isCaptain = captainsOnRecord != null
                                    && captainsOnRecord.Any(c => c != null
                                        && c.Equals(p._alias, StringComparison.OrdinalIgnoreCase));

                                // Calculate AvgResourcePerDeath - average of RepCoil, RepCharge, Energizer, Stim left per death
                                double avgResourcePerDeath = 0.0;
                                if (_averageItemsUsedPerDeath != null && _averageItemsUsedPerDeath.ContainsKey(p._alias))
                                {
                                    var stats = _averageItemsUsedPerDeath[p._alias];
                                    avgResourcePerDeath = (stats.ContainsKey("RepCoil") ? stats["RepCoil"] : 0) +
                                                         (stats.ContainsKey("RepCharge") ? stats["RepCharge"] : 0) +
                                                         (stats.ContainsKey("Energizer") ? stats["Energizer"] : 0) +
                                                         (stats.ContainsKey("Stim") ? stats["Stim"] : 0);
                                }

                                // Calculate AvgExplosivePerDeath - average of Frag and WP left per death
                                double avgExplosivePerDeath = 0.0;
                                if (_averageItemsUsedPerDeath != null && _averageItemsUsedPerDeath.ContainsKey(p._alias))
                                {
                                    var stats = _averageItemsUsedPerDeath[p._alias];
                                    avgExplosivePerDeath = (stats.ContainsKey("Frag") ? stats["Frag"] : 0) +
                                                          (stats.ContainsKey("WP") ? stats["WP"] : 0);
                                }

                                // Get EBHits - number of EB hits for this player
                                int ebHits = 0;
                                if (_ebHitStats != null && _ebHitStats.ContainsKey(p))
                                {
                                    ebHits = _ebHitStats[p];
                                }

                                writer.WriteLine(string.Format("{0},{1},{2},{3},{4},{5},{6},{7:F2},{8},{9},{10},{11},{12},{13},{14},{15:F3},{16:F2},{17:F2},{18}",
                                    p._alias.Replace(",", ""),
                                    p._team._name ?? "None",
                                    p.StatsLastGame.kills,
                                    p.StatsLastGame.deaths,
                                    p.StatsLastGame.zonestat5,
                                    p.StatsLastGame.zonestat7,
                                    p.StatsLastGame.zonestat3,
                                    gameLengthMinutes,
                                    result,
                                    mainClass,
                                    classSwaps,
                                    turretDamage,
                                    gameMode,
                                    side,
                                    baseUsed,
                                    accuracy,
                                    avgResourcePerDeath,
                                    avgExplosivePerDeath,
                                    ebHits));

                                // Add to web integration data
                                playerStatsForWeb.Add(new CTFGameType.PlayerStatData
                                {
                                    PlayerName = p._alias.Replace(",", ""),
                                    Team = p._team._name ?? "None",
                                    GameMode = gameMode,
                                    ArenaName = arena._name,
                                    BaseUsed = baseUsed,
                                    Side = side,
                                    Result = result,
                                    MainClass = mainClass,
                                    Kills = p.StatsLastGame.kills,
                                    Deaths = p.StatsLastGame.deaths,
                                    Captures = p.StatsLastGame.zonestat5,
                                    CarrierKills = p.StatsLastGame.zonestat7,
                                    CarryTimeSeconds = p.StatsLastGame.zonestat3,
                                    ClassSwaps = classSwaps,
                                    TurretDamage = turretDamage,
                                    EBHits = ebHits,
                                    Accuracy = accuracy,
                                    AvgResourceUnusedPerDeath = avgResourcePerDeath,
                                    AvgExplosiveUnusedPerDeath = avgExplosivePerDeath,
                                    GameLengthMinutes = gameLengthMinutes,
                                    // schema 2
                                    ClassPlayTimes = classSeconds,
                                    Weapons = weaponsByName,
                                    PlaySeconds = playSeconds,
                                    TimesSummoned = summonedCounts.ContainsKey(p._id) ? summonedCounts[p._id] : 0,
                                    SummonsPerformed = summonsPerformed.ContainsKey(p._id) ? summonsPerformed[p._id] : 0,
                                    MinedTso = minedTsoByPlayer.ContainsKey(p) ? minedTsoByPlayer[p] : 0,
                                    MinedTox = minedToxByPlayer.ContainsKey(p) ? minedToxByPlayer[p] : 0,
                                    IsCaptain = isCaptain
                                });

                                ctfPlayerProxy.player = null;
                            }

                            // The recorded session has now been read for every player, so consume it.
                            // Leaving it set would make the next ordinary pub game inherit this
                            // match's mode and defending team.
                            if (_mixManager != null)
                                _mixManager.ClearLastSession();

                            // Send player stats to website
                            if (playerStatsForWeb.Count > 0)
                            {
                                try
                                {
                                    // A league match game keeps the id it was reported under at start, so the site links these stats to it
                                    string gameId = (_matchAuto != null ? _matchAuto.CurrentGameId : null)
                                        ?? string.Format("{0}_{1}", arena._name, DateTime.UtcNow.ToString("yyyyMMdd_HHmmss"));
                                    // Use Task.Run to avoid blocking the main thread, but still get proper error handling
                                    Task.Run(async () => {
                                        try
                                        {
                                            await CTFGameType.PlayerStatsIntegration.SendPlayerStatsToWebsite(playerStatsForWeb, gameId);
                                        }
                                        catch (Exception asyncEx)
                                        {
                                            Console.WriteLine(string.Format("Error in async player stats submission: {0}", asyncEx.Message));
                                        }
                                    });
                                }
                                catch (Exception ex)
                                {
                                    Console.WriteLine(string.Format("Error initiating player stats submission: {0}", ex.Message));
                                }
                            }
                        }
                    }
                }
            }
            if (_matchAuto != null)
                _matchAuto.OnGameEnd(gameWinner != null && !mixRestartInProgress);

            gameState = GameState.PostGame;
            arena.flagReset();
            // Deactivate sdFlag — flagReset re-enables all flags but sdFlag should only
            // be active during sudden death (activated explicitly by startSuddenDeath)
            var sdFs = arena.getFlag("sdFlag");
            if (sdFs != null) { sdFs.bActive = false; sdFs.posX = 0; sdFs.posY = 0; Helpers.Object_Flags(arena.Players, sdFs); }
            isSD = false;
            isSecondOvertime = false;
            overtimeStart = 0;
            secondOvertimeStart = 0;
            redirectSide = null;
            redirectBase = null;
            _turretStats.Clear();
            // Create a deep copy of player weapon stats to properly store last game data
            _lastgamePlayerWeaponStats = new Dictionary<Player, Dictionary<int, WeaponStats>>();
            foreach (var playerEntry in _playerWeaponStats)
            {
                Dictionary<int, WeaponStats> weaponCopy = new Dictionary<int, WeaponStats>();
                foreach (var weaponEntry in playerEntry.Value)
                {
                    // Create a new WeaponStats object with the same values
                    WeaponStats statsCopy = new WeaponStats
                    {
                        ShotsFired = weaponEntry.Value.ShotsFired,
                        ShotsLanded = weaponEntry.Value.ShotsLanded,
                        AverageDistance = weaponEntry.Value.AverageDistance,
                        TotalHits = weaponEntry.Value.TotalHits
                    };
                    weaponCopy[weaponEntry.Key] = statsCopy;
                }
                _lastgamePlayerWeaponStats[playerEntry.Key] = weaponCopy;
            }
            _averageItemsUsedPerDeath.Clear();
            _playerWeaponStats.Clear();
            _ebHitStats.Clear();
            minedStats.Clear();
            minedTsoByPlayer.Clear();
            minedToxByPlayer.Clear();
            playerClassPlayTimes.Clear();
playerLastClassSwitch.Clear();
            playerClassSwaps.Clear();
            winningTeamOVD = "defense";
            summonedCounts.Clear();
            summonsPerformed.Clear();
            ovdMatchStartTick = null;
            pendingTsoTeam = null;
            is5v5 = false;
baseUsed = "Unknown";
            killStreaks.Clear();
            mixGameActive = true;
            isMixActive = false;
            playerPool.Clear();
            playerRolePreferences.Clear();
            assignedPlayersGlobal.Clear();
            team1.Clear();
            team2.Clear();
            aliasCounter = 0;
            signUpOrder.Clear();
            disallowClassChange.Clear();
            playerDamageStats.Clear();
            return true;
        }

        /// <summary>
        /// Called to reset the game state
        /// </summary>
        [Scripts.Event("Game.Reset")]
        public bool gameReset()
        {
            try { ReturnAllQueuedDrops("GAME RESET"); } catch (Exception ex) { Console.WriteLine("[flagdrop] game reset: " + ex.Message); }
            _roundHadAction = false;
            gameState = GameState.PostGame;
            arena.flagReset();
            // Deactivate sdFlag after reset — it should only activate during sudden death
            var sdFs2 = arena.getFlag("sdFlag");
            if (sdFs2 != null) { sdFs2.bActive = false; sdFs2.posX = 0; sdFs2.posY = 0; Helpers.Object_Flags(arena.Players, sdFs2); }
            ResetKiller(null);
            killStreaks.Clear();

            // Reset mix state and player pool
            mixGameActive = true;
            isMixActive = false;
            isSD = false;
            isSecondOvertime = false;
            overtimeStart = 0;
            secondOvertimeStart = 0;
            playerPool.Clear();
            playerRolePreferences.Clear();
            assignedPlayersGlobal.Clear();
            team1.Clear();
            team2.Clear();
            aliasCounter = 0;
            signUpOrder.Clear();
            redirectSide = null;
            redirectBase = null;
            is5v5 = false;
            baseUsed = "Unknown";
            minedStats.Clear();
            minedTsoByPlayer.Clear();
            minedToxByPlayer.Clear();
            _turretStats.Clear();
// Create a deep copy of player weapon stats to properly store last game data
            // _lastgamePlayerWeaponStats = new Dictionary<Player, Dictionary<int, WeaponStats>>();
            // foreach (var playerEntry in _playerWeaponStats)
            // {
            //     Dictionary<int, WeaponStats> weaponCopy = new Dictionary<int, WeaponStats>();
            //     foreach (var weaponEntry in playerEntry.Value)
            //     {
            //         // Create a new WeaponStats object with the same values
            //         WeaponStats statsCopy = new WeaponStats
            //         {
            //             ShotsFired = weaponEntry.Value.ShotsFired,
            //             ShotsLanded = weaponEntry.Value.ShotsLanded,
            //             AverageDistance = weaponEntry.Value.AverageDistance,
            //             TotalHits = weaponEntry.Value.TotalHits
            //         };
            //         weaponCopy[weaponEntry.Key] = statsCopy;
            //     }
            //     _lastgamePlayerWeaponStats[playerEntry.Key] = weaponCopy;
            // }
            // _playerWeaponStats.Clear();
            _ebHitStats.Clear();
            playerClassPlayTimes.Clear();
            playerLastClassSwitch.Clear();
            playerClassSwaps.Clear();
            winningTeamOVD = "defense";
            summonedCounts.Clear();
            summonsPerformed.Clear();
            pendingTsoTeam = null;
            disallowClassChange.Clear();
playerDamageStats.Clear();

            // Show breakdown for current game stats
            //arena.breakdown(true);

            if (isOVD)
            {
                arena.sendArenaMessage("& ----=[ Please type ?team spec or ?playing or ?p to ready up for the next game! ]=----", 30);

                // Spec all players and show their individual breakdowns
                foreach (Player p in arena.Players)
                {
                    p.spec("np");
                    //arena.individualBreakdown(p, true); // Show current game stats
                }
            }

            return true;
        }


