        /// <summary>
        /// Called when a player requests to pick up/drop the flag.
        /// </summary>
        /// <param name="from"></param>
        /// <param name="bPickup"></param>
        /// <param name="bSuccess"></param>
        /// <param name="flag"></param>
        /// <returns></returns>
        // Dictionary to track players and the flags they are carrying
        Dictionary<Player, LioInfo.Flag> playerFlagMap = new Dictionary<Player, LioInfo.Flag>();

        [Scripts.Event("Player.FlagAction")]
        public bool playerFlagAction(Player from, bool bPickup, bool bSuccess, LioInfo.Flag flag)
        {
            if (!bPickup && bSuccess && from != null && flag != null && !from.IsDead)
                _flagSetDownAt[flag.GeneralData.Id] = Environment.TickCount;   // *flagfix: set down by the carrier, not a return
            if (!bPickup && from != null && flag != null)
            {   // a carrier sets the flag down: move the minerals the engine would delete around it (flag zones)
                try { RescueMineralsAround(from._state.positionX, from._state.positionY, FlagPrizeRange + Math.Max(0, flag.FlagData.DropRadius), "flag dropped", from._team, true); }
                catch (Exception ex) { Console.WriteLine("[flagzone] flag drop: " + ex.Message); }
            }
            if (bPickup && bSuccess)
            {
                _roundHadAction = true;
                // Track the flag the player picked up
                if (!playerFlagMap.ContainsKey(from))
                {
                    playerFlagMap[from] = flag;  // Store the flag the player is carrying
                }

                ctfPlayerProxy.player = from;
                ctfPlayerProxy.Captures++;
                ctfPlayerProxy.player = null;
            }
            else if (!bPickup && bSuccess)
            {
                // If the player successfully drops the flag, remove it from the tracking map
                if (playerFlagMap.ContainsKey(from))
                {
                    playerFlagMap.Remove(from);
                }
            }

            return true;
        }

        public void EmulateSwitch(Player player, bool? isOpen = null)
        {
            // Find the associated switch
            LioInfo.Switch sw = player._server._assets.getLioByID(708) as LioInfo.Switch;

            if (sw == null)
            {
                player.sendMessage(0, "Switch not found.");
                return;
            }

            // Get the current switch state
            Arena.SwitchState ss;
            if (!player._arena._switches.TryGetValue(sw.GeneralData.Id, out ss))
            {
                player.sendMessage(0, "Switch state not found.");
                return;
            }

            // Determine the desired state
            bool currentState = ss.bOpen;
            bool desiredState = isOpen ?? !currentState; // If isOpen is null, toggle the state

            // Call the arena's handlePlayerSwitch method via an event
            player._arena.handleEvent(delegate (Arena arena)
            {
                player._arena.handlePlayerSwitch(player, desiredState, sw);
                // Send a message indicating the switch operation was successful
                player.sendMessage(0, string.Format("Switch operation successful. Switch is now {0}.", desiredState ? "open" : "closed"));
            });
        }

        // Arena boolean if ?energizer command is useable or not, starts disabled
        // ?energizer is OFF until it gets proper timing (Travis 2026-10-24): holding the shotgun's fire key while sending the macro
        // used the energizer on top of the shots. *togglegizer still turns it on until the next restart. The fix to queue: gate it by
        // the last weapon's fireDelay / fireDelayOther so it is never stronger than using the item by hand (?stim could share it).
        private bool _energizerCommandEnabled = false;

        // Display current lineups with team prefixes
        public void DisplayLineups(Player player)
        {
            try
            {
                player.sendMessage(0, "*Current Lineups:");
                
                // Get all unspecced players
                var unspeccedPlayers = arena.Players.Where(p => !p.IsSpectator).ToList();
                
                if (unspeccedPlayers.Count == 0)
                {
                    player.sendMessage(0, "No players are currently unspecced.");
                    return;
                }
                
                // Group players by team type
                var titanPlayers = new List<Player>();
                var collectivePlayers = new List<Player>();
                var otherPlayers = new List<Player>();
                
                foreach (var p in unspeccedPlayers)
                {
                    string teamName = p._team._name;
                    if (teamName.Contains(" T"))
                    {
                        titanPlayers.Add(p);
                    }
                    else if (teamName.Contains(" C"))
                    {
                        collectivePlayers.Add(p);
                    }
                    else
                    {
                        otherPlayers.Add(p);
                    }
                }
                
                // Display Titan players with ~ prefix
                if (titanPlayers.Count > 0)
                {
                    player.sendMessage(0, "Titan Team:");
                    foreach (var p in titanPlayers.OrderBy(p => p._alias))
                    {
                        string className = GetPrimarySkillName(p);
                        player.sendMessage(0, String.Format("~{0} - {1}", p._alias, className));
                    }
                }
                
                // Display Collective players with @ prefix
                if (collectivePlayers.Count > 0)
                {
                    player.sendMessage(0, "Collective Team:");
                    foreach (var p in collectivePlayers.OrderBy(p => p._alias))
                    {
                        string className = GetPrimarySkillName(p);
                        player.sendMessage(0, String.Format("@{0} - {1}", p._alias, className));
                    }
                }
                
                // Display other players without prefix
                if (otherPlayers.Count > 0)
                {
                    player.sendMessage(0, "Other Teams:");
                    foreach (var p in otherPlayers.OrderBy(p => p._alias))
                    {
                        string className = GetPrimarySkillName(p);
                        player.sendMessage(0, String.Format("{0} - {1}", p._alias, className));
                    }
                }
                
                player.sendMessage(0, String.Format("Total unspecced players: {0}", unspeccedPlayers.Count));
            }
            catch (Exception ex)
            {
                Console.WriteLine(String.Format("Error displaying lineups: {0}", ex.Message));
                player.sendMessage(-1, "Error displaying lineups.");
            }
        }

        /// <summary>
        /// Called when a player sends a chat command
        /// </summary>
        [Scripts.Event("Player.ChatCommand")]
        public bool playerChatCommand(Player player, Player recipient, string command, string payload)
        {
            // Mix commands run FIRST but consume only while a session is active, so every command
            // below behaves exactly as before when no mix is running.
            if (_mixManager != null && _mixManager.HandleChatCommand(player, command.ToLower(), payload))
                return true;

            switch (command.ToLower())
            {
                case "y":
                case "n":
                    // Answer to the captain's plan for a league match (CTFMatchAutomation.cs).
                    if (_matchAuto != null && _matchAuto.HandlePlanReply(player, command, payload))
                        return true;
                    break;

                case "side":
                    // Home captain picks the league match side in game (CTFMatchAutomation.cs).
                    if (_matchAuto != null && _matchAuto.HandleSideCommand(player, payload))
                        return true;
                    break;

                case "sub":
                    // Captain's in-game sub for a league match: ?sub in:out (CTFMatchAutomation.cs).
                    if (_matchAuto != null && _matchAuto.HandleSubCommand(player, payload))
                        return true;
                    break;

                case "cancel":
                    // Captain cancels their squad's queued league sub (CTFMatchAutomation.cs).
                    if (_matchAuto != null && _matchAuto.HandleCancelCommand(player))
                        return true;
                    break;

                case "debug":
                {
                    player.sendMessage(0, String.Format("=== DEBUG: {0} ===", player._alias));
                    player.sendMessage(0, String.Format("PlayerID: {0} | TeamID: {1} | Team: {2}",
                        player._id, player._team != null ? player._team._id : -1, player._team != null ? player._team._name : "null"));
                    player.sendMessage(0, String.Format("bIgnoreUpdates: {0} | bSpectator: {1} | IsSpectator: {2}",
                        player._bIgnoreUpdates, player._bSpectator, player.IsSpectator));
                    player.sendMessage(0, String.Format("BaseVeh ID: {0} | BaseVeh TypeID: {1}",
                        player._baseVehicle != null ? player._baseVehicle._id : -1,
                        player._baseVehicle != null ? player._baseVehicle._type.Id : -1));
                    player.sendMessage(0, String.Format("OccupiedVeh: {0} | ActiveVeh VehType: {1}",
                        player._occupiedVehicle != null ? player._occupiedVehicle._type.Id.ToString() : "null",
                        player.ActiveVehicle != null ? player.ActiveVehicle._type.Type.ToString() : "null"));
                    player.sendMessage(0, String.Format("Pos: ({0},{1}) | Vel: ({2},{3}) | Dir: {4} | Health: {5} | Energy: {6}",
                        player._state.positionX, player._state.positionY,
                        player._state.velocityX, player._state.velocityY,
                        (int)player._state.direction,
                        player._state.health, player._state.energy));
                    player.sendMessage(0, String.Format("bIngame: {0}",
                        player._bIngame));
                    // Dump all other ingame players
                    foreach (Player p in arena.PlayersIngame)
                    {
                        if (p == player) continue;
                        player.sendMessage(0, String.Format("-- {0}: pos=({1},{2}) vel=({3},{4}) dir={5} unk1={6}",
                            p._alias,
                            p._state.positionX, p._state.positionY,
                            p._state.velocityX, p._state.velocityY,
                            (int)p._state.direction,
                            p._state.unk1));
                    }
                    // Also dump ALL arena players (including spectators)
                    player.sendMessage(0, "--- All Players ---");
                    foreach (Player p in arena.Players)
                    {
                        player.sendMessage(0, String.Format("  {0}: bIngame={1} bSpec={2} bIgnore={3} team={4}",
                            p._alias, p._bIngame, p._bSpectator, p._bIgnoreUpdates,
                            p._team != null ? p._team._name : "null"));
                    }
                    break;
                }
                case "lineups":
                    DisplayLineups(player);
                    break;
                case "stim":
                    UseStimPack(player);
                    break;
                case "energizer":
                    if (!_energizerCommandEnabled){
                        player.sendMessage(0, "Energizer command is currently disabled.");
                        break;
                    }
                    UseEnergizer(player);
                    break;
                case "register":
                    InGameRegistration.HandleRegisterCommand(player, command, payload);
                    break;
                case "regstatus":
                    InGameRegistration.HandleCheckRegistrationCommand(player, command, payload);
                    break;
                case "playtime":
                    SendOrderedPlayTimes(player);
                    break;
                case "stats":
                    ListPlayerWeaponStats(player, payload);
                    break;
                case "itemusage":
                    ListPlayerItemUsedAverage(player, payload);
                    break;
                case "autooccupy":
                case "ao": // Alias for autooccupy (it used to skip the switch below and answer "now enabled" for nothing)
                    if (!AutoOccupyOn)
                    {
                        player.sendMessage(-1, "Auto-occupy is switched off for the whole zone by staff right now.");
                        break;
                    }
                    HandleAutoOccupyCommand(player, payload);
                    break;
                case "v": // this death: respawn on the class vehicle or on foot; alive: the vehicle now (Travis 10-24)
                    HandleVehicleNowCommand(player);
                    break;
                case "autooccupydeathboard":
                case "aodb": // Alias for autooccupy deathboard
                    // Toggle Jump Trooper vehicle preference (Deathboard vs Drop Pack)
                    {
                        string playerClass = GetPrimarySkillName(player);
                        if (playerClass != "Jump Trooper")
                        {
                            player.sendMessage(-1, "This command is only available for Jump Troopers.");
                            break;
                        }
                        
                        bool currentlyUsingDeathboard = jumpTrooperDeathboardPreference.ContainsKey(player._alias) && 
                                                       jumpTrooperDeathboardPreference[player._alias];
                        jumpTrooperDeathboardPreference[player._alias] = !currentlyUsingDeathboard;
                        
                        string vehicleType = jumpTrooperDeathboardPreference[player._alias] ? "Deathboard" : "Drop Pack";
                        player.sendMessage(0, String.Format("Jump Trooper AutoOccupy vehicle set to: {0}", vehicleType));
                    }
                    break;
                case "bot":
                case "botinfo":
                    if (CtfxBotsInfo != null && CtfxBotsHere) CtfxBotsInfo(player, payload);
                    else player.sendMessage(-1, "?bot works in the arena the bots run in.");
                    break;
                case "classtime":
                    {
                        // Verification aid for the per-class play-time tracking that feeds the site's
                        // MostPlayedClass. Shows the live accumulation so a class change made ANY way
                        // (?swap, F11, ?bw, a mod prize) can be confirmed to land on the right class,
                        // instead of the numbers only being checkable after the game on the website.
                        ReconcileClassPlayTime(player);   // fold in the open session first

                        Dictionary<string, int> times;
                        if (!playerClassPlayTimes.TryGetValue(player, out times) || times.Count == 0)
                        {
                            player.sendMessage(0, "No class play time recorded yet this game.");
                            break;
                        }

                        player.sendMessage(0, String.Format("Class play time (now playing: {0}):", CTFClass.ResolveName(player)));
                        foreach (KeyValuePair<string, int> entry in times.OrderByDescending(e => e.Value))
                            player.sendMessage(0, String.Format("  {0,-22} {1:F1}s", entry.Key, entry.Value / 1000.0));
                    }
                    break;
                case "playing":
                case "p": // Alias for playing
                    player.spec("spec");
                    player.sendMessage(0, "You are PLAYING - you'll be included in the next game. ?np to sit out.");
                    break;
                case "np":
                    {
                        // "np" (not playing) is a real cfg team - TeamInfo38 in ctfpl/ctfdl - and is
                        // what the end-of-game spec-all moves everyone to. This used to call the
                        // no-argument player.spec(), which redirects to spec("spec") and is therefore
                        // IDENTICAL to ?p: ?np never actually opted anyone out, which is why
                        // "?team np" was the only thing that worked.
                        if (arena.getTeamByName("np") != null)
                            player.spec("np");
                        else
                            player.spec(); // zone has no np team - plain spectate is the best we can do
                        player.sendMessage(0, "You are NOT PLAYING - you won't be picked. ?p to play again.");
                    }
                    break;
                case "pool":
                    DisplayCurrentPlayerPool(player);
                    break;
                case "teamJoin":
                case "t":
                    privateTeams(player, recipient, command, payload);
                    break;
                case "build":
                case "b": // Alias for build
                    if (RefusePrivateBuild(player, payload)) break;
                    // On the arena thread, never Task.Run: see LogBuildFault.
                    arena.handleEvent(a => LogBuildFault(HandleBuildCommand(player, payload), "build command"));
                    break;
                case "bsave":
                    HandleBuildSave(player, payload);
                    break;
                case "bdel":
                    HandleBuildDelete(player, payload);
                    break;
                case "wipe":
                case "w":  // Alias for wipe
                    WipeInventory(player, payload);
                    break;
                case "bw":
                    if (RefusePrivateBuild(player, payload)) break;
                    arena.handleEvent(a => LogBuildFault(WipeAndBuy(player, payload, false), "bw command"));
                    break;
                case "bwd":
                    if (RefusePrivateBuild(player, payload)) break;
                    arena.handleEvent(a => LogBuildFault(WipeBuyAndMaxAmmo(player, payload), "bwd command"));
                    break;
                case "d":
                    if (RefusePrivateBuild(player, payload)) break;
                    DropUnusedItems(player, payload);
                    break;
                case "dm":
                    HandleDropMacroCommand(player);   // ?bwd / ?d as two macro lines (Travis 10-26)
                    break;
                case "short":
                    commandHandler.HandleShortCommand(player, payload);
                    break;
                case "swap":
                    if (player.IsDead)
                    {
                        // Queue the class swap for when the player respawns
                        queuedClassSwap[player] = payload;
                        player.sendMessage(0, "You are dead. Your class change will be applied when you respawn.");
                    }
                    else
                    {
                        // Exit vehicle before swapping if player is in one and not spectating
                        if (!player.IsSpectator && player._occupiedVehicle != null)
                        {
                            string vehicleName = player._occupiedVehicle._type != null ? player._occupiedVehicle._type.Name : "vehicle";
                            player.sendMessage(0, String.Format("Exiting {0} to change class...", vehicleName));
                            ForcePlayerLeaveVehicle(player);
                        }
                        
                        commandHandler.HandleSwapCommand(player, payload, CFG, this, true, false);
                        
                        // Auto-occupy after a class swap (the Swap trigger)
                        InitiateAutoOccupy(player, "manual class swap");
                        
                        // If MiniTP event, warp player to the MiniTP start. Box 0 = that exact tile; the default box is health (1000 after a
                        // class change), which scattered ?swap up to 500 px in Arena 1 (TP batch 9).
                        if (currentEventType == EventType.MiniTP){
                            if (player._team._name.Contains("Titan")) {
                                WarpPlayerToRange(player, 654, 654, 518, 518, -1, 0);
                            }
                            else if (player._team._name.Contains("Collective")) {
                                WarpPlayerToRange(player, 648, 648, 565, 565, -1, 0);
                            }
                        }
                    }
                    break;
                case "champ":
                    HandleChampCommand(player, payload);   // saved, so it can be set where champion items are off too
                    break;
                case "phrase":
                    HandlePhraseCommand(player, payload);   // change your kill phrase in game (the perk's holders)
                    break;
                case "cosmetic":
                case "skin":
                case "skins":
                    Skins.HandleCommand(player, payload, isChampEnabled, skinsEnabled);   // one command for every item skin (CTFSkins.cs)
                    break;
                case "inv":
                    DisplayInventoryItems(player);
                    break;
                case "mg":
                    BuildTurret(player, "MG Turret");
                    break;
                case "rocket":
                    BuildTurret(player, "Rocket Turret");
                    break;
                case "plasma":
                    BuildTurret(player, "Plasma Turret");
                    break;
                case "duel":
                    // Check if this is a new dueling system command with parameters
                    if (!string.IsNullOrEmpty(payload))
                    {
                        // Handle new dueling system commands (challenge, accept, decline, etc.)
                        // Use fire-and-forget to avoid blocking the event handler
                        Task.Run(async () => {
                            try
                            {
                                await CTFGameType.DuelingSystem.HandleDuelCommand(player, command, payload);
                            }
                            catch (Exception ex)
                            {
                                Console.WriteLine(String.Format("Error handling duel command: {0}", ex.Message));
                            }
                        });
                    }
                    else
                    {
                        // Handle legacy duel command (just "?duel" with no parameters)
                        Duel(player);
                    }
                    break;
                case "mix":
                    if (isMixActive)
                    {
                        HandleRoleSelection(player, payload);
                    }
                    else
                    {
                        player.sendMessage(-1, "*Mix is not currently active.");
                    }
                    break;
                case "glad":
                    if (currentEventType == EventType.Gladiator)
                    {
                        JoinGladiatorEvent(player);
                    }
                    else
                    {
                        player.sendMessage(-1, "Gladiator event is not currently active.");
                    }
                    break;
                case "autobuy":
                case "ab":
                    {
                        // ?ab on / ?ab off set it, a bare ?ab toggles. A preset build switches autobuy on by itself, so a bare
                        // toggle after one turned it OFF without anyone noticing: the reply now says what a recall or
                        // respawn will rebuy, or that nothing is saved.
                        string abArg = (payload ?? "").Trim().ToLower();
                        bool was = autoBuyEnabled.ContainsKey(player._alias) && autoBuyEnabled[player._alias];
                        bool enabled = abArg == "on" || (abArg != "off" && !was);
                        autoBuyEnabled[player._alias] = enabled;
                        bool loadoutDropped;
                        string loadout = AutoBuyLoadout(player, out loadoutDropped);
                        if (!enabled)
                            player.sendMessage(0, "AutoBuy is now DISABLED. ?ab on turns it back on.");
                        else if (!String.IsNullOrEmpty(loadout))
                            player.sendMessage(0, "AutoBuy is now ENABLED: a dropship recall or respawn rebuys " + loadout + ". ?ab off turns it off.");
                        else if (premadeActiveSetup.ContainsKey(player._alias.ToLower()))
                            player.sendMessage(0, "AutoBuy is now ENABLED. You are on a premade kit, which restocks on its own; ?bw <build or items> to rebuy a build instead.");
                        else
                            player.sendMessage(0, "AutoBuy is now ENABLED, but nothing is saved to rebuy yet: ?bw <build or items> saves your loadout.");
                    }
                    break;

                case "autodrop":
                case "ad":
                    {
                        // Toggle the player's own choice, not the zone switch: flipping AutoDropEnabledFor
                        // while staff have it off would always answer ON.
                        bool now = !AutoDropPreference(player);
                        autoDropOverride[player._alias] = now;
                        player.sendMessage(0, now
                            ? "AutoDrop is now ON: warp from the dropship to a teammate near a flag your team holds (or to your squad leader) and a supply pile for the team appears where you land, once per life. It is extra: nothing is taken from you. ?ad again turns it off."
                            : "AutoDrop is now OFF for you. ?ad again turns it back on.");
                        LoadAutoDropState();
                        if (now && _autoDropOff)
                            player.sendMessage(0, "Note: staff have switched autodrop off for the whole zone right now; your choice applies once it is back on.");
