                    {
                        autoBuyEnabled[player._alias] = true;
                        autoDropOverride[player._alias] = true;
                        autoPickupOff.Remove(player._alias);
                        if (!autoPickupItems.ContainsKey(player._alias))
                        {
                            var derived = DeriveAutoPickupItemsFromBuild(player);
                            if (derived.Count > 0)
                                SetAutoPickupList(player, derived);
                        }
                        bool occupy = false;
                        if (AutoOccupyOn)
                        {
                            autoOccupyEnabled[player._alias] = true;
                            occupy = true;
                        }
                        player.sendMessage(0, String.Format("Auto: buy ON, drop ON, pickup {0}{1}. Toggle one at a time with ?ab ?ad ?ap{2}.",
                            autoPickupItems.ContainsKey(player._alias) ? "ON" : "needs a loadout (buy a premade, ?bw or ?b first)",
                            occupy ? ", occupy ON" : "", occupy ? " ?ao" : ""));
