            if (command.Equals("mix", StringComparison.OrdinalIgnoreCase))
            {
                if (player.PermissionLevelLocal < Data.PlayerPermission.ArenaMod)
                    return false;

                // Routed to CTFMixes.cs. The previous handler here started the role-preference
                // auto-assign (StartMixProcess / AssignPlayersBasedOnSkills), which had no captains,
                // no draft, a hardcoded 20-player gate and hardcoded "CKY C"/"PT T" team names.
                if (_mixManager != null)
                    return _mixManager.HandleModCommand(player, payload);

