            if (command.Equals("setup"))
            {
                if (player.PermissionLevelLocal < Data.PlayerPermission.ArenaMod)
                    return false;

                SetupBase(payload, player);
                return true;
            }

            if (command.Equals("armory"))
            {
                if (player.PermissionLevelLocal < Data.PlayerPermission.ArenaMod)
                    return false;

                string[] ap = (payload ?? "").Trim().Split(new char[] { ' ' }, StringSplitOptions.RemoveEmptyEntries);
                string sub = ap.Length > 0 ? ap[0].ToLower() : "";
                ReloadArmoryIfChanged();
                int tx = player._state.positionX / 16, ty = player._state.positionY / 16;
                if (sub == "reload")
                {
                    ReloadArmoryIfChanged(true);
                    player.sendMessage(0, String.Format("ArmoryTiles.txt reloaded: {0} cell(s).", _armoryCells.Count));
                    return true;
                }
                if (sub == "list")
                {
                    player.sendMessage(0, String.Format("{0} armory cell(s):", _armoryCells.Count));
                    foreach (ArmoryCell c in _armoryCells)
                        player.sendMessage(0, String.Format("~ {0},{1}-{2},{3}  {4} {5}", c.X1, c.Y1, c.X2, c.Y2, c.Kind, c.Arg));
                    return true;
                }
                if (sub == "set")
                {
                    // *armory set build dinfcaw [w h]
                    if (ap.Length < 3 || (ap[1].ToLower() != "build" && ap[1].ToLower() != "class" && ap[1].ToLower() != "base"))
                    {
                        player.sendMessage(-1, "Usage: *armory set <build|class|base> <name> [w h]  - writes the cell at the tile you stand on (default 2x2).");
                        return true;
                    }
                    int w = 2, h = 2;
                    if (ap.Length >= 5) { int.TryParse(ap[3], out w); int.TryParse(ap[4], out h); }
                    if (w < 1) w = 1; if (h < 1) h = 1;
                    ArmoryWriteCell(player, ap[1].ToLower(), ap[2], w, h);
                    return true;
                }
                if (sub == "clear")
                {
                    // *armory clear <build|class|base> <name>
                    if (ap.Length < 3) { player.sendMessage(-1, "Usage: *armory clear <build|class|base> <name>"); return true; }
                    if (System.IO.File.Exists(ARMORY_TILES_PATH))
                    {
                        var lines = System.IO.File.ReadAllLines(ARMORY_TILES_PATH).Where(l => !ArmoryLineIs(l, ap[1], ap[2])).ToArray();
                        System.IO.File.WriteAllLines(ARMORY_TILES_PATH, lines);
                        ReloadArmoryIfChanged(true);
                    }
                    player.sendMessage(0, String.Format("Armory: removed {0} {1}. {2} cell(s) remain.", ap[1], ap[2], _armoryCells.Count));
                    return true;
                }
                // default: where am I
                ArmoryCell here = ArmoryCellAt(tx, ty);
                player.sendMessage(0, String.Format("You are on tile {0},{1}. {2}. {3} cell(s) loaded; *armory list / set / clear / reload.",
                    tx, ty, here == null ? "Not on an armory cell" : "Cell: " + here.Kind + " " + here.Arg, _armoryCells.Count));
                return true;
            }

            if (command.Equals("tips"))
            {
                if (player.PermissionLevelLocal < Data.PlayerPermission.ArenaMod)
                    return false;

                string arg = (payload ?? "").Trim().ToLower();
                ReloadArenaTipsIfChanged();
                if (arg == "reload")
                {
                    _arenaTipsMtime = DateTime.MinValue;   // force
                    ReloadArenaTipsIfChanged();
                    player.sendMessage(0, String.Format("ArenaTips.txt reloaded: {0} tip(s).", _arenaTips.Count));
                    return true;
                }
                if (arg == "status" || arg == "list")
                {
                    player.sendMessage(0, String.Format("{0} tip(s) loaded, next is #{1}; one goes out per hour to {2}+ players, never during a draft.",
                        _arenaTips.Count, _arenaTips.Count == 0 ? 0 : _arenaTipIndex + 1, TIPS_MIN_PLAYERS));
                    for (int i = 0; i < _arenaTips.Count; i++)
                        player.sendMessage(0, String.Format("~ {0}. {1}", i + 1, _arenaTips[i]));
                    return true;
                }
                // default: send the next one now
                string sent = SendNextArenaTip();
                player.sendMessage(0, sent == null ? "No tips loaded - ArenaTips.txt is missing or empty." : "Sent.");
                return true;
            }
// Trigger command overtime or ot with optional minutes parameter
            if (command.Equals("overtime") || command.Equals("ot"))
            {
                if (player.PermissionLevelLocal < Data.PlayerPermission.ArenaMod){
                    player.sendMessage(-1, "permissions lacking, cannot trigger overtime.");
                    return false;
                }

                if (!string.IsNullOrEmpty(payload))
                {
                    int minutes;
                    if (int.TryParse(payload, out minutes))
                    {
                        ScheduleOvertime(minutes);
                        player.sendMessage(0, "Overtime scheduled to start at " + minutes + " minutes.");
                    }
                    else
                    {
                        player.sendMessage(-1, "Invalid minutes parameter. Please enter a valid number.");
                        return false;
                    }
                }
                else
                {
                    ToggleOvertimeMode();
                }
                return true;
            }

            if (command.Equals("sd"))
            {
                if (player.PermissionLevelLocal < Data.PlayerPermission.ArenaMod)
                    return false;
                
                arena.flagReset();
                //SpawnMapFlag();
                //Arena.FlagState flag = arena.getFlag("Hill201");
                // Get the "sdFlag" and activate it
                Arena.FlagState flag = arena.getFlag("sdFlag");

                if (flag == null)
                {
                    player.sendMessage(-1, "Sudden death flag not found.");
                    return false;
                }

                // Set the flag to active
                flag.bActive = true;

                Random random = new Random();
                int sdrr = random.Next(5); // Generates a random number between 0 and 4 (inclusive)
                switch (sdrr)
                {
                    case 0:
                        flag.posX = (short)(202 * 16);
                        flag.posY = (short)(120 * 16);
                        break;
                    case 1:
                        flag.posX = (short)(202 * 16);
                        flag.posY = (short)(202 * 16);
                        break;
                    case 2:
                        flag.posX = (short)(202 * 16);
                        flag.posY = (short)(286 * 16);
                        break;
                    case 3:
