        private void HealAll()
        {
            foreach (Player p in arena.PlayersIngame)
            {
                p.inventoryModify(104, 1);
            }
            
            if (!quietGameStart)
                arena.sendArenaMessage("&All players have been healed");
        }

        #region Warp exits
        // Travis 10-24: "when they warp to someone, and they're on our screen, the client predicts their movement and they walk forward
        // and look like they're lagging out before they disappear". Player.warp moves a player on the SERVER at once (it sets _state
        // before the client answers), so when their first update from the new spot arrives, the engine's "warped? tell the old audience
        // too" check (Helpers.getRouteList: old vs new position > routeRange) compares the new position with itself and never fires.
        // Whoever could see them where they were gets no further update, and their client keeps walking them along their last velocity
        // until it gives up. 20 times a second, a player whose server position jumped since the last look is sent once, at the new
        // spot, to everyone near the old spot who is out of routing range of the new one (the engine's own updates reach the rest): the
        // player leaves their screen on the spot. Warps the client makes itself (warp fields) already worked: the engine sees the jump.
        private readonly Dictionary<Player, long> _warpWatch = new Dictionary<Player, long>();
        private int _warpWatchDue;
        private const int WARP_WATCH_MS = 50, WARP_JUMP = 400;   // px between two looks 50 ms apart: only a warp moves that far
        internal long WarpExitSends;

        private void PollWarpExits(int now)
        {
            if (now - _warpWatchDue < 0)
                return;
            _warpWatchDue = now + WARP_WATCH_MS;
            List<Player> ingame = arena.PlayersIngame.ToList();
            if (_warpWatch.Count > ingame.Count * 2 + 16)
                _warpWatch.Clear();   // players who left
            foreach (Player p in ingame)
            {
                if (p == null || p._state == null || p.IsSpectator)
                    continue;
                long key = ((long)(ushort)p._state.positionX << 16) | (ushort)p._state.positionY, old;
                bool seen = _warpWatch.TryGetValue(p, out old);
                _warpWatch[p] = key;
                if (!seen || old == key)
                    continue;
                int ox = (int)(old >> 16), oy = (int)(old & 0xFFFF), dx = p._state.positionX - ox, dy = p._state.positionY - oy;
                if (dx * dx + dy * dy >= WARP_JUMP * WARP_JUMP)
                    SendWarpExit(p, ox, oy);
            }
        }

        private void SendWarpExit(Player p, int ox, int oy)
        {
            Vehicle v = p.ActiveVehicle;
            if (v == null || v._state == null)
                return;
            // the packet carries the vehicle's state: a ride that did not move with them would only re-announce the old spot
            long rx = v._state.positionX - p._state.positionX, ry = v._state.positionY - p._state.positionY;
            if (rx * rx + ry * ry >= (long)WARP_JUMP * WARP_JUMP)
                return;
            // standing still at the new spot, as the client is after the warp (and as the engine's own notice says), so the dot on a
            // far viewer's radar does not drift on the pre-warp velocity
            p._state.velocityX = p._state.velocityY = p._state.velocityZ = 0;
            v._state.velocityX = v._state.velocityY = v._state.velocityZ = 0;
            long near = (long)Arena.routeRange * Arena.routeRange;
            int tick = Environment.TickCount;
            SC_PlayerUpdate up = null;
            SC_PlayerTeamUpdate tu = null;
            foreach (Player viewer in arena.getPlayersAndSpecInRange((short)ox, (short)oy, Arena.routeRadarRangeFar))
            {
                if (viewer == p || viewer._client == null || viewer._state == null)
                    continue;
                long vx = viewer._state.positionX - p._state.positionX, vy = viewer._state.positionY - p._state.positionY;
                if (vx * vx + vy * vy <= near)
                    continue;   // in routing range of the new spot: their next real update reaches this viewer anyway
                if (viewer.IsSpectator || viewer._team == p._team)
                {
                    if (tu == null)
                        tu = new SC_PlayerTeamUpdate { tickUpdate = tick, player = p, vehicle = v, itemID = 0, activeUtilities = p.activeUtilities };
                    viewer._client.send(tu);
                }
                else
                {
                    if (up == null)
                        up = new SC_PlayerUpdate { tickUpdate = tick, player = p, vehicle = v, itemID = 0, activeUtilities = p.activeUtilities };
                    viewer._client.send(up);
                }
                WarpExitSends++;
            }
        }
        #endregion

        #region AutoOccupy System - Full Implementation (Memory Leak Fixed)
        
        /// <summary>
        /// Schedules auto-occupy for a player (ProcessPendingAutoOccupy runs it after the delay, once they are alive) when
        /// they have ?ao on for this trigger and their class has a vehicle. when = None forces it (*startoccupy).
        /// </summary>
        private bool InitiateAutoOccupy(Player player, string reason, OccupyWhen when = OccupyWhen.Swap, int delay = 3500, bool chosen = false)
        {
            if (!AutoOccupyOn)
                return false;

            try
            {
                // Check if player has autooccupy enabled for this trigger (chosen = they asked for this one: ?v)
                if (when != OccupyWhen.None && !chosen && !AutoOccupyFor(player, when))
                    return false;

                // Skip if player is spectator
                if (player.IsSpectator || player._team.IsSpec)
                    return false;

                // Every class may turn ?ao on; it only does something for a class with a vehicle
                string playerClass = GetPrimarySkillName(player);
                int vehicleTypeToCreate = GetVehicleTypeForClass(player, playerClass);
                if (vehicleTypeToCreate == -1)
                    return false;

                // Schedule the auto-occupy operation (every trigger but game start needs the pack item when it fires). The vehicle
                // appears after the pack's prefire at the earliest, like pressing its key; the prefire effect starts that long before
                // Game start is the exception (Travis 10-25): the pack can be made during the countdown, so it is ready the moment the
                // game starts - no prefire wait, just the short delay that lets the spawn warps land first
                bool gameStart = reason == "game start";
                int prefireMs = gameStart ? 0 : OccupyPrefireMs(player);
                int dueIn = Math.Max(delay, prefireMs), nowTick = Environment.TickCount;
                pendingAutoOccupy[player._alias] = nowTick + dueIn;
                occupyFxAt[player._alias] = gameStart ? nowTick : nowTick + dueIn - prefireMs;
                autoOccupyRetryCount.Remove(player._alias);
                pendingOccupyWhen[player._alias] = when;
                if (when == OccupyWhen.Start || when == OccupyWhen.None)
                    pendingOccupyNeedsPack.Remove(player._alias);
                else
                    pendingOccupyNeedsPack.Add(player._alias);

                // Notify player that auto-occupy is in progress
                player.sendMessage(0, "Auto-Occupy initiated - creating vehicle...");

                return true;
            }
            catch (Exception ex)
            {
                Console.WriteLine(String.Format("Error in InitiateAutoOccupy for {0}: {1}", player._alias, ex.Message));
                return false;
            }
        }

        /// <summary>Auto-occupy covers this trigger for the player (OccupyTriggers).</summary>
        private bool AutoOccupyFor(Player player, OccupyWhen when)
        {
            return (OccupyTriggers(player) & when) != 0;
        }

        /// <summary>
        /// When auto-occupy fires for the player. Their ?ao choice wins (?ao off = never; ?ao on = OccupyBase; ?ao death start ... =
        /// those). Without one it follows the build: a Jump Trooper carrying a Drop Pack / Deathboard = every trigger (an overweight
        /// pack JT lives on it; a foot JT = none), Infantry / Squad Leader on a standard build (a premade or a named ?bw build:
        /// OnDefaultLoadout) = game start, everyone else (Medic, Engineer, custom ?bw item lists) = nothing until they opt in.
        /// </summary>
        private OccupyWhen OccupyTriggers(Player player)
        {
            bool chosen;
            if (autoOccupyEnabled.TryGetValue(player._alias, out chosen))
            {
                OccupyWhen picked;
                return !chosen ? OccupyWhen.None : autoOccupyWhen.TryGetValue(player._alias, out picked) ? picked : OccupyBase(player);
            }
            string cls = GetPrimarySkillName(player);
            if (cls == "Jump Trooper")
                return HasPackItem(player, cls) ? OccupyWhen.All : OccupyWhen.None;
            if ((cls == "Squad Leader" || cls.Contains("Infantry") || cls == "Field Medic" || cls == "Combat Engineer") && OnDefaultLoadout(player))
                return OccupyWhen.Start;   // Travis 10-26: medics and engineers get their hoverboard at game start too
            return OccupyWhen.None;
        }

        /// <summary>What "?ao on" means: every trigger for a Jump Trooper with a pack, game start for everyone else.</summary>
        private OccupyWhen OccupyBase(Player player)
        {
            string cls = GetPrimarySkillName(player);
            return cls == "Jump Trooper" && HasPackItem(player, cls) ? OccupyWhen.All : OccupyWhen.Start;
        }

        // The VehicleMaker items behind each class's vehicle (ctfpl.itm; none of them is used up when it makes the vehicle)
        private static readonly int[] JT_PACK_ITEMS = { 30, 31, 315 };   // Drop Pack, Deathboard, ChUcKdaPaCK
        private static readonly int[] FLIGHT_PACK_ITEMS = { 13, 270 };  // Flight Pack, FPack (one-time)
        private static readonly int[] HOVERBOARD_ITEMS = { 1, 271 };    // Hoverboard, HBoard

        // One-time packs use themselves up when fired (ctfpl.itm: their ammo is the item itself). Travis 10-26: auto-occupy spends one the same
        // way when it is the only pack the player carries, so one cheap FPack is one ride, not a free pack every death.
        private static readonly int[] ONE_TIME_PACK_ITEMS = { 270, 271 };   // FPack, HBoard

        private static int[] PackItemsFor(string playerClass)
        {
            return playerClass == "Jump Trooper" ? JT_PACK_ITEMS
                : (playerClass == "Combat Engineer" || playerClass == "Field Medic") ? HOVERBOARD_ITEMS
                : (playerClass == "Squad Leader" || playerClass.Contains("Infantry")) ? FLIGHT_PACK_ITEMS : null;
        }

        private bool HasPackItem(Player player, string playerClass)
        {
            int[] items = PackItemsFor(playerClass);
            return items != null && items.Any(i => player.getInventoryAmount(i) > 0);
        }

        /// <summary>After a trigger that needed the pack: a one-time pack is spent when no reusable pack is carried.</summary>
        private void SpendOneTimePack(Player player, string playerClass)
        {
            int[] items = PackItemsFor(playerClass);
            if (items == null || items.Any(i => Array.IndexOf(ONE_TIME_PACK_ITEMS, i) < 0 && player.getInventoryAmount(i) > 0))
                return;   // a reusable pack: nothing spent
            int one = items.FirstOrDefault(i => Array.IndexOf(ONE_TIME_PACK_ITEMS, i) >= 0 && player.getInventoryAmount(i) > 0);
            ItemInfo pack = one != 0 ? AssetManager.Manager.getItemByID(one) : null;
            if (pack != null && player.inventoryModify(pack, -1))
                player.sendMessage(0, String.Format("Auto-Occupy used one {0} ({1} left).", pack.name, player.getInventoryAmount(one)));
        }

        /// <summary>The pack a ?v respawn buys when they carry none: the one-time FPack / HBoard; a Jump Trooper's Drop Pack, or Deathboard with
        /// ?aodb (no one-time JT pack exists).</summary>
        private int OccupyPackToBuy(Player player, string playerClass)
        {
            if (playerClass == "Jump Trooper")
            {
                bool pref;
                return jumpTrooperDeathboardPreference.TryGetValue(player._alias, out pref) && pref ? 31 : 30;
            }
            if (playerClass == "Combat Engineer" || playerClass == "Field Medic")
                return 271;
            if (playerClass == "Squad Leader" || playerClass.Contains("Infantry"))
                return 270;
            return 0;
        }

        private string OccupyPackToBuyName(Player player, string playerClass)
        {
            ItemInfo item = AssetManager.Manager.getItemByID(OccupyPackToBuy(player, playerClass));
            return item != null ? item.name : "pack";
        }

        /// <summary>?v: gives them the pack as ?b would (TP's store items cost nothing), after the class's skill check. False = not given.</summary>
        private bool BuyOccupyPack(Player player)
        {
            ItemInfo item = AssetManager.Manager.getItemByID(OccupyPackToBuy(player, GetPrimarySkillName(player)));
            if (item == null || !Logic_Assets.SkillCheck(player, item.skillLogic) || (HardEconomy.On && HardEconomy.Grant(player, item, 1) < 1) || !player.inventoryModify(item, 1))
                return false;
            player.sendMessage(0, String.Format("Auto-Occupy bought you a {0}.", item.name));
            return true;
        }

        /// <summary>?v's game-start ride: 1 s after the start, no prefire, like ?ao's. No pack on them = one is bought when it is made and a one-time
        /// pack is used up by the ride (Travis 10-29: buy it, not the "you carry none" warning); a pack they already carry is kept, as with ?ao.</summary>
        private bool OccupyAtGameStart(Player player)
        {
            bool had = HasPackItem(player, GetPrimarySkillName(player));
            DropPendingOccupy(player._alias);
            if (!InitiateAutoOccupy(player, "game start", OccupyWhen.Start, 1000, true))
                return false;
            if (!had)
            {
                pendingOccupyBuys.Add(player._alias);
                pendingOccupyNeedsPack.Add(player._alias);
            }
            return true;
        }

        private string OccupyVehicleName(Player player)
        {
            int vehicleId = GetVehicleTypeForClass(player, GetPrimarySkillName(player));
            VehInfo vehicle = vehicleId == -1 ? null : AssetManager.Manager.getVehicleByID(vehicleId);
            return vehicle != null ? vehicle.Name : null;
        }

        /// <summary>
        /// At death: whether this respawn puts them on their vehicle (their default, Death trigger and the pack item), told in one
        /// line so ?v can flip it while the death timer runs. Players whose default is off but who carry the pack get a short
        /// reminder now and then.
        /// </summary>
        private void NoteOccupyAtDeath(Player player)
        {
            if (!AutoOccupyOn || player == null || player.IsSpectator)
                return;
            string cls = GetPrimarySkillName(player), vehicle = OccupyVehicleName(player);
            occupyThisLife.Remove(player._alias);
            occupyBuyAtRespawn.Remove(player._alias);
            if (occupyArmed.Remove(player._alias) && vehicle != null)
            {   // ?v sent while alive: this respawn puts them on it, buying the pack if they carry none
                occupyThisLife[player._alias] = true;
                occupyBuyAtRespawn.Add(player._alias);
                player.sendMessage(0, String.Format("Auto-Occupy: respawning on your {0} (your ?v){1} - ?v to stay on foot.", vehicle,
                    HasPackItem(player, cls) ? "" : ", a " + OccupyPackToBuyName(player, cls) + " is bought for you"));
                return;
            }
            if (vehicle == null || !HasPackItem(player, cls))
                return;
            bool on = AutoOccupyFor(player, OccupyWhen.Death);
            occupyThisLife[player._alias] = on;
            if (on)
                player.sendMessage(0, String.Format("Auto-Occupy: respawning on your {0} - ?v to stay on foot.", vehicle));
            else
            {
                int last;
                if (!occupyHintAt.TryGetValue(player._alias, out last) || Environment.TickCount - last > OCCUPY_HINT_EVERY)
                {
                    occupyHintAt[player._alias] = Environment.TickCount;
                    player.sendMessage(0, String.Format("Auto-Occupy: ?v while dead respawns you on your {0}.", vehicle));
                }
            }
        }

        /// <summary>
        /// ?v: while dead, flips whether this respawn puts them on their vehicle; alive and on foot, the vehicle now (with the pack
        /// item, like pressing its key).
        /// </summary>
        private void HandleVehicleNowCommand(Player player)
        {
            if (!AutoOccupyOn)
            {
                player.sendMessage(-1, "Auto-occupy is switched off for the whole zone by staff right now.");
                return;
            }
            if (player.IsSpectator || player._team.IsSpec)
            {
                player.sendMessage(-1, "?v works once you are in the game.");
                return;
            }
            string cls = GetPrimarySkillName(player), vehicle = OccupyVehicleName(player);
            if (vehicle == null)
            {
                player.sendMessage(-1, "Your class has no auto-occupy vehicle (Eng/Med hoverboard, JT drop pack or deathboard, Inf/SL flight pack).");
                return;
            }
            if (player.IsDead)
            {
                bool on;
                if (!occupyThisLife.TryGetValue(player._alias, out on))
                    on = AutoOccupyFor(player, OccupyWhen.Death);
                occupyThisLife[player._alias] = !on;
                if (!on)
                    occupyBuyAtRespawn.Add(player._alias);      // asked for by ?v: no pack on them = one is bought at the respawn (Travis 10-29)
                else
                    occupyBuyAtRespawn.Remove(player._alias);
                player.sendMessage(0, !on
                    ? String.Format("Auto-Occupy: you will respawn on your {0} (?v again to stay on foot).{1}", vehicle,
                        HasPackItem(player, cls) ? "" : " You carry none: a " + OccupyPackToBuyName(player, cls) + " is bought for you at the respawn.")
                    : String.Format("Auto-Occupy: you will respawn on foot (?v again for your {0}).", vehicle));
                return;
            }
            if (player._occupiedVehicle != null)
            {
                player.sendMessage(-1, "You are already in a vehicle.");
                return;
            }
            // Travis 10-29: a game start coming = armed for the start or the next respawn, whichever comes first. Any start counts: the first seconds
            // of a game (a *restart or *startgame has no countdown) are the start's ride. A missing pack is bought; mid-game only on the dropship, as ?b.
            bool startComing = gameState == GameState.PreGame || gameState == GameState.PostGame || gameState == GameState.Transitioning;
            bool justStarted = gameState == GameState.ActiveGame && unchecked(Environment.TickCount - _gameStartedAt) < OCCUPY_START_WINDOW_MS;
            bool hasPack = HasPackItem(player, cls), wasArmed = occupyArmed.Remove(player._alias);
            if (justStarted)
            {
                OccupyAtGameStart(player);
                return;
            }
            bool buyHere = !hasPack && OnStoreTerrain(player);
            if ((hasPack || buyHere) && !startComing)
            {   // on it now (uses up an armed ?v too); on the dropship a missing pack is bought first
                DropPendingOccupy(player._alias);
                if (InitiateAutoOccupy(player, "?v", OccupyWhen.Swap, 0, true) && buyHere)   // the pack's prefire, then the vehicle: never faster than by hand
                    pendingOccupyBuys.Add(player._alias);
                return;
            }
            if (wasArmed)
            {
                player.sendMessage(0, String.Format("Auto-Occupy: cancelled - no {0} at your next respawn or game start.", vehicle));
                return;
            }
            occupyArmed.Add(player._alias);
            if (startComing)
                player.sendMessage(0, String.Format("Auto-Occupy: on your {0} 1 s after the game starts{1}, or at your next respawn. ?v again cancels.", vehicle,
                    hasPack ? "" : " (a " + OccupyPackToBuyName(player, cls) + " is bought for you)"));
            else
                player.sendMessage(0, String.Format("Auto-Occupy: you carry no {0} - your next respawn or game start buys a {1} and puts you on it (or ?v on the dropship). ?v again cancels.",
                    vehicle, OccupyPackToBuyName(player, cls)));
        }

        private void DropPendingOccupy(string alias)
        {
            occupyFxAt.Remove(alias);
            pendingAutoOccupy.Remove(alias);
            autoOccupyRetryCount.Remove(alias);
            pendingOccupyWhen.Remove(alias);
            pendingOccupyNeedsPack.Remove(alias);
            pendingOccupyBuys.Remove(alias);
        }

        /// <summary>
        /// A warp item used by the player (attach, teleport, recall), or a summon by a teammate, drops their queued occupy, so
        /// auto-occupy never lands on top of a warp (Travis 10-24: an SL warping on respawn, a pack JT attaching to a teammate).
        /// </summary>
        private void DropPendingOccupyForWarp(Player user, ItemInfo.WarpItem item, Player target)
        {
            if (pendingAutoOccupy.Count == 0 || user == null || item == null)
                return;
            DropPendingOccupy(user._alias);
            if (item.warpMode != ItemInfo.WarpItem.WarpMode.SummonTeam && item.warpMode != ItemInfo.WarpItem.WarpMode.SummonAnyone)
                return;
            if (target != null)
                DropPendingOccupy(target._alias);
            foreach (string alias in pendingAutoOccupy.Keys.ToList())
            {
                Player p = arena.Players.FirstOrDefault(x => x._alias == alias);
                if (p != null && p._team == user._team)
                    DropPendingOccupy(alias);
            }
        }

        /// <summary>The prefire of the pack or board the player would use (ms): the item they carry, else their class's first one.</summary>
        private int OccupyPrefireMs(Player player)
        {
            string cls = GetPrimarySkillName(player);
            int[] items = cls == "Jump Trooper" ? JT_PACK_ITEMS
                : (cls == "Combat Engineer" || cls == "Field Medic") ? HOVERBOARD_ITEMS
                : (cls == "Squad Leader" || cls.Contains("Infantry")) ? FLIGHT_PACK_ITEMS : null;
            if (items == null)
                return OCCUPY_PREFIRE_FALLBACK_MS;
            int held = items.FirstOrDefault(i => player.getInventoryAmount(i) > 0);
            ItemInfo.VehicleMaker maker = AssetManager.Manager.getItemByID(held != 0 ? held : items[0]) as ItemInfo.VehicleMaker;
            return maker != null && maker.prefireDelay > 0 ? maker.prefireDelay * 10 : OCCUPY_PREFIRE_FALLBACK_MS;
        }

        /// <summary>
        /// Handles auto-occupy on player respawn
        /// </summary>
        private void HandleAutoOccupyOnRespawn(Player player)
        {
            if (!AutoOccupyOn)
                return;

            // this death's choice (NoteOccupyAtDeath, flipped by ?v); a death the script never saw falls back to their default
            bool on, buy = occupyBuyAtRespawn.Remove(player._alias);
            if (occupyArmed.Remove(player._alias))
                on = buy = true;   // armed alive by ?v, and the script never saw the death
            else if (!occupyThisLife.TryGetValue(player._alias, out on))
                on = AutoOccupyFor(player, OccupyWhen.Death);
            occupyThisLife.Remove(player._alias);
            if (on && InitiateAutoOccupy(player, "respawn", OccupyWhen.Death, OCCUPY_RESPAWN_DELAY, true) && buy)
                pendingOccupyBuys.Add(player._alias);   // ?v: the pack is bought when the vehicle is made, if they still carry none (an autobuy wipe in between)
        }
        
        /// <summary>
        /// Gets the vehicle type that should be created for a player's class
        /// </summary>
        private int GetVehicleTypeForClass(Player player, string playerClass)
        {
            if (playerClass == "Combat Engineer" || playerClass == "Field Medic")
            {
                return 105; // Hoverboard ID
            }
            else if (playerClass == "Jump Trooper")
            {
                // Special case for Chuckie - use different vehicle ID (his ChUcKdaPaCk, a Season 1 champion item: a plain Drop Pack where they are off)
                if (player._alias == "Chuckie" && isChampEnabled && Skins.IsOn(player._alias, "Drop Pack", isChampEnabled, skinsEnabled))
                {
                    return 153; // Special vehicle for Chuckie
                }
                else
                {
                    // ?aodb choice, else the pack they carry (a Deathboard and no Drop Pack = the Deathboard)
                    bool pref;
                    bool useDeathboard = jumpTrooperDeathboardPreference.TryGetValue(player._alias, out pref) ? pref
                        : player.getInventoryAmount(31) > 0 && player.getInventoryAmount(30) <= 0;
                    if (useDeathboard)
                    {
                        return 108; // Deathboard ID
                    }
                    else
                    {
                        return 109; // Drop Pack ID
                    }
                }
            }
            else if (playerClass == "Infantry" || playerClass.Contains("Infantry") || playerClass == "Squad Leader")
            {
                return 106; // Flight Pack ID  
            }
            
            return -1; // Unknown class
        }
        
        /// <summary>
        /// Plays the vehicle creation sound using custom vehicleMakerEffect projectile
        /// </summary>
        private void PlayVehicleCreationSound(Player player, int vehicleTypeId)
        {
            try
            {
                // Use the custom vehicleMakerEffect projectile (ID 1378) that simulates vehicle creation
                const int VEHICLE_MAKER_EFFECT_ID = 1378;
                
                // Get the projectile info
                ItemInfo.Projectile projectileInfo = AssetManager.Manager.getItemByID(VEHICLE_MAKER_EFFECT_ID) as ItemInfo.Projectile;
                if (projectileInfo != null)
                {
                    // Trigger the vehicle maker effect sound using RouteItemUsed
                    Helpers.Player_RouteItemUsed(player, player, player._id, (short)VEHICLE_MAKER_EFFECT_ID, 
                        player._state.positionX, player._state.positionY, (byte)player._state.yaw);
                    
                    // Trigger the explosion effect for the projectile (players near it: every auto-occupy, not the whole arena)
                    Helpers.Player_RouteExplosion(arena.getPlayersAndSpecInRange(player._state.positionX, player._state.positionY, LOCAL_FX_RANGE), (short)VEHICLE_MAKER_EFFECT_ID, 
                        player._state.positionX, player._state.positionY, player._state.positionZ, 
                        (byte)player._state.yaw, (ushort)player._id);
                }
            }
            catch (Exception ex)
            {
                // Silently handle errors
            }
        }
        
        /// <summary>
        /// Puts the player on a NEW vehicle of their class's type, made where they stand. It used to grab any empty vehicle
        /// of that type anywhere on the map - an enemy's dismounted board included - and pull it to them, and a second
        /// version queued a Vehicle reference across ticks (the stale-vehicle risk); both are gone.
        /// </summary>
        private void HandleAutoOccupyImmediate(Player player)
        {
            if (!AutoOccupyOn)
                return;

            try
            {
                // Alive, here, and on foot (already in a vehicle or turret = leave them be)
                if (player == null || player._arena != arena || player.IsSpectator || player.IsDead || player._occupiedVehicle != null)
                    return;

                int targetVehicleTypeId = GetVehicleTypeForClass(player, GetPrimarySkillName(player));
                if (targetVehicleTypeId == -1)
                    return;   // Class doesn't have an auto-occupy vehicle

                VehInfo vehicleInfo = AssetManager.Manager.getVehicleByID(targetVehicleTypeId);
                if (vehicleInfo == null)
                {
                    player.sendMessage(-1, String.Format("Auto-Occupy: vehicle type {0} not found.", targetVehicleTypeId));
                    return;
                }

                Helpers.ObjectState objState = new Helpers.ObjectState
                {
                    positionX = player._state.positionX,
                    positionY = player._state.positionY,
                    positionZ = 0,
                    yaw = player._state.yaw,
                    velocityX = player._state.velocityX,
                    velocityY = player._state.velocityY,
                    energy = 1000,
                    health = 1000,
                    direction = Helpers.ObjectState.Direction.None
                };

                // Their previous auto-occupy vehicle, left empty somewhere, goes: one per player, no free packs piling up on the map
                ushort oldId;
                if (autoOccupyVehicle.TryGetValue(player._alias, out oldId))
                {
                    Vehicle old = arena.Vehicles.FirstOrDefault(v => v != null && v._id == oldId);
                    if (old != null && !old.IsDead && old._inhabitant == null && old._type != null && old._type.Id == targetVehicleTypeId)
                        old.destroy(false);
                    autoOccupyVehicle.Remove(player._alias);
                }

                // Create the vehicle like normal manual vehicle creation (unowned)
                Vehicle newVehicle = arena.newVehicle(vehicleInfo, player._team, null, objState);
                if (newVehicle == null)
                {
                    player.sendMessage(-1, String.Format("Auto-Occupy: Failed to create {0}.", vehicleInfo.Name));
                    return;
                }

                autoOccupyVehicle[player._alias] = newVehicle._id;

                // Update vehicle state to sync immediately, then occupy it
                newVehicle.update(false);
                OccupyPlayerOnVehicle(player, newVehicle);
            }
            catch (Exception ex)
            {
                Console.WriteLine(String.Format("Error in HandleAutoOccupyImmediate for {0}: {1}", player._alias, ex.Message));
            }
        }
        
        /// <summary>
        /// Occupies a player on a specific vehicle with proper synchronization
        /// </summary>
        private void OccupyPlayerOnVehicle(Player player, Vehicle vehicle)
        {
            try
            {
                // Only a live, empty vehicle that is still in this arena
                if (vehicle == null || vehicle.IsDead || vehicle._inhabitant != null || !arena.Vehicles.Contains(vehicle))
                    return;

                // Ensure the vehicle is not considered dead and has proper state
                vehicle._tickDead = 0;
                vehicle._state.energy = Math.Max(vehicle._state.energy, (short)500); // Ensure good energy
                vehicle._state.health = Math.Max(vehicle._state.health, (short)500); // Ensure good health
                
                // Create player state for warping - preserve current velocity for smooth transition
                Helpers.ObjectState playerState = new Helpers.ObjectState
                {
                    positionX = player._state.positionX,
                    positionY = player._state.positionY,
                    positionZ = 0,
                    yaw = player._state.yaw,
                    velocityX = player._state.velocityX,
                    velocityY = player._state.velocityY,
                    energy = player._state.energy,
                    health = player._state.health,
                    direction = player._state.direction
                };
                
                // Warp player to establish proper state sync
                player.warp(Helpers.ResetFlags.ResetAll, playerState, player._state.health, player._state.energy, (byte)player._state.yaw);
                
                // Now occupy the vehicle
                player.enterVehicle(vehicle);
                
                // Update the vehicle's state after entering - preserve velocity for smooth transition
                vehicle._state.positionX = player._state.positionX;
                vehicle._state.positionY = player._state.positionY;
                vehicle._state.velocityX = player._state.velocityX;
                vehicle._state.velocityY = player._state.velocityY;
                vehicle._state.yaw = player._state.yaw;
                vehicle._state.direction = player._state.direction;
                
                // Final sync operations
                vehicle.update(false);
                player.syncState();
                
                // Determine vehicle name for message
                string vehicleName = vehicle._type != null ? vehicle._type.Name : "vehicle";
                player.sendMessage(0, String.Format("Auto-Occupy: You have been placed on a {0}!", vehicleName));
            }
            catch (Exception ex)
            {
                Console.WriteLine(String.Format("Error occupying {0} on vehicle: {1}", player._alias, ex.Message));
            }
        }
        
        /// <summary>
        /// Processes pending auto-occupy operations with proper alive checks and retry logic. An entry whose player is no
        /// longer in the arena is dropped at once (it used to wait forever and fire on their next visit).
        /// </summary>
        private void ProcessPendingAutoOccupy()
        {
            if (!AutoOccupyOn)
            {   // drop anything already queued so nothing is acted on later
                pendingAutoOccupy.Clear();
                autoOccupyRetryCount.Clear();
                pendingOccupyWhen.Clear();
                pendingOccupyNeedsPack.Clear();
                pendingOccupyBuys.Clear();
                return;
            }

            int currentTick = Environment.TickCount;
            var playersToRemove = new List<Player>();
            var playersToRetry = new List<Player>();
            var aliasesGone = new List<string>();
            var fxDue = new List<Player>();

            // Process pending operations
            foreach (var kvp in pendingAutoOccupy)
            {
                string playerAlias = kvp.Key;
                int scheduledTick = kvp.Value;
                
                // Find the actual player object
                Player player = arena.Players.FirstOrDefault(p => p._alias == playerAlias);
                if (player == null)
                {
                    aliasesGone.Add(playerAlias);
                    continue;
                }

                // The prefire effect and sound start when the prefire does (the pack's key press), not at the trigger
                int fxAt;
                if (occupyFxAt.TryGetValue(playerAlias, out fxAt) && unchecked(currentTick - fxAt) >= 0)
                    fxDue.Add(player);

                // Check if it's time to occupy the vehicle
                if (currentTick >= scheduledTick)
                {
                    try
                    {
                        if (pendingOccupyBuys.Contains(playerAlias) && !player.IsSpectator && !player.IsDead && !HasPackItem(player, GetPrimarySkillName(player)))
                            BuyOccupyPack(player);   // ?v (Travis 10-29): the pack first, as ?b would; then made like any other
                        // Check if player is valid and alive (and still carries the pack, when this trigger needs it)
                        if (!player.IsSpectator && !player.IsDead && player._state != null && player._state.health > 0
                            && (!pendingOccupyNeedsPack.Contains(playerAlias) || HasPackItem(player, GetPrimarySkillName(player))))
                        {
                            bool spendsPack = pendingOccupyNeedsPack.Contains(playerAlias);
                            HandleAutoOccupyImmediate(player);
                            if (spendsPack && player._occupiedVehicle != null)
                                SpendOneTimePack(player, GetPrimarySkillName(player));
                            playersToRemove.Add(player);
                        }
                        else
                        {
                            // Player not alive or invalid, retry if we haven't exceeded max attempts
                            HandleRetryAutoOccupy(player, currentTick, playersToRemove, playersToRetry);
                        }
                    }
                    catch (Exception ex)
                    {
                        Console.WriteLine(String.Format("Error processing auto-occupy for {0}: {1}", player._alias, ex.Message));
                        playersToRemove.Add(player);
                    }
                }
            }

            foreach (Player player in fxDue)
            {
                occupyFxAt.Remove(player._alias);
                PlayVehicleCreationSound(player, GetVehicleTypeForClass(player, GetPrimarySkillName(player)));
            }

            // Process retries with optimized timing
            foreach (Player player in playersToRetry)
            {
                // Use shorter retry delays for faster response
                pendingAutoOccupy[player._alias] = currentTick + 500; // 500ms between retry attempts
            }

            // Clean up completed/failed operations
            foreach (Player player in playersToRemove)
                DropPendingOccupy(player._alias);
            foreach (string alias in aliasesGone)
                DropPendingOccupy(alias);
        }
        
        /// <summary>
        /// Handles retry logic for auto-occupy operations
        /// </summary>
        private void HandleRetryAutoOccupy(Player player, int currentTick, List<Player> playersToRemove, List<Player> playersToRetry)
        {
            const int MAX_RETRY_ATTEMPTS = 3;
            
            if (!autoOccupyRetryCount.ContainsKey(player._alias))
                autoOccupyRetryCount[player._alias] = 0;
                
            autoOccupyRetryCount[player._alias]++;
            
            if (autoOccupyRetryCount[player._alias] <= MAX_RETRY_ATTEMPTS)
            {
                playersToRetry.Add(player);
            }
            else
            {
                if (pendingOccupyNeedsPack.Contains(player._alias) && !player.IsDead && !player.IsSpectator
                    && !HasPackItem(player, GetPrimarySkillName(player)))
                    player.sendMessage(0, String.Format("Auto-Occupy: you carry no {0}, so you stay on foot.", OccupyVehicleName(player) ?? "vehicle"));
                playersToRemove.Add(player);
            }
        }
        
        /// <summary>
        /// Game start: everyone with ?ao on for game start - or, with *startoccupy on, every player whose class has a
        /// vehicle - is put on it a moment after the start (scheduled, so a player still respawning is retried).
        /// </summary>
        private void StartAutoOccupyForGameStart()
        {
            if (!AutoOccupyOn)
                return;

            try
            {
                foreach (Player player in arena.PlayersIngame.ToList())
                {
                    // Skip spectators only (dead players are retried by ProcessPendingAutoOccupy)
                    if (player.IsSpectator || player._team.IsSpec)
                        continue;
                    if (occupyArmed.Remove(player._alias))
                        OccupyAtGameStart(player);   // ?v before the start: 1 s after the whistle, a missing pack bought
                    else
                        InitiateAutoOccupy(player, "game start", startOccupyEnabled ? OccupyWhen.None : OccupyWhen.Start, 1000);
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine(String.Format("Error in StartAutoOccupyForGameStart: {0}", ex.Message));
            }
        }
        
        /// <summary>
        /// ?ao toggles it; ?ao on; ?ao off; ?ao all = every trigger; ?ao death start recall swap = only the ones named. By
        /// default it fires after death and at game start, not on a dropship recall or a class change (Travis, 2026-10-17).
        /// </summary>
        private void HandleAutoOccupyCommand(Player player, string payload)
        {
            string[] args = (payload ?? "").ToLower().Split(new[] { ' ', ',' }, StringSplitOptions.RemoveEmptyEntries);
            bool on = OccupyTriggers(player) != OccupyWhen.None;   // on by their build counts as on
            OccupyWhen when = OccupyWhen.None;                      // None = the class's base triggers (OccupyBase)
            if (args.Length == 0)
                on = !on;
            else if (args[0] == "off")
                on = false;
            else if (args[0] == "on")
                on = true;
            else if (args[0] == "all")
            {
                on = true;
                when = OccupyWhen.All;
            }
            else
            {
                OccupyWhen picked = OccupyWhen.None;
                foreach (string a in args)
                {
                    if (a == "death" || a == "respawn") picked |= OccupyWhen.Death;
                    else if (a == "start" || a == "gamestart") picked |= OccupyWhen.Start;
                    else if (a == "recall" || a == "ds") picked |= OccupyWhen.Recall;
                    else if (a == "swap" || a == "class") picked |= OccupyWhen.Swap;
                    else
                    {
                        player.sendMessage(-1, "Usage: ?ao [on|off|all] or pick when: ?ao death start recall swap  (e.g. ?ao death start recall)");
                        return;
                    }
                }
                on = true;
                when = picked;
            }
            autoOccupyEnabled[player._alias] = on;
            if (when == OccupyWhen.None)
                autoOccupyWhen.Remove(player._alias);
            else
                autoOccupyWhen[player._alias] = when;
            if (!on)
            {
                player.sendMessage(0, "AutoOccupy is now OFF. ?ao turns it back on; ?v still works for one death.");
                return;
            }
            when = OccupyTriggers(player);
            var parts = new List<string>();
            if ((when & OccupyWhen.Death) != 0) parts.Add("after death");
            if ((when & OccupyWhen.Start) != 0) parts.Add("game start");
            if ((when & OccupyWhen.Recall) != 0) parts.Add("dropship recall");
            if ((when & OccupyWhen.Swap) != 0) parts.Add("class change");
            int vehicleId = GetVehicleTypeForClass(player, GetPrimarySkillName(player));
            VehInfo vehicle = vehicleId == -1 ? null : AssetManager.Manager.getVehicleByID(vehicleId);
            player.sendMessage(0, String.Format("AutoOccupy is now ON ({0}){1}. ?ao death start recall swap picks when; ?ao off stops it; ?v flips one death.",
                String.Join(", ", parts.ToArray()),
                vehicle != null ? ": you get a " + vehicle.Name : ", but your class has no vehicle for it (Eng/Med hoverboard, JT drop pack, Inf/SL flight pack)"));
        }

        private static void LoadAutoOccupyState()
        {
            if (_autoOccupyStateLoaded)
                return;
            _autoOccupyStateLoaded = true;
            try
            {
                if (!System.IO.File.Exists(AUTOOCCUPY_STATE_PATH))
                    return;
                foreach (string raw in System.IO.File.ReadAllLines(AUTOOCCUPY_STATE_PATH))
                {
                    string[] kv = raw.Split(new[] { '=' }, 2);
                    if (kv.Length == 2 && kv[0].Trim().ToLower() == "enabled")
                    {
                        string val = kv[1].Trim().ToLower();
                        _autoOccupyOff = (val == "off" || val == "false" || val == "0");
                    }
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine("AutoOccupyState.txt not read: " + ex.Message);
            }
        }

        private static void SaveAutoOccupyState()
        {
            try
            {
                System.IO.File.WriteAllLines(AUTOOCCUPY_STATE_PATH, new[]
                {
                    "# Written by *autooccupy. enabled=on|off (zone-wide).",
                    "enabled=" + (_autoOccupyOff ? "off" : "on"),
                });
            }
            catch (Exception ex)
            {
                Console.WriteLine("AutoOccupyState.txt not written: " + ex.Message);
            }
        }

        /// <summary>*autooccupy [on|off] - the zone-wide safety switch, like *autodrop: status for any mod, changing it needs IsAutoDropStaff.</summary>
        private void AutoOccupyCommand(Player player, string payload)
        {
            LoadAutoOccupyState();
            string arg = (payload ?? "").Trim().ToLower();
            if (arg.Length > 0)
            {
                if (!IsAutoDropStaff(player))
                {
                    player.sendMessage(-1, "Only zone staff can change autooccupy.");
                    return;
                }
                if (arg != "on" && arg != "off")
                {
                    player.sendMessage(-1, "Usage: *autooccupy [on|off]");
                    return;
                }
                _autoOccupyOff = arg == "off";
                SaveAutoOccupyState();
                Console.WriteLine(String.Format("[autooccupy] {0} set {1}", player._alias, arg));
            }
            player.sendMessage(0, String.Format("Autooccupy: {0} (zone-wide) | {1} player(s) have ?ao on in this arena | *startoccupy {2}",
                _autoOccupyOff ? "OFF" : "ON", autoOccupyEnabled.Count(kv => kv.Value), startOccupyEnabled ? "ON" : "off"));
        }

        /// <summary>
        /// Triggers autooccupy after class change (can be called from HandleSwapCommand)
        /// </summary>
        public void TriggerAutoOccupyAfterClassChange(Player player, string reason)
        {
            // This is the path an Infiltrator swap took - exactly when the crash was reported.
            if (!AutoOccupyOn)
                return;

            if (autoOccupyEnabled.ContainsKey(player._alias) && autoOccupyEnabled[player._alias])
            {
                InitiateAutoOccupy(player, reason);
            }
        }
        
        #endregion

